local ADDON, ns = ...
ns.LoreZones = {
    ["Азшара"] = {
        _zone = "Азшара лежит на северо-востоке Калимдора, между Ясеневым лесом и Великим морем, южнее Зимних Ключей и севернее Дуротара. Здесь царит вечная осень: листва рыжая и багряная, утёсы обрываются к пляжам, а над заливом Бурь гремят грозы. Десять тысяч лет назад тут стоял Эльдарат, великий город высокорожденных; в Войне Древних и Великом Расколе большая его часть обрушилась в море, и ныне лишь обломки колонн цепляются за скалы, а остальное лежит под волнами. Ночные эльфы считают эту землю проклятой: в руинах бродят призраки высокорожденных, в лагерях засели сатиры, а побережье держат наги Злобного Прибоя. Реликвии Эльдарата стерегут синие драконы во главе с Азурегосом. Орда держит на западе заставу Храбростан, Альянс — заставу Талрендис у моста через Строптивую, но дальше их костров Азшара пуста и безмолвна.",
        ["Река Строптивая"] = "Строптивая берёт начало в озере на склонах Хиджала и водопадами спускается в низины, чтобы широкой быстрой рекой отделить Ясеневый лес от Азшары. Дальше к югу она становится границей Дуротара и Степей и впадает в Великое море возле Кабестана. Через реку перекинут единственный здесь мост: за ним начинается дорога в Ясеневый лес, а у самого берега Азшары стоит застава Талрендис.",
        ["Крепость Черночревов"] = "У подножия северных гор Азшары укрыта фурболгская крепость, названная по племени Черночревов. Вход в неё вырублен в виде медвежьей головы, а вокруг тянутся грубые ограды и тотемы. Фурболги здесь не жалуют чужаков, и путнику лучше не задерживаться у их ворот.",
        ["Лагерь Ванндир"] = "Лагерь Ванндир — тихий уголок среди осенних холмов Азшары, где нет ни огней, ни дорог. Только ветер с залива Бурь шумит в рыжей листве, и никто не помнит, кто и зачем собирался здесь поселиться.",
        ["Лагерь Легаши"] = "Лагерь Легаши раскинулся на севере Азшары, восточнее Урсолана. Среди обломков эльфийских построек засели сатиры Легаши — порождения Пылающего Легиона, некогда бывшие высокорожденными. Они творят здесь тёмные обряды, и говорят, что в их лагере хранились книги демонической магии, которыми интересовался даже верховный маг Ксилем. Тому, кто чтит Элуну, здесь не рады.",
        ["Талассийское поселение"] = "На холме к югу от лагеря Легаши разбили палатки эльфы крови из Кель'Таласа. Экспедицию привела волхв Римтори: она выпросила у Орды деньги и охрану под обещание поделиться находками, а затем перебила орочьих воинов и оставила всё найденное себе. Пока Римтори бродит по Азшаре в поисках рун высокорожденных, её магистры сторожат лагерь, и над ним витает запах демонической волшбы.",
        ["Руины Эльдарата"] = "До Великого Раскола Эльдарат был цветущим городом и твердыней высокорожденных. В Войну Древних здесь бились с Пылающим Легионом, а потом море поглотило большую часть города, и лишь обломки на утёсах напоминают о былом величии. Ночные эльфы давно сторонятся этих мест: руины заняли наги Злобного Прибоя, а среди колонн стоят таблички, на которых маги высокорожденных записывали свои прозрения о тайной магии. Говорят, здесь спрятаны могущественные реликвии — не случайно за руинами приглядывают синие драконы.",
        ["Гнездо Хетайры"] = "Под водами залива Бурь скрывается затонувший храм Элуны, который ныне называют Гнездом Хетайры. Его заняли гидры — дети Хетайры, а сама многоголовая мать плавает в водах чуть севернее и порой выбирается на скалистый островок. Спускаться сюда отваживаются лишь самые опытные пловцы.",
        ["Храм Зин-Малор"] = "Храм Зин-Малор стоит посреди руин Эльдарата; когда-то ночные эльфы поклонялись здесь Элуне, и его очертания напоминают Храм Луны в Дарнасе. Ныне храм захватили наги Злобного Прибоя, и их военачальник восседает там, где прежде звучали молитвы. Здесь хранился кристалл Зин-Малора, дающий владельцу почти безграничную магическую силу, если он её достоин; но кристалл давно похищен и увезён на север, в Зимние Ключи.",
        ["Медвежий угол"] = "Медвежий угол лежит у юго-восточного края гор Азшары. На утёсе здесь поднимается башня, в которой затворился верховный маг Ксилем со своими учениками; к нему приходят маги и разбойники, ищущие наставления. Свое имя это место получило по деревушкам фурболгов Древобрюхов, что стоят здесь как передовые посты их крепости и Урсолана.",
        ["Урсолан"] = "Урсолан назван в честь Урсола, медвежьего полубога Калимдора, которого чтят фурболги. Он лежит на севере Азшары, к востоку от прохода в крепость Древобрюхов, и посреди него зияет глубокая расселина. Здесь раскинулось обширное поселение фурболгов Древобрюхов, тянущееся на юг до Медвежьего угла; чужакам, не заслужившим доверия племени, лучше держаться подальше.",
        ["Храм Арккоран"] = "На северо-восточном берегу Азшары, на Разорённом побережье, стоит древний храм Элуны, ныне известный как храм Арккоран. В его верхних покоях обитает морской великан, которого мурлоки и макрура почитают как божество и стерегут его от чужаков. Говорят, у великана давняя вражда с гидрами залива Бурь и их матерью Хетайрой.",
        ["Залив Бурь"] = "Залив Бурь — часть Великого моря у восточного берега Азшары, где грозы не утихают почти никогда. На дне залива лежит затонувшая половина Эльдарата, и наги Злобного Прибоя стекаются сюда за зачарованными кораллами. У берегов залива находятся Гнездо Хетайры, храм Арккоран и островок с пещерой Чешуеборода, а среди волн торчат острые скалы и лабиринт рифов, делающий плавание почти невозможным.",
        ["Разоренное побережье"] = "Разорённое побережье тянется по северному краю залива Бурь. Его пляжи густо населены гидрами, морскими великанами, макрурами и мурлоками, так что путь вдоль воды опасен. Здесь же стоят храм Арккоран и башня Эльдары — последние следы эльфийской цивилизации на этом берегу.",
        ["Башня Эльдары"] = "Башня Эльдары стоит на самой оконечности мыса к северо-востоку от залива Бурь. Когда-то она была частью обширных владений ночных эльфов, что простирались по всей Азшаре, а теперь стоит запертой и заброшенной. Песчаные пляжи вокруг неё патрулируют мурлоки, макрура и гидры.",
        ["Острые рифы"] = "Острыми рифами зовут северное побережье Азшары: полосы песка, разбитые скальными гребнями и узкими заливчиками. Плавать здесь опасно из-за коварных мелей и подводных камней, а по берегу бродят в поисках пищи мурлоки, гидры и макрура.",
        ["Южный пляж"] = "Южный пляж лежит в сердце Азшары, по южному краю залива Бурь. Его населяют наги, а с ними макрура, гидры, мурлоки и изредка морские великаны. Весь берег усеян обломками колонн и стен — это остатки некогда великого Эльдарата, ушедшего под воду.",
        ["Памятник Черному Ворону"] = "На южной оконечности Азшары, на утёсах над Великим морем, лежат руины исполинской статуи ночных эльфов. От колосса остались лишь ноги на постаменте, прочее разбросано вокруг или давно ушло под воду. Говорят, памятник воздвигли в честь лорда Чёрного Ворона, водившего войска смертных в Войне Древних, но точно этого никто не знает. Ныне среди обломков обосновались наги Злобного Прибоя, а с моря к памятнику не подойти — сюда ведёт лишь мост с суши.",
        ["Одинокая вершина"] = "Одинокая вершина — гора на юго-западе Азшары, что возвышается над окрестными холмами. Её склоны видны отовсюду, и от тихих лесов у её подножия веет покоем, редким для этой земли. Говорят, в кольце её хребтов скрыт огромный кратер, куда путникам нет дороги.",
        ["Озеро Меннар"] = "Озеро Меннар — одно из немногих мест за пределами Нордскола, где можно встретить синих драконов. Все берега озера заняты их выводком: драконьи отродья и синие дракончики стерегут подходы к воде, и только самые сильные пробьются к ней. Само же озеро тихо и безопасно, и тот, кто добрался до его берега, может отдохнуть в прохладе.",
        ["Святилище Песни Теней"] = "Святилище Песни Теней — холм на западе Азшары, покрытый руинами. Здесь бродят призраки высокорожденных, готовые истребить всякую живую душу, что забредёт в их владения. Святилище носит то же имя, что Джарод и Майев Песнь Теней, но связано ли оно с ними, неведомо.",
        ["Лагерь Халдарр"] = "Лагерь Халдарр стоит на западе Азшары, к северо-востоку от святилища Песни Теней и к югу от Храбростана. Среди эльфийских руин здесь плотно засели сатиры Халдарр, и путникам с дороги лучше не сходить: сатиры не терпят живых.",
        ["Храбростан"] = "Храбростан — маленькая застава Орды на северо-западе Азшары, прижатая к горам. Орде эта земля мало интересна, и лагерь беден и плохо защищён. Когда-то здесь стояло больше воинов, но большинство погибли по вине волхва Римтори — эльфийки крови, которую Белгром прислал из Оргриммара за сокровищами высокорожденных. Сюда же в наказание сослана Джедига: она ищет древние таблички, чтобы выбраться из Азшары. Отсюда летают ветрокрылы в Оргриммар и Ясеневый лес.",
        ["Опустошенный берег"] = "Опустошённый берег — южное побережье Азшары у границы с Дуротаром: пляжи и утёсы, изрезанные заливчиками, усеянные руинами и остовами кораблей. Как и у Острых рифов, здесь опасны и мели, и обитатели — мурлоки, гидры и макрура. На западной оконечности берега на холме стоит домик гномов-инженеров, торгующих припасами для мастеров.",
        ["Великое море"] = "Великое море — океан, разделяющий земли Азерота. Оно родилось в Великом Расколе, когда воды хлынули в разлом на месте Источника Вечности, а посреди него по сей день бушует Водоворот. У берегов Азшары море сурово: волны бьют в утёсы, среди рифов торчат скалистые островки, а в глубине плавают наги, гидры и морские великаны. Уплывший слишком далеко от берега не вернётся.",
        ["Горькие плесы"] = "Горькими плёсами называют северо-восток Азшары. Здесь во множестве водятся гиппогрифы, слизнюки и химеры, а по северному краю бродят горные великаны, вытеснившие прочую живность. Среди осенних трав изредка попадается горный серебряный шалфей.",
        ["Застава Талрендис"] = "Застава Талрендис — небольшой лагерь ночных эльфов на юго-западе Азшары, у самого моста через Строптивую. Отсюда часовые следят за проклятой землёй, что начинается сразу за рекой. Путникам Альянса застава даёт приют и гиппогрифов до Аубердина и Кабестана, но иных услуг здесь не найти.",
        ["Святилище Ретресса"] = "Святилище Ретресса — разрушенная эльфийская часовня на Опустошённом берегу, к юго-западу от памятника Чёрному Ворону. Ныне оно пустует; лишь заблудшие мурлоки и макрура порой забредают сюда с пляжа.",
        ["Пещера Чешуеборода"] = "На крохотном островке в западной части залива Бурь темнеет пещера Чешуеборода. Здесь живёт древняя морская черепаха, но застать её дома удаётся редко: Чешуебород предпочитает охотиться в водах Великого моря.",
        ["Оплот Легаши"] = "Оплот Легаши — укреплённое гнездо сатиров Легаши на севере Азшары. Здесь, среди обломков высокорожденных, демонические отродья собираются под защитой стен и тёмных знаков, и жар их костров виден издалека. Путнику лучше обойти это место стороной.",
        ["Лагерь талассийского авангарда"] = "Лагерь талассийского авангарда — передовой пост экспедиции эльфов крови из Кель'Таласа, пришедшей в Азшару за реликвиями высокорожденных. Его палатки и знамёна стоят на пути к главному поселению, и дозорные с подозрением встречают всякого чужака.",
    },
    ["Альтеракские горы"] = {
        _zone = "Альтеракские горы — высокий лесистый край в сердце Лордерона, где часто идут дожди, а небо почти всегда затянуто тучами. Когда-то здесь стояло королевство Альтерак, но во Вторую войну его правители предали Альянс, сговорившись с Ордой, и армии людей обратили столицу в руины. Ныне развалины заняли огры клана Раздробленного Хребта, а потомки альтеракской знати сколотили Синдикат — шайку разбойников, засевшую в Странбраде и на холмах Высокогорья; обе стороны без конца воюют за эту землю. На берегу озера Лордамер под магическим куполом укрылся Даларан, город магов Кирин-Тора, переживший Третью войну. В заснеженной долине в глубине гор дворфы Грозовой Вершины сражаются с орками клана Северного Волка, а по пещерам бродят свирепые йети. Ни у Альянса, ни у Орды здесь нет своих поселений: путники приходят сюда из Южнобережья и с мельницы Таррен.",
        ["Пещеры предгорий"] = "Пещеры предгорий уходят в склон холма на южной границе Альтеракских гор, там, где горы спускаются к Хилсбраду. Некогда здесь укрылся чернокнижник Гелькулар, задумавший превратить себя в лича, но толпа крестьян отыскала его логово и жестоко расправилась с ним. С тех пор пещеры облюбовали йети: их рёв разносится по тёмным ходам, а на стенах поблёскивают жилы олова и альтеракского гранита. Лишь самые отчаянные путники решаются заглянуть сюда ради добычи.",
        ["Лордамерские выселки"] = "Лордамерские выселки стоят на холме над берегом озера, неподалёку от купола Даларана. После Второй войны здесь держали пленных орков, а теперь лагерь охраняют щитоносцы и теурги Даларана, и его стены служат тюрьмой и лабораторией разом. Сюда угодила небольшая группа нежити во главе с Кеганом Мракмаром — беглецы из Подгорода, которых Отрекшиеся считают предателями. Стражница лагеря изучает загадочные кровавые подвески, принесённые пленниками, а часовые на вышках зорко следят за дорогой: гостей с севера здесь не жалуют.",
        ["Даларан"] = "Даларан — город магов, столица Кирин-Тора, что стоит на южном берегу озера Лордамер. В Третью войну демон Архимонд обратил его в развалины, и уцелевшие волшебники накрыли город непроницаемым лиловым куполом, чтобы отстроить его в тайне от чужих глаз. Сквозь мерцающую завесу не пройти никому, а снаружи, среди разрушенных окраин, несут дозор волшебники Даларана и их каменные слуги-элементали. Здесь же обосновался верховный маг Ансирем Руноплет, чьи мысли заняты пропавшей в далёких джунглях дочерью. Маги Даларана враждебны Отрекшимся и ревниво следят за берегами озера.",
        ["Странбрад"] = "Странбрад — городок на северо-восточных склонах гор, у самой границы с Чумными землями. Он принадлежал королевству Альтерак, а после его падения отошёл к Лордерону; накануне Третьей войны его разоряли орки Чёрной Горы, уводя жителей в рабство. Когда чума опустошила Лордерон, брошенный город заняли разбойники Синдиката, и теперь среди пустых домов, заброшенной ратуши и кузни хозяйничают их бойцы и чародеи. В одном из домов они держат пленников — среди них и орк Гол'дир, вождь отряда, посланного с мельницы Таррен разведать силы Синдиката.",
        ["Руины Альтерака"] = "Руины Альтерака — всё, что осталось от столицы горного королевства. Во Вторую войну король Альтерака тайно сговорился с Ордой, и когда измена раскрылась, войска Альянса разрушили город, а его жители разбрелись по свету. Опустевшие стены заняли огры клана Раздробленного Хребта во главе с вождём Муг'толом; здесь же слоняется жадный маг-огр Грел'борг Скряга. Среди обломков ещё лежат бесценные книги погибшей альтеракской библиотеки, и хранители знаний Южнобережья мечтают спасти их из лап огров. Синдикат считает эти камни своими и ведёт с ограми нескончаемую войну.",
        ["Логово Раздробленного Хребта"] = "Логово Раздробленного Хребта — огромный курган огров к северу от руин Альтерака. В пещере и окрестных лагерях живёт основная сила клана: громилы, крушители и маги-огры, готовые броситься на любого, кто подойдёт к их кострам. Отсюда огры совершают набеги на дороги Хилсбрада, и маршалы Южнобережья давно назначили награду за их головы.",
        ["Кровавая низина"] = "Кровавая низина — ещё один курган огров Раздробленного Хребта, укрытый в глубине гор. Здесь клан хранит награбленное, а в одной из клеток томится пленный гном, который от безысходности приторговывает с редкими гостями. Название низины говорит само за себя: мало кто выбирался отсюда невредимым.",
        ["Высокогорье"] = "Высокогорье — холмистая земля на северо-востоке Альтеракских гор. Когда-то это была житница королевства Альтерак, но после гибели государства здесь укрепился Синдикат: на холмах стоят его лагеря, и нигде разбойники не чувствуют себя так вольготно. Среди их главарей известен барон Вардус, чьи головорезы нападают на Южнобережье. На западной окраине Высокогорья, у самого озера, прячется Овчарня Дандреда — убежище вожаков Синдиката.",
        ["Озеро Лордамер"] = "Озеро Лордамер — одно из величайших озёр Восточных королевств. На его берегах и в окрестных горах выросли три человеческих державы: Лордерон, Даларан и Альтерак. Посреди вод лежат Рассветные острова, а над ними чернеет крепость Фенрис, где обосновались слуги Плети. Аптекари Подгорода поминают древнюю чуму, что когда-то погубила в озере всё живое; ныне на островах водятся озёрные ползуны, а у разрушенной пристани копошатся мурлоки. Для Отрекшихся озеро — водная граница между Серебряным бором и беспокойными Альтеракскими горами.",
        ["Перекресток Висельников"] = "Перекрёсток Висельников — развилка дорог у подножия руин Альтерака, где над старым трактом стоит разрушенная сторожевая башня. Земля здесь принадлежит ограм Раздробленного Хребта: их дозоры кружат вокруг башни и стерегут путь из Хилсбрада к северным перевалам. Мрачное имя перекрёстка напоминает о временах, когда здесь вершился суд павшего королевства.",
        ["Возвышенность Гэвина"] = "Возвышенность Гэвина — самый западный из холмов, что выступают из гор к югу, в сторону Хилсбрада. По его травянистым склонам бродят горные львы, а с вершины видно дорогу от Южнобережья. Тихое место, где о людях напоминает лишь название.",
        ["Возвышенность Соферы"] = "Возвышенность Соферы — холм над северо-восточными предгорьями Хилсбрада. На его вершине стоит лагерь Синдиката: отсюда разбойники следят за дорогой на мельницу Таррен и в Странбрад. Пастухи и путники обходят это место стороной.",
        ["Уступ Коррана"] = "Уступ Коррана — второй из холмов, отделяющих горы от предгорий Хилсбрада. Здесь укрепились люди Синдиката: их костры видно с дороги, а стражи и наёмные убийцы не спускают глаз с проходящих внизу караванов.",
        ["Высокий отрог"] = "Высокий отрог — холм, нависающий над городком Хилсбрад и полями предгорий. Отсюда открывается вид на крепость Дарнхольд на востоке, а рядом начинается тропа к проходу в Альтеракскую долину. На скалистых склонах живут горные львы, а по вечерам с гор спускаются йети.",
        ["Мглистый берег"] = "Мглистый берег — полоса побережья озера Лордамер, что тянется от Овчарни Дандреда до купола Даларана. Здесь всегда стоит туман, в камышах греются черепахи, а на воде виднеются Рассветные острова и мрачная громада крепости Фенрис. У берега затаились фанатики Алого ордена, готовые напасть на всякого, кто подойдёт слишком близко.",
        ["Овчарня Дандреда"] = "Овчарня Дандреда — небольшая усадьба с фермой и пристанью на западном краю Высокогорья, у самого озера Лордамер. Некогда она принадлежала альтеракскому дворянину, а теперь стала тайным убежищем предводителя Синдиката — наследника павшего королевского дома Альтерака. Здесь его окружают телохранители и убийцы, а гостит у него орк Нагаз, жрец тайного ордена Недремлющего Аргуса. Мировой судья Южнобережья подозревает, что за Синдикатом стоят силы куда страшнее разбойников.",
        ["Промерзшая пещера"] = "Промёрзшая пещера — логово горных йети в центральной части Альтеракских гор. Для этих свирепых созданий пещера — священное место: в её глубине горит древний ритуальный костёр, некогда сложенный чернокнижником Гелькуларом. Говорят, что если сжечь на этом огне мясо, из глубин гор на запах явится самый могучий из йети.",
        ["Берег Промозглого Ветра"] = "Берег Промозглого Ветра — невысокая возвышенность на восточной окраине Альтеракских гор. Здесь стоят древние тролльские руины, а из ущелья с севера, из Западных Чумных земель, задувает ледяной ветер, давший месту имя. Среди камней поселился одинокий тролль из джунглей, миролюбивый мистик, знающий толк в старинных клинках. Дальше на север дорога ведёт прямо к границе Чумных земель.",
        ["Альтеракская долина"] = "Альтеракская долина — заснеженная долина в самом сердце гор. Давным-давно чернокнижник Гул'дан изгнал сюда клан Северного Волка, и орки жили здесь в уединении, пока в долину не пришла экспедиция дворфов Грозовой Вершины в поисках руды и реликвий предков. С тех пор две армии сошлись в нескончаемой битве: орков ведёт старый шаман Дрек'Тар, а дворфов — их генерал из крепости Дун Балдар. У входов в долину вербовщики зазывают бойцов: воевода Лаггронд собирает силы Орды, а офицеры Грозовой Вершины — воинов Альянса. В глубине долины обитают ещё троги, кобольды, гарпии и гноллы.",
        ["Поместье Черного Ворона"] = "Поместье Чёрного Ворона прячется в восточных горах, и путь к нему ведёт по извилистой тропе через тесную пещеру над крепостью Дарнхольд. Это дом братства убийц Чёрного Ворона: здесь есть свой сад, тренировочная площадка и мастера, обучающие разбойников тонкостям ремесла. Хозяин поместья — лорд, возглавляющий лигу ассасинов; чужаков здесь не любят, а с Синдикатом братство враждует не на жизнь, а на смерть. Оранжевые крыши поместья напоминают, что эти земли когда-то принадлежали королевству Альтерак.",
        ["Руины старого Даларана"] = "Руины старого Даларана окружают лиловый купол на берегу озера Лордамер. Это остатки окраин города магов, разрушенных демоном Архимондом в Третью войну: обломки башен и стен торчат из земли у самой мерцающей завесы. Среди руин несут стражу волшебники и заклинатели Даларана в сопровождении каменных элементалей, оберегая тайну возрождающегося города.",
    },
    ["Бесплодные земли"] = {
        _zone = "Бесплодные земли лежат на юго-востоке Каз Модана, между Лок Моданом на севере и Тлеющим ущельем на западе. Это растрескавшаяся пустыня бурого камня и сухих равнин, где палит солнце и гуляют суровые ветры; здесь нет ни озёр, ни ручьёв, и воду берут из глубоких колодцев да редких кактусов. Выживают тут лишь самые стойкие: койоты, хищные кошки, стервятники и каменные элементали. На севере из-под земли показались своды Ульдамана, древнего хранилища титанов, где дворфы Стальгорна нашли первые ключи к тайне своего происхождения. Раскопки потревожили троггов, а следом в руины пришли дворфы Чёрного Железа, укрепившиеся в крепости Ангор. По раскалённым пескам рыщут огры-Гнилобрюхи, на западной окраине стоит Каргат, единственная застава Орды в этих краях, а на востоке, в долине Летлор, живут чёрные драконы, откуда разведчики уже не возвращаются.",
        ["Скелет Апокрифана"] = "К югу от Каргата среди песков лежат исполинские кости дракона, которые называют Скелетом Апокрифана. Никто не помнит, как и когда погиб этот зверь: его рёбра давно выбелены солнцем и ветром. Над костями кружат громадные стервятники, слетающиеся сюда со всей западной пустыни, а в тени рёбер рыщут хищные кошки. Место это мрачное, и путники стараются миновать его засветло.",
        ["Крепость Ангор"] = "На севере Бесплодных земель, к югу от Ульдамана, стоит крепость Ангор, главный оплот дворфов Чёрного Железа в этом краю. Отсюда клан Тенегорна ведёт вылазки в древние своды: дворфы верят, что в Ульдамане сокрыты тайны титанов, которые пригодятся их огненному владыке Рагнаросу. В крепости пребывает и посланник самого Рагнароса, огненный элементаль, надзирающий за усердием его слуг. Стены стерегут воины и чтецы заклинаний, а по дворам тяжело ступают каменные големы. Говорят, что силы Тенегорна в Ульдамане рассеются, если ударить по крепости, в самое их сердце.",
        ["Долина Летлор"] = "Долина Летлор — широкий скалистый каньон на востоке Бесплодных земель и самое опасное место во всей округе. Здесь обитают чёрные драконы: над обрывами кружат опалённые дракончики, а в глубине долины ходят взрослые драконы-стражи. Разведчики Каргата, что подбирались слишком близко, назад не возвращались, и никто не знает, сколько здесь драконов и как они велики. Среди скал высятся кристаллические обелиски древних времён; говорят, под ними томятся в узилище чёрные драконы, и отомкнуть его может лишь Знак Земли.",
        ["Каргат"] = "Каргат — небольшая застава на западной окраине Бесплодных земель и единственный оплот Орды во всём Каз Модане, названный в честь орочьего вождя Каргата Острорука. По приказу самого Тралла Каргатский экспедиционный корпус совершает отсюда вылазки в пустыню: главная его цель — проложить путь через Тлеющее ущелье к Чёрной горе, но и раскопки Ульдамана, которыми так дорожат дворфы, не остались без внимания орков. Суровый климат, злобные звери и отсутствие помощи извне закаляют бойцов: как пишет глава разведчиков Ника Алый Шрам, выйдут отсюда лишь лучшие из воинов. В Каргате есть таверна и конюшня, а ветрокрылы связывают северные и южные владения Орды в Восточных королевствах.",
        ["Лагерь Кош"] = "Лагерь Кош — самая северная из четырёх стоянок огров-Гнилобрюхов, разбитая среди скал на северо-востоке пустыни. Отсюда огры нападают на обозы, что идут через Бесплодные земли в Каргат или дальше, в Тлеющее ущелье. Когда дворфы спешно уходили с раскопок Ульдамана, им пришлось бросить по дороге повозки и ящики с припасами, и всё это, вместе с оружием и провизией, растащили огры из лагеря Кош. Здесь живут воины и мистики племени, и путникам лучше обходить их костры стороной.",
        ["Лагерь Бофф"] = "Лагерь Бофф стоит на юго-востоке Бесплодных земель, у дороги, ведущей к долине Летлор. Это небольшая стоянка огров-Гнилобрюхов, которую стерегут лишь несколько громил. Но именно сюда наведывается главарь племени То'грун, что обходит все четыре лагеря огров, и в Каргате давно ждут с ним встречи.",
        ["Лагерь Вург"] = "Лагерь Вург расположился среди Знойных Песков, к востоку от Каргата, в западной части пустыни. Это одна из четырёх стоянок огров-Гнилобрюхов: здесь стоят их грубые шатры, а вокруг бродят громилы племени. Всерьёз огры не угрожают ни дворфам, ни оркам, но нападают на караваны и одиноких путников, и дорога мимо лагеря считается неспокойной.",
        ["Лагерь Кэгг"] = "Лагерь Кэгг лежит на юго-западе Бесплодных земель, у подножия скал перед Гротом Гнилобрюхих. Здесь собралось больше всего огров племени: громилы, шаманы, мистики и охотники на драконов. Между лагерями ходит их главарь То'грун, огромный огр, что держит племя в кулаке. Стервятники кружат над самыми шатрами, чуя поживу.",
        ["Удел Эгмонда"] = "Удел Эгмонда — заброшенный раскоп на юге Бесплодных земель, названный по имени дворфа-старателя, что нашёл здесь свой конец: раскоп кишел троггами, и в Стальгорне до сих пор ждут вестей о его судьбе. Ныне по ямам и отвалам по-прежнему копошатся трогги, а среди камней бродят разъярённые каменные элементали. Неподалёку разбил стоянку безумный дворф-отшельник, бежавший из Сумеречного Молота: он бормочет о грядущей гибели, что поднимается из-под земли, и о свитке, который отобрали у него элементали.",
        ["Карьер Тяжелоступа"] = "Карьер Тяжелоступа лежит в восточной части пустыни, к северу от Долины Клыков. Раскоп назван по имени дворфа Тяжелоступа, что вёл здесь работы для Лиги Исследователей и искал древности титанов. По слухам, место прибрала к рукам шайка дворфов Чёрного Железа, часть тех же сил, что засели в Ульдамане, а сам Тяжелоступ пропал. Уцелевшие старатели держатся у палаток на краю карьера и не теряют надежды, хотя, как говорят здесь, в Бесплодных землях каждый день убивает надежду.",
        ["Грот Гнилобрюхих"] = "Грот Гнилобрюхих — большой курган-пещера на юго-западе Бесплодных земель, родовое гнездо огров племени Гнилобрюхов. Здесь живут их вожди и огры-маги, и отсюда племя расходится по четырём лагерям, разбросанным по пустыне. Огры мало заботятся о других народах: они грабят караваны и разоряют одинокие стоянки, но их слишком мало, чтобы всерьёз угрожать дворфам или оркам Каргата. И всё же в темноту грота без нужды не заходит никто.",
        ["Ульдаман"] = "Ульдаман — древнее хранилище титанов, погребённое в недрах Каз Модана со времён сотворения мира. Легенды говорят, что титаны создали троггов из камня, сочли опыт неудачным и заперли их здесь, а затем попробовали снова, и так появились земельники, предки дворфов. Дворфы Стальгорна докопались до забытого города ещё до Третьей войны и разбудили троггов, которые перебили большую часть исследователей. Ныне по залам рыщут трогги и дворфы клана Тенегорна: те ищут Диски Норганнона, где записана история сотворения дворфов, чтобы поднести их своему огненному владыке. Город стерегут исполинские стражи из живого камня, а где-то за баррикадами держатся трое дворфов во главе с Бейлогом, ищущие путь в Чертог Хаз'Мула.",
        ["Долина Клыков"] = "Долина Клыков — узкая долина между двумя громадами скал в самом сердце Бесплодных земель. Путь через неё небезопасен: здесь охотятся волки и хищные кошки, а над скалами кружат стервятники. И всё же тут разбита одна из немногих стоянок в пустыне: у костра работает кузнец-изгнанник Мартек, мастер по металлу, к которому за помощью обращаются даже гонщики из далёкой Тысячи Игл. Соседствуют с ним гном-изобретатель и гоблин-торговец, и вместе они держатся у огня посреди враждебной пустыни.",
        ["Знойные Пески"] = "Знойные Пески — широкая равнина на северо-западе Бесплодных земель, между Каргатом и Долиной Клыков. Среди редких кактусов и чахлых деревьев рыщут койоты, кружат стервятники и медленно бредут малые каменные элементали. У дороги, к востоку от Каргата, разбил свой лагерь учёный Лотвил, что изучает здешних элементалей и не терпит, когда его отвлекают от работы. К югу от равнины дымят костры огрского лагеря Вург.",
        ["Маревые равнины"] = "Маревые равнины лежат на юго-западе, к востоку от Грота Гнилобрюхих и к югу от Каргата. Здесь, где воздух дрожит от жары, охотятся огромные стервятники, старые хищные кошки и койоты, а вдали неспешно ступают осадные големы. Плоская выжженная земля просматривается на многие мили, но найти тень в этих местах почти негде.",
        ["Терраса Творца"] = "Терраса Творца — обширный раскоп у самого входа в Ульдаман, на севере Бесплодных земель. Для тех, кто спускается сюда из Лок Модана, это первое, что встречает их в пустыне: колонны и ступени, высеченные ещё в древности, и вырытые дворфами траншеи. Ныне террасу патрулируют дворфы Чёрного Железа: их землекопы и надсмотрщики ведут раскопки, надеясь добраться до сокровищ титанов раньше Стальгорна. Здесь же начинаются внешние залы Ульдамана.",
        ["Лощина Суховея"] = "Лощина Суховея — пыльный, обточенный ветром распадок к западу от долины Летлор. Здесь среди камней устроили логово трогги, а по склонам крадутся хищные кошки. Через лощину ветер несёт песок к драконьему каньону, и путники редко задерживаются в её тени.",
    },
    ["Болотина"] = {
        _zone = "Болотина — холодная сырая низина к северу от Лок Модана, с трёх сторон зажатая горами Каз Модана и открытая морю с запада. Туман стелется по земле, серое небо редко проясняется, а между озёрами и протоками бродят кроколиски, крапчатые ящеры, гноллы и мурлоки. Когда-то здесь стояли крепости дворфов Стальгорна, но войны обратили их в руины, и теперь в топях хозяйничают дикие звери и орки клана Драконьей Пасти, потерявшие Грим Батол. Единственный оплот Альянса в этом краю — Гавань Менетилов, порт на западном берегу, названный в честь короля Теренаса Менетила. С юга в Болотину ведёт перевал Дун Альгаз, с севера — мост Тандола, и обе дороги сейчас неспокойны. На востоке над болотами возвышается запечатанный Грим Батол, к вратам которого не пускают красные драконы.",
        ["Раскопки Вельгара"] = "К востоку от Гавани Менетилов Лига Исследователей ведёт раскопки под началом геолога Вельгара. Дворфы искали в этой земле древние окаменелости и каменные скрижали, но раскоп заполонили крапчатые ящеры, и учёным пришлось укрыться на уступе над ямой. Внизу среди костей и обломков бродят ящеры и ожившие окаменелости, а в рыхлой земле по-прежнему лежит то, что дворфы не успели вынести на поверхность.",
        ["Гавань Менетилов"] = "Гавань Менетилов стоит на острове в бухте Барадин и носит имя короля Теренаса Менетила Второго. Дворфы Стальгорна и их союзники-люди отстроили здесь порт и крепость, и сегодня это единственное пристанище Альянса среди болот. От причалов уходят корабли на запад, в Аубердин и в Терамор, а по дорогам из гавани расходятся торговцы и гонцы. Над крышами возвышается крепость Менетил, а в таверне «Большая вода» у огня сходятся моряки, солдаты и странники. Город невелик, но именно он связывает Каз Модан с далёкими берегами.",
        ["Дун Модр"] = "Дун Модр — дворфийский город на севере Болотины, у самого моста Тандола. Недавно его захватили и разграбили дворфы Чёрного Железа, и теперь на улицах слышна их речь, а не речь Стальгорна. Уцелевшие защитники отступили и разбили лагерь у дороги к югу от города, откуда наблюдают за захватчиками и ждут подкреплений. Тому, кто идёт от Гавани Менетилов на север, стоит помнить: за этим лагерем начинается земля, где приказы отдаёт Чёрное Железо.",
        ["Бухта Барадин"] = "Бухта Барадин — часть Великого моря, омывающая западный берег Болотины. Её воды простираются от северных утёсов Дун Морога до дальних берегов Лордерона, и именно по ним ходят корабли из Гавани Менетилов. У побережья до сих пор видны остовы Третьей флотилии Кул-Тираса, сожжённой и потопленной красными драконами во Вторую войну. На прибрежных отмелях промышляют мурлоки, а по мелководью бродят кроколиски.",
        ["Бухта Менетил"] = "Бухта Менетил — залив между Гаванью Менетилов и северными утёсами Дун Морога, часть большой бухты Барадин. Вода здесь мутная и тихая, и в ней в изобилии водятся кроколиски всех возрастов, чьи шкуры высоко ценят кожевники гавани. К югу от порта, на дне залива, покоится эльфийский корабль «Орлик», шедший вместе с Третьей флотилией Кул-Тираса и потопленный теми же драконами, от которых пытался спастись. Восточнее берега начинается Чёрная трясина.",
        ["Гробница Железноборода"] = "К западу от дороги на Дун Модр стоит старая дворфийская усыпальница — Гробница Железноборода. Рядом с ней кладбище и каменная статуя дворфа, в честь которого названо это место. Склеп давно осквернён: по его плитам и между могил ползают чёрные и багровые слизнюки, и никто больше не приходит сюда хоронить своих мёртвых. Путники обходят гробницу стороной, разве что ищут вещи, которые слизнюки утащили с собой.",
        ["Дун Альгаз"] = "Дун Альгаз — горный перевал, соединяющий Лок Модан с Болотиной, единственная сухопутная дорога с юга. Прежде здесь стоял пост горных пехотинцев Стальгорна, но орки клана Драконьей Пасти вытеснили дворфов к верхнему туннелю и заняли проход. Теперь путь между дворфийскими землями и Гаванью Менетилов стал опасен, и пехотинцы собирают добровольцев, чтобы орки не отрезали порт от Лок Модана.",
        ["Мост Тандола"] = "Мост Тандола — два огромных дворфийских моста через пролив, ведущие из Болотины в Нагорье Арати. Недавно дворфы Чёрного Железа устроили здесь диверсию: один пролёт почти разрушен, и по нему уже не пройти. Второй мост дворфы Стальгорна удерживают ценой немалой крови, ведь без него север Каз Модана отрезан от Арати. Внизу шумит вода, а на уцелевшем пролёте стоят дозорные и смотрят на север.",
        ["Зловещий холм"] = "Зловещий холм лежит на северо-востоке Болотины, юго-восточнее Дун Модра. Здесь дворфы Чёрного Железа разбили большой лагерь, откуда их отряды выходят к мосту Тандола и к захваченному городу. Между палаток горят кузнечные огни, а на подступах стоят стрелки и сапёры, так что случайному путнику здесь не рады.",
        ["Гряда Ящеров"] = "Гряда Ящеров тянется на востоке Болотины, к северо-западу от Врат Драконьей Пасти. Ящеры гнездятся здесь во множестве, а в пещере на гряде матриарх стаи стережёт свой выводок. Земля вокруг усеяна костями добычи, и даже опытные охотники подходят к этому месту с осторожностью.",
        ["Черная трясина"] = "Чёрная трясина — заболоченный край к востоку от бухты Менетил, у самой дороги в Гавань Менетилов. Здесь много логовищ ящеров, и самые голодные твари выходят к обочине, так что даже короткий путь от гавани требует осторожности. Среди кочек и чёрной воды бродят кроколиски, а в тумане легко сбиться с тропы.",
        ["Болото Мохошкуров"] = "На юго-востоке Болотины, недалеко от дворфийских врат Дун Альгаза, раскинулось Болото Мохошкуров — земля гноллов одноимённой стаи. Долгие годы они жили здесь тихо, но стая разрослась: гноллы вытаптывают луга, рубят лес на дрова и жгут костры по всему болоту. Их стоянки разбросаны между деревьев, и Зелёный Страж, хранитель здешних мест, давно смотрит на них с неприязнью.",
        ["Пещера Тельгена"] = "Пещера Тельгена уходит глубоко в горы на юге Болотины. Её ходы кишат ядовитыми пауками, и алхимики говорят, что отрава здесь пропитала саму землю. В глубине залегает редкая руда, ради которой сюда спускаются рудокопы и искатели, несмотря на паутину и шорохи в темноте.",
        ["Болота Синежабрых"] = "Болота Синежабрых лежат на западном побережье Болотины, к северу от Гавани Менетилов. Здесь стоят поселения мурлоков племени Синежабрых, которые выходят из морских глубин и селятся на берегу. Они нападают на рыбаков и торговцев, устраивают засады на дорогах и растаскивают грузы с кораблей, а потом прячутся в своих хижинах у воды, где их непросто достать. Мурлоки держатся стайками, и одинокому путнику здесь лучше не задерживаться.",
        ["Долина Солевого Тумана"] = "Долина Солевого Тумана — небольшая низина на северо-западе Болотины, между Болотами Синежабрых и Гробницей Железноборода, открытая бухте Барадин. Своё имя она получила за то, что при сильном ветре с залива море забрасывает солёные брызги далеко вглубь суши. Как и на других болотах, здесь гнездятся ящеры, и их следы видны на мокрой земле повсюду.",
        ["Закатное болото"] = "Закатное болото — самая глубокая часть Болотины на северо-западе. Посреди топи стоит небольшой каменный дом с ветряной мельницей, где живут гном и дворфийка, торгующие странными находками из болота и редкими рецептами. Вокруг же на все стороны тянется трясина, полная кроколисков, гноллов, ящеров, болотных чудищ и слизнюков, так что неопытные путники сюда не суются.",
        ["Зеленый Пояс"] = "Зелёный Пояс — полоса леса и болот на востоке Болотины, за развилкой на дороге к Дун Модру. Здесь обитает Зелёный Страж, древний хранитель здешних мест, о котором в гавани говорят с опаской: он рыщет по болотам вместе с кроколисками и прочими тварями. Страж печётся о природе края и с неприязнью смотрит на гноллов, вырубающих лес, и на порчу, что поразила его меньших болотных сородичей.",
        ["Лагерь Злого Клыка"] = "Лагерь Злого Клыка в сердце Болотины — крупнейшая стоянка орков клана Драконьей Пасти в этом краю. Когда красные драконы вырвались из рабства и разорили Грим Батол, уцелевшие орки бежали в горы и болота, и с тех пор их отряды бесчинствуют по всей Болотине. Отсюда они уходят к Дун Альгазу и к дорогам вокруг гавани, а в лагере за частоколом горят костры и стоят шатры воинов и шаманов.",
        ["Грим Батол"] = "Грим Батол — горная крепость на востоке Болотины, некогда возведённая дворфами. В Войну Трёх Молотов она была проклята и покинута, а во Вторую войну её заняли орки клана Драконьей Пасти, державшие здесь в плену саму Королеву драконов. Когда драконы вырвались на свободу, они разорили лагеря орков, а после сами запечатали крепость. Теперь к её огромным закрытым вратам ведёт лишь горная дорога, и красные драконы не пускают внутрь никого.",
        ["Врата Драконьей Пасти"] = "Врата Драконьей Пасти — подступы к Грим Батолу на юго-востоке Болотины. У подножия горной дороги орки клана Драконьей Пасти держат укреплённую стоянку, откуда мечтают вернуть утраченную крепость, но выше по склону путь стерегут красные драконы и их отродья, не пропускающие никого к запечатанным вратам. Это самое опасное место в Болотине, и дозорные из гавани советуют обходить его стороной.",
        ["Погибший Флот"] = "На северном берегу Болотины, у Болот Синежабрых, лежат остовы Третьей флотилии Кул-Тираса — Погибший Флот. Корабли вышли из Лордерона во время Второй войны и были сожжены и потоплены красными драконами, которых тогда держали в рабстве орки Драконьей Пасти. Экипажи не нашли покоя: по разбитым палубам бродят призраки и скелеты моряков, а в трюме одного из судов, говорят, до сих пор спрятан проклятый груз. Немногие отваживаются подниматься на эти обломки.",
        ["Крепость Менетил"] = "Крепость Менетил возвышается над Гаванью Менетилов, и её четыре башни, словно суровые стражи, смотрят на город и бухту. Здесь размещён гарнизон Альянса, отсюда отдают приказы о защите дорог и порта, и сюда докладывают о вылазках орков Драконьей Пасти и о делах у Дун Модра. В залах крепости можно встретить офицеров и посыльных, а в её подвалах хранятся припасы порта.",
        ["Таверна \"Большая вода\""] = "Таверна «Большая вода» — сердце Гавани Менетилов. У её очага сходятся моряки, ждущие корабля, солдаты гарнизона и путники, только что сошедшие с трапа. Здесь можно снять комнату, выучить основы врачевания и услышать последние слухи со всей Болотины, а то и угодить в драку, которые в этом заведении не редкость.",
        ["Великое море"] = "Великое море простирается на запад от берегов Болотины и отделяет Восточные королевства от Калимдора. По его водам из Гавани Менетилов уходят корабли в Аубердин и Терамор. У побережья на дне покоятся суда, потопленные в былые войны, а над волнами кружат чайки и стелется вечный туман.",
        ["Зловещее море"] = "Зловещее море — открытые холодные воды вдали от берегов Болотины, куда редко заходят корабли из гавани. Здесь нет ни причалов, ни маяков, лишь волны и туман, и заплывшему сюда лучше повернуть назад, пока берег ещё виден.",
        ["Убежище Драконьей Пасти"] = "Убежище Драконьей Пасти — укромная стоянка орков клана Драконьей Пасти, спрятанная в стороне от больших дорог Болотины. Сюда уходят отряды, разбитые у гавани и на перевалах, чтобы зализать раны и собраться с силами. Дым костров над скалами выдаёт их лишь тому, кто знает, куда смотреть.",
        ["Раскопки: Болотина"] = "Небольшой раскоп в топях Болотины, где искатели древностей копаются в сырой земле. Болотный грунт хранит кости давно вымерших тварей и обломки дворфийской старины, но каждую яму быстро затягивает водой, и работа продвигается медленно.",
        ["Пьяный дворф"] = "«Пьяный дворф» — небольшое дворфийское заведение на юге Болотины, недалеко от дороги к перевалу Дун Альгаз. Здесь гонят и разливают крепкие настойки, и дворфийка за стойкой рада любому гостю, будь он из Стальгорна или из самых дальних краёв. После сырого болота кружка горячительного и сухая крыша кажутся особенно желанными.",
    },
    ["Болото Печали"] = {
        _zone = "Болото Печали лежит на юго-востоке Восточных королевств: с запада его запирает перевал Мёртвого Ветра, на юге начинаются Выжженные земли, а восточный берег омывает Зловещее море. Когда-то это была северная половина огромных Чёрных топей; когда в конце Второй войны рухнул Тёмный портал, юг обратился в пустошь, а север так и остался болотом. Здесь стоячая солоноватая вода, покрытые солью коряги и плакучие деревья, а единственная дорога едва поднимается над трясиной, где охотятся кроколиски и ягуары. В древности сюда бежали тролли Атал'ай, жрецы Хаккара, и воздвигли свой храм, но Изера утопила его в озере Слёз, и с тех пор зелёные драконы стерегут затонувшие руины. Орки Старой Орды заложили здесь Каменор ещё в Первую войну, а при Тралле отстроили заново – это единственный город на всём болоте. По окраинам ютятся Заблудшие, которых путь через портал лишил разума, и лишь горстка изгнанников в Убежище ещё помнит, кем они были.",
        ["Озеро Слез"] = "Озеро Слёз – большое озеро на востоке Болота Печали, со всех сторон обступленное топью. Больше тысячи лет назад изгнанные из Зул'Гуруба жрецы Атал'ай воздвигли здесь Храм Атал'Хаккара, готовя возвращение Свежевателя Душ, но Изера обрушила храм в глубину, и теперь над водой видны лишь его верхние ярусы. Вокруг несут стражу зелёные драконы и дракониды, не пуская никого ни внутрь, ни наружу. По берегам и на дне разбросаны артефакты Атал'ай, по которым чернокнижник Фел'зерул из Каменора пытается понять, что здесь произошло.",
        ["Каменор"] = "Каменор – орочий форпост и единственный город на Болоте Печали. Его заложила Старая Орда в Первую войну, вскоре после открытия Тёмного портала, и это одно из старейших поселений орков на Азероте. При Тралле Каменор отстроили заново: здесь стоят большой зал и две землянки, а вокруг ходят патрули каменорских рубак. Отсюда летают в Гром'гол, Пиратскую Бухту и Каргат; мастер-алхимик Рогвар обучает своему ремеслу, Хелгрум Быстроногий ждёт донесений из Бесплодных земель, а чернокнижник Фел'зерул по поручению вождя изучает тайны затонувшего храма.",
        ["Болотное пристанище"] = "Болотное пристанище – деревня Заблудших на севере Болота Печали, в виду гор Красногорья. Здесь живут те, кого путь через Тёмный портал и тоска по утраченной родине довели до безумия: они одичали и нападают на всякого, кто подойдёт к их хижинам и кострам. Заблудшие грабят караваны на дороге и воруют у своих бывших братьев из Убежища священные для тех кристаллы. В клетке посреди селения томится пленник – человек по имени Гален Добростраж, отчаянно ждущий, что кто-нибудь выведет его отсюда.",
        ["Туманная долина"] = "Туманная долина – узкая долина в северо-западном углу болота, к северу от входа на перевал Мёртвого Ветра. Здесь нет ни дорог, ни жилья: среди тумана бродят тиноброды и их старейшины, а из вязкой земли поднимаются перевитые ужасы. В глубине долины, в пещере, обитает Хозяин болота – древнее создание, к которому редко кто решается спуститься.",
        ["Тростниковый берег"] = "Тростниковый берег – унылая полоса побережья, тянущаяся вдоль всего восточного края болота. На песке лишь плавник, обломки и следы прилива; в прибое роются иловые и чудовищные крабы, у воды греются кроколиски. Берег и прибрежные пещеры держат мурлоки Болотного племени, и орки с Тростниковой заставы то и дело посылают охотников проредить их ряды. Здесь же собирают плавник те, кому нужно чинить повозку, чтобы выбраться с болота.",
        ["Убежище"] = "Убежище – маленькое поселение на севере болота, к западу от Болотного пристанища. Здесь живёт горстка Заблудших, сохранивших рассудок, – изгнанники, которых ведёт Магтур. Они называют себя дренеями и помнят, кем были до перехода через Тёмный портал; их обезумевшие сородичи из Болотного пристанища стали для них врагами и грабителями. Больше всего изгнанники дорожат дренетистовыми кристаллами: без них, говорят они, и сами могут сбиться с пути. Убежище держится в стороне от войны Орды и Альянса.",
        ["Пещера Итара"] = "Пещера Итара – уединённый грот в самом юго-западном углу болота. Здесь под личиной высшего эльфа живёт Итар, зелёный дракон, брат Эраникуса, супруга Изеры. Вокруг пещеры резвятся зелёные дракончики, за которыми Итар присматривает, пока они не подрастут. Он пришёл сюда ради затонувшего храма: драконов, стерёгших его, поглотил кошмар, и Итар ищет способ освободить своих сородичей от скверны.",
        ["Горемрак"] = "Горемрак – глухая часть болота к востоку от озера Слёз и затонувшего храма. Земля здесь принадлежит зелёным драконидам: они несут стражу вдоль берегов, а над топью кружит зелёный дракон, и путников тут не ждут. Даже опытные охотники обходят Горемрак стороной – сюда идут лишь те, кто готов встретить драконью стражу лицом к лицу.",
        ["Деревня Дренил'дур"] = "Дренил'дур – старое название одного из поселений Заблудших на севере болота. Здесь такие же хижины из прутьев и дымящие костры, как в Болотном пристанище, и такие же настороженные взгляды: чужаков в этих краях не ждут.",
        ["Развилка Расщепленного Копья"] = "Развилка Расщеплённого Копья – место, где единственная дорога через Болото Печали расходится надвое. Северная ветка ведёт мимо Убежища к Болотному пристанищу, южная – к Каменору и дальше, к перевалу в Выжженные земли. У развилки стоит старая орочья сторожевая башня, а по дороге ходят патрули каменорских рубак, так что путникам Альянса здесь стоит быть настороже.",
        ["Вязкая топь"] = "Вязкая топь – густые болота на юго-востоке, к югу от озера Слёз, у подножия южных гор. Это самая непроходимая часть болота: ни дорог, ни жилья, только вода по колено, коряги и туман. В зарослях охотятся острозубые кроколиски и пантеры Тени, а у края гор чернеет вход в пещеру, которую заняли мурлоки.",
        ["Ползучая трясина"] = "Ползучая трясина – сердце Болота Печали, широкая топь между развилкой дорог и озером Слёз. Грязь здесь и впрямь будто ползёт под ногами, и с дороги лучше не сходить. В трясине водятся молодые острозубые кроколиски, болотные ягуары и ткачи скорби, а между кочками бродят шайки Заблудших: их вожак Нобору Дубина месяцами наводил страх на изгнанников из Убежища. Недалеко от дороги разбил лагерь дозорный Биггс – единственный уцелевший из каравана, разграбленного Заблудшими.",
        ["Пещера у Вязкой топи"] = "Пещера у Вязкой топи – большая пещера у края гор на востоке болота. Её заняли мурлоки Болотного племени: внутри сыро, пахнет тиной и рыбой, а в глубине сидит их вожак – Болотный говорун. Орки с Тростниковой заставы считают этих мурлоков угрозой и рады любому, кто согласится пройтись по пещере с оружием.",
        ["Тростниковая застава"] = "Тростниковая застава – маленький орочий пост Каменора между Вязкой топью и южной частью Тростникового берега. Здесь нет ни стен, ни башни – только костёр, бочонок медовухи и горстка каменорских охотников с шаманом под началом Ток'Кара; рядом с ним держится и Катор. Ток'Кар мечтает, что однажды здесь поставят хоть землянку, а пока отсюда посылают охотников на мурлоков побережья. Гриф сюда не летает: добираться придётся пешком через трясину.",
        ["Зловещее море"] = "Зловещее море омывает восточный берег Болота Печали и всё восточное побережье королевств. Это неизведанные, не нанесённые на карты воды: ни один корабль не уходил далеко на восток, чтобы вернуться с рассказом о том, что там. Для путника здесь кончается земля – дальше только серые волны и туман.",
    },
    ["Внутренние земли"] = {
        _zone = "Внутренние земли — лесистый горный край на востоке Лордерона, между нагорьем Арати и Чумными землями, обрывающийся на востоке в Зловещее море. Когда-то здесь билось сердце империи Амани, и руины троллей до сих пор стоят среди сосен и папоротников. После войны Трёх Кланов сюда пришли дворфы клана Громового Молота: они построили Заоблачный Пик над землёй и приручили местных грифонов. Лесные тролли считают дворфов захватчиками: племя Порочной Ветви держит древний Джинта'Алор и Алтарь Зула, Сухокожие живут у храмов Шадра'Алора, а малое племя Сломанного Клыка, вставшее на сторону Орды, укрылось в деревне на побережье. На западе, в сторожке Кель'Данил, держатся высшие эльфы, а на севере растёт великое древо Серадан с порталом в Изумрудный Сон. В лесах между ними бродят волки, медведи и совухи, и путник здесь редко остаётся один надолго.",
        ["Отвесные скалы"] = "Отвесные скалы — восточный край Внутренних земель, где горы резко обрываются к морскому берегу. Большая река, что пересекает весь край, здесь срывается с обрыва огромным водопадом. Высоту этих скал многие путники недооценивали, и не всякий спуск заканчивался благополучно. На узкой полосе песка внизу греются морские кусачие черепахи, доставляющие немало хлопот рыбакам из деревни Сломанного Клыка, а за прибоем начинается Зловещее море.",
        ["Заоблачный Пик"] = "Заоблачный Пик — столица дворфов клана Громового Молота, вырубленная в горе на северо-западе Внутренних земель. После войны Трёх Кланов и потери Грим Батола клан осел здесь, отказавшись от жизни под землёй: слишком памятны были подземные битвы с дворфами Чёрного Железа. Здесь Громовые Молоты сблизились с природой и приручили могучих грифонов, а в знак этой связи высекли над входом исполинскую статую грифона. Во Вторую войну всадники на грифонах под началом тана Курдрана громили Орду с небес, и с тех пор отсюда поднимаются в небо лучшие грифоны Азерота. Тролли не оставляют попыток напасть на гнездовья, и дозор на Пике не смыкает глаз.",
        ["Крепость Громового Молота"] = "Крепость Громового Молота — главный зал Заоблачного Пика, высеченный в толще горы. Здесь правит верховный тан Фалстад Громовой Молот, принявший клан после того, как Курдран ушёл с экспедицией Альянса в Дренор. В крепости есть постоялый двор и наковальня, но горна нет: Громовые Молоты живут ближе к небу, чем к кузнице. У очага дворфы охотно рассказывают о грифонах и о старых войнах с троллями.",
        ["Сторожка Кель'Данил"] = "Сторожка Кель'Данил на западе Внутренних земель — одно из последних поселений высших эльфов в Лордероне. Отсюда послы высших эльфов сносились с другими народами Альянса и делились тем, что знали о троллях Сухокожих, живущих южнее. Со временем эльфы заключили союз с дворфами Громового Молота и навлекли на себя ненависть общих врагов, а Орда не раз посылала сюда своих лазутчиков. Среди деревянных построек на склоне по-прежнему стоят на страже следопыты и магистры.",
        ["Осклизлая скала"] = "Осклизлая скала — руины лесных троллей на востоке Внутренних земель, ныне кишащие слизнями. Во Вторую войну здесь стояла база старой Орды, пока Альянс Лордерона и дворфы Громового Молота не выбили орков и их союзников-троллей из этих мест. Орки ушли в спешке и бросили здесь ящики с местным медовым напитком, о котором до сих пор помнят любители выпить. В пещере под скалой растут редкие призрачные грибы, а на её склонах пузырится и ползёт всё, что осталось от прежних хозяев.",
        ["Зун'вата"] = "Зун'вата — небольшие руины лесных троллей на западе Внутренних земель, недалеко от дороги к Заоблачному Пику. Среди замшелых камней и разбитых идолов империи Амани обитают тролли племени Сухокожих. Отсюда ближе всего до гнездовий дворфов, и Громовые Молоты давно держат это место под присмотром.",
        ["Шадра'Алор"] = "Шадра'Алор — главное поселение троллей племени Сухокожих на юго-западе Внутренних земель. Три ступенчатых храма стоят вокруг озера, и всё здесь посвящено Шадре, богине-паучихе, чьё имя носит город. Тролли разводят у алтарей её выводок, а знахари, как говорят, умеют по имени призвать её дитя, Элорту но Шадру, и одно это имя приводит духов в смятение. Сухокожие слабее Порочной Ветви, но чужаков у своих храмов не терпят, и меж колонн здесь караулят охотники за головами и ворожеи.",
        ["Джинта'Алор"] = "Джинта'Алор — огромный город лесных троллей на юго-востоке Внутренних земель, второй по величине после Зул'Амана. Его построили тролли империи Амани и назвали в честь Джинты, древнего вождя, а ныне им владеет племя Порочной Ветви. Террасы и лестницы поднимаются к вершине, где стоит алтарь, и на нём жрецы приносят жертвы кровавому богу Хаккару. Порочная Ветвь охотится на слабых соседей из племени Сломанного Клыка, а однажды сюда затащили даже похищенного у дворфов грифона Остроклюва. В городе полно воинов, ворожей, пауков и слизи, и пройти его в одиночку почти невозможно.",
        ["Алтарь Зула"] = "Алтарь Зула — ступенчатая пирамида племени Порочной Ветви к югу от Джинта'Алора. На её вершине тролли совершают жертвоприношения, а верховный хранитель стережёт священный молот, которым, если верить старым записям, можно пробудить силу алтаря в Джинта'Алоре и выковать молот Зул'Фаррака. Название алтаря, как считают, восходит к Зулу, пророку троллей. У подножия пирамиды бродят охотники и ворожеи, и здесь, как и в Джинта'Алоре, нет пощады никому из чужаков.",
        ["Серадан"] = "Серадан — священная роща на северо-востоке Внутренних земель, посреди которой растёт великое древо. В его корнях открыт круглый портал в Изумрудный Сон — один из четырёх на всём Азероте, наряду с порталами Ясеневого леса, Сумеречного леса и Фераласа. Рощу оберегает зелёный род драконов: по тропам ходят дозоры драконоподобных стражей и оракулов, а в кронах отдыхают зелёные драконы. Изредка из портала выходят и куда более древние и могучие создания Сна, и тогда даже бывалые путники предпочитают обойти Серадан стороной.",
        ["Домик Пероборода"] = "Домик Пероборода — одинокая хижина дворфа из клана Громового Молота у дороги неподалёку от Заоблачного Пика. Она стоит на самом краю леса, где лесные тролли уже чувствуют себя как дома, и хозяин её бывает здесь не всегда. Внутри тесно, пахнет дымом и перьями грифонов.",
        ["Лагерь Выпивохи"] = "Лагерь Выпивохи — стоянка на холмах к северу от Заоблачного Пика, где у костра осел дворф по прозвищу Выпивоха. Он ищет ингредиенты для крепкого коктейля, за которыми посылает всякого проходящего мимо: от фиолетовых грибов с озера Доблести до редких ядов. Компанию ему составляет высший эльф, охотно делящийся местным медовым напитком, и с ним, как говорят, лучше иметь дело, когда он уже выпил.",
        ["Чумная лощина"] = "Чумная лощина — узкий проход в горах на западе Внутренних земель, к северо-западу от сторожки Кель'Данил. По нему можно выйти на север, к Кэр Дарроу и в Западные Чумные земли. Над тропой висит ядовитый туман, тянущийся из-за перевала, и он резко отличается от свежести остальных лесов. В лощине не живёт никто, и это, пожалуй, самое верное предупреждение для путника.",
        ["Озеро Доблести"] = "Озеро Доблести — небольшое тихое озеро к северо-востоку от Шадра'Алора, в стороне от дорог. По его берегам растёт редкий фиолетовый гриб, за которым сюда приходят не только звери, но и охотники за диковинными ингредиентами. Вокруг бродят волки и совухи, а до троллей Сухокожих отсюда рукой подать.",
        ["Агол'вата"] = "Агол'вата — руины лесных троллей в северной части Внутренних земель, некогда храм поздней империи Амани. Ныне древние камни заполонили зелёная слизь и нефритовые слизнюки, и между разрушенными стенами не слышно ничего, кроме их чавканья. Эта тишина обманчива: с востока к руинам подступают земли Порочной Ветви.",
        ["Хири'вата"] = "Хири'вата — деревня троллей племени Сухокожих на западе Внутренних земель, к югу от сторожки Кель'Данил. Среди старых руин Амани стоят хижины, горят костры и висят тотемы: Сухокожие живут здесь, как их предки, а до эльфийской сторожки и дворфийских дорог отсюда рукой подать. Меж хижин ходят охотники, ворожеи и берсерки, и пришельцу лучше не задерживаться на виду.",
        ["Ползучие руины"] = "Ползучие руины — остатки древнего поселения троллей у реки в центральной части Внутренних земель. Своё имя они получили не зря: по замшелым камням ползёт живая слизь, поглотившая всё, что осталось от прежних жителей. Здесь почти нет троллей, но нефритовые слизнюки и зелёная слизь опасны не меньше.",
        ["Грот Богена"] = "Грот Богена — небольшая пещера в скалах на юго-западе Внутренних земель, к югу от дороги на Заоблачный Пик. Внутри сыро и темно, а вход прикрывают заросли, так что найти его непросто. В окрестностях бродят волки и медведи, а с юга к гроту подступают земли троллей Сухокожих.",
        ["Шаол'вата"] = "Шаол'вата — руины лесных троллей на северо-востоке Внутренних земель, некогда храм империи Амани. Ныне здесь обосновались тролли племени Порочной Ветви: воины и ворожеи стерегут разрушенные постройки на берегу реки, недалеко от рощи Серадан. До деревни Сломанного Клыка отсюда недалеко, и дозоры на обеих сторонах не смыкают глаз.",
        ["Зловещее море"] = "Зловещее море омывает восточный берег Внутренних земель, у подножия Отвесных скал. Это неизведанные воды, которые редко пересекают корабли, и на картах за ними не значится ничего. Лишь рыбаки из деревни Сломанного Клыка выходят в прибрежные волны, да морские черепахи греются на песке.",
        ["Деревня Сломанного Клыка"] = "Деревня Сломанного Клыка — единственное поселение троллей племени Сломанного Клыка, портовая деревня на восточном берегу Внутренних земель. После поражения старой Орды во Вторую войну это малочисленное племя не отреклось от прежних союзников, за что другие лесные тролли объявили их предателями. Столетия скитаний закончились, когда посланцы новой Орды Тралла отыскали племя: тролли заключили с орками договор о дружбе и с их помощью построили свою первую деревню. Порочная Ветвь и сейчас совершает набеги на берег, а рыбакам мешают морские кусачие черепахи.",
        ["Озеро Мерельдар"] = "Озеро Мерельдар — большое озеро на юге Восточных Чумных земель, к югу от Перекрёстка Корина. Вода здесь давно отравлена чумой, и над гладью поднимаются осквернённые водные элементали. На берегу стоят развалины старого дома, паром и рыбацкая хибара — всё, что осталось от прежнего хозяйства.",
        ["Крипта"] = "Крипта — старое захоронение на юго-западе Восточных Чумных земель. Здесь обосновалась шайка нежити-троллей под началом дикого тролля-изгоя, и они время от времени совершают вылазки к Часовне Последней Надежды за телами из могильника Серебряного Рассвета. Здесь же стоит и могила, которую многие считают могилой паладина Тириона Фордринга, хотя сам он ещё жив.",
        ["Лагерь Алого ордена"] = "Лагерь Алого ордена — небольшое укрепление с баррикадами на восточном берегу озера Мерельдар, неподалёку от Длани Тира. Здесь стоят солдаты и инквизиторы Алого ордена, охраняющие подступы к своей крепости. Орден не делает различий между нежитью и живыми чужаками, так что путнику стоит обходить лагерь стороной.",
        ["Дарроушир"] = "Дарроушир — деревня на юге Восточных Чумных земель, разрушенная в Третью войну. Плеть под началом повелителя вурдалаков и рыцаря смерти обрушилась на неё, и защитники, поначалу державшиеся стойко, были перебиты до последнего. Ныне Дарроушир молчит: здесь остались лишь руины, призраки и память. Павшие защитники бродят по Чумным землям вурдалаками на службе Плети, их души заперты в гниющих телах, и лишь изредка над развалинами вновь разыгрывается битва за Дарроушир.",
    },
    ["Восточные Чумные земли"] = {
        _zone = "Восточные Чумные земли — самая израненная часть павшего Лордерона. Когда-то здесь стояли богатые сёла и Стратхольм, второй по величине город королевства. Чума нежити пришла сюда с заражённым зерном, принц Артас предал Стратхольм огню вместе с его жителями, и с тех пор город горит и служит Плети столицей в Лордероне, а над Проклятым лесом парит некрополь Наксрамас. Земля побурела, деревья обратились в исполинские грибы, и по дорогам бродят вурдалаки, скелеты и служители Культа Проклятых. С ними воюет Алый орден, засевший в Длани Тира и в западных кварталах Стратхольма, но для чужаков рьяные крестоносцы опасны не меньше нежити. На севере доживают свой век лесные тролли Зул'Машара, а у перевала в Кель'Талас держат сторожку высшие эльфы. Единственное пристанище для путников — часовня Последней Надежды, где Серебряный Рассвет принимает всех, кто готов поднять оружие против Плети.",
        ["Грибная долина"] = "Грибная долина к северу от поместья Маррисов и Башни королевской стражи — одно из самых поражённых чумой мест края. Земля здесь потемнела до лилового, над ней висит мутная дымка, а между исполинскими грибами тянутся тропы Плети. В долине хозяйничают вурдалаки и служители Культа Проклятых, и путнику лучше держаться дороги, не углубляясь в эту мглу.",
        ["Поместье Маррисов"] = "Поместье Маррисов стоит на невысокой гряде у главной дороги, недалеко от границы с Западными Чумными землями. Здесь жила семья следопыта Натаноса, единственного человека, которого эльфы Кель'Таласа приняли в ряды своих следопытов. Когда Плеть захлестнула Лордерон, он погиб у собственного дома и был поднят как безвольный раб Короля-лича. Ныне Натанос вернулся сюда уже Отрекшимся, защитником Тёмной Госпожи, и его двор стерегут чумные псы. Орде он даёт поручения против Плети и Алого ордена, а слухи о нём дошли и до ШРУ в Штормграде.",
        ["Крипта"] = "Крипта — старинный склеп на юго-западе края, южнее Дарроушира. В нём укрылась шайка троллей-нежити, чей предводитель, изгнанный своим племенем, устраивает набеги на часовню Последней Надежды и похищает тела из её погребальной ямы. Здесь же стоит могильный камень с именем Тириона Фордринга, хотя паладин, как говорят, вовсе не умер. А где-то за склепом, по слухам, зарыт сундук тролля по имени Хамейя.",
        ["Дарроушир"] = "Дарроушир на южной окраине края назван в честь озера Дарроумир. Когда Плеть хлынула в Лордерон, деревню защищали её ополченцы под началом капитана Джозефа Редпата и паладины Серебряной Длани во главе с Дейвилом Крокфордом. Вурдалаков лорда Хоргуса удалось остановить, но рыцарь смерти Мардук Чёрный обратил душу Редпата во тьму, и защитники сами перерезали тех, кого укрывали. Ныне Дарроушир — тихие руины, где среди пепла бродят призраки, а девочка Памела всё ещё ждёт своего отца. Говорят, порой над деревней тени вновь разыгрывают ту битву.",
        ["Башня королевской стражи"] = "Башня королевской стражи возвышается над дорогой к востоку от поместья Маррисов. Некогда дозорная башня Лордерона, она была разрушена при нашествии Плети, и от неё остались лишь руины. Теперь за эти развалины, как и за три другие башни края, сражаются Альянс и Орда: тот, кто удержит башню, получает преимущество на всех окрестных землях.",
        ["Перекресток Корина"] = "Перекрёсток Корина лежит в сердце южных равнин, между Чумным оврагом и озером Мерельдар, там, где сходятся дороги на Андорал, Дарроушир, Стратхольм и Длань Тира. Некогда оживлённый городок с ратушей и кузницей теперь до краёв полон нежити: вурдалаки, банши, сшитые из плоти чудовища и наставники Культа Проклятых. Даже тем, кто умеет ходить в тени, здесь не спрятаться — незримые слуги Плети видят всё. Именно близ перекрёстка агенты Серебряного Рассвета когда-то подобрали израненного Карлина Редпата.",
        ["Лагерь Алого ордена"] = "Лагерь Алого ордена — небольшое укрепление за частоколом на восточном берегу озера Мерельдар, невдалеке от Длани Тира. Отсюда крестоносцы выходят в дозоры по южным дорогам и встречают гонцов, что идут в Стратхольм и обратно. Путнику стоит помнить: для Алых любой чужак — возможный разносчик чумы.",
        ["Длань Тира"] = "Длань Тира на юго-востоке края — укреплённый город, названный в честь легендарного Тира. Это одно из древнейших святых мест Церкви Света, «город церквей», с Алой Базиликой и аббатством. Когда Лордерон пал, Длань Тира выстояла под почти ежедневными атаками нежити и стала главной твердыней Алого ордена в Чумных землях: отсюда в Стратхольм идут обозы и подкрепления, а гонцы под усиленной охраной везут донесения. Здесь же пребывает Алый Оракул, прорицательница ордена. Чужаков за этими стенами не ждут.",
        ["Алая Базилика"] = "Алая Базилика — огромный собор в сердце Длани Тира, выстроенный по образу Собора Света в Штормграде. Это высшее седалище духовной власти Алого ордена, тесно связанное с аббатством Длани Тира и далёким Монастырём Алого ордена в Тирисфале. Под его сводами восседает лорд-крестоносец, правящий городом, и здесь орден вершит свои обряды и суды.",
        ["Часовня Последней Надежды"] = "Часовня Последней Надежды на восточных склонах края — одно из древнейших святилищ Церкви Света. После падения Лордерона сюда, в освящённую землю, тайно перенесли останки тысячи героев Света, чтобы Король-лич не поднял их в свою армию. Паладины, отвергнувшие фанатизм Алого ордена, основали Серебряный Рассвет и сделали часовню своим оплотом под началом лорда Максвелла. Здесь принимают всех — людей и эльфов, орков и Отрекшихся, — лишь бы они готовы были сражаться с Плетью. Это последний огонёк Света в краю, укрытом тьмой.",
        ["Мельница Бровача"] = "Мельница Бровача стоит к северу от часовни Последней Надежды. Когда-то здесь пилили лес, но чума добралась и сюда: хозяин мельницы погиб, был поднят вурдалаком и теперь сторожит собственные владения. Среди сараев бродят скелеты, банши и сшитые из плоти поганища.",
        ["Ядовитая поляна"] = "Ядовитая поляна прячется на холме к северу от часовни Последней Надежды. Даже по меркам Чумных земель это гиблое место: воздух здесь густой, тошнотворно-зелёный, а земля темна, как запёкшаяся кровь. Плеть возвела на поляне свои зиккураты, и в мгле копошатся её твари.",
        ["Восточная башня"] = "Восточная башня стоит у дороги между озером Чернолесья и Моровым оврагом, на пути к Северному Долу. Её, как и остальные дозорные башни, разрушила Плеть при вторжении в Лордерон. Теперь Альянс и Орда сражаются за её руины: власть над башней даёт войскам преимущество по всему краю.",
        ["Северный Дол"] = "Северный Дол — разрушенный городок к северу от часовни Последней Надежды, на пути к перевалу в Кель'Талас. Живых здесь давно нет: по руинам скользят банши и незримые безглазые соглядатаи Плети, а воду соседнего озера отравили и населили порчёные элементали. Говорят, именно здесь сын Тириона Фордринга отрёкся от Серебряной Длани и ушёл к Алому ордену.",
        ["Зул'Машар"] = "Зул'Машар на северо-востоке края — древняя столица лесных троллей, некогда отделившихся от империи Амани. Долгие войны с людьми Лордерона отняли у них большую часть земель, а чума довершила разгром: почти все тролли за пределами города обратились в нежить. Ныне Зул'Машар — тень былого величия, и его обитатели с тревогой видят, как порча тайно подтачивает их собственных сородичей. В сердце города высится зиккурат Мазра'Алор.",
        ["Мазра'Алор"] = "Мазра'Алор — большой зиккурат в сердце Зул'Машара, святилище лесных троллей. На его ступенях несут стражу охотники за духами, и чужаков здесь встречают копьями. Тролли говорят с лоа и чтят старые обряды даже теперь, когда чума подступает к самым стенам.",
        ["Башня Северного перевала"] = "Башня Северного перевала — самая северная из дозорных башен края, у дороги, что ведёт к перевалу в Кель'Талас. Плеть разрушила её при вторжении, и от башни остались руины. Теперь Альянс и Орда оспаривают их друг у друга: тот, кто удержит башню, получает преимущество на землях вокруг.",
        ["Сторожка Кель'Литиен"] = "Сторожка Кель'Литиен у самого входа в Кель'Талас — охотничий приют высших эльфов, одна из двух крупных общин их народа в Лордероне. Некогда следопыты радушно принимали здесь гостей из Луносвета и хранили в стенах сторожки эльфийские летописи. После нашествия Плети сторожка осталась отрезанной от родины, и её обитатели ожесточились: они не доверяют никому и встречают чужаков стрелами. С владыкой следопытов, что правит сторожкой, есть свои счёты и у Натаноса из поместья Маррисов.",
        ["Проклятый лес"] = "Проклятый лес тянется от стен Стратхольма на юг и запад до самой Долины Ужаса. Некогда эти рощи сравнивали с Элвиннским лесом; чума превратила землю в бурую губку, а грибы выросли до размеров деревьев и выдыхают клубы чёрного газа. Лес густо занят Плетью: здесь стоят её зиккураты и бойни, а над кронами парит некрополь Наксрамас, врата к которому стережёт Серебряный Рассвет. По дороге к Стратхольму ходят и дозоры Алого ордена, что рубят живых и мёртвых без разбора.",
        ["Стратхольм"] = "Стратхольм — некогда северная жемчужина Лордерона, второй по величине город королевства и место, где архиепископ Алонсус Фаол основал орден Серебряной Длани. Заражённое зерно из Андорала принесло в город чуму, и принц Артас, отвергнув Утера, вырезал жителей и предал Стратхольм огню. Город горит по сей день. Восточную его половину держит Плеть во главе с бароном Ривендером, рыцарем смерти на гнилой кобыле; западные кварталы заняли крестоносцы Алого ордена под командой Верховного рыцаря Датрохана. Говорят, впрочем, что под его личиной скрывается повелитель ужаса, и обе стороны ведут в руинах бесконечную резню.",
        ["Озеро Дарроумир"] = "Озеро Дарроумир, одно из крупнейших в Восточных королевствах, лежит у юго-западной границы края. За его водами, уже в Западных Чумных землях, виден остров Каэр Дарроу с башнями рода Баровых, под которыми скрыт Некроситет. В годы Второй войны на озере гремели морские сражения, а теперь его воды отравлены Плетью, и к берегу выносит мёртвую рыбу.",
        ["Река Тондрорил"] = "Река Тондрорил служит естественной границей между Западными и Восточными Чумными землями. Она начинается в закрытых северных горах, у выхода из Туннеля Ужаса, и впадает в озеро Дарроумир на юге. По её берегам ползают личинки, кружат летучие мыши и бродят чумные медведи. У разрушенной фермы на восточном берегу нашёл приют Тирион Фордринг, некогда лорд Марденхольдский, лишённый ордена и изгнанный из Альянса.",
        ["Озеро Мерельдар"] = "Озеро Мерельдар раскинулось к югу от Перекрёстка Корина. Его воды давно отравлены, и в них поднимаются порчёные элементали. На берегу стоят развалины старого дома, а рядом — хижина и паром, когда-то принадлежавшие здешней ферме.",
        ["Моровой овраг"] = "Моровой овраг — глубокое ущелье в отравленной земле к западу от часовни Последней Надежды. Похоже, некогда здесь было озеро, высохшее, когда пришла чума. По дну расселины ползают слизни, и путники обходят её по краю.",
        ["Чумной овраг"] = "Чумной овраг тянется к западу от Перекрёстка Корина. В отличие от Морового оврага, эта расселина — не творение природы, а след тёмной магии: когда рунный клинок рыцаря смерти Мардука Чёрного сломался о щит дворфийского капитана в бою у перекрёстка, обломок лезвия ушёл в землю и разверз её. Рукоять Мардук забрал с собой, а расселина осталась.",
        ["Озеро Чернолесья"] = "Озеро Чернолесья лежит в центре края, к северу от Чумного оврага. Его воды загрязнены чумой, и в них ходят порчёные элементали. Когда-то на берегу стоял городок Чернолесье, а в Анналах Дарроушира сказано, что именно в этом озере паладины утопили отрубленную голову Хоргуса Опустошителя.",
        ["Восточные ворота"] = "Восточные ворота — боковой вход в Стратхольм с северо-востока Чумных земель. За ними лежит площадь Старейшин и часовня, где ещё держится горстка живых. Ворота заперты, и открыть их можно лишь ключом от города или искусной отмычкой; изнутри же их отворяет рычаг.",
        ["Туннель Ужаса"] = "Туннель Ужаса — длинный извилистый ход сквозь гору на северо-западе края, от Долины Ужаса до берега реки Тондрорил. Его населили нерубы, могильные твари Плети, и время от времени по туннелю проходит их могучий надсмотрщик. У выхода к реке живёт отшельник Тирион Фордринг.",
        ["Долина Ужаса"] = "Долина Ужаса — городок в северо-западном углу края, на краю Проклятого леса. Живых здесь почти не осталось: по улицам бродят вурдалаки-людоеды, чумные кабаны и раздутые големы, а над обгорелыми домами витают беспокойные духи. Лишь безумный торговец, что зовёт Долину «жемчужиной Лордерона», да дворф-изобретатель, поклявшийся освобождать души нежити, всё ещё живут здесь. К северу зияет вход в Туннель Ужаса.",
        ["Новый Авалон"] = "Новый Авалон — поселение Алого ордена на побережье к востоку от Длани Тира, у самого Зловещего моря. У крестоносцев здесь свои сады, кузница и ратуша; орден живёт тут замкнутым миром, куда чужакам хода нет.",
        ["Зловещее море"] = "Зловещее море омывает восточный берег Лордерона за Дланью Тира. Это неизведанные, не нанесённые на карты воды; по преданию, во Вторую войну Орда держала крепость на острове в устье залива Тира, чтобы перерезать пути снабжения в Кель'Талас. Ныне только ветер с моря приносит в отравленный край глоток свежего воздуха.",
    },
    ["Выжженные земли"] = {
        _zone = "Выжженные земли — мёртвая красная пустыня на самом юге Восточных королевств. Когда-то здесь была глухая топь, но магия Тёмного портала, через который на Азерот хлынула Орда, навсегда искалечила эту землю: почва спеклась в багровую глину, вода ушла, и лишь василиски, скорпионы и гиены живут среди раскалённых скал. После Второй войны врата были разрушены, и по настоянию архимага Кадгара на единственной дороге сюда поднялась Крепость Стражей Пустоты, чтобы никто больше не пришёл из Дренора. Двадцать лет Портал молчит, но покоя здесь нет: на западе, в Гниющем Шраме, засели демоны Пылающего Легиона во главе с Владыкой Каззаком, а по пустыне бродят огры клана Молота Ужаса. Днём здесь сухо и жарко, ночью — пронизывающе холодно, и лишь молнии да ветер тревожат тишину. Путнику здесь никто не рад, даже суровые маги Стражей Пустоты.",
        ["Темный портал"] = "В юго-восточном углу пустыни стоит Тёмный портал — врата между Азеротом и Дренором, родиной орков. Их открыли объединёнными усилиями Медив и чернокнижники Совета Теней во главе с Гул'даном, и именно отсюда началась Первая война. В конце Второй войны Кадгар и маги Кирин-Тора разрушили врата, а остатки Орды бежали сквозь них в свой гибнущий мир. С тех пор колоссальная арка стоит безмолвной и тёмной, но разведчики доносят, что подступы к ней стерегут демоны, и мало кто верит, что путь между мирами закрыт навсегда. Стражи Пустоты не спускают с Портала глаз.",
        ["Гниющий шрам"] = "Гниющий Шрам — низина на западе Выжженных земель, глубже всего отравленная энергиями Тёмного портала. Земля здесь цвета крови, воздух пропитан Скверной, а над дымящимися кратерами стелется ядовитая мгла. После Третьей войны сюда отступили уцелевшие силы Пылающего Легиона, и ныне Шрамом правит Владыка Каззак, могучий демон, окружённый своей чудовищной свитой. Лишь отряды самых отчаянных героев решаются войти сюда, и немногие возвращаются, чтобы рассказать об увиденном.",
        ["Форт Молота Ужаса"] = "На северо-западе пустыни, у подножия гор, стоит Форт Молота Ужаса — крепость, некогда заложенная орками как одно из первых их поселений на Азероте. После войн её захватили огры клана Молота Ужаса: они пришли сквозь Тёмный портал вместе с Ордой, но, в отличие от орков, так и остались в Выжженных землях. Отсюда огры и их маги совершают набеги на Крепость Стражей Пустоты, а в обгоревших орочьих строениях гремят их грубые пиры. Чужаку здесь не рады.",
        ["Крепость Стражей Пустоты"] = "Крепость Стражей Пустоты возвышается на утёсе у единственной дороги, ведущей в Выжженные земли. Её построили после Второй войны по настоянию архимага Кадгара, чтобы никто больше не пришёл из Дренора сквозь разрушенный Тёмный портал, а гарнизон составили маги Кирин-Тора. С тех пор здесь изучают, как энергии Портала искалечили эту землю, отбивают набеги огров и не спускают глаз с демонов на юге. После гибели Даларана крепость держится лишь на поддержке Штормграда и караванах с припасами. Суровые и неразговорчивые, Стражи Пустоты — единственные, кто здесь примет путника из Альянса. Хоть и без особого радушия.",
        ["Змеиные Кольца"] = "Змеиные Кольца — извилистая пещера на востоке пустыни, у обгоревших остовов орочьих построек, оставшихся со времён Второй войны. В её петляющих ходах свили гнездо чернокнижники из Приверженцев Тени, служащие демонам Выжженных земель. Здесь творят тёмные ритуалы, и здесь же, по слухам, укрывается один из трёх могущественных слуг Разелиха Осквернителя, чья жизнь связана с осколком демонического амулета. Тьма пещеры ревниво хранит свои тайны.",
        ["Алтарь Бурь"] = "На западном краю Выжженных земель стоит Алтарь Бурь — мрачное святилище, какие возводили в дни Второй войны, чтобы превращать бездумных великанов в огров-магов. Этот алтарь построила одна из слуг Разелиха Осквернителя, и вокруг него по сей день собираются Приверженцы Тени и их демонические подручные. Сюда же приходят чернокнижники, готовые заплатить кровью и золотом за ритуал призыва коня погибели. Ветер над алтарём пахнет серой.",
        ["Мастерские Гарнизона"] = "Мастерские Гарнизона — рудник неподалёку от Крепости Стражей Пустоты, где шахтёры и инженеры гарнизона добывают руду и камень для крепости. Часть добытого отправляют караванами в Штормград в обмен на припасы, без которых крепости не выстоять. Стук кирок в этих штольнях — едва ли не единственный мирный звук во всех Выжженных землях.",
        ["Утес Осквернителя"] = "Утёс Осквернителя — скалистый кряж посреди пустыни, логово повелителя демонов Выжженных земель. Разелих Осквернитель, самый грозный из подручных Каззака, получил приказ подчинить эту землю и связал клятвой трёх могущественных слуг, отдав каждому по трети своего амулета. Пока осколки остаются в пределах Выжженных земель, ни слуг, ни их хозяина не берёт обычное оружие. На вершине утёса вырезаны руны телепортации, и путь туда открыт лишь тому, кто соберёт амулет воедино. У подножия, среди обгоревших купольных построек, ютятся Заблудшие — дренеи-изгнанники, собирающие дренетист в надежде вернуться домой.",
        ["Гниющий Шрам"] = "Гниющий Шрам — низина на западе Выжженных земель, глубже всего отравленная энергиями Тёмного портала. Земля здесь цвета крови, воздух пропитан Скверной, а над дымящимися кратерами стелется ядовитая мгла. После Третьей войны сюда отступили уцелевшие силы Пылающего Легиона, и ныне Шрамом правит Владыка Каззак, могучий демон, окружённый своей чудовищной свитой. Лишь отряды самых отчаянных героев решаются войти сюда, и немногие возвращаются, чтобы рассказать об увиденном.",
    },
    ["Гора Хиджал"] = {
        _zone = "Гора Хиджал — священная вершина северного Калимдора между Оскверненным лесом и Зимними Ключами. После Великого Раскола Иллидан вылил в горное озеро воду Источника Вечности, а ночные эльфы вырастили над ним Нордрассил, Древо Жизни, благословлённое Алекстразой, Изерой и Ноздорму. Тысячи лет древо дарило калдорай бессмертие. В конце Третьей войны сюда пришёл Архимонд с Пылающим Легионом и Плетью: ночные эльфы, люди Джайны Праудмур и Орда Тралла держали склоны, пока Малфурион не призвал к Древу огоньков. Их жертва испепелила демона у самых корней, но Нордрассил был опалён, а бессмертие ночных эльфов утрачено. Долгие годы гора оставалась закрытой, и лишь теперь в предгорья снова ведёт путь через Теснину Зловещего Шепота. Лес медленно исцеляется, но склоны ещё хранят следы битвы, а у подножия Древа лежат кости самого Архимонда.",
        ["Стародревье"] = "Стародревье лежит на западной окраине Хиджала, у перевалов, за которыми начинается Оскверненный лес. Это старый лес горы, помнящий времена, когда ночные эльфы после Великого Раскола строили новые дома среди зелёных деревьев у подножия Хиджала. Здесь, под сенью древних стволов, стоит небольшое поселение — одно из немногих обжитых мест на горе. Отсюда видно, как далеко отступила порча: за хребтом лес искалечен Скверной, а тут он всё ещё дышит покоем.",
        ["Вершина Вечности"] = "На северо-востоке горы, выше всех её хребтов, поднимается Вершина Вечности: здесь стоит Нордрассил, Древо Жизни, а под его корнями скрыт новый Источник Вечности. Сюда в конце Третьей войны прорвался Архимонд, чтобы вырвать древо и завладеть Источником. Малфурион призвал к Нордрассилу тысячи огоньков, и их жертва испепелила демона, но опалила и само древо, а с чарами драконов ушло и бессмертие калдорай. Нордрассил медленно залечивает раны под присмотром друидов, а у его подножия по сей день белеют кости Осквернителя.",
        ["Оскверненные предгорья"] = "Юго-восточные предгорья Хиджала — те самые склоны, по которым войско Архимонда поднималось к Нордрассилу, и земля здесь до сих пор отравлена Скверной. Отсюда рукой подать до Теснины Зловещего Шепота, куда после гибели своего повелителя бежали уцелевшие демоны Легиона; из Зимних Ключей на гору ведёт именно эта дорога. Лес в предгорьях искажён и болен, но именно здесь начинается работа по исцелению горы. Для путника это первый привал на Хиджале и ворота ко всему остальному.",
        ["Даэ'ган"] = "Даэ'ган раскинулся в сердце горы, в долине к северу от Святилища Авианы. Даже имя этого места звучит чуждо: здесь укрепились демоны, оставшиеся на Хиджале после гибели Архимонда. Не все слуги Легиона бежали в Теснину Зловещего Шепота — часть их осела на самой горе, и с тех пор Даэ'ган остаётся гнездом Скверны посреди исцеляющегося леса. Друиды не могут считать Хиджал очищенным, пока здесь горят демонические огни.",
        ["Святилище Авианы"] = "На горном уступе в середине Хиджала стоит Святилище Авианы — Древней, повелительницы всех крылатых созданий Азерота и матери гарпий. В Войну Древних Авиана сражалась против Пылающего Легиона и пала, сбитая с неба демонами; с тех пор её чтят друиды Когтя, принимающие облик птиц. Это тихое место среди сожжённых склонов, и ветер с вершины доносит сюда дыхание Нордрассила. Друиды приходят сюда, чтобы почтить память Древней и просить её благословения.",
        ["Обитель Скорби"] = "К западу от Святилища Авианы, среди скал, лежит Обитель Скорби. Имя её говорит о скорби по павшим в битве за Хиджал, которых было без счёта. Но покой этого места нарушен: нежить Плети, которую Архимонд привёл на гору вместе с демонами, не исчезла с гибелью своего повелителя, и мёртвые здесь по-прежнему не знают отдыха. Друиды и стражи Хиджала не спускают глаз с этих склонов.",
        ["Сквернокровный Шрам"] = "На юге горы, между Укрытием Малорна и Оскверненными предгорьями, в земле зияет Сквернокровный Шрам — рана, оставленная Пылающим Легионом. Здесь Скверна выжгла лес до камня, и в расселинах до сих пор светятся зелёные лужи демонической магии. Такая сила манит чернокнижников, и они стекаются к Шраму, чтобы черпать из него. Для друидов это самая больная язва Хиджала: пока она не затянется, гора не исцелится.",
        ["Укрытие Малорна"] = "На юго-западе Хиджала, в укромной долине, лежит Укрытие Малорна. Малорн — Древний в облике огромного белого оленя, отец Кенария и возлюбленный самой Элуны; таурены зовут его Апа'ро. В Войну Древних он вышел против Пылающего Легиона и погиб от руки Архимонда — того самого демона, чьи кости ныне лежат под Нордрассилом. Место, названное в его честь, друиды берегут как святыню: здесь чтят память Древнего, чья власть над природой перешла к его сыну.",
        ["Колыбель Спокойствия"] = "В северо-западной части горы, среди хребтов, укрыта Колыбель Спокойствия — тихая долина с озером, к востоку от Стародревья. Название говорит о покое, которого так не хватает остальному Хиджалу. Вода здесь чиста, лес густ, и друиды видят в этой долине залог того, что гора исцелится. Для путника, уставшего от выжженных склонов, это место, где можно перевести дух.",
    },
    ["Громовой Утес"] = {
        _zone = "Громовой Утёс — столица тауренов, поднятая на вершинах высоких столовых гор посреди зелёного Мулгора. Много поколений таурены кочевали по равнинам, страдая от набегов кентавров, пока в дни Третьей войны вождь Кэрн Кровавое Копыто не заручился помощью Тралла и его Орды. Отбив Мулгор у кентавров, Кэрн возвёл на ветреных утёсах прибежище, где рады тауренам любого племени. Вершины соединены длинными мостами из дерева и канатов, а над пропастями стоят шатры, длинные дома и раскрашенные тотемы. Наверх поднимают подъёмники из верёвок и брёвен — изобретение самих тауренов, а гости прилетают на ветрокрылах или прибывают дирижаблем из Оргриммара. На центральной вершине в своём шатре сидит сам Кэрн, старейшины собираются на Вершине Старейшин, шаманы — на Вершине Духов, а охотники — на Вершине Охотников. Здесь же живёт и старая Магата из племени Зловещего Тотема, чьи замыслы не всем по нраву. Ветер гуляет между шатрами, и город живёт в мире с землёй и небом.",
        ["Вершина Старейшин"] = "Вершина Старейшин лежит к востоку от центрального утёса и соединена с ним верёвочными мостами. Здесь живут друиды и жрецы тауренов, здесь собирается совет старейшин и держит слово верховный друид Хамуул Рунический Тотем, старший из друидов Круга Кенария в Громовом Утёсе. В шатре между двумя мостами обитает Магата из племени Зловещего Тотема, старая и много знающая о духах. Не все в городе доверяют ей, но никто не смеет прогнать.",
        ["Вершина Духов"] = "Вершина Духов поднимается к северо-западу от центрального утёса. Это средоточие шаманских знаний тауренов: здесь учат говорить с духами земли, огня и ветра. Верёвочные мосты связывают вершину с нижним и средним ярусами города. У края утёса причаливает дирижабль, летящий в Оргриммар, а под самой вершиной, в пещерах, прячутся тёплые Пруды Видений.",
        ["Вершина Охотников"] = "Вершина Охотников лежит к югу от центрального утёса. Здесь живут охотники и воины тауренов, а с ними трапперы, следопыты и кожевники. Под навесами стоят мишени для упражнений, и здесь же вербовщики ищут желающих сразиться с Альянсом. Мосты ведут отсюда на нижний ярус и к вершине вождя.",
        ["Пруды Видений"] = "Пруды Видений скрыты в пещерах прямо под Вершиной Духов, и вход в них — у правого края моста, ведущего с нижнего яруса. Здесь, среди тёплой воды и пара, обосновались Отрекшиеся: их аптекари и заклинатели живут в Громовом Утёсе как гости Орды. Таурены смотрят на них настороженно, но Кэрн принял союз, заключённый Траллом. В тихой воде прудов, говорят, можно увидеть больше, чем в зеркале.",
    },
    ["Дарнасс"] = {
        _zone = "Дарнасс — столица ночных эльфов, выросшая в кроне Тельдрассила, нового Мирового Древа, которое друиды взрастили у северных берегов Калимдора после Третьей войны. Лишившись бессмертия, калдорай нашли здесь новое пристанище среди лунного света и тихой воды. Городом правит верховная жрица Тиранда Шелест Ветра, чей престол — Храм Луны, где Сестринство Элуны возносит молитвы богине. Малфурион Ярость Бури так и не вернулся из Изумрудного Сна, и друидов возглавляет верховный друид Фэндрал Олений Шлем — тот, кто настоял на посадке нового древа. Город разделён на террасы: воины и Часовые несут стражу на Террасе Воинов, мастера и купцы заняли свои террасы, а друиды собираются в Анклаве Кенария. Посреди Храмовых садов лежит озеро с островами, и вода здесь так же спокойна, как и сама столица. Попасть сюда с большой земли можно лишь через Деревню Рут'теран у подножия древа, откуда светящийся портал ведёт наверх. Дарнасс — тихое свидетельство всему, что ночные эльфы почитают священным.",
        ["Анклав Кенария"] = "Анклав Кенария — роща на северо-западе Дарнасса, где живут и собираются друиды города. Высокие дубы и ясени несут на коре руны, а среди них стоят дома, выращенные из живого дерева и камня. Отсюда верховный друид Фэндрал Олений Шлем направляет своих учеников. В восточном дереве обучают охотников, а в западном, если знать, где искать, скрывается тихое братство разбойников. У подножия деревьев можно научиться ездить на ночных саблезубах.",
        ["Терраса Ремесленников"] = "Терраса Ремесленников занимает север Дарнасса. Здесь живут и учат мастера всех ремёсел, здесь же стоит одна из главных таверн города. Свои дела ведут гильдии, а посланники Серебряного Рассвета принимают тех, кто хочет помочь в борьбе с Плетью. Отсюда дороги ведут на юг, к Террасе Воинов, и на запад, к Анклаву Кенария.",
        ["Терраса Воинов"] = "Терраса Воинов лежит на востоке Дарнасса, у главных ворот, ведущих в леса Тельдрассила. Здесь обучают воинов, здесь несут службу Часовые, и патрули на ночных саблезубах охраняют вход в город. На тренировочных площадках стоят мишени и звенит оружие, а рядом работают кузнецы. Терраса — щит столицы, и всякий, кто входит в Дарнасс, первым видит именно её.",
        ["Храмовые сады"] = "Храмовые сады — сердце Дарнасса, широкое озеро с островами и мостами в самом центре города. Названы они по Храму Луны, что высится на южном берегу. На самом большом острове стоит банк, а на западном краю светится портал, ведущий вниз, в Деревню Рут'теран у подножия древа. Мосты связывают сады со всеми террасами города и с Анклавом Кенария. Здесь тихо, и вода отражает лунный свет даже днём.",
        ["Терраса Торговцев"] = "Терраса Торговцев занимает юг Дарнасса и служит средоточием всей торговли ночных эльфов. Здесь стоят лавки и лотки, здесь же работает аукцион города. К северу лежит Терраса Воинов, а на западе — Храм Луны и Храмовые сады. Даже торговля здесь ведётся негромко, как и всё в столице калдорай.",
    },
    ["Дун Морог"] = {
        _zone = "Дун Морог — заснеженное нагорье в сердце Каз Модана, самые высокие горы Восточных королевств. Попасть сюда можно лишь через перевалы, которые стерегут дворфийские горные пехотинцы. Когда-то этими землями правили ледяные тролли Мерзлогривы, но пришедшие из Ульдамана гномы, а следом и дворфы, построили здесь свои города и оттеснили троллей в холмы. Под самой высокой горой дворфы возвели Стальгорн, а на западе помогли гномам выстроить Гномреган. Недавно Гномреган пал: город захватили трогги, а отчаянная попытка выжечь их радиацией погубила большую часть гномьего народа. Уцелевшие нашли приют в Стальгорне у короля Магни Бронзоборода. Пока армия сражается за Альянс вдали, трогги Каменной Челюсти выползают из-под земли по всему краю, а в холмах вновь поднимают голову Мерзлогривы. Снег здесь лежит круглый год, но над каждым посёлком вьётся дым кузниц и пивоварен.",
        ["Старая Наковальня"] = "Старая Наковальня — первое пристанище молодых дворфов в Холодной долине. Это не город, а укреплённый дом в скале, и в самом его сердце гудит большая кузница. Здесь учат военному делу, торгуют снаряжением и раздают первые поручения новобранцам. После падения Гномрегана сюда добрались и беженцы-гномы, растерявшие по дороге всё своё добро. От дверей Старой Наковальни дорога ведёт на восток, к тоннелю, за которым лежит остальной Дун Морог.",
        ["Каранос"] = "Каранос — самый большой городок Дун Морога, укрытый среди горных вершин к северу от Холодной долины. Здесь стоят кузница, гномья мастерская и знаменитая таверна «Громоварка». Сюда докладывают новобранцы из Старой Наковальни, и здесь Сенир Белобород собирает донесения о троллях и троггах для Стальгорна. С запада к городу подступает Серая берлога, полная вендиго, а на севере, на Мерцающем хребте, закрепились тролли Мерзлогривы. При всём своём уюте Каранос живёт как передовой пост.",
        ["Холодная долина"] = "Холодная долина — укромный уголок на юго-западе Дун Морога, отрезанный от остального края горами. Долгие годы здесь было тихо, и молодые дворфы учились охотиться на скальных вепрей да ледолапых медведей. Теперь в южной пещере обосновались тролли Мерзлогривы, а трогги напали на лагерь у замёрзшего озера, где стоит охотник Талин Остроглаз. Грелин Белобород послан сюда разведать, насколько серьёзна угроза. Единственный выход из долины — тоннель на северо-востоке.",
        ["Гномреган"] = "На западной окраине Дун Морога лежит вход в Гномреган — подземную столицу гномов. Дворфы помогли гномам заложить этот город, и веками он был чудом инженерной мысли. Но недавно в его глубины прорвались трогги, и, чтобы выжечь их, гномы наполнили город радиацией. Захватчиков это не остановило, а большая часть гномов погибла или превратилась в безумных лепрогномов. Теперь у ворот бродят прокажённые и трогги, а изгнанники в Стальгорне строят машины, чтобы отбить родной дом.",
        ["Карьер Гол'Болар"] = "Карьер Гол'Болар на юго-востоке Дун Морога — большой раскоп, где дворфы добывали руду и камень. Чем глубже копали горняки, тем больше троггов лезло наружу, пока племя Каменной Челюсти не выгнало их из шахт и не разгромило лагерь. Штейгер Камнелоб до сих пор не может смотреть на разбитые бочки с порохом без злости. Сенатор Мер Каменная Реликвия от имени Лиги Исследователей нанимает добровольцев, чтобы очистить карьер и вернуться к работе.",
        ["Форт Мерзлогривов"] = "Форт Мерзлогривов — пещерное логово ледяных троллей на западе Дун Морога, к юго-западу от Посёлка Пивоваров. Некогда Мерзлогривы правили всеми этими горами, а теперь укрываются здесь, среди немногих хижин и тёмных тоннелей. Пещеру стерегут охотники за головами и свежеватели, и Сенир Белобород не решился идти туда в одиночку. Стальгорну нужно знать, сколько троллей засело в форте и что они замышляют.",
        ["Серая берлога"] = "Серая берлога — большая пещера к западу от Караноса, где живут стаи вендиго. Эти косматые твари дышат морозом и набрасываются на чужаков все разом. Дворфы ходят сюда за гривами вендиго: пилот Камнекожец мечтает обить ими кабину своего Троллеукладчика. В глубине пещеры поблёскивают медные жилы, а у входа не так давно вендиго разграбили лагерь курьера с боеприпасами для Хегнара Громострела.",
        ["Поселок Пивоваров"] = "Посёлок Пивоваров — крохотное поселение на западном берегу Заледеневшего озера, неподалёку от Гномрегана. Здесь живёт семья Ячменоваров, без устали совершенствующих дворфийское искусство пивоварения. Регольд Ячменовар варит «Вечное сияние», способное уложить самого крепкого дворфа, а Марлетта не даёт покоя Громоварам из Караноса. Вокруг посёлка бродят медведи, леопарды и кабаны, и пивоварам вечно не хватает рук, чтобы отгонять зверьё.",
        ["Сторожка у заснеженной сосны"] = "Сторожка у заснеженной сосны — одинокий домик среди сосен в центральной части Дун Морога. Он стоит в стороне от дороги, и снег вокруг него редко тревожат чужие следы. В последнее время здесь держит пост посланник ордена Серебряного Рассвета, следящий за далёкими вестями с чумных земель.",
        ["Поселок Сталежара"] = "Посёлок Сталежара лежит сразу за поворотом к северо-востоку от Караноса. Это небольшое поселение горняков и инженеров, каменная мастерская под деревянными навесами, где чинят осадные машины. Хозяин её, Белдин Сталежар, слывёт лучшим техником по паровикам, а его тангенциальные вращатели выходят из строя быстрее, чем их успевают привозить. Здесь любят собираться ветераны-водители осадных машин, и в снегу вокруг ржавеют остовы недостроенных танков.",
        ["Заледеневшее озеро"] = "Заледеневшее озеро на западе Дун Морога сковано льдом почти круглый год. Дворфы из Посёлка Пивоваров держат во льду прорубь, чтобы брать пресную воду и рыбачить. Посреди озера лежат два больших острова, но ходить туда не советуют: там хозяйничает стая голодных волков во главе с матёрым воргом. Вдоль замёрзшей реки к северу от озера идёт дорога к Караносу.",
        ["Озеро Хельмово Ложе"] = "Озеро Хельмово Ложе — небольшое озеро на юго-востоке Дун Морога. Оно почти всегда затянуто льдом, лишь одну прорубь держат открытой ради пресной воды. По льду ходить безопасно, но берега кишат зверьём и отбившимися от стаи троггами. Хуже того, к югу от озера окопались дворфы Чёрного Железа, и разведчик Нарм Фолк заплатил жизнью, подобравшись к ним слишком близко.",
        ["Мастерская Сталекрута"] = "Мастерская Сталекрута стоит к югу от озера Хельмово Ложе, на восточной окраине Дун Морога. Когда-то здесь учил кузнечному делу Стурги Сталекрут, лучший из наставников. Однажды ученики принесли ему странную мрачную руду, и вскоре на мастерскую напал отряд дворфов Чёрного Железа, перебивший всех. Теперь в пустых стенах хозяйничают убийцы, и они нападают на любого, кто подойдёт слишком близко.",
        ["Туннель Холодной долины"] = "Туннель Холодной долины — единственный проход, связывающий долину с остальным Дун Морогом. Через него новобранцы уходят в Каранос, но в последнее время тоннель кишит троггами, которые нападают на всякого, кто сунется внутрь. У входа несёт дозор горный пехотинец Талос, предупреждая путников об опасности. Иных здесь спасают только быстрые ноги, а иных — крепкий топор.",
        ["Долина Промозглого Ветра"] = "Долина Промозглого Ветра лежит между Гномреганом на западе и Караносом на востоке. По её широкой части проходит оживлённая дорога, а вот в узкий южный отрог заглядывают немногие: снег там залит кровью, а вокруг разбросаны растерзанные туши. В тамошних пещерах обитают вендиго, и не всякий, кто отправился на охоту за ними, вернулся назад. Ветер в долине действительно промозглый, как и обещает её имя.",
        ["Мерцающий хребет"] = "Мерцающий хребет тянется на севере Дун Морога, к западу от Врат Стальгорна. На нём разбили два лагеря тролли Мерзлогривы, соединив их мостом, и здесь же они держат прирученных вепрей. Тролли выращивают звездолист, траву для своих ритуалов, а дворфы-пивовары зарятся на неё ради необычного вкуса нового портера. Отсюда тролли следят за дорогой на Стальгорн.",
        ["Ферма Янтарленов"] = "Ферма Янтарленов стоит у дороги на Лок Модан, к северу от карьера Гол'Болар. Семья Янтарленов разводит горных баранов, лучших ездовых животных дворфов, и здесь можно обучиться верховой езде. Пока армия короля Магни сражается в дальних краях, ферму некому защищать, и по ночам к отаре подбирается вендиго Вагаш. Рудра Янтарлен обещает награду тому, кто принесёт его клык.",
        ["Холмы Тандрид"] = "Холмы Тандрид лежат в южной части Дун Морога, к западу от карьера Гол'Болар. Здесь водятся снежные леопарды, скальные вепри и ледолапые медведи, и без оружия сюда лучше не ходить. По холмам рыщут и тролли Мерзлогривы. Иные путники срезают через эти холмы путь из Холодной долины на восток, но дорога через Каранос куда безопаснее.",
        ["Южные врата"] = "Южные врата — перевал, ведущий из высоких гор Дун Морога вниз, к озеру Лок Модан. Этим путём чаще всего ходят в Телсамар и обратно. Посреди перевала стоит сторожевая застава горных пехотинцев. Снег здесь лежит до самой границы, а дальше начинаются более тёплые холмы Лок Модана.",
        ["Форт у Южных врат"] = "Форт у Южных врат — сторожевая застава посреди южного перевала на границе с Лок Моданом. Горные пехотинцы под началом капитана Ругельфасса давно очистили окрестности от зверья, и здесь спокойнее, чем на северной заставе. Однако полк не может отойти от Врат: в холмах Лок Модана расплодились трогги, и капитан ищет добровольцев для вылазок. Через заставу постоянно идут путники в Телсамар.",
        ["Северные врата"] = "Северные врата — перевал на северо-востоке Дун Морога, ведущий в Лок Модан. Через него идут те, кто направляется к Болотине, ведь этот путь ближе всего к спуску с озера. На перевале стоит застава горных пехотинцев. Дорога вьётся между заснеженных скал, и в стороне от неё бродят опасные звери.",
        ["Форт у северных врат"] = "Форт у северных врат — самое северо-восточное поселение дворфов в Дун Мороге, застава посреди северного перевала. Горные пехотинцы здесь без конца отбиваются от зверья, а несколько дворфов пропали в горах, отправившись на самых свирепых хищников. Пилот осадного орудия Мори Хилдельв ушёл в холмы искать редкую руду и не вернулся. Молодым дворфам и гномам поручают искать следы пропавших.",
        ["Врата Стальгорна"] = "Врата Стальгорна ведут из снегов Дун Морога в дворфийскую столицу. Их видно издалека: к ним поднимается широкий пандус с северной дороги, обставленный штандартами. За воротами, в первом зале, стоит огромная статуя древнего верховного короля дворфов. Здесь всегда людно: торговцы, послы и беженцы-гномы идут под своды горы, где правит Магни Бронзобород.",
        ["Таверна \"Громоварка\""] = "Таверна «Громоварка» — сердце Караноса и одна из самых известных пивоварен мира. Здесь варят громовой эль, а завсегдатаи больше всего любят кабаньи рёбрышки в пиве по фамильному рецепту Рагнара Громовара. В таверне есть постель для путников, а наверху и на кухне обучают ремёслам и боевому искусству. Соперники из семьи Ячменоваров не прочь подменить бочонок в её подвале, чтобы доказать, чьё пиво лучше.",
    },
    ["Дуротар"] = {
        _zone = "Дуротар — суровая красная земля на восточном побережье Калимдора, ставшая домом орков после Третьей войны. Тралл назвал её в честь своего отца Дуротана, вождя клана Северного Волка, а столицу Оргриммар — в честь Оргрима Молота Рока. Растрескавшаяся почва, сухие каньоны и колючие заросли напоминают оркам о родном Дреноре. На западе, за рекой Строптивой, лежат Степи, на севере — Азшара, а восточный берег омывает Великое море. Мир здесь хрупок: флот Кул-Тираса под началом адмирала Праудмура уже пытался уничтожить молодую Орду, и остатки его солдат до сих пор держат крепость Тирагард. Иглогривые, кентавры Колкар и гарпии Пыльного Ветра теснят поселения, а в пещерах тайно собирается культ Пылающего Клинка. Рядом с орками живут тролли Чёрного Копья, изгнанные с островов Эха.",
        ["Колючий Холм"] = "Колючий Холм — орочье поселение на перекрёстке дорог в сердце Дуротара. Южный путь ведёт к деревне Сен'джин и Долине Испытаний, северный — к воротам Оргриммара, а западный уходит через реку Строптивую в Степи. Над низкими хижинами возвышаются казармы, самое большое здание посёлка. Здесь Оргнил Душегрыз ведёт расследование против культа Пылающего Клинка, чьи последователи всё смелее хозяйничают в окрестных каньонах. Для многих молодых воинов Орды именно отсюда начинается настоящая служба.",
        ["Долина Испытаний"] = "Долина Испытаний — замкнутая котловина среди красных скал на юго-западе Дуротара, куда приходят молодые орки и тролли, чтобы доказать, что достойны Орды. Обряды посвящения просты и суровы: охота на кабанов и скорпидов, поручения наставников и, наконец, поход в пещеру на севере долины, где поселились демоны. Здесь нет ни роскоши, ни покоя, лишь кактусы, пыль и учителя, следящие за каждым шагом новичков. Тот, кто выдержал испытания, получает право покинуть долину и отправиться в деревню Сен'джин.",
        ["Логово"] = "Логово — большое строение в глубине Долины Испытаний, сердце тренировочного лагеря Орды. Под его сводами ждут наставники, оружейники и мясники, обучающие новобранцев ремёслам войны. У входа стоят стражники, а вокруг снуют ленивые батраки, которым вечно нужен окрик надсмотрщика. Именно сюда молодые орки и тролли возвращаются с каждым выполненным поручением, прежде чем получить следующее.",
        ["Грот Пылающего Клинка"] = "Грот Пылающего Клинка скрыт в пыльных горах, замыкающих Долину Испытаний с севера. Из его устья выползают бесы и другие слабые демоны, и покоя в долине больше нет. Поговаривают, что в заброшенных пещерах обосновались чернокнижники культа Пылающего Клинка, а в глубине хозяйничает нечто пострашнее бесов. Для новобранцев поход в этот грот становится последним испытанием перед тем, как долина отпустит их во внешний мир.",
        ["Утес Колкара"] = "Утёс Колкара — каменистое ущелье на юге Дуротара, названное по племени кентавров, что засели в нём. Колкары совершают набеги на окрестности, и разведчики Орды уже перехватывали их замыслы — тройной удар по позициям троллей и орков. Ущелье лежит недалеко от деревни Сен'джин, и её жители первыми ощущают на себе жестокость кентавров.",
        ["Деревня Сен'джин"] = "Деревня Сен'джин — рыбацкое поселение троллей Чёрного Копья на южном побережье Дуротара. Вол'джин основал её, когда племени пришлось бежать с островов Эха, и назвал в честь своего отца Сен'джина, вождя и знахаря, погибшего в Третью войну, когда он спасал соплеменников от мурлоков. Здесь живут алхимики и травники, а делами деревни ведает Мастер Гадрин. Тролли не забыли о родных островах и мечтают вернуть их себе.",
        ["Острова Эха"] = "Острова Эха — россыпь тропических островков у юго-восточного берега Дуротара, новая родина племени Чёрного Копья в Калимдоре. Тролли едва успели обжиться здесь, когда знахарь Залазан, некогда друг Вол'джина, обратил тёмные силы против своих же и подчинил их разум. Племени пришлось отступить на берег Дуротара, а острова остались во власти Залазана и его околдованных слуг. В джунглях рыщут ящеры и тигры, а на самом большом острове стоит круг черепов, в которых заперты души погибших.",
        ["Громовой хребет"] = "Громовой хребет — глухая долина на северо-западе Дуротара, одно из немногих зелёных мест этой земли. Здесь водятся громовые ящеры, чьи стада не дают покоя всей округе. В последнее время в долине обосновалась горстка сектантов Пылающего Клинка во главе с гоблином-чернокнижником Пшиксом Черношквалом, и Оргнил Душегрыз из Колючего Холма ищет тех, кто положит конец их бесчинствам.",
        ["Сухая лощина"] = "Сухая лощина — узкий каньон на севере Дуротара, куда с земли можно попасть лишь через небольшую пещеру из Каньона Колючего Ветра. Здесь свили гнёзда гарпии Пыльного Ветра. Они промышляют разбоем, грабят караваны Орды и стаскивают добычу на высокие уступы. Самые сильные из гарпий стерегут кладки яиц, и чужаков здесь встречают когтями.",
        ["Пещера Пыльного Ветра"] = "Пещера Пыльного Ветра — небольшой грот на скалах Каньона Колючего Ветра, к северо-востоку от Колючего Холма. Несмотря на название, гарпий здесь нет: пещеру заняли сектанты Пылающего Клинка, и старшие культисты обучают здесь новобранцев тёмным искусствам. Совсем рядом с дорогой на Оргриммар зреет заговор, о котором в Колючем Холме догадываются, но пока не знают всего.",
        ["Крепость Тирагард"] = "Крепость Тирагард — белокаменная твердыня на восточном берегу Дуротара, чужая среди красных скал. Её наспех возвёл адмирал Праудмур, лорд Кул-Тираса и отец Джайны, когда его флот вторгся в Дуротар, нарушив договор, заключённый Траллом с Джайной Праудмур. Штурм крепости и гибель адмирала должны были положить конец войне, но подкрепление под командой лейтенанта Бенедикта вновь заняло руины. Солдаты Кул-Тираса продолжают дело адмирала, и Колючий Холм не может выбить их с этого плацдарма.",
        ["Берег Разбитых Кораблей"] = "Берег Разбитых Кораблей тянется вдоль Великого моря к юго-востоку от Колючего Холма и к северу от крепости Тирагард. Своё имя он получил из-за кораблей Кул-Тираса, разбитых о скалы в битвах орков с флотом адмирала Праудмура. Остовы судов до сих пор торчат из воды, а по песку среди обломков снуют крабы и макрура.",
        ["Бухта Острорука"] = "Бухта Острорука — часть Великого моря у северо-восточного берега Дуротара, рядом со Скалой Черепа. Она названа в честь Каргата Острорука, вождя клана Изувеченной Длани. Через пролив на севере виден берег Азшары. Пристани здесь нет, лишь пустынный пляж, на котором хозяйничают макрура.",
        ["Взморье Мертвого Глаза"] = "Взморье Мёртвого Глаза — пустынный участок восточного побережья Дуротара, к востоку от Сухой лощины. Берег назван в честь Килрогга Мёртвого Глаза, вождя клана Кровавой Глазницы и героя старой Орды. Путников здесь почти не бывает, зато среди дюн бродят ящеры, скорпиды и кабаны.",
        ["Побережье Черного Копья"] = "Побережье Чёрного Копья — полоса песка у деревни Сен'джин. Именно сюда высадились тролли Чёрного Копья, когда Залазан вынудил их покинуть острова Эха, и здесь Вол'джин собрал уцелевших. Отсюда видны родные острова, до которых рукой подать и куда племя пока не может вернуться. По берегу ползают крабы, а в прибрежных водах ловят рыбу жители деревни.",
        ["Каньон Колючего Ветра"] = "Каньон Колючего Ветра лежит по обе стороны дороги из Колючего Холма в Оргриммар. Это гнездовье гарпий Пыльного Ветра, и в каньоне их великое множество. Тропы уводят к ферме Тор'кренов на западе и к пещере, ведущей в Сухую лощину. Неосторожный путник, свернувший с дороги, рискует не вернуться.",
        ["Потайная тропа"] = "Потайная тропа — скрытый путь через горы, окружающие Долину Испытаний. Начинающие шаманы должны отыскать его сами, чтобы подняться к Священному Камню. С самой высокой точки тропы открывается вид на Степи. Тропа известна немногим, и для большинства новичков она так и остаётся тайной.",
        ["Священный Камень"] = "Священный Камень — место, святое для шаманов Орды. Он стоит высоко в горах над Долиной Испытаний, куда ведёт Потайная тропа. Здесь начинающие шаманы пьют сапту, напиток, связывающий дух со стихией, и впервые слышат голос Земли. Сапту можно пить лишь в священном месте, и потому камень оберегают от чужих глаз.",
        ["Святилище Дремлющего Пламени"] = "Святилище Дремлющего Пламени венчает одну из высочайших гор Дуротара, к северо-западу от Долины Испытаний. К нему ведёт тайная тропа, спиралью обвивающая вершину; начинается она у реки Строптивой. Святилище хранит одинокий Телф Джулам, наставник шаманов на пути Огня. Жаровню на вершине зажигают углём поверженного духа огня в знак того, что шаман овладел стихией. С вершины виден весь Дуротар, но неверный шаг здесь стоит жизни.",
        ["Река Строптивая"] = "Река Строптивая — самая большая река Калимдора. Она берёт начало в озере на горе Хиджал, водопадами обрушивается в низины и разделяет Ясеневый лес и Азшару, а южнее — Степи и Дуротар. Через неё переброшен мост, по которому дорога из Колючего Холма уходит к Перекрёстку. Река впадает в Великое море к северу от Кабестана. В её водах живут кроколиски, и охота на них не раз кончалась гибелью.",
        ["Земли Иглогривых"] = "Земли Иглогривых лежат в сердце Дуротара, к западу от Колючего Холма. Это передовая войны со свинобразами Иглогривых, рвущимися из Степей в земли орков. Землю усыпают обглоданные кости, а из красных скал вырываются заросли колючек. Орки не пускают Иглогривых дальше, но на месте каждого убитого из зарослей выходят двое.",
        ["Скала Черепа"] = "Скала Черепа — пещера на северо-востоке Дуротара, к востоку от Оргриммара, одно из убежищ культа Пылающего Клинка. Здесь скрывается орк-чернокнижник Газз'уз, а его сектанты совершают гнусные обряды и носят обжигающие ошейники, связывающие их с демонами. Заговор зреет под самым носом у столицы Орды.",
        ["Ферма Каменного Клыка"] = "Ферма Каменного Клыка стоит у западной дороги, сразу за воротами Оргриммара. Это свиноферма, и её хозяева чувствуют себя в безопасности под стенами столицы. Свиньи с этой фермы кормят Орду, а рядом, у пруда, всегда стоит кто-нибудь из стражи.",
        ["Свиноферма"] = "Свиноферма — одна из нескольких свиных ферм у ворот Оргриммара. Здесь есть амбар, большой загон и пруд, а свинина отсюда идёт на столы Орды. Ферма выглядит заброшенной: в загонах бродят одичавшие свиньи, а хозяев не видно.",
        ["Казармы Колючего Холма"] = "Казармы Колючего Холма — самое большое здание посёлка, отличающее его от прочих застав Дуротара. Под их крышей обучают воинов, жрецов и шаманов, учат искусству первой помощи и торгуют всем необходимым. Отсюда же командование Колючего Холма следит за угрозами округи, от Иглогривых до сектантов Пылающего Клинка.",
        ["Ферма Тор'кренов"] = "Ферма Тор'кренов расположена на северо-западе Дуротара, к юго-востоку от Громового хребта. Это небольшая свиноферма, не столь прибыльная, как соседние. Хозяйка, Майша Тор'крен, ведёт хозяйство одна: её сын Крон ушёл охотиться на кроколисков к реке Строптивой и не вернулся, и мать всё ещё ждёт вестей о нём.",
    },
    ["Западные Чумные земли"] = {
        _zone = "Западные Чумные земли лежат в северном Лордероне, между Тирисфальскими лесами и рекой Тондрорил. Когда-то это была житница королевства: из Андорала зерно расходилось по всем северным провинциям. Этим и воспользовался некромант Кел'Тузад: его Культ Проклятых заразил зерно Чумой нежити, а на четырёх крупнейших фермах поставил громадные чумные котлы. С тех пор земля укрыта серой мглой, звери здесь больны и злобны, а деревья покрыты уродливыми наростами. В руинах Андорала правит лич Арадж Призыватель, и мертвецы стерегут котлы на полях и кладбище на Холме Печали. На севере, в Дольном Очаге, окопался Алый орден, на юге держится горстка бойцов Серебряного Рассвета, а на западной границе стоит Бастион Отрекшихся. Посреди озера Дарроумир чернеет остров Каэр Дарроу, под которым укрылась школа некромантии, и лишь гробница Утера Светоносного ещё хранит в этом умирающем краю Свет.",
        ["Дольный Очаг"] = "Дольный Очаг стоит на севере Чумных земель и выглядит удивительно мирно посреди отравленного края. Некогда это была столица княжества, которым правил паладин Тирион Фордринг, а во Вторую войну его стены так и не покорились Орде. В Третью войну сюда пришло заражённое зерно из Андорала, и город устоял лишь потому, что принц Артас с Утером Светоносным отбили осаду Плети. Теперь за стенами хозяйничает Алый орден, а командует им верховный лорд Таэлан Фордринг, сын Тириона. Чужаков крестоносцы встречают сталью, и разведчики Альянса и Орды наблюдают за городом лишь издалека.",
        ["Лесопилка Северного Кряжа"] = "Лесопилка Северного Кряжа стоит у самой границы Дольного Очага и снабжает лесом Алый орден. Здесь ещё сохранились живые деревья, а на дворе не смолкают пилы. Крестоносцы дорожат этим местом, и потому Серебряный Рассвет ищет способы лишить их запасов древесины.",
        ["Руины Андорала"] = "Андорал был сердцем северных провинций Лордерона: отсюда зерно расходилось по всему королевству, и именно его отравил Кел'Тузад, чтобы разнести Чуму. После падения королевства рыцари Серебряной Длани под началом Утера удерживали город, пока сюда не пришёл рыцарь смерти Артас за останками Кел'Тузада. Утер пал у стен Андорала, и с тех пор город принадлежит Плети: в руинах правит лич Арадж Призыватель, а по улицам бродят вурдалаки, скелеты и поганища. Все часы в городе остановились ровно в три, в тот миг, когда здесь вспыхнула Чума, и бронзовый дракон Хроми ищет в руинах следы искажения времени.",
        ["Школа некромантии"] = "Под усадьбой дома Баровых на острове Каэр Дарроу укрылся Некроситет, школа некромантии. Перед Третьей войной Кел'Тузад заключил с Баровыми сделку, и в катакомбах древней крепости обосновался Культ Проклятых. Здесь послушники учились поднимать мёртвых, а слуг семьи использовали для опытов с Чумой нежити. Ныне школой заправляет тёмный магистр Гандлинг, а среди его наставников лич Рас Снегошепот. У ворот стерегут вход стражи Плети, и ключ к этим дверям достаётся нелегко. Ходят слухи, что здесь выращивают даже зачумлённых драконьих детёнышей.",
        ["Гробница Утера"] = "Гробница Утера Светоносного венчает Холм Печали, и это единственное место в Чумных землях, где ещё чувствуется Свет. Утер погиб у стен Андорала от руки Артаса, своего лучшего ученика, которого любил как сына. Уцелевшие воины вынесли его тело и выстроили ему усыпальницу к югу от руин. На постаменте стоит статуя паладина с книгой Света в одной руке и боевым молотом в другой. За гробницей и садом присматривает эльф-жрец Тельданис, но склоны вокруг кишат тварями Плети, и путь сюда небезопасен.",
        ["Холм Печали"] = "Холм Печали — старое кладбище к югу от Андорала. В мирные годы здесь хоронили и знать, и бедняков, оттого рядом с богатыми склепами тянутся ряды простых плит. Когда началась Чума, могилы рыли наспех и почти не помечали, а под конец горожане и вовсе стали сжигать мертвецов, боясь, что те восстанут. Последним делом уходящих жителей стала гробница Утера на вершине холма. Но чумные котлы сделали своё: скелеты павших солдат и вурдалаки из бывших горожан сторожат собственные могилы, а из склепа поднимаются мёртвые чародеи.",
        ["Грот Слез"] = "Грот Слёз — сырая пещера на северо-востоке Чумных земель, у самой реки Тондрорил. Здесь, во тьме и гнили, копошатся болотные твари и разъедающие слизни. Немногие рискуют заходить внутрь, хотя знахари ценят то, что можно найти в этих недрах.",
        ["Поле Джанис"] = "На северо-западе Чумных земель лежит поле Джанис, когда-то живая, кормившая людей ферма. Плеть поставила посреди поля громадный котёл, который днём и ночью выдыхает в небо ядовитые пары; стерегут его Хранитель котла Желчень, скелеты-чародеи и вурдалаки. Порой сюда прорываются и крестоносцы Алого ордена, рубящие без разбора и мёртвых, и живых. А в доме на краю поля бродит призрак хозяйки, Джанис Фелстоун. Она всё зовёт мужа и не понимает, отчего ей так холодно.",
        ["Слезы Далсона"] = "Слёзы Далсона — заброшенная ферма в самом сердце Чумных земель. Когда-то здесь был фруктовый сад, но Плеть поставила посреди поля чумной котёл, и теперь его охраняют Хранитель котла, гниющие трупы и ходячие мертвецы. Хозяева фермы так и не покинули её: миссис Далсон бродит по двору скелетом, а фермер Далсон заперт где-то в постройках и давно уже не человек. В доме ещё сохранились её дневник и запертый шкаф.",
        ["Пустошь Гаррона"] = "Пустошь Гаррона — восточная из четырёх чумных ферм, и здесь стоит последний котёл, до которого ещё не добрался Серебряный Рассвет. Над полем кружат голодные призраки и стонущие духи, а стережёт котёл один из Хранителей Плети. Именно сюда судьба привела Джозефа Редпата, капитана ополчения Дарроушира: во время битвы за его деревню рыцарь смерти Мардук Чёрный растерзал его душу и обратил в злобную тень. Силы Альянса в конце концов одолели Редпата на пустоши Гаррона, и его щит до сих пор лежит у амбара. Приспешники Плети об этом помнят.",
        ["Удел Страданий"] = "Удел Страданий лежит сразу к востоку от руин Андорала. Когда-то и эта ферма кормила людей, но теперь посреди поля бурлит чумной котёл, а вокруг него бродят гниющие и ледяные вурдалаки да зловонные зомби. Кто-то из живых ещё прячется в уцелевшем доме, но лучше не задерживаться здесь надолго.",
        ["Крепость Марденхольд"] = "Крепость Марденхольд — сердце Дольного Очага, и отсюда некогда правил всем краем Тирион Фордринг, лорд Марденхольдский. Горожане гордились, что её стены не пали даже в самые чёрные дни орочьего нашествия. Тирион был обвинён в измене за помощь орку, отлучён от ордена Серебряной Длани и изгнан. После падения Лордерона именно здесь собирались уцелевшие паладины, и здесь родился Алый орден. Теперь крепостью владеет верховный лорд Таэлан Фордринг, сын Тириона, и Марденхольд стал главной твердыней крестоносцев в Чумных землях.",
        ["Бастион"] = "Бастион — последний рубеж Отрекшихся на границе Тирисфаля и Чумных земель. Во время Третьей войны здесь стоял лагерь Утера, где он укрывал беженцев из павшей столицы. Ныне у частокола стражи смерти несут дозор вместе с бойцами Серебряного Рассвета: общая угроза Плети заставила забыть о разногласиях. Верховный палач Деррингтон готовит удар по Андоралу, а жрица Тени Вандис изучает чумные котлы. Небо над Бастионом уже затянуто той же желтоватой мглой, что и над Чумными землями.",
        ["Озеро Дарроумир"] = "Озеро Дарроумир — одно из крупнейших озёр Восточных королевств, лежащее на юго-востоке Чумных земель. Во Вторую войну на его водах гремели морские сражения. Посреди озера чернеет остров Каэр Дарроу с усадьбой дома Баровых, а под ней укрылся Некроситет. С севера в Дарроумир впадает река Тондрорил. Ныне воды озера безжизненны и тихи.",
        ["Каэр Дарроу"] = "Каэр Дарроу — остров и древняя крепость посреди озера Дарроумир. Во Вторую войну Орда разграбила её и вывезла священный эльфийский рунический камень, из обломков которого чернокнижники Орды сложили свои алтари. После войны крепость стала родовым гнездом Баровых, но перед Третьей войной жадные аристократы заключили сделку с Кел'Тузадом, и под усадьбой возник Некроситет. Вскоре мор выкосил весь остров, а его жители обречены бродить призраками, вновь и вновь переживая последний день. Наследники дома Баровых и ныне спорят о праве на эти руины.",
        ["Река Тондрорил"] = "Река Тондрорил течёт с севера и впадает в озеро Дарроумир, служа границей между Западными и Восточными Чумными землями. Её берега облюбовали чумные медведи, летучие мыши-кровососы и пауки. Мутная вода несёт с собой ту же заразу, что отравила всю эту землю.",
        ["Лагерь Промозглого Ветра"] = "Лагерь Промозглого Ветра стоит на самом юге, там, где дорога из Альтерака входит в Чумные земли. Это последнее безопасное место для путников Альянса: здесь держится небольшой отряд Серебряного Рассвета, сюда же присылают на закалку молодых паладинов Серебряной Длани. Сил у лагеря немного, поэтому Рассвет полагается на наёмников и добровольцев, ведя тайную войну против Андорала и чумных котлов. Высшая жрица Макдонелл собирает образцы отравы из котлов, надеясь обратить их против самой Плети. Отсюда же грифоны уносят гонцов в Стальгорн, Южнобережье и к часовне Последней Надежды.",
    },
    ["Западный Край"] = {
        _zone = "Западный Край когда-то был житницей королевства Штормград: на этих равнинах к западу от Элвиннского леса растили хлеб для всего юга. Но годы войн и небрежения сделали своё дело: урожаи скудели, рудники пустели, а когда содержание гарнизонов стало слишком дорогим, Штормград отозвал и войска. В беззащитный край пришло Братство Справедливости — бывшие каменщики Эдвина ван Клифа, восстанавливавшие столицу после Первой войны и обманутые знатью. Они заняли брошенные фермы, а по полям бродят их механические големы, вышедшие из-под контроля. К разбойникам примкнули гноллы, побережье кишит мурлоками. Всё, что осталось у здешних людей, — Народное ополчение на Сторожевом холме да несколько упрямых фермеров. А под опустевшим Луноречьем, в Мёртвых копях, ван Клиф готовит нечто, о чём в Штормграде пока лишь догадываются.",
        ["Бескрайний берег"] = "Бескрайний берег тянется вдоль всего западного побережья края — один из самых длинных пляжей Азерота. Тишина здесь обманчива: песок кишит мурлоками, а среди них появляется и Старый Мрачноглаз, которого боятся даже сородичи. У кромки воды лежат обломки разбитых кораблей, и говорят, что у ржавого якоря зарыт сундучок покойного капитана Сандерса. На дальнем юго-западе одиноко стоит ферма Дафны Стилвелл, а над южной оконечностью берега светит маяк.",
        ["Луноречье"] = "Луноречье на юго-западе края было шахтёрским городком, но теперь это лишь тень былого. Жители давно бежали, и по опустевшим улицам расхаживают бандиты Братства Справедливости. Именно здесь, под городом, лежат Мёртвые копи — заброшенная сеть штолен, которую Эдвин ван Клиф сделал своей цитаделью. Шахтёры из Союза шахтёров погибли тут при обвале, устроенном Братством, и их беспокойные тени, говорят, до сих пор бродят в штольнях. Дальше к югу поднимается гряда Холмов Разбойничьих Кинжалов.",
        ["Маяк"] = "Белая башня маяка стоит на скалистом островке у самого южного края побережья, и ночью её луч медленно кружит над рифами Великого моря. Когда-то здесь жила семья смотрителя, но теперь у подножия слышен лишь прибой да возня мурлоков на берегу. Огонь всё же горит — есть кому за ним присматривать.",
        ["Ферма Сальдена"] = "Ферма Сальдена — единственное хозяйство Западного Края, которое Братство Справедливости так и не сумело отобрать целиком. По полям бродят механические големы, дозорные полей, но фермер Сальден и его жена Сальма упрямо отказываются уезжать. Их дом давно стал приютом для тех, кого война и разбой лишили крова, а Сальма кормит гостей знаменитой похлёбкой Западного Края — из того, что удаётся собрать в округе.",
        ["Сторожевой холм"] = "Сторожевой холм — последний оплот порядка в Западном Крае. Когда Штормград отозвал войска, здешние фермеры сами взялись за оружие и создали Народное ополчение. Лагерь раскинулся у подножия старой сторожевой башни; здесь Гриан Камнегрив и капитан Данувин принимают всех, кто готов помочь против Братства Справедливости и гноллов. Разведчики ополчения следят за передвижениями бандитов, а с холма видна почти вся равнина — до самого Луноречья.",
        ["Тыквенная ферма Хмуроброва"] = "Тыквенная ферма Хмуроброва на севере края — одно из хозяйств, доставшихся Братству Справедливости. Бандиты заняли постройки, а по грядкам вышагивают их механические големы. Фермер Теодор Хмуробров и его жена Верна бежали, но их повозка сломалась на дороге у Владения Янсена. Документ на владение фермой Братство силой отняло у хозяина — чтобы потом присвоить землю.",
        ["Рудник Янго"] = "Рудник Янго на северо-западе края когда-то поставлял в Штормград руду и золото. Теперь шахта заброшена, и в её штольнях хозяйничает Братство Справедливости: грабители обирают всё, что осталось от старых выработок. Разведчики ополчения замечали здесь и звероловов Братства, а по дороге к Прииску на Золотом Берегу ходят их вестники.",
        ["Прииск на Золотом Берегу"] = "Прииск на Золотом Берегу — старый золотой карьер неподалёку от побережья, к западу от башни на Сторожевом холме. Он приносил королевству неплохой доход, пока край не пришёл в упадок. Сейчас карьер занят Братством Справедливости: здесь бесчинствуют погромщики и мошенники Братства, и Народное ополчение считает это место одним из главных их гнёзд.",
        ["Маяк в Западном Крае"] = "Маяк на южной оконечности Бескрайнего берега предупреждает моряков об опасных прибрежных рифах. Семья смотрителя дважды пережила нападения мурлоков, которых вёл Старый Мрачноглаз; во второй раз не уцелел никто. Огонь, однако, не погас: за ним следит призрак капитана Грейсона — моряка, чей корабль разбился о здешние скалы в ту ночь, когда маяк не светил. Теперь он хранит пламя ради тех, кто ещё ходит по Великому морю, и ищет помощи у путников, чтобы очистить побережье.",
        ["Поместье Алекстона"] = "Поместье Алекстона лежит к западу от Сторожевого холма. Хозяева бежали, когда Братство Справедливости захватило ферму, а дом был разграблен и сожжён; по полям остались бродить лишь механические дозорные. Отсюда родом Барос Алекстон, ныне архитектор Штормграда, — мальчишкой он работал на этой самой земле.",
        ["Владение Янсена"] = "Владение Янсена — самая северная ферма Западного Края, у моста из Элвиннского леса. Хозяев давно прогнало Братство Справедливости, и на полях теперь дежурят их механические големы да сами бандиты. На дороге рядом стоит сломанная повозка Хмуробровых: старая кобыла Савраска ждёт, пока фермер починит колесо. Для многих путников с востока это первое, что они видят в Западном Крае.",
        ["Мертвая пашня"] = "Мёртвая пашня — выжженное поле на юго-востоке края, у моста в Сумеречный лес. Когда Братство Справедливости пришло в Западный Край, стоявшую здесь ферму сожгли вместе с посевами. От хозяйства остались лишь дымящиеся руины, а по обугленной земле по-прежнему кружат механические дозорные полей.",
        ["Ферма Мольсена"] = "Ферма Мольсена — одно из многих хозяйств Западного Края, отнятых Братством Справедливости. Хозяева ушли, и по пустым полям бродят лишь механические големы, дозорные полей. Ополчение доносило, что звероловы Братства промышляют и здесь, и у соседней тыквенной фермы Хмуроброва.",
        ["Пруд Стенделя"] = "Пруд Стенделя — небольшой водоём к юго-западу от Сторожевого холма. Вода здесь мутная, а по берегу расположились гноллы; кости и две старые могилы у кромки намекают, что пить из пруда не стоит. Впрочем, рыбаки всё равно не обходят его стороной.",
        ["Холмы Разбойничьих Кинжалов"] = "Холмы Разбойничьих Кинжалов — скалистая гряда за Луноречьем, её ещё называют южным Западным Краем. Народное ополчение полагает, что именно здесь скрываются разбойники, налётчики и кастетчики Братства Справедливости, ускользнувшие от него. Среди камней нашёл уединение и дворф-пивовар Мрачнобух Громовар, который варит здесь своё светлое.",
        ["Участок Демонта"] = "Участок Демонта лежит к западу от Луноречья. От прежней фермы, как и от Мёртвой пашни, почти ничего не осталось. Уцелевшие постройки заняли агенты Братства Справедливости, и здесь, на окраине их вотчины, чужаков не ждут.",
        ["Пыльные равнины"] = "Пыльные равнины — самый южный уголок Западного Края, сухая земля на границе с Сумеречным лесом. Здесь стоят лагеря гноллов, а по равнине рыщут койоты и падальщики. На восточном краю возвышается старая башня мага, и с ней тоже не всё ладно: её обжили люди, связанные с Братством Справедливости.",
        ["Великое море"] = "Великое море омывает весь западный берег края. Здесь опасные рифы, о которые разбился не один корабль, — их остовы до сих пор лежат у берега, а в тёмной воде ходят акулы. Ночью над волнами кружит луч маяка, единственный ориентир для тех, кто идёт вдоль этого побережья.",
    },
    ["Зимние Ключи"] = {
        _zone = "Зимние Ключи — заснеженная долина на северо-востоке Калимдора, на склонах горы Хиджал, выше Лунной поляны и восточнее Осквернённого леса. Здесь царит вечная зима: воздух чист и морозен, а над долиной нависают исполинские корни Нордрассила. После Великого Раскола ночные эльфы пытались начать здесь новую жизнь, и от тех времён остались руины Кел'Терила с призраками высокорожденных. Ныне единственный город долины — Круговзор, торговый пост гоблинов картеля Хитрая Шестерёнка, где принимают и Орду, и Альянс. Ночные эльфы держат Деревню Звездопада, фурболги Древобрюхи стерегут проход в Осквернённый лес, а их сородичи из племени Зимней Спячки поддались порче и нападают на всех подряд. В ледяных пещерах Маззорила несут стражу синие драконы, на севере бродят ледопарды, а на юге, в Теснине Зловещего Шепота, затаились демоны Пылающего Легиона.",
        ["Уступ Ледопардов"] = "Уступ Ледопардов — высокая скала на севере Зимних Ключей, где обитает прайд белых ледопардов: детёныши, охотницы и стражи прайда. Ночные эльфы почитают этих зверей, и на самой вершине скалы живёт наставник, обучающий доверенных друзей Альянса приручать ледопардов и ездить на них верхом. Такое доверие нужно заслужить — и у него, и у самих кошек, самых диких и своенравных из всех саблезубов. По преданию, прайдом правит могучая Шай-Ротам, и тому, кто увидит её, суждена удача до конца дней.",
        ["Сокрытая роща"] = "Сокрытая роща — лесистая котловина на северо-востоке Зимних Ключей, со всех сторон окружённая отвесными скалами; попасть внутрь можно лишь через пещеру на юго-восточном склоне гряды. Когда-то здесь водились лишь безобидные белые зайцы, теперь же рощу заполонили обезумевшие совухи, яростно нападающие на любого чужака. Ночные эльфы считают это место священным: друиды помнят, что совухов поставила Элуна охранять её святыни.",
        ["Застава Древобрюхов"] = "Застава Древобрюхов — небольшой лагерь фурболгов на западе Зимних Ключей, через дорогу к юго-востоку от Источников Ледяного Пламени. Название напоминает о временах, когда здесь стояли Древобрюхи, но ныне заставу целиком удерживают их падшие сородичи из племени Зимней Спячки: следопыты, тотемники и стражи берлоги. Древобрюхи из крепости у прохода в Осквернённый лес с горечью говорят, что бывшие союзники обратились против них, и принимают помощь лишь от тех, кто доказал свою верность.",
        ["Деревня Зимней Спячки"] = "Деревня Зимней Спячки — большое поселение фурболгов на востоке Зимних Ключей, к северо-востоку от Круговзора. Племя Зимней Спячки некогда дружило с Древобрюхами, но по странным велениям своего верховного вождя стало нападать на всех, кого встречает; сам вождь укрылся в пещере на вершине деревни. Фурболги пьют «огненную воду» — зелёное зелье, от которого они становятся крупнее и злее, а гонцы носят её сюда из лагеря Мёртвого Леса. Древобрюхи верят, что за порчей сородичей стоит демон, и надеются найти способ исцелить племя.",
        ["Маззорил"] = "Маззорил — огромная ледяная пещера в центральной части Зимних Ключей, к югу от Круговзора и недалеко от озера Кел'Терил. Здесь обитают синие драконы, потомство Малигоса: в туннелях несут стражу драконьи отпрыски-чародеи и юные дракончики, а могучие драконы охраняют руны в глубине пещеры. Хозяйка выводка — затворница, которую видят лишь в облике высшей эльфийки на вершине пещеры, куда ведёт руна-портал в полу. Говорят, синие драконы держат здесь стражу с тех пор, как над вторым Источником Вечности выросло Древо Жизни, — они оберегают Нордрассил снизу, со склонов горы.",
        ["Источники Ледяного Пламени"] = "Источники Ледяного Пламени — цепочка дымящихся горячих озёр на дальнем западе Зимних Ключей, у самого выхода из Крепости Древобрюхов. Посреди вечных снегов эти тёплые воды кажутся чудом: в Зимних Ключах нет вулканов, и дворфийка Донова, разбившая рядом лагерь, пытается понять, откуда взялся жар. Она подозревает, что источники связаны с демонами далеко на юге, в Теснине Зловещего Шепота. К горячим ключам часто приходят фурболги племени Зимней Спячки, так что купаться здесь небезопасно.",
        ["Холмы Ледополоха"] = "Холмы Ледополоха раскинулись к юго-востоку от Круговзора. Здесь живут йети Ледополоха — неповоротливые, но покрытые такой толстой шкурой, что выдерживают любые удары; матриархи и патриархи племени держатся в пещере на склоне, а молодняк бродит по округе. Охотники приходят сюда за густым мехом и рогами йети, а в самой пещере поблёскивают ториевые жилы. Гоблинские инженеры Круговзора тоже присматриваются к местным йети — одна из них мечтает собрать механического йети и разыграть друзей.",
        ["Дун Мандарр"] = "Дун Мандарр — небольшая стоянка у ледяной пещеры на юго-востоке Зимних Ключей. Лагерь разбил дворф Джерон, и дворфийское имя выдаёт, кто дал название этому месту; но стоило ему найти амулет с синими перьями, как совухи пришли в ярость, разгромили лагерь и прогнали его прочь. Теперь среди разбросанных пожитков и брошенного фургона хозяйничают разъярённые совухи, а сам дворф зарёкся соваться сюда без крайней нужды.",
        ["Теснина Ледяного Шепота"] = "Теснина Ледяного Шепота — каньон на юге Зимних Ключей, лежащий прямо перед Тесниной Зловещего Шепота; над пропастью перекинут большой мост, ведущий дальше на юг. По дну ущелья и по гребням над ним разбросаны руины ночных эльфов. Здесь живут великаны ледяного молота — огромные ледяные исполины и их хранители, сильные и яростные. В развалинах древнего храма на юго-восточном гребне обосновался сатир Лоракс, и терпение его лучше не испытывать.",
        ["Совиная чаща"] = "Совиная чаща — цепь пещер на юге Зимних Ключей, где во множестве гнездятся обезумевшие и разъярённые совухи. У входа в чащу стоит лагерь ночной эльфийки Раншаллы, изучающей древние надписи: она полагает, что на вершине гряды скрыт алтарь Элуны, а пять факелов в пещерах отпирают путь к нему. Раншалла хочет узнать, почему совухи так ревностно стерегут это место, и ключ к разгадке, по её мнению, кроется в заклинаниях, переписанных ею с камней в руинах Кел'Терила.",
        ["Озеро Кел'Терил"] = "Озеро Кел'Терил — небольшое замёрзшее озеро в сердце Зимних Ключей. Когда-то здесь стоял город высокорожденных; Великий Раскол обратил его в озеро, которое затем сковало льдом, и теперь из-подо льда торчат лишь верхушки колонн, а большая часть города покоится на дне. Над льдом бродят измученные призраки высокорожденных — они до сих пор ищут осколки реликвии, из-за которой прокляты и навеки прикованы к Кел'Терилу. Это самое большое озеро долины, и самое печальное.",
        ["Руины Кел'Терила"] = "Руины Кел'Терила — остатки великого города ночных эльфов на берегах озера Кел'Терил. Город погиб во время Великого Раскола, и с тех пор здесь бродят страдающие духи высокорожденных, не переживших катастрофы. Их проклятие связано с кристаллом Зин-Малора: высокорожденные некогда похитили его из храма в Азшаре, и осколки кристалла до сих пор лежат где-то во льду. Среди неупокоенных есть один раскаявшийся дух, понимающий, что прошлого не изменить, но всё ещё надеющийся на покой для сородичей.",
        ["Деревня Звездопада"] = "Деревня Звездопада — небольшое поселение ночных эльфов на главной дороге, к северо-западу от Круговзора и южнее Уступа Ледопардов; это единственный оплот Альянса в Зимних Ключах. Здесь стоит эльфийская хижина, домик поменьше и тихая берлога Бен'Таллоу, а торговцы предлагают еду, товары и припасы. Ночные эльфы деревни присматривают за совухами, живущими по соседству, и хранят память о высокорожденных Кел'Терила; вместе с ними здесь трудится дворф Джерон, изучающий руины у озера.",
        ["Берлога Бен'Таллоу"] = "Берлога Бен'Таллоу — курганная берлога ночных эльфов позади Деревни Звездопада. Такие подземелья друиды устраивают для долгого сна, но эта берлога пустует: в её тёмных проходах никто не спит и никто не сторожит покой спящих. Лишь холод да тишина встречают того, кто заглянет внутрь.",
        ["Круговзор"] = "Круговзор — торговый город гоблинов картеля Хитрая Шестерёнка, стоящий на перекрёстке главных дорог Зимних Ключей. Это единственный крупный гоблинский форпост на севере Калимдора: гоблины добывают здесь торий и арканит и торгуют со всеми, кто платит, — с Ордой и Альянсом наравне. В городе есть таверна, банк, аукцион и площадка для гиппогрифов и ветрокрылов, а за порядком следят крепкие вышибалы, готовые заступиться за друзей картеля. Здесь же посланник Серебряного Рассвета Грегор ведёт переговоры с гоблинами, дворф из Братства Тория торгует редкими рецептами, а инженеры вроде Мегги и Харло вечно ищут помощников для своих затей.",
        ["Теснина Зловещего Шепота"] = "Теснина Зловещего Шепота — сеть тоннелей и пропастей на самом юге Зимних Ключей, на склонах, за которыми лежит вершина Хиджала. Воздух здесь тяжёлый и душный, небо темнеет, а из ям поднимаются ядовитые испарения. В теснине засели демоны Пылающего Легиона — остатки войска, штурмовавшего гору Хиджал в Третью войну и бежавшего после гибели Архимонда; ими верховодит демоница Хедерин, чьи слуги источают яд, застывающий в тёмные кристаллы. В одной из пещер прячется бес-торговец экзотическими реагентами, а в глубине ущелья стоит высший эльф, изучающий стихии этого мира.",
        ["Обитель Лунного Ужаса"] = "Обитель Лунного Ужаса — небольшая пещера к северо-востоку от ворот Круговзора, всего в нескольких минутах ходьбы от города. Внутри гнездятся разъярённые совухи, и их крики слышны у самых стен гоблинского форпоста. Хотя отсюда рукой подать до Деревни Зимней Спячки, гора преграждает прямой путь, и к фурболгам приходится ехать в обход.",
    },
    ["Когтистые горы"] = {
        _zone = "Когтистые горы поднимаются между Ясеневым лесом на севере, Степями на востоке и Пустошами на юге. Когда-то здесь были пологие холмы, но Раскол вздыбил песчаник и вознёс к небу острые пики, а ветер и воды Волчьей реки прорезали в камне сеть каньонов. Ветер тут не стихает почти никогда: то бриз с океана, то шквал, поднимающий тучи пыли. Испокон веков горы были родиной гарпий, а Пик Каменного Когтя равно чтили ночные эльфы и таурены: в Третью войну сюда, к Оракулу, приходили и Тралл, и Джайна Праудмур. Ныне гоблины Торговой компании свели лес на Утёсе Ветрорезов и отравили реку, а Обугленная долина выжжена и кишит гарпиями и элементалями. Таурены и орки держат Приют у Солнечного Камня, тролли живут в Малака'джине, ночные эльфы укрепились на Пике, а на юго-востоке бесчинствует племя Зловещего Тотема.",
        ["Приют у Солнечного Камня"] = "Приют у Солнечного Камня укрыт среди скал в сердце Когтистых гор, к югу от Мутного озера. Говорят, в незапамятные времена сам Ан'ше коснулся этой горы, и таурены издревле совершали сюда паломничества: здесь тонка грань между миром живых и миром духов. Ныне это главная застава Орды в горах, где таурены и орки пытаются исцелить землю, изувеченную Торговой компанией. Маггран посылает отсюда воинов против гарпий, Таммра Поле Ветров растит семена Геи, а Мор'рогал тревожится о том, что скрыто под горами. Ветрокрылы летают в Громовой Утёс, на Перекрёсток и в Деревню Ночных Охотников.",
        ["Утес Ветрорезов"] = "Утёс Ветрорезов некогда был долиной вековых деревьев, а теперь это пни, чад и скрежет механизмов. Торговая компания валит здесь лес с невиданной жадностью: по вырубкам ходят механические измельчители, а за лесопилкой у Скалистого озера присматривает прокажённый гном Геренцо, чьё тело наполовину заменено железом. Нечистоты стекают в Волчью реку, и духи земли вопиют от боли. Кела Копье Тени и Гаксим Ржавошиппи стоят лагерем к западу от долины, а гоблин Зиз Физзикс по своим причинам жаждет гибели Геренцо. На севере скрыт Туннель Когтя, ведущий в Ясеневый лес.",
        ["Скалистое озеро"] = "Скалистое озеро лежит в верхней части Утёса Ветрорезов, и отсюда берёт начало Волчья река. Над водой Торговая компания возвела громадное водяное колесо, к которому ведёт башня шатких лесов, и с этой высоты Геренцо надзирает за всей вырубкой. Подняться туда непросто, а внизу, у самой воды, гоблинские механизмы день и ночь перемалывают то, что осталось от леса.",
        ["Мутное озеро"] = "Мутное озеро раскинулось в самом центре Когтистых гор, и от него расходятся дороги во все уголки края: к Пику Каменного Когтя, к Утёсу Ветрорезов и на юг по Паучьему тракту. В его водах плодится слизь, а в скалах над озером гнездятся виверны. Таурены верят, что земля здесь особенно сильна: у самой кромки воды находят семена Геи, способные вернуть жизнь выжженной земле. Ходят слухи, что орки тайно собирают у озера яд виверн для отравленных клинков.",
        ["Обугленная долина"] = "Обугленная долина на западе гор когда-то была цветущей рощей, а ныне от деревьев остался лишь пепел. Торговая компания разорила её и разгневала духов: из-под земли вырвались элементали огня, а почерневшие древние стражи леса обезумели от горя. Здесь гнездится стая гарпий Кровавой Ярости, откуда расселяются гарпии по всему Калимдору, а среди углей рыщут обожжённые василиски и химеры. И всё же таурены Приюта и друиды Пика не теряют надежды: в плодородную землю они сажают семена Геи, чтобы круговорот жизни продолжился.",
        ["Долина Кровавой Ярости"] = "Здесь, среди отвесных стен каньона, испокон веков гнездится стая гарпий Кровавой Ярости. Скалы усеяны их гнёздами, а на дне ущелья белеют кости тех, кто не сумел уйти. Мало кто возвращался отсюда живым, и те, кому это удалось, советуют одно: не поднимать шума.",
        ["Пик Каменного Когтя"] = "Пик Каменного Когтя, высочайшая вершина гряды, издревле священен и для ночных эльфов, и для тауренов. В Третью войну сюда приходили Джайна Праудмур и Тралл, ища в пещерах горы совета Оракула. Ныне в зелёной долине на вершине, среди древних эльфийских руин, стоит единственная застава Альянса в горах: её хранит Хранитель Албагорм, гостей принимает таверна Фаралии, а гиппогрифы уносят путников в Аубердин, Астранаар и Пустоши. Эльфам помогают дриады и хранители рощи, а в недрах горы скрыта Пещера Когтей, где спят друиды.",
        ["Пещера Когтей"] = "Пещера Когтей — курган друидов, вырытый в недрах Пика Каменного Когтя. Здесь, под присмотром дриад, хранителей рощи и кенарийских смотрителей, спят друиды, странствуя по Изумрудному Сну. В коридорах кургана порхают волшебные дракончики, а сокровища и могущественные предметы друиды укрыли в хитроумных тайниках. Ключами к ним ведает дриада Ринтариэль, Хранительница Ключей, и Орда давно точит на неё зуб.",
        ["Долина Высокого леса"] = "Долина Высокого леса лежит в предгорьях на востоке, там, где Когтистые горы спускаются к Степям. Среди редких сосен здесь ещё сохранился настоящий лес, и именно через эту долину идёт дорога с Перекрёстка. У её края стоит лагерем шаманка Орды Сирит Камнелом, слышащая стенания духов этих гор. Но покоя в долине нет: по ней рыщут отступники племени Зловещего Тотема, разорившие соседнюю деревню тауренов.",
        ["Волчья река"] = "Волчья река берёт начало у Скалистого озера и течёт через весь Утёс Ветрорезов до Рудника Ветрорезов. Некогда её воды точили песчаник, вырезая в горах каньоны; теперь в неё сливают масло и отходы гоблинских лесопилок, и река стала чёрной и зловонной. Таурены и орки говорят, что земля кричит от этой отравы.",
        ["Паучий тракт"] = "Паучий тракт — главная дорога юга Когтистых гор, тянущаяся от Малака'джина на север до Мутного озера. Название своё она заслужила честно: по обочинам бродят моховые пауки, а деревья над тропой оплетены их сетями. Тролли Малака'джина жалуются, что по ночам восьминогие твари пробираются к их стоянкам и воруют добычу. От тракта ответвляются тропы в Сиширский каньон и в Ущелье Камнепадов.",
        ["Туннель Когтя"] = "Туннель Когтя — извилистый проход под горами, соединяющий Утёс Ветрорезов с Ясеневым лесом у озера Мистраль. В темноте здесь тихо: ни зверя, ни человека, лишь тупики и странные ниши в стенах. Над пещерой ещё можно различить остатки старой дороги, по которой когда-то ходили поверху.",
        ["Рудник Ветрорезов"] = "Рудник Ветрорезов вырыт на восточной окраине Утёса Ветрорезов, там, где кончается Волчья река. Торговая компания добывает здесь олово руками кобольдов, что копошатся в штольнях и не терпят чужаков. Говорят, в глубине рудника гоблины хранят свои бумаги и письма.",
        ["Застава Зловещего Тотема"] = "Застава Зловещего Тотема на юго-востоке гор — оплот отступников-тауренов, не признающих единения племён под властью Кэрна Кровавого Копыта. Здесь правит свирепый Грундиг Тёмное Облако, а вокруг патрулируют громилы, бузотёры, наёмники и колдуны племени. Отсюда Зловещие Тотемы напали на соседний Лагерь Апарахе и увели пленных.",
        ["Лагерь Апарахе"] = "Лагерь Апарахе на юго-востоке гор был мирной деревней тауренов, пока сюда не пришли воины Зловещего Тотема под началом Грундига Тёмное Облако. Почти всех жителей перебили; уцелевший Макаба Плоское Копыто скитается у границы гор и ищет свою дочь Кайю. Теперь у большого красного тотема хозяйничают захватчики.",
        ["Малака'джин"] = "Малака'джин — небольшая деревня троллей Чёрного Копья на юге Когтистых гор, у границы со Степями. Здешние охотники живут с земли и продают добычу проезжим воинам Орды; за целебными зельями сюда шлют гонцов даже из лагерей Степей. В пещере деревни обитает знахарь Джин'Зил: в клетках у него томятся пленные ночные эльфы, а в котле варится его лесная магия. По ночам к стоянкам подкрадываются моховые пауки с Паучьего тракта, и Ксен'Зилла рад любой помощи.",
        ["Ущелье Камнепадов"] = "Ущелье Камнепадов — тихая расселина к востоку от Паучьего тракта, ведущая к Пещере Камнепадов. Здесь бродят горные бараны, в скалах попадаются жилы руды, а напротив пещеры темнеет заброшенный грот с бочками и грубыми росписями на стенах, похожими на тауренские.",
        ["Сиширский каньон"] = "Сиширский каньон целиком захвачен пауками из густого мха. Стены и дно затянуты паутиной, повсюду лежат кладки яиц, а в глубине каньона ждёт Бесселет, самая крупная и злобная из здешних тварей. Маггран из Приюта у Солнечного Камня назначил за неё награду, но дорога сюда опасна даже для бывалого путника.",
        ["Пещера Камнепадов"] = "Пещера Камнепадов в конце одноимённого ущелья кишит кобольдами. Они лихорадочно копают редкие кристаллы резонита, светящиеся лиловым светом и хранящие след древней магии земли, и защищают их ценой жизни. Мор'рогал из Приюта у Солнечного Камня чует в этой пещере неладное: что-то беспокойное таится под горами.",
    },
    ["Красногорье"] = {
        _zone = "Красногорье лежит к востоку от Элвиннского леса, там, где земли Штормграда упираются в красные скалы предгорий, а на севере за перевалом дымятся Пылающие степи. В сердце края лежит Озеро Безмолвия, а на его берегу стоит Приозерье, единственный оплот людей в этих горах. Времена тревожные: орки клана Чёрной Горы спустились из степей и захватили крепость Каменной Стражи, а беженцы с северных земель набились в город. Подкрепления из Штормграда так и не пришли, и мировой судья Соломон шлёт гонцов к соседям в надежде на помощь. В холмах воют гноллы стаи Красногорья, на востоке чародей Моргант из башни Илгалара повелевает гноллами Темношкурами, а в озере расплодились мурлоки. И всё же город держится: маршал Маррис у моста собирает добровольцев, а кузнец Вернер Осгуд куёт оружие для защитников края.",
        ["Озеро Безмолвия"] = "Озеро Безмолвия раскинулось в самом сердце Красногорья, и его прозрачные лазурные воды отражают красные склоны гор. На западном берегу стоит Приозерье, а с востока озеро вытекает рекой, что бежит мимо тёмной крепости Каменной Стражи. Когда-то эти воды славились рыбной ловлей, но теперь по берегам селятся всё новые племена мурлоков. Дети Приозерья по-прежнему удят рыбу с причала, хотя родители и пугают их чудовищами, живущими в глубине.",
        ["Приозерье"] = "Приозерье, небольшой городок людей на берегу Озера Безмолвия, остаётся единственным поселением королевства во всём Красногорье. В ратуше заседает мировой судья Соломон, а в таверне у пристани всегда полно народу. Город переполнен беженцами с северных земель, спасающимися от орков клана Чёрной Горы, а подкрепления из Штормграда так и не пришли. У моста маршал Маррис набирает добровольцев, кузнец Вернер Осгуд куёт оружие, а штейгер Ослоу никак не может достроить Мост Безмолвия: не хватает железа.",
        ["Водопад Каменной Стражи"] = "Здесь река, вытекающая из Озера Безмолвия, обрывается с уступа под стенами Каменной Стражи и наполняет глубокое озерцо в укромной восточной складке гор. Шум воды не смолкает ни днём, ни ночью, а над ним нависает захваченная орками крепость. У воды поселилось небольшое племя мурлоков: они ловят рыбу в заводи и строят из веток и тростника грубые хижины. Место тихое и красивое, но чужак здесь всегда под чьим-то взглядом.",
        ["Каньоны Красногорья"] = "Каньоны Красногорья прорезают северо-западную часть края: узкие проходы между красных скал, где эхо разносит каждый шаг. Здесь логово Изувоя, вожака гноллов стаи Красногорья, чей вой слышен даже в холмах над Приозерьем. Его громилы и мистики спускаются к городу, воруют лошадей из конюшен и грабят обозы на дорогах. Кузнец Вернер Осгуд уверен, что без вожака стая разбежится, но Изувой не зря возглавляет её.",
        ["Башня Илгалара"] = "На восточной окраине Красногорья возвышается башня Илгалара, обитель чародея Морганта. Некогда он заключил союз с орками Чёрной Горы и помог им взять крепость Каменной Стражи, но вскоре обратился против бывших соратников и укрылся в этой башне. Тайной магией он подчинил себе гноллов стаи Темношкуров, и теперь они стерегут подступы к его жилищу. Из башни Азоры в Элвиннском лесу за Моргантом следит его соперник Теокрит, а у подножия башни стоит статуя льва.",
        ["Лесопилка Альтера"] = "Лесопилка Альтера стоит у дороги к северо-востоку от Приозерья, среди сосен на склоне холма. Работа здесь давно остановилась: пилы молчат, брёвна гниют, а по двору бродят гноллы да шныряют пауки. Заброшенное место облюбовали и люди с сомнительной репутацией: старый плут Люций, что проводит дни на пристани Приозерья, хранит здесь сундук и посылает сюда учеников оттачивать ловкость рук.",
        ["Пещеры Ретбана"] = "Пещеры Ретбана уходят глубоко в скалы в холмах к северу от Приозерья. Они названы в честь Барта Ретбана, первооткрывателя тёмной руды: металл из неё мягче железа, зато переписчики делают из неё чернила приятного тёмного цвета. Из-за набегов орков жители города забросили добычу, и теперь в пещерах хозяйничают гноллы стаи Красногорья, а их работяги сами копают руду. В таверне Приозерья дворф Йорус Ячменовар предлагает смельчакам испытание: дойти до первой развилки пещер и вернуться за час.",
        ["Лагерь Ренда"] = "Лагерь Ренда раскинулся на северо-западе Красногорья, у самого перевала в Пылающие степи. Это форпост орков клана Чёрной Горы: отсюда они спускаются в долины, устраивают засады на дорогах и грабят земли к северу от озера. Здесь стоят самые сильные орки края, а дорога через лагерь ведёт к выжженным пустошам, над которыми властвует Чёрная гора. Из Приозерья грифоны летают над этими горами на север, к Дозору Моргана.",
        ["Долина Ренда"] = "Долина Ренда лежит на юго-востоке Красногорья, за озером и рекой, вдали от дорог. Здесь орки клана Чёрной Горы разбили второй лагерь, поменьше и послабее северного, но вести о нём уже дошли до Приозерья, и маршал Маррис велит бить орков без колебаний, где бы они ни встретились. К югу от озера летают чёрные дракончики, и кузнец Вернер Осгуд охотно платит за чешую с их брюха.",
        ["Скала Ренда"] = "Скала Ренда, большая пещера в северо-западных горах Красногорья, лежит рядом с лагерем орков у перевала в Пылающие степи. Внутри засели сильные воины клана Чёрной Горы, и соваться сюда в одиночку не стоит. В этой пещере орки держат пленных: среди них капрал Кеешан, тяжело раненный солдат Штормграда, чей отряд попал в окружение. Он ждёт, что кто-нибудь из сторонников Альянса поможет ему добраться до города.",
        ["Башня Каменной Стражи"] = "Башня Каменной Стражи стоит при одноимённой крепости, вторая часть старого людского укрепления на восточном берегу озера. Прежде её держали стражники Приозерья, но вместе с крепостью башня досталась оркам клана Чёрной Горы, и теперь на её ярусах несут дозор подручные Гат'Илзогга. Это единственная уцелевшая башня рядом с крепостью, и с её вершины видны и озеро, и восточные долины. Чародей Теокрит из башни Азоры знает, что Моргант враждует с орками крепости, и ищет способ подслушать их отсюда.",
        ["Долина Галарделл"] = "Долина Галарделл лежит на северо-востоке Красногорья, в стороне от озера. Над ней возвышается башня Илгалара, где обосновался чародей Моргант, а сама долина кишит гноллами стаи Темношкуров, которых он подчинил своей тайной магией. Ими командует лейтенант Фангор, объявленный в Приозерье предателем Штормграда: стоит напасть на него, и он созывает на помощь всю стаю. Мировой судья Соломон приговорил его к смерти и назначил награду тому, кто принесёт его лапу в ратушу.",
        ["Озерный тракт"] = "Озёрный тракт, старая дорога, огибает Озеро Безмолвия с юга. До Первой войны по ней шли обозы и путники, но с тех пор как орки взяли крепость Каменной Стражи, тракт опустел. Теперь вдоль южной дороги стоят лагеря гноллов стаи Красногорья: браконьеры и полукровки подстерегают редких прохожих. Заместитель судьи Фелдон обходит участок к югу от моста, но людей у города не хватает, и дорога считается небезопасной.",
        ["Три Угла"] = "Три Угла, перекрёсток на самом западном краю Красногорья, лежит сразу за границей Элвиннского леса. Отсюда три дороги расходятся к трём городкам: на запад в Златоземье, на восток в Приозерье и на юго-запад через мост в Темнолесье, что в Сумеречном лесу. Посреди перекрёстка стоит сторожевая башня стражи Штормграда, и отсюда путник впервые видит красные скалы. Стражник на посту говорит, что на дороге пока спокойно, но к северу и востоку он замечал лагеря гноллов.",
        ["Крепость Каменной Стражи"] = "Крепость Каменной Стражи стоит на восточном берегу Озера Безмолвия, там, где река покидает озеро. Её выстроили люди Приозерья для защиты края, но орки клана Чёрной Горы, спустившиеся из Пылающих степей, взяли её штурмом с невиданной яростью: им помогала тёмная магия чародея Морганта. Теперь здесь засел вождь орков Гат'Илзогг, отсюда его воины грабят земли к северу от озера, а отступники Тарил'зуна устраивают засады на дороге между городом и крепостью. Чародеи Чёрной Горы принесли сюда полуночные сферы, источники тёмной силы. Мировой судья Соломон объявил Гат'Илзогга в розыск, и награда за его голову ждёт смельчака.",
    },
    ["Кратер Ун'Горо"] = {
        _zone = "Кратер Ун'Горо — огромная зелёная чаша на юге Калимдора, зажатая между пустынями Танариса и Силитуса. Со всех сторон его окружают отвесные стены, и путник, спустившийся с раскалённых песков, будто попадает в другой мир: здесь парят влажные джунгли, гремят водопады и бродят ящеры, каких не встретишь больше нигде в Азероте. Посреди кратера дымит вулкан, у подножия которого рыщут элементали огня, а на гребнях стен стоят три древних пилона, чьё назначение не разгадал никто. Учёные считают эту землю древней лабораторией титанов: по всему кратеру рассыпаны кристаллы Силы, а в свитках киражи Ун'Горо назван «Землёй Богов», куда их полчища так и не смогли ступить. Единственный приют для смертных — Укрытие Маршалла, пещера в северной стене, где остатки разбитой экспедиции изучают здешние чудеса. На юге гудит улей силитидов, а на Пути Ужаса хозяйничают дьявозавры.",
        ["Вулкан Огненного Венца"] = "Вулкан Огненного Венца возвышается в самом сердце кратера. По его склонам стекает лава, среди обугленных камней бродят элементали огня, а на вершине, в пещере, обитает сильнейший из них — Яропламень, к чьему логову не решаются подходить даже исследователи: многие смельчаки сгинули в расщелинах сердца кратера. Жар вулкана греет всю чашу Ун'Горо: неглубокие жилы магмы тянутся под землёй и питают гейзеры источников Голакка. В пещере у южного подножия укрылся гном Ринго, забредший сюда из любопытства и едва живой от зноя.",
        ["Смоляные ямы Лаккари"] = "Смоляные ямы Лаккари лежат на севере кратера, к югу от Укрытия Маршалла, там, где редеют деревья. Чёрная вязкая смола выглядит обманчиво спокойной, но ноги увязают в ней, и зверь, ступивший слишком близко, уже не выбирается: из ям торчат кости сотен ящеров, иные древнее любой памяти. Вокруг кружат падальщики в ожидании лёгкой добычи, а сама смола порой шевелится — из неё поднимаются твари, слепленные из чёрной жижи и костей. Исследователи ценят эти места: вырытые здесь кости рассказывают о временах, когда кратер был ещё молод.",
        ["Путь Ужаса"] = "Путь Ужаса тянется по юго-западу кратера, между источниками Голакка и Скользким оврагом. Имя оправдано: здесь водятся самые крупные и свирепые твари Ун'Горо — исполинские панцирные ящеры, диметрадоны, жутедактили и дьявозавры, чьи шаги слышны задолго до того, как покажется сам зверь. Среди зарослей встречаются странные каменные глыбы, которые дворфы экспедиции считали следами титанов, но рассмотреть их вблизи так никто и не сумел. На восточной кромке остался брошенный лагерь экспедиции, а среди камней здесь находят красные кристаллы Силы.",
        ["Скользкий овраг"] = "Скользкий овраг — глубокая расселина на юге кратера, изрытая ходами силитидов. Здесь живёт рой Гориши: рабочие и осы стерегут кладки яиц в тёплых сырых туннелях, а из глубины улья тянется гул, от которого дрожит земля. Насекомые не терпят чужаков и бросаются на любого, кто ступит на их землю, но преследовать беглеца за пределы оврага не станут. Учёные из Укрытия Маршалла заметили, что улей вырос как раз там, где у кратера недостаёт южного пилона, и гадают, что бы это могло значить.",
        ["Укрытие Маршалла"] = "Укрытие Маршалла — пещера в северной стене кратера и единственное подобие поселения в Ун'Горо. Сюда отступила экспедиция Маршалла, когда её лагеря на равнине растоптали ящеры: теперь исследователи живут в шатрах под сводом скалы, изучают кратер и мечтают выбраться отсюда живыми. В глубине пещеры мерцают кристаллы Силы, над которыми колдует гномка Джей Ди, составившая руководство к пилонам, а у входа сидит гном Линкен, потерявший память и не помнящий, зачем ему меч. Рядом жуёт листья кодо Даданга, а над лагерем кружат жутедактили, которых здесь боятся больше всего. Отсюда летают в Прибамбасск и в Оплот Кенария.",
        ["Пещера Лишайников"] = "Пещера Лишайников — большой грот в северо-восточной стене кратера, недалеко от Укрытия Маршалла. Его своды поросли светящимися грибами, а в полумраке живут обезьяны Ун'Горо — одни из немногих зверей кратера, не покрытых чешуёй. Они яростно защищают своё логово и гонят прочь всякого ящера, а вожак Уча, огромная рыжая обезьяна с зубами-кинжалами, считается самым грозным зверем этих пещер. У входа, возле маленького водопада, стоит механическая обезьяна Чи-Та 3 — творение гномки Карны, которая мечтает изучить племя обезьян изнутри.",
        ["Горячие источники Голакка"] = "Горячие источники Голакка лежат на западе кратера, к северу от Пути Ужаса. Вода здесь кипит и бьёт из земли гейзерами: неглубокие жилы магмы, идущие от вулкана Огненного Венца, греют озёра, и над ними круглые сутки стоит пар. У берегов бродят элементали, рождённые кипятком и жаром, а исследователь Кракл, забравшись сюда с термометром, вычисляет, как связаны источники с вулканом. Тёплая вода, говорят, годится и для любовных зелий — если кому-то хватит смелости её зачерпнуть.",
        ["Топи"] = "Топи занимают юго-восток кратера — это первое, что видит путник, спустившийся из Танариса. Влажные низины поросли высокой травой и тростником, а между лужами снуют равазавры — стремительные ящеры, среди которых немало ядовитых. На высоком холме разбил стоянку таурен-следопыт, выслеживающий чудовище Лар'корви, огромную тварь с зубами, подобными булатным клинкам, а на другом склоне тролль-укротитель приручает равазавров. Только здесь среди камней находят синие кристаллы Силы.",
        ["Плато Железного Камня"] = "Плато Железного Камня — полоса голого камня на северо-восточной кромке кратера, у самой стены. Здесь почти не растёт лес, зато на уступах гнездятся молодые жутедактили, и их крики разносятся над всей северной частью Ун'Горо. Место уединённое и на удивление тихое; отсюда открывается вид на топи и вулкан.",
        ["Угодья"] = "Угодья — участок кратера, вытоптанный исполинскими ящерами Ун'Горо. Земля здесь утрамбована тяжёлыми шагами, трава примята, и тот, кто прислушается, различит далёкий гул — стадо на марше.",
        ["Терраса Создателя"] = "Терраса Создателя — площадка, вырубленная в скалах кратера, где среди стен стоят машины титанов. Их металл не тронут временем: устройства гудят, по назначению неясные, и с террасы видна вся чаша Ун'Горо. Учёные полагают, что именно отсюда создатели наблюдали за своими творениями и что кратер — древняя лаборатория, где выводили жизнь. Пилоны и кристаллы Силы, рассыпанные внизу, — лишь часть этого замысла.",
        ["Столп поглощения"] = "Столп поглощения — сооружение титанов на террасе: каменная колонна, покрытая рунами и окутанная гудящей энергией. Что именно она поглощает и зачем, знали лишь те, кто её возвёл; смертным остаётся лишь смотреть и не касаться.",
    },
    ["Лок Модан"] = {
        _zone = "Лок Модан лежит к востоку от Дун Морога, в восточной части Каз Модана. Здесь теплее, чем в заснеженных горах у Стальгорна: серые скалистые хребты обступают долину со всех сторон, а склоны поросли сосной и берёзой. Сердце этих земель — огромное озеро Лок, чьи воды удерживает Каменная Плотина, одно из величайших творений дворфийских зодчих. Край видел немало крови: во Вторую войну орки Орды захватили Лок Модан, и дворфы Стальгорна отвоевали его лишь после долгих боёв. Ныне главную угрозу несут трогги, потревоженные раскопками и расселившиеся по окрестным пещерам, кобольды в старых шахтах и огры клана Мо'грош на северо-восточном берегу. На юге всё чаще замечают дворфов Чёрного Железа. Единственный город здесь — Телсамар, откуда горные пехотинцы несут дозор на дорогах и перевалах.",
        ["Раскопки Сталекрута"] = "К востоку от озера, среди древних руин, Лига исследователей ведёт обширные раскопки под началом геолога Сталекрута. Из-под земли здесь показались каменные стражи и своды, возведённые задолго до прихода дворфов. Но работы почти остановились: из потревоженных глубин вышли трогги, необычайно крупные и свирепые, и выгнали рудокопов с площадки. Учётчик Магмар Рудокол ведёт отчётность о ходе работ, а припасы из Стальгорна расходуются впустую.",
        ["Оплот Мо'грош"] = "Пещеры на северо-восточном берегу озера заняли огры клана Мо'грош. Среди старых руин они устроили курганы и ходят оттуда в набеги на Телсамар, Каменную Плотину и раскопки. Возглавляет их Чок'сул, за голову которого магистрат Телсамара назначил награду. Подкрепление из Стальгорна придёт нескоро, поэтому городу приходится надеяться на наёмников и странствующих искателей приключений. У огров находят и странные кристаллы, которые они добывают в своих пещерах.",
        ["Телсамар"] = "Телсамар стоит на западном берегу озера Лок и остаётся единственным городом Лок Модана. Дворфы и гномы живут здесь под властью Стальгорна, а порядок блюдёт мировой судья Тупонос. В городке есть таверна, кузница с наковальней, конюшня и кладбище, а грифоны с площадки летают в Стальгорн и в Гавань Менетилов. По дороге через Телсамар ходит дозором горный пехотинец Кэдрелл. Городок славится кровяными колбасками, а вечерами в таверне собираются путники со всей округи.",
        ["Врата Альгаза"] = "Врата Альгаза — верхняя часть тоннеля, прорубленного дворфами в северных горах Лок Модана. Отсюда дорога уходит вниз, к Болотине и Гавани Менетилов, единственному порту дворфийских земель. Когда орки клана Драконьей Пасти заняли нижний перевал, горные пехотинцы отступили именно сюда, к верхней части тоннеля, и держат здесь заслон. Путникам советуют не сходить с дороги и не задерживаться.",
        ["Каменная Плотина"] = "Каменная Плотина перегородила северную оконечность озера и вдвое увеличила его размеры, а излишки воды превратили низины Болотины в топи. Дворфы считают её одним из чудес света, хотя мало кто помнит, что способ каменной кладки для неё придумал зодчий из клана Чёрного Железа. Ныне плотину охраняют хуже прежнего: большая часть стражи ушла воевать за Альянс, а по восточной стороне дамбы всё чаще крадутся дворфы Чёрного Железа, и главному инженеру не до сна.",
        ["Приют Странников"] = "В юго-восточных холмах Лок Модана стоит охотничий домик, построенный в изящном стиле высших эльфов, хотя из эльфов здесь остался лишь один. Приютом Странников заправляет седой дворф Марек Железносерд, а вместе с ним тут живут люди, гномы и дворфы, промышляющие охотой. Гости приезжают ради знаменитых кроколисков озера Лок: их шкуры и мясо охотно скупают торговцы. Молодой Дэрил Юный любит похвастать своими подвигами и охотно бросает вызов новичкам.",
        ["Рудник у Серебряного ручейка"] = "Рудник у Серебряного ручейка лежит в северной части Лок Модана, между станцией Альгаз и Каменной Плотиной. Некогда он щедро давал серебро дворфам Стальгорна, но давно выработан, и Лига рудокопов превратила штольни в склад для своих инструментов. Теперь рудник кишит кобольдами-крысами, которые растащили ящики с оборудованием по всем ходам. За рудником до сих пор ржавеют разбитые орочьи повозки и катапульты, оставшиеся от прежних войн.",
        ["Озеро Лок"] = "Озеро Лок — самое большое озеро Каз Модана и одно из крупнейших в известном мире. Своими размерами оно обязано Каменной Плотине, удерживающей талые воды гор. На островах посреди озера гнездятся кроколиски, а в глубинах ходят трешадоны и стаи прожорливых рыб. На дне и на отмелях до сих пор лежат обломки катапульт и баллист, оставшиеся со Второй войны, когда орки Орды сражались здесь с дворфами. Недавно над озером видели гномский летательный аппарат, пропавший вместе с пилотом.",
        ["Дун Альгаз"] = "Дун Альгаз — извилистый горный перевал, ведущий из Лок Модана вниз, к Болотине. Во Вторую войну здесь стоял последний оплот Орды в Каз Модане, а после войны дворфы обустроили в проходе сторожевой пост. Недавно орки клана Драконьей Пасти вышли из укрытий в холмах и захватили перевал, вынудив горных пехотинцев отступить к верхнему тоннелю. Теперь дорога между дворфийскими землями и Гаванью Менетилов стала опасной, и Лок Модану грозит оказаться отрезанным от порта.",
        ["Северные врата"] = "Северные врата — тоннель, пробитый сквозь горы между высокогорным Дун Морогом на западе и Лок Моданом на востоке. Этим путём чаще всего идут те, кто направляется к Болотине: отсюда ближе всего до спуска с озёрных высот. На дун-морогской стороне прохода стоит застава горных пехотинцев, а на восточном выходе дорога ведёт к станции Альгаз и рудникам северного берега.",
        ["Южные врата"] = "Южные врата соединяют Дун Морог с юго-западом Лок Модана и выводят путника в Долину Королей. Посреди перевала стоит застава горных пехотинцев Стальгорна, которые давно очистили окрестности от опасного зверья, так что здесь спокойнее, чем у северных соседей. Через заставу проходит большинство путников, идущих в Телсамар или из него. Среди пехотинцев служит и Велларт Ячменовар из известной семьи пивоваров.",
        ["Долина Камнедробов"] = "Долина Камнедробов врезается в горы на юго-западе Лок Модана. Когда-то это было тихое место, но теперь склоны и пещеры кишат троггами клана Камнедробов, которых потревожили дворфийские раскопки. Разведчики выяснили, что тварей привёл к озеру вождь по имени Громаг, и его ни на шаг не покидают два стража, Скрежетун и Буян. Дворфы надеются, что без вождя троггов удастся загнать обратно под землю.",
        ["Долина Королей"] = "Долина Королей лежит в юго-западном углу Лок Модана, у выхода из Южных врат. Над зелёной долиной возвышаются две огромные статуи дворфийских королей из кланов Бронзобородов и Громового Молота: после смерти отцов их сыновья вместе заказали эти изваяния, чтобы те вечно стерегли проход в южные земли. Отсюда же начинается путь в Тлеющее ущелье, но ворота туда заперты и охраняются. В сторожевой башне капитан Ругельфасс собирает молодых дворфов на войну с троггами.",
        ["Станция Альгаз"] = "Станция Альгаз — застава горных пехотинцев в северо-западной части Лок Модана, к востоку от Северных врат и к югу от перевала Дун Альгаз, по которому она и названа. Здесь у сторожевой башни несёт службу горный пехотинец Грингер Грозовая Вершина, а оружейник чинит доспехи путникам. Пехотинцы приглядывают за дорогой к Болотине и за выработанным рудником у Серебряного ручейка, куда пробрались кобольды.",
        ["Хребет Седых Лап"] = "Хребет Седых Лап поднимается к югу от Телсамара и к востоку от Долины Камнедробов. Эти скалы облюбовала большая стая медведей, и самый грозный из них — Старина Черношкур, огромный зверь, который порой спускается из своего логова к подножию долины. Год назад весь Приют Странников выходил на него охотой, но никому не посчастливилось его одолеть.",
        ["Таверна \"Крепкое пойло\""] = "Таверна \"Крепкое пойло\" — сердце Телсамара и самое людное место во всём Лок Модане. Здесь можно снять комнату, отогреться у очага и попробовать местные кровяные колбаски под кружку дворфийского эля. За столами собираются горные пехотинцы после дозора, охотники с озера и путники, идущие между Стальгорном и Гаванью Менетилов, чтобы обменяться новостями и байками.",
    },
    ["Лунная поляна"] = {
        _zone = "Лунная поляна — укромная долина в горах северного Калимдора, между Оскверненным лесом и Зимними Ключами. По суше сюда ведут лишь туннели фурболгов-Древобрюхов, и чужаки редко находят дорогу в это святилище друидов. В древности здесь обитал полубог Кенарий, и по сей день Лунная поляна остаётся домом Круга Кенария: ночные эльфы и таурены вместе служат природе, и вражда Альянса с Ордой не имеет здесь силы. Посреди долины лежит озеро Элуне'ара, на его берегу стоит селение Ночная Гавань, а на северо-востоке — кельи, где в Изумрудном Сне спит Малфурион Ярость Бури. Стражем Лунной поляны служит хранитель Ремул, сын Кенария. Раз в год друиды открывают долину всем народам: на Лунный фестиваль сюда съезжаются праздновать древнюю победу над Легионом, а из глубин озера поднимается безумный Омен.",
        ["Озеро Элуне'ара"] = "Озеро Элуне'ара занимает середину Лунной поляны и названо в честь самой Элуны. Его вода прозрачна и чиста, и в ней, словно в зеркале, отражаются звёзды и луна. На северном берегу стоит Ночная Гавань, а молодые друиды ищут на дне озера реликвии, постигая облик водных существ. Но в глубине спит Омен — древний волк, благословлённый Элуной и потерявший рассудок от ран Войны Древних. Каждый год, когда приходит Лунный фестиваль, он поднимается из вод, и герои вновь возвращают его в озеро.",
        ["Ночная Гавань"] = "Ночная Гавань — главное селение Лунной поляны, стоящее на берегу озера Элуне'ара. Это посёлок ночных эльфов с каменными стенами и лунными колодцами, и живут здесь друиды Круга Кенария. Обычно Гавань закрыта для чужих: попасть сюда легко лишь друидам, которые переносятся сюда заклинанием, а гиппогрифы отсюда летают только в Рут'теран и Громовой Утёс. Здесь наставляет молодых друидов Дендрит Блеск Звёзд. Раз в год селение оживает: на Лунный фестиваль друиды принимают и Альянс, и Орду, и над озером гремят фейерверки — знак силы Элуны.",
        ["Святилище Ремулоса"] = "К западу от Ночной Гавани, в нескольких минутах пути, стоит Святилище Ремулоса. Здесь обитает хранитель Ремул, сын полубога Кенария и страж Лунной поляны. Он присматривает за друидами, погружёнными в спячку, и наставляет Круг Кенария в деле сохранения природы и равновесия. Молодые друиды приходят к святилищу за советом и за первыми уроками, и само это место считается одной из опор Круга.",
        ["Кельи Малфуриона"] = "На северо-восточной окраине Лунной поляны лежат священные кельи, названные в честь Малфуриона Ярость Бури. Под курганами спят друиды ночных эльфов, чей дух странствует в Изумрудном Сне. В Третью войну Плеть Тикондруса рвалась сюда, чтобы добраться до спящего Малфуриона, но Тиранда успела разбудить его, и он повёл друидов на защиту Хиджала. После войны верховный друид вновь ушёл в Сон и не вернулся: его тело покоится здесь, под охраной Круга Кенария и Сестринства Элуны, а руководство друидами принял Фэндрал Олений Шлем.",
    },
    ["Мулгор"] = {
        _zone = "Мулгор — зелёная долина, укрытая горами со всех сторон; единственный проход из неё ведёт на восток, в Степи. Это исконная земля тауренов: среди высоких плато и травяных равнин они кочевали долгие века, отбиваясь от кентавров. После Третьей войны Кэрн Кровавое Копыто заключил союз с Траллом, изгнал кентавров с равнин и возвёл на вершинах утёсов Громовой Утёс — столицу своего народа. На юге, на плато Красного Облака, учат молодых охотников, а в сердце долины у озера Каменного Быка стоит деревня Кровавого Копыта. По равнинам бродят кодо, долгоноги, волки прерий и пумы плоскогорья. Но и в этом мирном краю есть тревоги: свинобразы Дыбогривы захватили Ежевичную лощину и священные Красные скалы, гоблины Торговой компании отравили колодцы и роют рудник в восточных горах, а на гребнях гнездятся гарпии Ярости Ветра.",
        ["Плато Красного Облака"] = "Плато Красного Облака поднимается над южным Мулгором высокими обрывами, и молодые таурены делают здесь первые шаги, прежде чем спуститься в долину. Охотничье мастерство здесь — предмет особой гордости: племя добывает мясо и перья равнинных долгоногов. С северо-востока на плато напирают свинобразы Дыбогривы из Ежевичной лощины, и юные храбрецы учатся защищать родную землю. Спуск с плато ведёт по тропе на север, к дороге в деревню Кровавого Копыта.",
        ["Лагерь Нараче"] = "Лагерь Нараче стоит на северном краю плато Красного Облака — это селение племени Соколиного Ветра, где начинают свой путь юные таурены. Вождь Соколиный Ветер посылает молодых на первые испытания, а его сын Грулл ведёт охоту на равнинных долгоногов. Здесь же начинаются Обряды Матери-Земли — три испытания, которыми юный таурен заслуживает уважение старейшин Громового Утёса. Провидица Воронье Перо ведёт молодых шаманов к зову земли.",
        ["Деревня Кровавого Копыта"] = "Деревня Кровавого Копыта лежит в самом сердце Мулгора, в подкове озера Каменного Быка, и названа в честь племени Кровавого Копыта. Здесь правит Бейн, сын Кэрна, и сюда приходят молодые таурены, спустившиеся с плато Красного Облака. В деревне приручают диких кодо и продают их как ездовых животных. Мулл Громовой Рог создаёт тотемы для очищения отравленных колодцев, Зарельман Две Луны хранит обряд Прозрения, а на дороге к востоку Морин Ловец Облаков следит за Торговой компанией.",
        ["Озеро Каменного Быка"] = "Озеро Каменного Быка длинной подковой охватывает деревню Кровавого Копыта с трёх сторон. Его прохладные воды славятся обилием рыбы, и не один час здесь проводят с удочкой в руках. В самом узком месте озеро пересекает мост, а дорога через него ведёт от деревни на север, к Громовому Утёсу. По северному берегу шли караваны Торговой компании — здесь и разгорелась вражда тауренов с гоблинами.",
        ["Разграбленный караван"] = "На северо-восточном берегу озера Каменного Быка чадят обгорелые повозки Торговой компании. Караван под охраной вёз припасы для гоблинского рудника, но таурены-разведчики, уже потерявшие двоих в прошлой стычке, напали без промедления и сожгли его. Ящики с рудой и минералами бросили, решив, что огонь уничтожит всё ценное, однако вскоре у тлеющих остатков появились мародёры Торговой компании, ревниво стерегущие свой груз.",
        ["Красные скалы"] = "Красные скалы — природное образование из красного песчаника на северо-востоке Мулгора. Это тихое, священное место: здесь павших героев тауренов через очищающее пламя провожают к Матери-Земле и Отцу-Небу, и сюда приводит юных тауренов один из обрядов Матери-Земли. Недавно свинобразы из племени Дыбогривов вторглись на Красные скалы и осквернили святыню. На утёсах над скалами стоит небольшая хижина, а под ней скрыта пещера.",
        ["Ежевичная лощина"] = "Ежевичная лощина на северо-восточной окраине плато Красного Облака — логово свинобразов из племени Дыбогривов. Отсюда они совершают набеги на охотничьи угодья и по ночам грабят Лагерь Нараче, натаскивая для войны боевых вепрей, а шаманы племени готовят здесь свои ритуальные мази. В глубине лощины, в большой хижине, обитает их вождь — Остроклык Терновая Мантия. Молодые таурены приходят сюда, чтобы пройти обряд Силы и доказать свою храбрость.",
        ["Рудник Торговой компании"] = "В восточных скалах Мулгора гоблины Торговой компании вырыли огромный рудник. Таурены отказали им в праве на добычу, но компания не приняла отказа: руду и минералы вывозят караванами, а бригадир Шумовик, управляющий работами, строит планы, как изгнать тауренов с их земель. У рудника три входа, но пешком можно пройти лишь через главный; в глубине скрыт небольшой лагерь лесорубов, куда компания собирается доставить свои новейшие крошшеры.",
        ["Колодец Заиндевевшего Копыта"] = "Колодец Заиндевевшего Копыта стоит на краю Холмистых равнин в южном Мулгоре. Это один из трёх священных колодцев тауренов, и именно с него начинается их очищение: гоблины Торговой компании и их прислужники отравили воду, чтобы взять под власть источники долины. Мулл Громовой Рог из деревни Кровавого Копыта создаёт тотем очищения из лап койотов и когтей долгоногов, а подступы к колодцу стерегут гоблины.",
        ["Колодец Громового Рога"] = "Колодец Громового Рога стоит посреди трав, у северной дороги между деревней Кровавого Копыта и Громовым Утёсом. Как и другие священные колодцы Мулгора, его захватили и отравили гоблины Торговой компании, желавшие управлять водой долины. Для его очищения нужен тотем из когтей охотников прерий и пум плоскогорья, и Мулл Громовой Рог, носящий то же имя, что и колодец, ведёт эту работу из деревни.",
        ["Колодец Буйногривых"] = "Колодец Буйногривых — самый северный из священных колодцев тауренов; он стоит чуть севернее Громового Утёса, там, где по равнине рыщут могучие волки прерий. Назван он в честь племени Буйногривых. Гоблины Торговой компании захватили и этот источник, и для его очищения нужен тотем из зубов лютых хищников. Это последний колодец в цепи очищений, которые ведёт Мулл Громовой Рог.",
        ["Гряда на горизонте"] = "Гряда на горизонте — один из хребтов, замыкающих Мулгор со всех сторон. Здесь нет поселений — только ветер, камень, редкие сосны на склонах и тропы зверей, спускающихся к траве равнин.",
        ["Раскопки Бейл'дана"] = "На западной окраине Мулгора дворфы вырыли в склоне горы большой карьер — раскопки Бейл'дана. Экспедиция ищет в земле следы своего тёмного прошлого, и Бейн Кровавое Копыто видит в этих бесконечных ямах оскорбление Матери-Земли: у земли нужно учиться, а не осквернять её. Уговоры не помогли, и племя Кровавого Копыта решило иначе — собирать и ломать кирки геологов, чтобы дворфы поняли, что им здесь не рады.",
        ["Плато Дерзкого Ветра"] = "Плато Дерзкого Ветра — одна из столовых гор Мулгора, каких немало в этой долине. Ветер здесь не стихает, пригибая траву к красноватой земле, а внизу расстилаются равнины, где пасутся кодо и бродят долгоноги.",
        ["Плато Огненного Камня"] = "Красноватый песчаник Мулгора на закате будто горит, и, быть может, отсюда пришло название плато Огненного Камня. Это одно из тихих плато долины: здесь лишь ветер, трава и редкие звери, спустившиеся с гор.",
        ["Скала Мантия"] = "Скала Мантия — одна из каменных глыб Мулгора, каких немало в этой долине. Такие скалы поднимаются над травой, как молчаливые стражи, и служат ориентирами охотникам и кочующим стадам кодо.",
        ["Лагерь племени Галак"] = "Кентавры племени Галак живут в Тысяче Игл, к югу от Мулгора, но их разведчиков видели и на равнинах долины. Когда-то кентавры безжалостно теснили кочующих тауренов, пока Кэрн Кровавое Копыто вместе с Траллом не отвоевал эти равнины. Небольшой лагерь налётчиков в Мулгоре — напоминание о том, что старые враги не забыли дорогу сюда, и таурены не намерены терпеть их у своих границ.",
        ["Дольмен Кодо"] = "Дольмен Кодо — природный памятник на плато Красного Облака, на полпути между Лагерем Нараче и Ежевичной лощиной. Заметить его можно лишь с близкого расстояния. Для тауренов это шаманское святилище: сюда юные шаманы приносят сапту — напиток, соединяющий дух со стихией, — и пьют её только здесь, в священном месте, чтобы впервые услышать голос земли.",
        ["Утес Бледногривов"] = "Утёс Бледногривов — пещера в западных горах Мулгора, где поселились гноллы племени Бледногривов. Они живут и в лагере снаружи, и в глубине пещеры, уходящей далеко в недра горы. Гноллы не отвечают на попытки договориться, нападают на всякого, кто подойдёт близко, и без жалости истребляют зверей Мулгора. Бейн Кровавое Копыто просит молодых тауренов искоренить эту угрозу, пока она не разрослась.",
        ["Гряда Ярости Ветра"] = "Гряда Ярости Ветра тянется вдоль гор на юго-востоке Мулгора, в стороне от дороги. На её гребнях гнездятся гарпии стаи Ярости Ветра — извечные враги тауренов: они бросаются на всякого, кто подойдёт к гнёздам, а по склонам рыщут пумы и волки. Таурены охотятся на гарпий ради ярких перьев, которыми в Громовом Утёсе украшают свадьбы и празднества, а воин Руул Орлиный Коготь посылает сюда молодых, чтобы испытать их силу.",
        ["Золотые равнины"] = "Золотые равнины — широкая котловина к юго-востоку от Громового Утёса, между столицей и деревней Кровавого Копыта. Это одно из самых дорогих сердцу тауренов мест и их излюбленные охотничьи угодья. Здесь пасутся большие стада кодо, и говорят, что в этом зелёном море трав бродит и знаменитый Арра'чея — могучий кодо, чей рог Кэрн Кровавое Копыто просит принести тех, кто прошёл обряды Матери-Земли.",
        ["Холмистые равнины"] = "Холмистые равнины занимают большую часть южного Мулгора, от деревни Кровавого Копыта до границы со Степями. Здесь живёт множество зверей: волки прерий, кодо, долгоноги и пумы. Это единственное место в Мулгоре, куда сумели проникнуть кентавры — их всадники порой бродят по этим травам. На востоке равнин гнездятся гарпии Ярости Ветра.",
        ["Мрачная вершина"] = "Мрачная вершина поднимается там, где горы смыкаются вокруг Мулгора. Тень здесь ложится раньше, чем на равнинах, а вместо трав — камень и редкие сосны. Это безлюдная высота, куда нечасто заходят даже охотники.",
        ["Плато звездочетов"] = "Плато звездочётов лежит к северо-западу от Громового Утёса. Здесь швартуется неборез — летучий корабль небеснорождённых с далёкого острова Зефрис, и Ваятели ветра, первопроходцы этого народа, ступают отсюда на землю Азерота. Алаана Штормовой Полёт встречает прибывших в Мулгоре, а юные шаманы возвращаются с этого плато домой, чтобы ответить на зов огня.",
        ["Лагерь Гев'рек"] = "Лагерь Гев'рек — новая стоянка кентавров у восточной границы Мулгора, недалеко от деревни Кровавого Копыта. Небольшой отряд налётчиков из племени Галак проник в долину и разбил здесь лагерь; в нём кипит бурная деятельность, а среди кентавров — Херак Разоритель. Дальноходы, доверенные разведчики верховного вождя, первыми заметили угрозу, и Бейн Кровавое Копыто не намерен допустить, чтобы деревня оказалась в опасности.",
    },
    ["Нагорье Арати"] = {
        _zone = "Нагорье Арати — сухая холмистая равнина на юго-востоке Лордерона, между Стеной Торадина на севере и мостом Тандола на юге. Это колыбель человеческой цивилизации: король Торадин основал здесь Стром, столицу империи Аратор, и отсюда люди вместе с эльфами сокрушили троллей. На месте распавшейся империи выросло королевство Стромгард, чьи солдаты во Вторую войну стали опорой Альянса. После Третьей войны оно пало: столицу захватили огры клана Тяжёлого Кулака и разбойники Синдиката, а остатки армии укрылись в Опорном пункте. Орда заняла бывший лагерь для пленных орков и назвала его Павшим Молотом в честь вождя Оргрима. В Низине Арати Лига Аратора и Осквернители Отрекшихся сражаются за рудники и поля. Между ними лежат древние круги Обуздания, а по холмам рыщут тролли, кобольды и хищные ящеры.",
        ["Северное поместье"] = "Северное поместье стоит на северо-западной окраине нагорья, у дороги, ведущей к Стене Торадина. Когда-то это была обычная ферма подданных Стромгарда, но после падения столицы её захватил Синдикат и превратил в свой форпост. Отсюда разбойники перехватывают обозы, которые Южнобережье отправляет защитникам Стромгарда. Ходят слухи, что в поместье творится и нечто похуже грабежа: на земле здесь находили амулеты из кровавого камня, какими пользуются при призыве демонов.",
        ["Ферма Го'Шека"] = "Ферма Го'Шека лежит на востоке нагорья, недалеко от деревни Сухокожих. Прежде здесь хозяйствовали люди, и ветеран Второй войны растил хлеб на этих полях. После Третьей войны ферму заняли орки и Отрекшиеся из Павшего Молота. Орки свозят отсюда припасы для гарнизона, а аптекари Отрекшихся устроили в амбарах место для своих тёмных опытов. Ферму стерегут рубаки Павшего Молота, и разведчики Альянса присматриваются к ней с растущей тревогой.",
        ["Усадьба Дабири"] = "Усадьба Дабири стоит на севере нагорья, в стороне от дороги, по которой ходят конные разъезды Стромгарда. Здесь живёт семья Дабири — подданные павшего королевства, сумевшие пережить войну и сохранить хозяйство. Хозяйка держит наёмных работников и собственное ополчение, и чужаков, будь то Альянс или Орда, на своей земле не жалуют. У Отрекшихся к этой семье старые счёты: те, кто потерял всё во время чумы, не простили Дабири их уцелевшего благополучия.",
        ["Крепость Тяжелого Кулака"] = "Крепость Тяжёлого Кулака — укреплённое логово огров на юге нагорья, между мостом Тандола и деревней Сухокожих. Огры устроили её в холме, обнесли частоколом и вырыли просторную пещеру, где сидит их вождь. Клан Тяжёлого Кулака заключил союз с троллями Сухокожими против людей Стромгарда и орков Павшего Молота и вместе с ними захватил целый квартал разрушенной столицы. Из этих пещер огры выходят в набеги, и пока крепость стоит, покоя на юге нагорья не будет.",
        ["Деревня Сухокожих"] = "Деревня Сухокожих раскинулась вокруг небольшого озера на юго-востоке нагорья. Здесь живут лесные тролли племени Сухокожих, а в большой пещере за деревней собираются их вожди и знахари. Тролли заключили союз с ограми клана Тяжёлого Кулака и вместе с ними удерживают часть Стромгарда. Небольшие отряды Сухокожих то и дело выходят из деревни и бегут по дороге к воротам Павшего Молота, чтобы испытать на прочность его стражу.",
        ["Теснина Сухоусов"] = "Теснина Сухоусов прорезает горы на востоке нагорья, к северо-востоку от Павшего Молота. В конце ущелья открывается пещера, где поселились кобольды племени Сухоусов. Они копают в глубине и ревниво стерегут странные светящиеся крупицы, которые находят в породе. В самом дальнем гроте лежит кристальный осколок, из которого доносится голос той, что зовёт себя принцессой земли и просит о помощи, а кобольды, похоже, служат её тюремщикам — горным великанам.",
        ["Опорный пункт"] = "Опорный пункт — лагерь Альянса в небольшом каньоне в самом сердце нагорья. Когда огры и Синдикат захватили Стромгард, остатки королевской армии отступили сюда и разбили палатки среди скал. Здесь стоят ополчение Стромгарда и Лига Аратора, готовясь к битве за свой великий город. Из Дун Модра приходили гонцы просить подмоги, но капитану нечего было им дать: все силы нужны для возвращения столицы. Отсюда же бойцы Лиги уходят в Низину Арати сражаться с Осквернителями.",
        ["Павший Молот"] = "Павший Молот стоит на северо-востоке нагорья. После Второй войны Альянс держал здесь один из крупнейших лагерей для пленных орков, и именно здесь при освобождении соплеменников погиб вождь Оргрим Молот Рока. После Третьей войны Орда вернулась в руины лагеря и назвала заставу в память о павшем вожде. Отсюда Осквернители Отрекшихся держат путь в Низину Арати. Огры Тяжёлого Кулака и тролли Сухокожие сговорились стереть Павший Молот с лица земли, и стража у ворот не знает покоя.",
        ["Обломки судов Черноводья"] = "У южного берега нагорья, на подводном рифе, лежат обломки двух кораблей пиратов Черноводья. Экспедиция шла сюда за эльфийскими сокровищами, но у самой бухты Фальдира на неё обрушился внезапный прилив, и два судна из трёх пошли ко дну. Теперь среди разбитых корпусов и рваных парусов хозяйничают наги, а в трюмах ещё хранятся судовые журналы погибших кораблей.",
        ["Лагерь О'Брина"] = "Лагерь О'Брина — стоянка пиратов Черноводья на песке бухты Фальдира. Здесь под началом капитана О'Брина собрались выжившие моряки с единственного уцелевшего корабля экспедиции. Наги с подводного рифа не дают им выйти в море, и команда коротает дни у костров, ожидая, когда найдётся кто-нибудь, кто поможет вернуть судовые журналы с затонувших судов. При лагере возятся и двое гномов-инженеров с прибором, который учуял эльфийские самоцветы в камнях рифа.",
        ["Крепость Стромгард"] = "Стромгард стоит на юго-западе нагорья, там, где Торадин мечом очертил границы своей столицы Строма. Тысячелетия этот город был сердцем империи Аратор, а затем столицей королевства Стромгард, чьи короли из рода Троллебоев вели людей во Вторую войну. Ныне город разграблен и расколот на три части: цитадель держит Синдикат, квартал магов заняли огры с троллями, а последний уголок удерживают верные солдаты Стромгарда. В склепе Троллебоев по-прежнему покоится Трол'калар, легендарный меч, гроза троллей.",
        ["Башня Аратора"] = "Башня Аратора возвышается в юго-западной части Стромгарда, в бывшем квартале магов, и носит имя древней империи. Когда-то здесь работал архимаг, создавший для башни магическую защиту, которую пробуждал зачарованный самоцвет. При осаде города он пытался отстоять башню, но не сумел и бежал из Стромгарда. Теперь башню и квартал вокруг заняли огры клана Тяжёлого Кулака, и в её залах засел огр-маг. В сундуках башни до сих пор лежат вещи, оставленные прежним хозяином.",
        ["Святилище"] = "Святилище — уголок разрушенного Стромгарда, который до сих пор удерживают верные королевству солдаты. Здесь держит свой штаб принц Гален Троллебой, наследник павшего дома, а вокруг стоят последние защитники столицы. Отсюда рукой подать до склепа Троллебоев, где заперт Трол'калар, а печати от его гробницы разделены между надёжными людьми. Пока Синдикат и огры делят остальной город, в Святилище ждут дня, когда над Стромгардом снова взовьётся королевское знамя.",
        ["Бухта Фальдира"] = "Бухта Фальдира — небольшая природная гавань на южном берегу нагорья, неподалёку от Стромгарда и подводного рифа. По преданию, она названа в честь Фальдира, который отсюда вместе со своими сподвижниками отплыл через море, чтобы основать королевство Штормград. Ныне в бухте стоит на якоре единственный уцелевший корабль пиратов Черноводья, а на берегу раскинулся лагерь его команды. Наги с рифа управляют приливами и не выпускают моряков в море.",
        ["Подводный риф"] = "Подводный риф тянется вдоль южного берега нагорья и издавна губит корабли: здесь нашли последнюю гавань и два судна пиратов Черноводья. Под водой залива лежат руины древнего эльфийского города, в которых поселились наги под началом своего принца. Говорят, наги научились повелевать приливами, и не одна команда, искавшая укрытия в бухте Фальдира, погибла из-за их колдовства. В камнях рифа скрыты окаменевшие эльфийские самоцветы, которые уже учуяли приборы гномов.",
        ["Восточный круг Обуздания"] = "Восточный круг Обуздания — кольцо древних камней на востоке нагорья. Это один из четырёх кругов, которыми горные великаны когда-то сковали принцессу земли глубоко под холмами. Восточный камень стерегут элементали воды, и над кругом стоит тихий плеск, словно ручей течёт сквозь сухую траву. Тому, кто попытается подойти к камню, придётся иметь дело с водяным изгнанником, что кружит среди монолитов.",
        ["Западный Круг Обуздания"] = "Западный Круг Обуздания стоит на западе нагорья, у самой Стены Торадина. Древние камни здесь окружены элементалями огня, и трава вокруг круга выжжена дочерна. Это один из четырёх кругов, которыми горные великаны сковали принцессу земли, и в западном камне заключён один из ключей от её темницы. Пламя, что мечется среди монолитов, служит не путнику, а стражу, и не любит, когда его тревожат.",
        ["Внутренний Круг Обуздания"] = "Внутренний Круг Обуздания лежит на юге нагорья, неподалёку от Стромгарда. Здесь стоит сильнейший из камней Обуздания — тот самый, что держит на замке темницу принцессы земли. Круг охраняют элементали земли, а между кругами нагорья бродит огромный каменный великан, один из её тюремщиков. Именно через осколок этого камня заточённая принцесса научилась говорить с путниками, что подходят к кругу.",
        ["Внешний Круг Обуздания"] = "Внешний Круг Обуздания стоит в центре нагорья, недалеко от Опорного пункта. Камень здесь стерегут элементали воздуха, и вокруг круга не смолкает свист ветра и вьются маленькие смерчи. Это один из четырёх кругов, которыми горные великаны сковали принцессу земли. Воины, что ищут силу вихря, приносят к этому кругу тотемные палочки троллей Сухокожих, чтобы вызвать сюда Циклониана — могучего духа ветра.",
        ["Мост Тандола"] = "Мост Тандола — две исполинские каменные арки через пропасть между Болотиной Каз Модана и нагорьем Арати. Дворфы Стальгорна возвели их после войны Трёх Кланов, чтобы сохранить торговлю с сородичами из клана Громового Молота. Во Вторую войну именно через мост Тандола Альянс вытеснил Орду обратно в Каз Модан. Недавно дворфы Чёрного Железа разрушили одну из арок и захватили Дун Модр по ту сторону пропасти, и теперь дворфы отчаянно обороняют уцелевший пролёт.",
        ["Пещеры Сухокожих"] = "Пещеры Сухокожих уходят в скалу за деревней троллей на юго-востоке нагорья. В просторном гроте собираются вожди и знахари племени Сухокожих, здесь же хранятся их тотемы и вудуистские снадобья. В этих пещерах тролли обсуждают набеги на Павший Молот и союз с ограми клана Тяжёлого Кулака, и чужаку сюда лучше не заходить без веской причины.",
        ["Стена Торадина"] = "Стена Торадина отделяет нагорье Арати от предгорий Хилсбрада. Король Торадин повелел возвести её вскоре после основания Строма, чтобы заслонить людей от набегов троллей Амани. Многие века стена стояла стражем над этими землями, но теперь она сильно повреждена и зияет широким проломом, через который проходит дорога из Хилсбрада. Обломки укреплений рассыпаны по холмам, а неподалёку от стены лежит Западный Круг Обуздания.",
        ["Камен'гор"] = "Камен'гор — холм к северу от Стромгарда, где обосновалась часть огров клана Тяжёлого Кулака. В склоне холма вырыт их лагерь, а рядом с ограми держатся и лесные тролли из племени Сухокожих. Когда в Павшем Молоте узнали о союзе огров и троллей, первых воинов послали именно сюда. Тропа через Камен'гор опасна для одинокого путника.",
        ["Зловещее море"] = "Зловещее море омывает восточный берег нагорья, но горы почти не пускают к нему путников. Это неисследованные, не нанесённые на карты воды, и моряки говорят, что за их пределами нет ничего. С крутого берега видно лишь серую воду до самого горизонта да птиц над волнами.",
    },
    ["Оргриммар"] = {
        _zone = "Оргриммар — столица орков и всей Орды, город, выстроенный среди рыжих скал на севере Дуротара. После битвы за гору Хиджал вождь Тралл привёл свой народ в эти суровые земли и назвал их Дуротаром в честь отца, а город — Оргриммаром, в память о своём наставнике Оргриме Молоте Рока. Таурены Мулгора и тролли Чёрного Копья помогли оркам возвести новую столицу, и с тех пор здесь живут бок о бок все народы Орды. В долине Силы, у самых ворот, кипит торговля и стоит крепость Громмаш, где Тралл держит совет. В долине Мудрости обитают таурены, в долине Духов — тролли, а в долине Чести звенят клинки воинов. По Волоку, узкому ущелью посреди города, тянутся лавки, а под ним лежит Расселина Теней, где чернокнижники и разбойники ведут свои дела в темноте. Ещё ниже уходит Огненная Пропасть, куда спускаются лишь самые отчаянные. Оргриммар — город воинов, и каждый камень его стен помнит, что Орда добыла это место своим трудом и кровью.",
    },
    ["Оскверненный лес"] = {
        _zone = "Осквернённый лес лежит на севере Калимдора, между Тёмными берегами и Ясеневым лесом, у подножия горы Хиджал. Когда-то это была цветущая земля ночных эльфов, но в Третью войну здесь прошёл Пылающий Легион, и порча Черепа Гул'дана въелась в саму землю. Иллидан поглотил череп, а повелитель ужаса Тихондрий пал, но лес не исцелился: деревья гниют стоя, реки отравлены, а звери, фурболги и даже древни сошли с ума. В руинах Джеденара засели чернокнижники Совета Теней, по холмам расселились сатиры Нефритового Пламени, а в долине Рваных Ран до сих пор дымятся кратеры инферналов. Друиды Изумрудного Круга с юга и фурболги Древобрюхи с севера пытаются вернуть лесу прежний облик, но пока лишь сдерживают порчу. Главная дорога ведёт к единственному проходу на Лунную поляну и в Зимние Ключи; днём по ней можно пройти спокойно, но сходить с тропы и задерживаться до темноты не советуют.",
        ["Деревня Мертвого Леса"] = "Деревня Мёртвого Леса стоит на самом юге Осквернённого леса, у дороги из Ясеневого леса. Здесь живут фурболги племени Мёртвого Леса — некогда мирный народ, чей разум отравила порча: теперь они нападают на всякого, кто подойдёт к их кострам и грубым шатрам. Шаманы племени вырезают ритуальные тотемы, от которых несёт разложением, а сородичи из Крепости Древобрюхов считают их потерянными. Фурболг Гразл у Изумрудного святилища просит путников проредить ряды племени — так чужак заслуживает доверие Древобрюхов.",
        ["Деревня Сквернолапов"] = "Деревня Сквернолапов прячется на самом севере леса, у подножия гор, недалеко от входа в Крепость Древобрюхов. Это второе крупное поселение осквернённых фурболгов Мёртвого Леса, и здесь собрались самые сильные из них — дозорные, мстители и шаманы. Вокруг рыщут волки-сквернолапы и падальщики, а по соседству, на Холме Нефритового Пламени, засели сатиры, которых считают виновниками безумия фурболгов. Говорят, здесь же обитает и вождь Кровавая Утроба, окружённый шаманами и стражей.",
        ["Джеденар"] = "Джеденар лежит на западе леса, среди древних руин ночных эльфов и двух друидских курганов. Имя ему дали в честь Кил'джедена, и служат здесь его почитатели — чернокнижники Совета Теней, орки и Отрекшиеся, окружённые гончими Скверны, суккубами и сатирами. В центре руин стоит лунный колодец с отравленной водой, и отсюда Совет Теней разносит порчу по лесу. Друиды Изумрудного Круга открыто воюют с сектантами, и Грета Замшелое Копыто ищет тех, кто поможет проредить их ряды. Под руинами скрыты Оплот Теней и Святилище Искусителя.",
        ["Река Отравленной Крови"] = "Река Отравленной Крови берёт начало у одноимённого водопада в сердце леса и течёт на запад, к обрывам над Тёмными берегами, где спускается с гор и становится Петляющей рекой. Вода в ней мутная и ядовитая: по берегам ползают проклятые и нечистые слизнюки, а звери, приходящие на водопой, теряют разум. Порчу этой реки чувствуют даже фурболги и олени далеко за пределами Осквернённого леса.",
        ["Водопад Отравленной Крови"] = "Водопад Отравленной Крови шумит в самом центре леса, и от него берут начало все отравленные воды этих мест. Когда-то его питали чистые родники, а теперь из земли сочится ядовитая жижа и падает с уступа в бурлящий зеленоватый омут. Ночные эльфы говорят, что глоток этой воды убивает, а брызги жгут, словно кислота. У воды копошатся слизнюки и ядовитые ужасы, рождённые самой порчей, и сколько их ни истребляй, меньше не становится. К северу от водопада начинается долина Рваных Ран.",
        ["Долина Рваных Ран"] = "Долина Рваных Ран лежит к северу от водопада Отравленной Крови. В Третью войну сюда с неба падали инферналы Пылающего Легиона, и до сих пор земля здесь изрыта дымящимися кратерами, залитыми осквернённой водой. По долине бродят караульные-инферналы и энтропические звери и ужасы — порождения Скверны, не дающие земле зажить. Друиды Изумрудного святилища шлют сюда разведчиков проверить, не высохли ли кратеры, а чернокнижники ищут среди камней останки инфернала Крошиуса.",
        ["Железнолесье"] = "Железнолесье раскинулось на севере леса, между водопадом Отравленной Крови и горами. Когда-то это была тихая роща, а теперь по ней бродят обезумевшие древни-криводревы, топотуны и бродяги Железнолесья и ядовитые ужасы. Здесь окаменели трое древних — Хастат, Стома и Вартус, великие живые деревья ночных эльфов: они стоят среди руин на юге, и, по слухам, дух их не угас. Говорят, если заиграть в этих руинах на флейте сатира, можно призвать духов осквернённых Дерев, что когда-то здесь жили.",
        ["Пещера Железнолесья"] = "Пещера Железнолесья уходит глубоко под холмы на северо-востоке Железнолесья. Внутри темно и сыро, и в этой темноте копошатся криводревы — живорезы и моходеры, порченые древни, которые сдирают мох и кору со всего, до чего дотянутся. У входа рыщут опустошители-сквернолапы, так что случайных путников здесь не бывает.",
        ["Крепость Древобрюхов"] = "Крепость Древобрюхов вырыта в горах на северо-востоке леса, и через её туннели лежит единственный путь на Лунную поляну и в Зимние Ключи. Здесь живут фурболги Древобрюхи — одно из немногих племён, избежавших порчи Легиона, когда их сородичи по всему Калимдору сходили с ума. Они видели, как любимый лес гниёт заживо, и теперь не доверяют никому: чужака принимают за осквернённого и встречают копьями. У входа со стороны леса стоит на страже Нафиэн, со стороны Зимних Ключей — Сальфа; внутри живут Горн Одноглаз, Мелиош и Кернда. Кто докажет верность в бою с фурболгами Мёртвого Леса, узнает, что Древобрюхи ценят друзей превыше сокровищ.",
        ["Оплот Теней"] = "Оплот Теней — подземный лабиринт под руинами Джеденара, бывший друидский курган, ставший главной твердыней Совета Теней в Азероте. По коридорам ходят чернокнижники с демонами, а путь вглубь стерегут четыре жаровни защиты, чьё пламя гасит лишь очищенная вода лунного колодца. В глубине правит владыка теней Скверн'дан с суккубами Моорой и Салией, здесь же обитают сатир принц Ксавалис и повелитель ужаса лорд Гиблопуст. В клетках держат пленников: сюда попали ночная эльфийка Арко'нарин и паладин Трей Светогорн, искавшие следы Совета Теней.",
        ["Святилище Искусителя"] = "Святилище Искусителя — осквернённый курган в Джеденаре, названный в честь Кил'джедена Искусителя, повелителя Пылающего Легиона. Внутри собираются чернокнижники Совета Теней, и для неподготовленного путника это одно из самых опасных мест в лесу. Тьма здесь густая, а воздух пропитан запахом Скверны.",
        ["Застава Отравленной Крови"] = "Застава Отравленной Крови — крохотный лагерь Орды на утёсах западной окраины леса, над обрывом к Тёмным берегам. Судя по постройкам и стражникам, основали её таурены, но заправляет здесь Отрекшаяся Винна Хеззард, которую осквернённая вода лунных колодцев интересует больше, чем исцеление леса. Рядом Трулл Баловень Судьбы нанимает охотников на совухов, а укротитель ветрокрылов Браккар держит единственный перелёт Орды в этих краях. К заставе ведёт тёмная тропа вдоль южного берега реки Отравленной Крови.",
        ["Поляна Когтистых Ветвей"] = "Поляна Когтистых Ветвей — небольшая застава ночных эльфов на севере леса, к югу от Крепости Древобрюхов. Здесь стоит дом у лунного колодца, дежурят часовые Альянса и держат гиппогрифов, чтобы летать в Аубердин, на Лунную поляну и в Круговзор. Для путников Альянса это единственное спокойное пристанище в северной части леса перед дорогой через туннели фурболгов.",
        ["Морлос'Аран"] = "Морлос'Аран — руины на южной окраине леса, к востоку от дороги. Задолго до Великого Раскола здесь стоял большой город ночных эльфов, такой же, как Амет'Аран и Башал'Аран на Тёмных берегах или Ордил'Аран в Ясеневом лесу. От него остались лишь колонны и разбитые арки среди больных деревьев — напоминание о золотом веке, который ушёл десять тысяч лет назад. Теперь среди камней бродят медведи злобных когтей и волки-сквернолапы.",
        ["Изумрудное святилище"] = "Изумрудное святилище стоит на юго-востоке леса, у главной дороги из Ясеневого леса. Это лагерь Изумрудного Круга — ветви Круга Кенария, созданной, чтобы вернуть Осквернённому лесу жизнь; здесь бок о бок трудятся друиды ночных эльфов и тауренов. Грета Замшелое Копыто ведёт отсюда войну с Советом Теней, Тарун Красное Перо следит за долиной Рваных Ран, а Эридана Грусть Ветра и Аратандис Серебряное Небо чуть южнее варят кенарийский бальзам для больных растений. Перелёт отсюда открыт и Альянсу, и Орде, а неподалёку фурболг Гразл ищет союзников против осквернённых сородичей.",
        ["Долина Нефритового Пламени"] = "Долина Нефритового Пламени лежит на юго-западе леса, к западу от дороги. Здесь разбили лагерь сатиры Нефритового Пламени — рогатые потомки высокорожденных, проклятых Саргерасом ещё в Войну Древних. Сатиры селятся у осквернённых лунных колодцев и своей магией вгоняют порчу леса всё глубже; поговаривают, что они же служат разведчиками и убийцами Совета Теней. Эридана Грусть Ветра из Изумрудного святилища считает, что за ними стоит нечто большее, и просит путников проредить их ряды.",
        ["Руины Констелласа"] = "Руины Констелласа лежат на западе леса, между Джеденаром и долиной Нефритового Пламени. По остаткам колонн и лунному колодцу видно, что здесь стояло одно из поселений ночных эльфов у подножия Хиджала. Теперь колодец отравлен Скверной, и его стережёт сатир Ксаватрас с разбойниками и тенеловами Нефритового Пламени — он растит порчу по воле Ксаварика, вожака сатиров с севера. За этой водой шлют посланцев и друиды Изумрудного святилища, и Винна Хеззард с заставы Отравленной Крови, хотя цели у них разные.",
        ["Холм Нефритового Пламени"] = "Холм Нефритового Пламени поднимается на северо-западе леса, недалеко от деревни Сквернолапов. Это главный лагерь сатиров Нефритового Пламени, и здесь собрались сильнейшие из них — призыватели огня, предатели и плуты во главе с Ксавариком, чья флейта, по слухам, связана с духами древних Дерев. Отсюда сатиры сеют порчу среди соседних фурболгов и, как считают, готовят набеги на Крепость Древобрюхов. Эридана Грусть Ветра просит смельчаков добраться сюда и положить конец Ксаварику.",
    },
    ["Перевал Мертвого Ветра"] = {
        _zone = "Перевал Мёртвого Ветра — изломанное ущелье, соединяющее Сумеречный лес на западе с Болотом Печали на востоке. Когда-то эти горы считали частью Красногорья, но теперь здесь всё иначе: деревья стоят окаменевшие и безлистные, небо вечно грозит бурей, а по каньону воет злой, мёртвый ветер, давший перевалу имя. Над южной частью ущелья высится Каражан — Башня из слоновой кости, где некогда жил чародей Медив. С его смерти башня стоит запечатанной, и её проклятие расползлось по округе, отравляя землю. Здесь не растут травы и не находят руды; из живого лишь стервятники да блуждающие огоньки, а в южных пещерах засели огры Мёртвого Ветра. У подножия башни лежит вымершее селение, где бродят беспокойные духи; говорят, именно отсюда спускались в Сумеречный лес тёмные всадники. Дорога через перевал одна, и сходить с неё не советуют.",
        ["Овраг Мертвого Ветра"] = "Овраг Мёртвого Ветра — каменистая расселина, уводящая от главной дороги на юг, в сторону Каражана. Западный путь идёт по её верхнему краю, между голых скал и окаменевших стволов, и обрывистые склоны хорошо заметны с тропы. Ветер здесь бьёт особенно зло: он мечется между стенами оврага и стонет, как живой. В конце расселины дорога выходит к южному мосту, за которым уже виднеется тёмный силуэт башни.",
        ["Река Алмазная"] = "Река Алмазная — единственная вода, пересекающая перевал. Тёмный поток тянется по дну ущелья под мостами и обрывами, и в нём не отражается ничего, кроме серого, вечно грозового неба. Кто назвал реку так и что она значила для тех, кто жил здесь прежде, теперь никто не помнит: земля вокруг неё давно мертва.",
        ["Лагерь Аридена"] = "Лагерь Аридена — заброшенная стоянка чуть севернее главной дороги, что ведёт из Сумеречного леса к Болоту Печали. Кострище давно остыло, повозки и пожитки брошены, но никаких следов хозяев: ни костей, ни могил. Кем был Ариден и куда он делся вместе со спутниками, на перевале не знает никто, и только имя на карте напоминает, что здесь однажды пытались обжиться. Путники, проходя мимо, обычно ускоряют шаг: пустой лагерь в мёртвой земле не сулит ничего хорошего.",
        ["Погань"] = "Погань — южная часть перевала, где дорога изгибается и выходит к Каражану. В отвесных скалах вдоль неё огры Мёртвого Ветра вырыли свои курганы и пещеры, а стоянки разбили у самой обочины, чтобы сверху высматривать чужаков. Одеты они в грязные лохмотья и бьются грубым самодельным оружием, но именно из-за них мало кто из шедших к башне возвращался. Почему огры выбрали этот пустынный край, где им составляют компанию лишь беспокойные духи и стервятники, остаётся загадкой. Иные шепчут, будто огры служат некоему «хозяину», но кто это — никто не скажет.",
        ["Каражан"] = "Каражан, Башня из слоновой кости, стоит в южной части перевала, у самого края каньона. Здесь жил Медив, последний Хранитель Тирисфаля — величайший чародей своего времени и тот, кто открыл оркам Тёмный портал. Его друг Андуин Лотар вместе с учеником Медива Кадгаром взяли башню штурмом и убили обезумевшего волшебника; с той поры Каражан закрылся от мира, и ни одни его ворота не отворяются. Проклятие башни просачивается наружу и высасывает жизнь из земли вокруг. Говорят, любопытные дворяне из Темнолесья отправлялись сюда разузнать о причинах напасти — и ни один не вернулся. Смотреть на башню лучше издали.",
        ["Надел Моргана"] = "Надел Моргана — ветхая часовня с погостом, притаившаяся за Каражаном. Покосившиеся надгробия и старый склеп говорят о том, что когда-то у стен башни жили люди и хоронили здесь своих близких. Но покой этому месту не дан: мёртвые не лежат в могилах, и в часовне и на склоне холма бродят призрачные обитатели. Кто такой Морган, чьё имя носит надел, история не сохранила.",
        ["Перекресток Мертвеца"] = "Перекрёсток Мертвеца — развилка на главной дороге перевала: на запад — Сумеречный лес, на восток — Болото Печали, а на юг — тропа к Каражану. Своё имя перекрёсток получил по дереву-виселице, на котором до сих пор качаются два тела. Рядом стоит столб с указателями «Поверни назад!» и «Оставь надежду, всяк сюда входящий». Несмотря на угрозы, сама дорога здесь сравнительно безопасна, и путники, идущие в болота, минуют её без потерь, если только не сходят с колеи.",
        ["Хозяйский погреб"] = "Хозяйский погреб — подземелья под руинами маленькой деревни к югу от Каражана. Похоже, здесь жила прислуга башни, и кто-то перебил всех её обитателей: кто именно — Медив или силы, которые он призвал, — по сей день неизвестно. Из двух уцелевших домов открытые входы ведут вниз: один — в обширный винный погреб, другой — в такой же, где пол провалился и открыл ходы в глубокие пещеры. И там, и там во тьме толпятся неупокоенные: бывшие жильцы, сторожа, воющие тени, — и их присутствие уходит далеко под землю.",
        ["Поселок Грош'гок"] = "Посёлок Грош'гок — самая большая и самая южная из пещер Погани, главное логово огров Мёртвого Ветра. Внутри курган пропах дымом и гнилью; огры и их колдуны сторожат вход, и тропа мимо него — последняя перед самой башней. Здесь редко кто задерживается по своей воле.",
        ["Спящая теснина"] = "Спящая теснина — небольшой разлом в восточной части перевала. Одна из троп к Каражану ныряет в него и тянется по дну между скал, прежде чем свернуть на восток, в Погань. Тишина здесь такая, будто ущелье и впрямь спит; только ветер над головой напоминает, что оно лишь притворяется.",
    },
    ["Подгород"] = {
        _zone = "Подгород лежит глубоко под руинами Лордерона, некогда гордой столицы людей. Здесь, в тронном зале, король Теренас Менетил пал от руки собственного сына Артаса, и с того дня дворец наверху стоит пустым, а жизнь ушла вниз — в древние склепы, темницы и сточные каналы. Плеть начала прокладывать эти катакомбы, но Артаса отозвали в Нордскол, и когда воля Короля-лича ослабла, часть нежити вырвалась из-под его власти. Их возглавила Сильвана Ветрокрылая, Тёмная Госпожа, и своих свободных мертвецов она назвала Отрекшимися. Они заняли брошенные подземелья и годами достраивали лабиринт зелёных каналов и тёмных залов. В Королевском квартале Сильвана держит совет, и рядом с ней стоит натрезим Вариматрас, склонивший перед ней голову. Королевское фармацевтическое общество в Районе Фармацевтов варит новую чуму, а в Квартале Магов и Квартале Разбойников Отрекшиеся готовятся к войне с Плетью. Подгород — дом тех, кого отверг мир, и они ничего не забыли.",
    },
    ["Предгорья Хилсбрада"] = {
        _zone = "Предгорья Хилсбрада — мягкий зелёный край на юге Лордерона, почти не тронутый чумой: сосны на холмах, тучные пастбища и дороги между деревнями напоминают, каким было королевство до Третьей войны. С севера на юг землю рассекает река, на востоке границу держит стена Торадина, а на юге лежит Великое море с одиноким Островом Очищения. Мирный вид обманчив: именно здесь Альянс и Орда впервые сошлись в бою во Вторую войну, и с тех пор эта земля не знает покоя. Люди Южнобережья хранят верность Альянсу, а Мельницу Таррен на севере заняли Отрекшиеся, и между двумя городами не утихает вражда. В руинах Дарнхольда засел Синдикат, на брошенных фермах хозяйничают гноллы, берега держат мурлоки и наги, а в пещерах живут йети. Дальше к северу поднимаются Альтеракские горы, где под магическим куполом укрылся Даларан.",
        ["Южнобережье"] = "Южнобережье — портовый город на южном берегу предгорий, один из последних оплотов людей в Лордероне, верных Альянсу. Когда-то это была рыбацкая деревня, но во Вторую войну сюда причалили корабли беженцев из Штормграда, и посёлок вырос в оживлённую гавань. Ныне здесь живут уцелевшие в Третьей войне, среди них бывшие рыцари Серебряной Длани и маги Кирин-Тора. Мировой судья Малеб видит в Синдикате угрозу самому существованию города, маршал Редпат ищет смельчаков против огров Альтерака, а хранитель мудрости Диббс собирает уцелевшие книги для библиотеки Штормграда. С севера городу угрожают Отрекшиеся с Мельницы Таррен.",
        ["Мельница Таррен"] = "Мельница Таррен стоит на севере предгорий, у подножия Альтеракских гор. До Третьей войны это был обычный городок Лордерона; Плеть истребила его жителей, а опустевшие дома заняли Отрекшиеся, и теперь это самое южное владение Подгорода. Гарнизоном командует верховный палач Дарталия, подчинённая Вариматрасу: её задача — сдерживать людей Хилсбрада, пока аптекари вроде Лидона ищут состав новой чумы. Церковь, несколько домов и высохшие сады окружают старую мельницу, а вокруг рыщут огры, йети и грабители Синдиката.",
        ["Крепость Дарнхольд"] = "К востоку от Мельницы Таррен, за рекой, лежат руины Дарнхольда. После Второй войны отсюда управляли лагерями для пленных орков, и правил крепостью Аделас Блэкмур. Здесь вырос его раб, орчонок по имени Тралл; повзрослев, он бежал, собрал свободных орков и вернулся, чтобы сравнять крепость с землёй. Теперь в развалинах засел Синдикат: его сторожа, головорезы и тёмные маги совершают отсюда набеги на фермы Хилсбрада, а леди Сильвана объявила их всех вне закона.",
        ["Южная башня"] = "Южная башня — разрушенная сторожевая вышка на самом западе предгорий, у дороги, ведущей в Серебряный бор. Люди давно оставили её, и теперь здесь несёт службу страж смерти Леш: с уединённого поста Отрекшиеся следят за передвижениями Альянса по дороге между Хилсбрадом и Южнобережьем. Место тихое и глухое, и одинокому наблюдателю не на кого рассчитывать, кроме гонцов с Мельницы Таррен.",
        ["Хилсбрадские поля"] = "Хилсбрадские поля — плодородная житница на западе предгорий, кормящая Южнобережье и весь край. На фермах растут яблони и тыквы, пасутся коровы, а в кузнице Веррингтана куют оружие для местного ополчения. Хозяева здешних земель, такие как фермеры Рей и Гетц, привыкли держать вилы рядом с плугом: Отрекшиеся с Мельницы Таррен раз за разом совершают налёты на северные фермы, чтобы перерезать снабжение города. Многие крестьяне отвечают засадами, и поля давно стали передовой в битве за Хилсбрад.",
        ["Хилсбрад"] = "Хилсбрад — городок в сердце Хилсбрадских полей, выросший вокруг ратуши. Отсюда мировой судья Бернсайд и городской совет управляют окрестными фермами и Лазуритовым рудником. Стражники здесь до сих пор носят цвета Лордерона: Хилсбрад и Южнобережье — единственные земли павшего королевства, которые не были разорены Третьей войной и не ушли под знамёна Алого ордена. Верховный палач Дарталия считает город уязвимым и посылает сюда своих агентов.",
        ["Лазуритовый рудник"] = "Лазуритовый рудник лежит к югу от Хилсбрадских полей, на холмах западнее Южнобережья. По записям Хилсбрада, шахта принадлежит Альянсу: здесь трудятся шахтёры из Хилсбрадских полей под началом штейгера Бондса, а стража охраняет входы в штольни. Добытое железо уходит в оружейни Альянса, и потому рудник — заманчивая цель для Отрекшихся, которые стремятся оставить людей без металла.",
        ["Владение Нетандера"] = "Владение Нетандера — заброшенная ферма к востоку от Южнобережья, некогда виноградник, а теперь гниющие лозы и пустые постройки. Землю захватили гноллы Грязного Рыла — единственное место в предгорьях, где их можно встретить. На запущенных полях разрослись огромные белые грибы, цветки Грязного Рыла: аптекарь Лидон с Мельницы Таррен интересовался ими как сырьём для смертоносного эликсира. На возвышенности к северу от фермы держит наблюдательный пост страж смерти Масодж.",
        ["Дун Гарок"] = "Дун Гарок — дворфийская крепость в юго-восточных холмах предгорий, недалеко от стены Торадина. У её ворот стоят осадные машины, а гарнизон горных пехотинцев, стрелков и жрецов из Стальгорна помогает людям Хилсбрада оборонять край и Лазуритовый рудник. Отрекшиеся с Мельницы Таррен ненавидят это присутствие Альянса у своих границ и посылают к крепости своих лазутчиков. Крепость невелика, но дворфы держат её крепко, а с холмов вокруг открывается вид на всё побережье.",
        ["Восточное побережье"] = "Восточное побережье — полоса пляжей к юго-востоку от Южнобережья, между городом и холмами Дун Гарока. На песке и в прибрежных водах хозяйничают наги: чешуйчатые воины и колдуньи выходят из моря и стоят лагерем прямо у кромки воды. Рыбакам Южнобережья сюда лучше не соваться, и маршал Редпат неспроста поручил одному из своих людей разобраться с угрозой с моря.",
        ["Западное побережье"] = "Западное побережье тянется от Южнобережья на запад, к подножию холмов Лазуритового рудника. Весь берег усеян маленькими стоянками мурлоков: они ставят хижины у самой воды, сушат сети и с визгом кидаются на всякого, кто подойдёт слишком близко. У этих же берегов водятся морские черепахи, чьё мясо шеф-повар Джессен из Южнобережья кладёт в свой знаменитый суп.",
        ["Остров Очищения"] = "Остров Очищения поднимается из Великого моря к югу от берега Хилсбрада — крутая скала, обвитая спиральной тропой. На вершине стоят старое кладбище и разрушенная сторожевая башня. Остров населён неупокоенными: проклятые паладины и судьи, осуждённые монахи и служители, корчащиеся в муках маги — духи людей и дворфов, которым нет покоя и после смерти. Живым здесь делать нечего, и лишь самые отчаянные переправляются сюда вплавь.",
        ["Холм Дарроу"] = "Холм Дарроу лежит на севере предгорий, под кручами, ведущими к Альтеракским горам. По его лугам бродят олени и горные львы, а в пещерах на склоне живут йети, чьи косматые шкуры ценят портные Южнобережья. Через холм проходит дорога между Мельницей Таррен и землями Альянса, и здесь нередко сходятся отряды обеих сторон.",
        ["Стена Торадина"] = "Стена Торадина замыкает предгорья с востока, отделяя их от нагорья Арати. Её возвёл король Торадин в дни империи Аратор, чтобы прикрыть молодые города людей от набегов троллей Амани. Прошли века; стена обветшала и во многих местах обрушилась, но её громада по-прежнему тянется через холмы, а дорога из Южнобережья проходит сквозь уцелевшие ворота в нагорье Арати.",
        ["Великое море"] = "Великое море омывает южный берег предгорий. Его воды у Хилсбрада холодны и неспокойны: у берега кормятся черепахи, а дальше в глубине ходят акулы. С пристани Южнобережья в ясный день виден Остров Очищения, а вдоль побережья тянутся стоянки мурлоков и наг.",
    },
    ["Пустоши"] = {
        _zone = "Пустоши — серая мёртвая земля на западе Калимдора. Когда-то здесь зеленела степь, но пробудившаяся от долгого сна принцесса Терадрас выпила из неё жизнь, и таурены назвали этот край Пустошами. От её союза с Зейтаром, первенцем Кенария, родились кентавры; первые ханы — Колк, Гелк, Магра, Мародос и Венг — дали начало племенам, воюющим друг с другом и со всеми пришлыми. Из пепла торчат кости кодо и мёртвые деревья, а над равниной вечно висят грозовые тучи. В руинах высокорождённых, разбитых Великим Расколом, поселились сатиры и наги, а культ Пылающего Клинка открывает порталы для демонов. Альянс держится на Высоте Найджела, Орда — в Деревне Ночных Охотников, и обе стороны ищут союзников среди племён Маграм и Гелкис. А в западных каньонах лежит Мародон — осквернённая гробница Зейтара, святыня кентавров.",
        ["Кладбище кодо"] = "Кладбище кодо — широкая котловина в сердце Пустошей, куда испокон веков приходят умирать старые кодо. Никто не знает почему, но огромные скелеты лежат здесь повсюду, наполовину засыпанные серой пылью, и многие принадлежат исполинам, каких ныне уже не встретишь. Между костями бродят изнурённые кодо, а на слабых слетаются падальщики. Говорят, духи павших зверей не покидают этих мест, и тот, кто тревожит их кости, может увидеть призрачных кодо.",
        ["Застава Скитающихся Духов"] = "Застава Скитающихся Духов — небольшой лагерь Орды у самого края Кладбища кодо. Здесь нет ни таверны, ни ветрокрылов, лишь шатры, торговцы да храбрецы-таурены на страже. Шаманы заставы провожают умирающих кодо в иной мир и говорят с духами павших зверей — отсюда и её название. Отсюда же Орда ведёт войну с кентаврами Колкар и демонами Пылающего Клинка, а чернокнижник из Отрёкшихся по имени Муарин ищет способ добраться до повелителя демонов лорда Азретока.",
        ["Побережье Сар'Терис"] = "Побережье Сар'Терис — полоса берега вдоль всего западного края Пустошей. В отличие от серых внутренних земель, здесь светит солнце и зеленеет трава, а волны Сокрытого Моря набегают на песок. Но берег небезопасен: у воды хозяйничают наги и морские великаны, в прибое роются макруры, а по холмам гуляют смерчи. У северной части побережья лежат обломки корабля Карнитола, разграбленного нагами, а на юге берег выводит к рыбацкой Деревне Ночных Охотников.",
        ["Крепость Громового Топора"] = "Крепость Громового Топора — оплот культа Пылающего Клинка на северо-западе: двор, казармы, башни и пещера в скале. Чернокнижники хранят здесь краденое: за красным кристаллом в пещере спрятана Демоническая шкатулка с Рукой Ируксоса, которой открывают порталы демонов на Поле Маннорок, а по слухам, здесь же скрыт Скипетр Света, похищенный у нагов. Сюда ушёл ночной эльф Тиранис, соблазнённый магией демонов, а его сестра Далинда томится в клетке культистов.",
        ["Пещера Болгана"] = "Пещера Болгана — грот в южных скалах Пустошей, куда ведёт шаткий верёвочный мост через ущелье Деревни Гелкис. Здесь живёт вождь племени Гелкис — Шак, и чужаку сюда хода нет. В глубине пещеры растут синие кристаллы, которые кентавры зовут Слезами Терадрас: шаманы Гелкис берегут их как святыню, веря, что через них мать кентавров хранит племя. Племя Маграм, не признающее власти Терадрас, мечтает разбить их и показать врагам, что заступницы у тех нет.",
        ["Поле Маннорок"] = "Поле Маннорок — выжженная равнина к югу от Заставы Скитающихся Духов, названная в честь повелителя преисподней Маннорота. Среди эльфийских руин пылают порталы, через которые Пылающий Клинок призывает инферналов, суккубов, гончих Скверны и стражей ужаса. Воздух густ от Скверны, и на плечи путника ложится мертвенная тяжесть. Демонами повелевает лорд Азреток, скрепляющий договоры с культистами, и сколько бы порталов ни запечатали, новые открываются вновь.",
        ["Саргерон"] = "Саргерон — руины древнего города ночных эльфов на северо-востоке Пустошей, разрушенного ещё в Войну Древних. Его истинное имя забыто; сатиры, поселившиеся среди колонн, назвали его Саргероном в честь своего хозяина Саргераса. Когда-то здесь стояли святилища Элуны, и в развалинах ещё можно найти её реликвии — жаровню, чашу и древние рунные камни. Теперь между ними крадутся сатиры, связанные с Пылающим Клинком, и Элуну здесь давно не чтут.",
        ["Деревня Маграм"] = "Деревня Маграм — стойбище кентавров на юго-востоке Пустошей, разбросанное по берегам и островкам жёлтых ядовитых озёр, связанным грубыми мостами. Маграм признают только силу: они не поклоняются Терадрас, как их братья Гелкис, и верят, что племя выживет лишь боевым духом. Вождь Джехн ведёт их в бесконечной войне с Гелкис, а старейшины охотно принимают помощь чужаков — если те докажут силу, пролив кровь врагов. Слабых же Маграм не слушают: их убивают.",
        ["Деревня Гелкис"] = "Деревня Гелкис — поселение кентавров на юге Пустошей, кольцом обступившее ущелье у дороги на Фералас. Утёсы внутри ущелья соединены мостами и ведут к Пещере Болгана, где укрылся вождь Шак. Гелкис — самое разумное из племён: они чтут землю и свою мать Терадрас, их шаманы слышат голос камня, и они знают общий язык. Их извечные враги — Маграм, и ради победы Гелкис готовы принять чужака, доказавшего дружбу кровью врага.",
        ["Долина Копий"] = "Долина Копий — укрытая горами долина на западе Пустошей, куда ведут лишь узкие проходы с юга и востока. Здесь живёт племя Мародин — хранители Мародона, священной гробницы Зейтара, отца всех кентавров; вход в неё — на юго-западе долины. Стеречь его дозволено лишь самым сильным воинам племени, а правит здесь вождь Храта. Мародин не ищут союзников и встречают пришельцев копьями. У северного края долины в клетке томится гоблинша Мелисса, пленница кентавров.",
        ["Высота Найджела"] = "Высота Найджела — форпост Альянса в северных горах Пустошей, среди скал и старых эльфийских развалин. Гарнизоном командует капитан Штормграда, следящий за войной Маграм и Гелкис: кто бы ни победил, он станет угрозой Альянсу. Рядом стоит Круг Кенария: хранитель рощи Марандис и его сёстры-дриады пришли из Когтистых гор, чтобы вернуть из Мародона останки Зейтара. Тут же Горная корпорация ищет пропавший груз Карнитола, а Алый орден держит своего посланника.",
        ["Деревня Колкар"] = "Деревня Колкар — стойбище племени Колкар на восточной окраине Пустошей, между руинами Саргерона и озёрами Маграм. Колкар — самое многочисленное племя кентавров Калимдора: их отряды грабят караваны в Степях и Дуротаре, и именно с ними первыми схлестнулась Орда. Здесь, в родовых землях, правит вождь Дез'хеп, и Орда шлёт воинов ударить в самое сердце племени. Другие племена тоже не любят Колкар и рады любому, кто их ослабит.",
        ["Лощина Тьмы"] = "Лощина Тьмы — потайное убежище культа Пылающего Клинка в горах на юго-востоке Пустошей, за землями Маграм. Среди исполинских грибов и скал культисты выстроили круг призыва, опутанный огромными цепями, и здесь, вдали от чужих глаз, свободно творят обряды призыва демонов. Чернокнижники культа охраняют лощину вместе с призванными тварями, и мало кто из путников знает, что за этими перевалами зреет угроза для всех Пустошей.",
        ["Сокрытое Море"] = "Сокрытое Море — бескрайний океан, омывающий западный берег Пустошей. Его штормовые волны бьют о Побережье Сар'Терис, а ветер поднимает над водой смерчи. В глубинах у берега скрыты затопленные руины высокорождённых, где обосновались наги, и обломки кораблей, так и не доплывших до Фераласа.",
        ["Тефрис-Аран"] = "Тефрис-Аран — развалины древнего поселения ночных эльфов на севере Пустошей, чуть севернее Крепости Громового Топора. Город, стоявший здесь, погиб, по всей видимости, в Великий Раскол, и теперь среди разбитых колонн бродят только дикие звери — ни культисты, ни кентавры сюда не заходят.",
        ["Этель-Ретор"] = "Этель-Ретор — руины ночных эльфов на северо-западном берегу Пустошей. Большая часть города ушла под воду; над волнами осталась лишь башня с мостиком к запертым вратам. В затопленных залах и на суше хозяйничают наги, но у башни держится маг Серебряного Рассвета: он изучает запечатанное строение и разыскивает Скипетр Света — реликвию, способную, по легендам, потопить целые города. Он подозревает, что скипетр в руках чернокнижников Крепости Громового Топора.",
        ["Остров Раназьяр"] = "Остров Раназьяр — скалистый островок у северо-западного берега Пустошей. На нём стоят руины высокорождённых, некогда бывшие частью того же города, что и Этель-Ретор, а ныне остров облюбовали наги. Капитан Ракмор, спасаясь от нагов, спрятал на этом острове свой сундук: его открывают два ключа, золотой и серебряный, но оба потеряны в бою — один достался нагам, другой утащили в глубину макруры. Сокровище всё ещё ждёт того, кто соберёт оба ключа.",
        ["Хижина Кормека"] = "Хижина Кормека — одинокая лачуга посреди голой равнины в северной части Пустошей, недалеко от Кладбища кодо. Кто такой Кормек, никто уже не помнит; ныне здесь обитает странная парочка: хозяйка хижины, о которой мало что известно, и гоблин Биббли, который приплясывает в загоне среди костей кодо, мечтая разбогатеть на них и утереть нос своему сопернику Смиду Заржавню.",
        ["Деревня Ночных Охотников"] = "Деревня Ночных Охотников — рыбацкий посёлок троллей на юго-западном берегу Пустошей, у Побережья Сар'Терис. Это главная опора Орды в этих краях: таверна с видом на море, ветрокрылы, торговцы и учителя рыбной ловли. Тролли кормят уловом и себя, и Заставу Скитающихся Духов, но море неспокойно: наги нападают на рыбаков, и кое-кто из троллей поклялся извести их род. А южнее, на берегу, дриада из Круга Кенария расспрашивает путников об останках Зейтара.",
        ["Лагерь Заржавня"] = "Лагерь Заржавня — крошечная стоянка гоблинов у дороги неподалёку от Кладбища кодо. Здесь хозяйничает предприимчивый Смид Заржавень: он скупает прирученных кодо и снаряжает караван, что ходит через Пустоши, и ему позарез нужны новые звери, пока караван не пришёл. Со своим соседом Биббли из Хижины Кормека он давно соперничает, кто первым разбогатеет на кодо.",
    },
    ["Пылающие степи"] = {
        _zone = "Пылающие степи — выжженная земля к северу от Красногорья, на единственной сухопутной дороге из Штормграда в Каз Модан. Когда-то это была часть зелёных Красногорных гор, но столетия назад чародей-тан Тауриссан, вождь изгнанных дворфов Чёрного Железа, призвал на помощь силу, которой не мог управлять: из недр земли восстал повелитель огня Рагнарос. Его пробуждение расплавило горы, обратило долины в пепел и породило вулкан, что ныне зовётся Чёрной горой. Во Вторую войну здесь стояла Орда, и у подножия вулкана пал сэр Андуин Лотар, верховный командующий Альянса. С тех пор небо над степями красно от извержений, а по трещинам течёт лава. Землю делят между собой орки клана Чёрной горы под началом Ренда Чернорука, чёрные драконы Нефариана, брата Ониксии, огры и дворфы Чёрного Железа. Альянс держится лишь в Дозоре Моргана на юго-востоке, а нейтральный Пламенеющий Стяг даёт приют редким путникам, что осмелились пройти этой дорогой.",
        ["Скала Молота Ужаса"] = "Скала Молота Ужаса возвышается на северо-востоке степей, в стороне от главной дороги. Внутри скалы вырыты запутанные пещеры и норы, а по склонам вьются тропы к самой вершине. Здесь обосновались огры, не признающие никаких союзников, кроме собственного племени, и мечтающие изгнать из степей все прочие народы. Их лагерь хорошо укреплён, и незваного гостя встречают задолго до того, как он увидит хоть одного огра. Среди этих великанов немало огров-магов, чьи чары не уступают их дубинам.",
        ["Руины Тауриссана"] = "Руины Тауриссана лежат посреди степей — всё, что осталось от первой столицы дворфов Чёрного Железа. Изгнанные из Стальгорна после Войны Трёх Молотов, они ушли на юг и построили здесь город, названный в честь чародея-тана Тауриссана. Проигрывая войну, тан попытался призвать на подмогу стихию и вызвал из-под земли самого Рагнароса. Город был уничтожен в одно мгновение, а уцелевшие дворфы стали рабами повелителя огня и ушли под Чёрную гору, где возвели Тенегорн. Ныне среди обломков бродят агенты Чёрного Железа, а учёные Стальгорна ищут здесь реликвии, хранящие память о гибели города.",
        ["Пламенеющий Стяг"] = "Пламенеющий Стяг стоит на скальном уступе в северной части степей; попасть сюда можно только по шаткому мосту. Это крохотное нейтральное пристанище, где гоблины и горстка отчаянных путников устроили лагерь под самой Чёрной горой. В пещере за лагерем живёт гоблин Киблер, торгующий диковинными зверушками и вечно спорящий со своим попугаем, а гоблинша Тинки изучает здешних драконов. У костра можно встретить и Джона-Оборванца — дворфа, чей рассудок пострадал в странствиях по этим землям. Для многих это последняя стоянка перед горой.",
        ["Крепость Черной горы"] = "Крепость Чёрной горы раскинулась на севере степей, у самого входа в вулкан. Это главное поселение орков клана Чёрной горы за пределами Пика — они не признали перемирия Тралла с Альянсом и живут по старым обычаям Первой и Второй войн. Орки добывают в окрестных горах руду, куют оружие и доспехи и постоянно готовятся к походу на юг. Крепость укрыта от дороги, но дозорные всегда следят за подступами, и всякого чужака здесь ждёт бой с рубаками и чародеями клана.",
        ["Башня Пепла"] = "Башня Пепла возвышается на пепельной равнине к югу от Чёрной горы. Вокруг неё раскинулось становище орков клана Чёрной горы: здесь стоят их хижины, горят костры и упражняются воины. Чародеи и чернокнижники клана поднимаются на башню, откуда видны все подходы к горе. Одинокому путнику лучше обойти это место стороной — орки не щадят никого, кто ступит на их землю.",
        ["Черная гора"] = "Чёрная гора — исполинский вулкан на северо-западе степей, рождённый в тот день, когда чародей-тан Тауриссан призвал в мир повелителя огня Рагнароса. Во Вторую войну Орда сделала Пик Чёрной горы своей цитаделью, и у его подножия Оргрим Молот Рока сразил сэра Андуина Лотара. Ныне гора поделена между врагами: в глубинах Тенегорна правят дворфы Чёрного Железа, ещё ниже, в Огненных Недрах, дремлет сам Рагнарос, а на вершине, в Логове Крыла Тьмы, чёрный дракон Нефариан плетёт свои замыслы. Между ними стоят орки Ренда Чернорука, называющие себя истинной Ордой. Через недра горы проходит и единственный путь из степей в Тлеющее ущелье.",
        ["Алтарь Бурь"] = "Алтарь Бурь стоит на западной окраине степей, в тени Пика Чёрной горы. Такие алтари орочьи чернокнижники возводили во Вторую войну: здесь они превращали огров в огров-магов, наделяя их разумом и колдовской силой. Камень давно растрескался и оплавился, но остатки его мощи по-прежнему притягивают чернокнижников клана Чёрной горы, творящих у алтаря свои обряды. На холме неподалёку живёт и чернокнижник Мор'зул Вестник Крови — он изучает алтарь и, говорят, знает, как призвать коня из самой Бездны.",
        ["Перевал Черной горы"] = "Перевал Чёрной горы — главные ворота в степи со стороны Красногорья. За воротами кончаются тихие холмы у озера и начинается выжженная земля: небо краснеет, воздух густеет от пепла, а по обочинам тлеет опалённая трава. Перевал стерегут орки клана Чёрной горы, и им же он служит дорогой для набегов на юг. Тому, кому такой путь не по силам, лучше повернуть обратно, пока не поздно, — за перевалом враг куда сильнее, чем в Красногорье.",
        ["Дозор Моргана"] = "Дозор Моргана — последний оплот Альянса в степях, укрывшийся в юго-восточном углу зоны. Когда-то это была деревня с каменной башней мага, но от неё остались лишь обгорелые стены; ныне жители ютятся в палатках между развалин. Гарнизоном командует маршал Максвелл, а вместе с ним здесь несут службу разведчики и учёные, следящие за кланом Чёрной горы и чёрными драконами. Отсюда грифоны летят в Штормград, и для героев Альянса это единственное место в степях, где можно перевести дух.",
        ["Скользкая скала"] = "Скользкая скала — небольшая пещера в дальнем северо-восточном углу степей, скрытая за Тропой Крылатого Ужаса. Здесь в одиночестве живёт чёрный драконид, который, в отличие от своих сородичей, готов вести дела с чужаками — правда, не скупясь на насмешки и колкости. Добраться до пещеры непросто: путь к ней лежит через долину, где хозяйничают драконы.",
        ["Тропа Крылатого Ужаса"] = "Тропа Крылатого Ужаса тянется по восточной части степей — это долина, которую облюбовал чёрный драконий выводок. Здесь кишат детёныши драконов и дракониды, а над тропой кружат чёрные драконы постарше. Среди лавовых потоков порой встречается и огромный магматический великан, бредущий по долине. Тропу считают одним из самых опасных мест в степях: даже бывалые герои не решаются пройти по ней в одиночку.",
        ["Драко'дар"] = "Драко'дар — опалённые холмы на юго-западе степей, где хозяйничает чёрный драконий выводок. Здесь бродят дракониды и детёныши драконов, а в небе патрулируют их старшие сородичи. Путникам, идущим по южной дороге, лучше не сходить с неё в сторону холмов: чёрный дракон считает каждого чужака своей добычей.",
    },
    ["Пылевые топи"] = {
        _zone = "Пылевые топи — жаркое, вечно сырое болото на восточном побережье Калимдора, между Степями и Тысячей Игл. Когда-то здесь лежала высокая равнина, но Великий Раскол обрушил её вниз, и подземные воды превратили долину в трясину, где кроколиски и мурлоки таятся в каждой заводи. После битвы за гору Хиджал сюда привела своих людей леди Джайна Праудмур: на скалистом острове вырос Терамор, а вдоль дороги в Степи встали сторожевые башни. Затем флот адмирала Даэлина Праудмура попытался подчинить эти земли, и его гибель сделала мир между Альянсом и Ордой хрупким. Огры клана Каменного Молота, союзники Орды, потеряли родную деревню на юге, когда туда пришёл выводок Ониксии, дочери Смертокрыла, и отступили в Гиблотопь. Теперь южные топи зовут Землёй Драконов, на дороге чернеют руины сожжённой таверны, а в глуши прячутся дезертиры Терамора и таурены Зловещего Тотема.",
        ["Таверна \"Последний привал\""] = "На границе Степей и Пылевых топей чернеют обгорелые стены таверны «Последний привал». Её построил человек из Терамора, Джеймс Хьяль, чтобы давать кров путникам на дороге к морю, но однажды таверна сгорела дотла, а его жена и ребёнок погибли в огне. Кто поджёг её, так и не выяснено: улики в пепле ведут в разные стороны, и дознание ведут разом стража Терамора и посланцы Орды из Гиблотопи. Над пожарищем тишина, и лишь ветер со Степей перебирает золу.",
        ["Деревня Гиблотопь"] = "Деревня Гиблотопь на северо-западе болота — единственный оплот Орды в Пылевых топях. Её основали огры клана Каменного Молота, бежавшие с юга после того, как их деревню разорили чёрные драконы; теперь ими правит властитель Мок'Морокк, а рядом живут орки и таурены. Среди хижин и огрского кургана горят костры, отсюда летают ветрокрылы в Оргриммар и Громовой Утёс, а дозорные следят за разведчиками Терамора у самых стен. Огры не забыли утраченный дом и ждут дня, когда вернутся на юг.",
        ["Сторожка \"Болотный огонек\""] = "«Болотный огонёк» — одинокая сторожка на Ведьмином холме, где живёт старый отшельник, знаменитый на всё болото своей похлёбкой. Ему нужны лягушачьи лапки, паучьи глаза и прочие дары трясины, и он охотно делится рецептами с теми, кто не боится бродить по округе. Дом окружён могилами и бродячими мертвецами, так что старик почти не выходит за порог, а в его огородике, говорят, зарыто нечто такое, что интересует и Терамор, и Гиблотопь.",
        ["Логово Кровавой Топи"] = "Логово Кровавой Топи — пещера в юго-западной части болота, где гнездится целая стая ящеров. Перед входом видны остатки чьего-то поселения, растерзанного хищниками: ящеры не оставили здесь ни живых, ни целых стен. Их крики разносятся над водой далеко, и путник, услышавший визг стаи, делает крюк, каким бы долгим он ни был.",
        ["Мглистая пещера"] = "Мглистая пещера на северо-западе топей когда-то была небольшой шахтой: у входа до сих пор стоят развалины домиков, где жили рудокопы. Теперь штольни принадлежат громадным паукам, чья паутина затягивает каждый проход, и никто уже не помнит, пещеру ли назвали в честь пауков или пауков в честь пещеры. Только отшельник с Ведьминого холма зачем-то ищет глаза этих тварей для своей похлёбки.",
        ["Место крушения Бизиля"] = "В самой глухой части Трясины, к востоку от хижины Табеты, лежит разбитый гоблинский дирижабль. Он вёз груз на юг, но рухнул в болото; его команда и пилот Бизиль пропали без следа, а по кочкам разбросаны ящики с товаром. Среди обломков ещё можно найти гоблинские взрывные механизмы, за которыми охотятся инженеры, если, конечно, их не опередят кроколиски и болотные чудища, облюбовавшие место крушения.",
        ["Ведьмин холм"] = "Ведьмин холм поднимается над болотом на полпути от Степей к Терамору, и дурная слава его не случайна: по склонам бродят зомби и беспокойные духи, а ночью среди могил мерещатся тени. Люди Терамора не знают, откуда взялась эта скверна; шепчутся, что над холмом тяготеет чья-то злая воля. У подножия расположились стойбища мурлоков, а на вершине стоит сторожка отшельника, который упрямо не желает покидать проклятое место.",
        ["Сторожевой пост"] = "Сторожевой пост — дозорная башня Терамора на материковом берегу, прямо напротив моста, ведущего к островному городу. Отсюда стража следит за всеми, кто идёт по дороге к Терамору, и первой встречает и торговцев, и лазутчиков. Место тихое, но караульные не дремлют: по эту сторону моста уже начинается болото со всеми его опасностями.",
        ["Северная башня"] = "Северная башня стоит у оживлённого участка дороги, ведущей из Терамора в Степи, — это самый дальний из постов, что люди леди Джайны возвели после основания города. Её гарнизон стережёт путь и присматривает за северными топями, где в Синей топи и дальше к востоку прячутся таурены Зловещего Тотема. С тех пор как западная башня досталась дезертирам, эта застава осталась последним надёжным оплотом Терамора на дороге.",
        ["Западная башня"] = "На западной окраине топей, у дороги в Степи, люди Терамора когда-то поставили одну из своих сторожевых башен, чтобы охранять путь от Степей к морю. Здесь болото ещё мелкое, но кроколиски и пауки подбираются к самым стенам. Гарнизон Терамора давно уже не держит эти места так крепко, как прежде, и башня стоит скорее памятником былым притязаниям, чем оплотом.",
        ["Разрушенная башня"] = "Разрушенная башня в западной части топей — обветшалый дозорный пост, некогда построенный людьми Терамора. Теперь в нём засели дезертиры, бросившие службу леди Джайне; их главарь, говорят, знает кое-что о пропавшем дипломате, которого ищет весь Терамор. Город считает башню потерянной и посылает сюда только тех, кто готов задавать вопросы силой.",
        ["Синяя топь"] = "Синяя топь — мокрая низина к востоку от Гиблотопи, где болото только начинает набирать силу. По кочкам снуют пауки и ящеры, в воде дремлют кроколиски, а над камышами кружат птицы. Здесь же, среди тростника, скрываются разведчики Терамора, следящие за деревней огров, а дальше к востоку раскинулось стойбище тауренов Зловещего Тотема, чьи замыслы никому не известны.",
        ["Руины Деревни Каменного Молота"] = "Руины Деревни Каменного Молота — всё, что осталось от прежнего дома огров клана. Они поселились в южных топях, придя в Калимдор вместе с Ордой; здесь Рексар одолел их жестокого вождя, возглавил клан и повёл его на войну с Кул-Тирасом. Но затем на деревню обрушился выводок Ониксии, и уцелевшие огры бежали на север, в Гиблотопь. Теперь среди обгорелых хижин хозяйничают драконоиды чёрной стаи, а огры мечтают однажды отвоевать родные руины.",
        ["Огненное логово"] = "Огненное логово к западу от руин Деревни Каменного Молота — бывший огрский курган, крупнейшая постройка клана. После падения деревни его захватили драконоиды чёрной стаи, и теперь у входа стоят на страже чешуйчатые воины Ониксии, а внутри тлеет огонь. Огры помнят, что где-то в этом кургане остались их святыни, но пробиться к ним сквозь драконью стражу под силу немногим.",
        ["Земля Драконов"] = "Земля Драконов — южная часть болота, где чёрная стая чувствует себя хозяйкой. Среди тёмных заводей бродят драконоиды, а над ними носятся стаи молодых дракончиков, вылупившихся в топях: Ониксия избрала эти края для своих кладок. Землю Драконов окружают Огненное логово и руины Деревни Каменного Молота, отнятые у огров, и всякий, кто идёт этой дорогой на юг, слышит шипение из-за каждого камня.",
        ["Драконьи топи"] = "Драконьи топи — самый юг Пылевых топей, край, где болото становится каменистым и где чёрные драконы водятся в таком множестве, что дали имя всей округе. Между скал разбросаны логова; в одном из них обитает древний дракон Огнебор, а в другом, за пастью, вырезанной в камне, укрылась сама Ониксия. Дракончики и чешуйчатые стражи чёрной стаи нападают на всякого, кто заходит слишком далеко, и даже Альянс и Орда обходят это место стороной.",
        ["Остров Терамор"] = "Остров Терамор — скалистый остров у восточного берега болота и главный оплот Альянса в Калимдоре. Леди Джайна Праудмур основала этот город после битвы за гору Хиджал, приведя сюда уцелевших с земель Лордерона, и отсюда держит хрупкий мир с Ордой Тралла. За крепкими стенами стоят гавань, откуда корабли ходят в Гавань Менетилов, казармы стражи и башня самой волшебницы. Но дальше стен власть Терамора не простирается: дороги стерегут дезертиры и таурены Зловещего Тотема, а в городе ищут пропавшего дипломата.",
        ["Цитадель"] = "Цитадель — сердце Терамора, приземистая крепость посреди города, где расположены казармы стражи. Отсюда командует гарнизоном капитан Ваймс, ведущий дознание о сожжённой таверне на границе Степей; здесь же несёт службу командир Самаул из гвардии леди Джайны. Стены цитадели помнят и худшие дни: именно здесь пал адмирал Даэлин Праудмур, когда Орда во главе с Рексаром штурмовала город, занятый флотом Кул-Тираса.",
        ["Потайная бухта"] = "Потайная бухта — укромный уголок на скалистом побережье возле Терамора, где мутная вода болота смешивается с морской. Прибой вымыл в камне ниши и гроты, и говорят, что некоторые из них уходят под самый остров. Сюда заглядывают разве что рыбаки да морские черепахи, а в тени скал тихо, как в подземелье.",
        ["Пылевая бухта"] = "Пылевая бухта — часть Великого моря между болотистым берегом и островом Терамор. Её воды бурые от ила, что несёт болото, но именно сюда приходят корабли из Гавани Менетилов, ведь подводные скалы делают путь из Кабестана слишком опасным. У берегов плавают черепахи и мурлоки, а к югу бухта переходит в залив, где живёт знаменитый рыбак Нэт Пэгл.",
        ["Залив Яростных Волн"] = "Залив Яростных Волн — южная оконечность Пылевой бухты, к югу от Терамора и у самого берега Драконьих топей. Мелководье усеяно островками и рифами, о которые разбились уже два корабля; их остовы облюбовали макруры. На одном из островков поселился Нэт Пэгл, самый знаменитый рыбак Азерота: он удит с утра до вечера и охотно рассказывает о своих приключениях каждому, кто по-настоящему предан рыбной ловле.",
        ["Зловещий берег"] = "Зловещий берег — полоса побережья и цепочка островков между Терамором и крепостью Северной Стражи в Степях. Эти солёные заводи давно облюбовали мурлоки: их стойбища теснятся на каждой отмели, а из воды выползают морские черепахи. Люди Терамора ходят сюда за черепашьим мясом и рыбой, но всегда с оглядкой: мурлоки ревниво берегут свой берег.",
        ["Остров Алькац"] = "Остров Алькац лежит у северо-восточного побережья топей и не похож на них: здесь растут пальмы, как на Островах Эха. Некогда на острове жили люди, но их сменили наги Страшаза, а в водах вокруг кишат гидры. Наги словно охраняют нечто спрятанное в подземных ходах острова, и никто не знает, что именно. Недавно на Алькац прилетел на летающей машине безумный гном-изобретатель со своими послушными прислужниками, и остров стал ещё опаснее.",
        ["Логово Огнебора"] = "Логово Огнебора — просторная пещера в Драконьих топях, где обитает древний чёрный дракон Огнебор. Он служит привратником чёрной стаи: молодые драконы проходят у него суровые испытания, и лишь сильнейшие удостаиваются права войти в свиту Ониксии. Вход стерегут чешуйчатые стражи, а внутри воздух дрожит от жара драконьего дыхания, и мало кто из смертных решается заглянуть в эту тьму.",
        ["Трясина"] = "Трясина — обширная топь в самом сердце болота, от Разрушенной башни на западе до Пылевой бухты на востоке. Здесь кроколиски дремлют в каждой заводи, по кочкам ползают пауки и слизни, а на тропах встречаются таурены Зловещего Тотема. В самом глухом углу стоит хижина волшебницы Табеты, которая живёт с двумя учениками и принимает магов, ищущих знаний; неподалёку в трясине лежит разбитый гоблинский дирижабль.",
        ["Великое море"] = "Великое море омывает Пылевые топи с востока. Оно родилось при Великом Расколе, когда воды хлынули в разлом древнего Калимдора, и с тех пор отделяет один континент от другого. Отсюда, от причалов Терамора, корабли уходят в Гавань Менетилов, а у берегов болота в солёных волнах живут черепахи, акулы и мурлоки; дальше в море заплывать не стоит — там нет ничего, кроме бездны.",
    },
    ["Серебряный бор"] = {
        _zone = "Серебряный бор лежит между Тирисфальскими лесами и предгорьями Хилсбрада, от Великого моря на западе до озера Лордамер на востоке. Когда-то это был чистый и красивый лес Лордерона, но Третья война прошла по нему огнём и чумой: Плеть жгла посевы и вырезала деревни, а сосны побледнели от заразы и стоят теперь серые и больные. Даларан был занят восстановлением своего города, Гилнеас затворился за Стеной Седогрива, и присматривать за лесом стало некому. Север заняли Отрекшиеся: из Гробницы стражи смерти ведут разведку, а аптекари варят новую чуму. На юге, в крепости Тёмного Клыка, засел безумный архимаг Аругал, и его воргены рыщут по дорогам. На острове Фенриса окопались гноллы-гнилошкуры, слуги Плети, а в Янтарной Мельнице держатся волшебники Кирин-Тора. Каждая из этих сил считает лес своим, и судьба его пока не решена.",
        ["Остров Фенриса"] = "Остров Фенриса лежит посреди озера Лордамер, и вместе с Рассветными островами он образует разорванное кольцо суши на воде. Когда Плеть пришла в Лордерон, жители острова бежали или были перебиты, а опустевшую крепость заняли гноллы-гнилошкуры. Ими правит Тул Коготь Ворона, бывший маг Кирин-Тора, предавший своих братьев ради Короля-лича. Отрекшиеся считают остров главным оплотом Плети в Серебряном бору и готовят на него нападение.",
        ["Деревня Погребальных Костров"] = "Деревня Погребальных Костров стоит на юге леса, у самого подножия холма с крепостью Тёмного Клыка. Аругал наложил на её жителей проклятие: днём они выглядят обычными людьми, но с заходом солнца обращаются в воргенов Лунной Ярости. Деревенский совет служит архимагу марионеткой, через которую он держит односельчан в повиновении. При свете дня здесь всё ещё торгуют с путниками, а в таверне сохранился кабинет аптекаря Берарда, тоже попавшего под чары Аругала.",
        ["Серебряный рудник"] = "Серебряный рудник уходит в холмы к юго-востоку от Гробницы. Магия Аругала дотянулась и сюда: бывший старшина рудника Мрачнон Белесый обратился в воргена и теперь ведёт стаю таких же тварей в тёмных штольнях. Для Отрекшихся рудник мог бы стать ценным ресурсом, и Далар Ткач Рассвета не оставил надежды однажды его отвоевать.",
        ["Струящаяся Тьма"] = "Струящаяся Тьма — заброшенная шахта на северо-западе леса, недалеко от берега. Её выработки и окрестности кишат пауками, а в глубине, среди коконов, прячется их огромная матка. Аптекари Гробницы посылают сюда за паучьей кровью: в соединении с ядом из сердца бешеного медведя она, по их расчётам, даёт смертельный эликсир для новой чумы.",
        ["Поле Валгана"] = "Поле Валгана — ещё одна из заброшенных ферм севера Серебряного бора, к западу от Сияющего берега и к востоку от главной дороги. Она названа по имени прежнего хозяина, который погиб или бежал, когда в лес пришла Плеть. Теперь по заросшим полям бродят воргены Лунной Ярости. В лучшие времена отсюда открывался прекрасный вид на озеро Лордамер.",
        ["Гробница"] = "Гробница когда-то была лишь кладбищем при дороге, пересекающей Серебряный бор. После Третьей войны Отрекшиеся превратили старый склеп в свою базу в этих краях. Отсюда верховный палач Хадрик рассылает стражей смерти, аптекарь Ренферрел ищет ингредиенты для новой чумы, а Далар Ткач Рассвета изучает магию Аругала. Воргены на юге, Плеть на востоке и Кирин-Тор на юго-востоке делают Гробницу едва ли не единственным безопасным местом во всём лесу.",
        ["Удел Ольсена"] = "Удел Ольсена стоит у главной дороги к югу от Гробницы и когда-то был бойкой фермой на самом торговом пути. Через несколько лет после Третьей войны от хозяйства остались лишь заросшие бурьяном руины. Здесь рыщет нежить, подчинённая Тулу Когтю Ворона, и нападает на любого, кто сойдёт с дороги.",
        ["Стена Седогрива"] = "Стена Седогрива закрывает весь юг Серебряного бора. Король Генн Седогрив возвёл её после Второй войны, когда Гилнеас вышел из Альянса и решил отгородиться от остального Лордерона. С тех пор ворота заперты, а стражи на стене не видно, и никто по эту сторону не знает, что происходит за ней. В её тени ютятся измождённые и больные беженцы, которым Гилнеас так и не открыл ворота, и они становятся лёгкой добычей воргенов, забредающих сюда из крепости Тёмного Клыка.",
        ["Погибель Берена"] = "Погибель Берена — пещера в холмах к юго-западу от Янтарной Мельницы, между главной дорогой и просёлком, ведущим от деревни. По донесениям разведчиков, здесь укрылась нежить, готовящая нападение на Гробницу. Это слуги Тула Когтя Ворона: чернорабочие и стражи, которых он послал с острова Фенриса на большую землю. Жрец Тьмы Алистер хочет ударить первым и задушить их замысел в зародыше.",
        ["Рассветные острова"] = "Рассветные острова — цепочка низких островков у восточного берега, к югу от острова Фенриса. Когда-то они поднимались из прозрачной воды озера Лордамер и считались чудесным местом, но чума нежити добралась и до них. Деревья здесь растут больные и чахлые, а по берегам хозяйничают мурлоки и болотные твари.",
        ["Янтарная мельница"] = "Янтарная Мельница на юго-востоке леса до Третьей войны была тихим посёлком лесорубов. После войны сюда пришли волшебники Даларана: деревня стоит на спящем узле силовых линий, и Кирин-Тор хочет пробудить его для какой-то большой цели. Повозки из Хилсбрада везут магам сундуки с припасами, а маги, окудники и заступники носят подвески Даларана. Для Отрекшихся это последний оплот людей в Серебряном бору, и Гробница внимательно следит за каждым шагом волшебников.",
        ["Крепость Фенриса"] = "Крепость Фенриса стоит на острове посреди озера Лордамер и не была пощажена, когда Плеть захлестнула Лордерон. Тул Коготь Ворона, честолюбивый молодой маг из Кирин-Тора, перешёл на сторону Плети, подчинил себе местных гноллов и создал из них стаю гнилошкуров. Он сделался хозяином крепости, а гноллы устроились у её стен. В её дворе, у стойл, лежит в безымянной могиле тело Аларика, бывшего телохранителя Тула, которого хозяин обезглавил ради забавы.",
        ["Крепость Темного Клыка"] = "Крепость Тёмного Клыка возвышается на холме над деревней Погребальных Костров. Когда-то это был замок гилнеасского барона, но в Третью войну архимаг Аругал, вопреки советам Кирин-Тора, призвал из иного мира воргенов, чтобы обратить их против Плети. Волчьи твари разгромили нежить, а затем набросились на людей: они взяли крепость и перебили барона со всем его домом. Сломленный виной Аругал назвал воргенов своими детьми и затворился с ними в крепости, получившей новое имя. Говорят, призрак барона до сих пор бродит по её залам.",
        ["Старая переправа"] = "Старая переправа — обветшалый причал на берегу озера Лордамер к востоку от Гробницы, откуда некогда ходили лодки на остров Фенриса. Теперь переправу стерегут гноллы-гнилошкуры и всякая нежить, а вдоль настила громоздятся кучи чумных трупов. Стражи смерти видели здесь Фенвика Татроса, вожака нежити, поселившейся в лесу, и Отрекшиеся уверены, что Плеть заняла это место неспроста.",
        ["Сад Мальдена"] = "Сад Мальдена — небольшой заброшенный фруктовый сад на севере леса, у подножия холмов. Хозяев здесь давно нет, деревья одичали, а по дорогам к саду бродят стаи воргов. Аптекари Отрекшихся ценят их обесцвеченные сердца: из них варят целительные зелья.",
        ["Делянка Ивара"] = "Делянка Ивара — тыквенное поле на севере леса, недалеко от дороги в Тирисфаль. Когда-то это была богатая ферма, и её владелец Ивар держал много работников, но Плеть разорила Лордерон, а сам хозяин обратился в вурдалака. Ивар Нечистый до сих пор торчит в старом амбаре. На заброшенной ферме укрылись стражи смерти Ран и Квинн Йорик, отправленные на разведку северного Серебряного бора.",
        ["Мертвое поле"] = "Мёртвое поле — заброшенная ферма на севере Серебряного бора, к северу от Гробницы. Чьё это было хозяйство, уже никто не помнит; теперь здесь устроили лагерь гноллы-гнилошкуры, слуги Плети. Отрекшиеся посылали против них небольшие отряды, но каждый раз гноллам приходила на помощь банши Плеть Ночи, и её крик обращал воинов в бегство.",
        ["Берег Северного прилива"] = "Берег Северного прилива — северо-западное побережье Серебряного бора, полоса песка и узкая кромка Великого моря. Самая приметная вещь здесь — полузатонувший корабль, лежащий у самой воды. Иных следов человека на этом пустынном берегу почти не осталось.",
        ["Берег Южного прилива"] = "Берег Южного прилива — юго-западное побережье Серебряного бора, длинная полоса берега вдоль Великого моря. Она тянется от северных пляжей до самой Стены Седогрива, за которой начинается закрытый Гилнеас. Здесь тихо: лишь шум прибоя, серые сосны над обрывом и звери, спускающиеся к воде.",
        ["Сияющий берег"] = "Сияющий берег — восточное побережье Серебряного бора вдоль озера Лордамер, от границы Тирисфаля на севере до холмов, отделяющих лес от Альтерака. Вдоль всего берега стоят поселения мурлоков, и для неопытного путника здесь опасно. Аптекарь Берард в своих записях упоминал редкую опухоль, которую можно добыть у этих мурлоков и которая, по его мнению, пригодилась бы для новой чумы.",
        ["Северная приливная низина"] = "Северная приливная низина — небольшая ложбина у северо-западного берега, рядом с Берегом Северного прилива. Воргены Аругала устроили здесь грубые стоянки, где есть лишь самое необходимое для выживания. Место глухое и безлюдное, и забредать сюда стоит с осторожностью.",
        ["Озеро Лордамер"] = "Озеро Лордамер — огромное пресное озеро в сердце Лордерона, у восточной границы Серебряного бора. В былые времена оно кормило рыбой и поило водой королевства людей, а на его южном берегу стоял Даларан. Давным-давно древняя чума погубила в озере всякую жизнь, и аптекари Отрекшихся до сих пор изучают её тайну. Посреди воды лежит остров Фенриса с разорённой крепостью, а южнее — Рассветные острова.",
        ["Великое море"] = "Великое море омывает западный берег Серебряного бора. Это бескрайний океан, разделяющий континенты Азерота, а в самом его центре бушует Водоворот. На побережье леса о нём напоминают лишь прибой, обломки кораблей на песке и серые сосны над обрывами.",
    },
    ["Силитус"] = {
        _zone = "Силитус — раскалённая пустыня на юго-западной оконечности Калимдора, куда ведёт единственная тропа из северо-западного угла кратера Ун'Горо. Тысячу лет назад здесь гремела Война Зыбучих песков: ночные эльфы Фэндрала Оленьего Шлема и драконы четырёх выводков во главе с Анахроносом остановили полчища киражей и заперли их в Ан'Кираже за Стеной Скарабея. Силитиды, насекомые-слуги киражей, с тех пор расплодились и изрыли пески громадными ульями. За ними следят друиды Круга Кенария из Крепости Кенария, а бронзовые драконы Ноздорму впервые за долгие века вернулись в пустыню. В дальних лагерях сектанты Сумеречного Молота через Ветровые Камни взывают к повелителям стихий из Совета Бездны. А у запертых врат висит Гонг Скарабея, и час, когда в него ударят, уже близок.",
        ["Сокрытое Море"] = "Сокрытое Море омывает западный край Силитуса, и его волны едва слышны за грядой прибрежных скал. Здесь пустыня обрывается в океан, что тянется вдоль всего западного побережья Калимдора, а с воды дует редкий прохладный ветер. На этот глухой берег почти никто не заходит: ни силитиды, ни сектанты не ищут ничего у солёной воды.",
        ["Стена Скарабея"] = "Стена Скарабея тянется вдоль южной кромки Силитуса от края до края, отделяя пустыню от крепости Ан'Кираж. Её возвели в конце Войны Зыбучих песков: ночные эльфы подняли стену из самого песка, а выше неё магия бронзовых драконов создала незримый заслон во много раз выше камня. Этот барьер тысячу лет удерживает силитидов и их повелителей-киражей внутри стен Ан'Киража. У самых врат ждёт своего часа Гонг Скарабея, а рядом несут вахту бронзовые драконы из выводка Ноздорму.",
        ["Деревня Южного Ветра"] = "Деревня Южного Ветра — руины ночноэльфийской заставы в юго-восточном Силитусе, у самой кромки Улья Регал. Тысячу лет назад Фэндрал Олений Шлем приказал своему сыну Вальстану оборонять эту деревню, и в тот же день она пала под натиском армий Ан'Киража, а Вальстан расстался с жизнью. С тех пор селение так и осталось лежать в песке: между разрушенных стен роятся силитиды, а по улицам бродят неупокоенные духи друидов и часовых, павших в ту ночь.",
        ["Сумеречный лагерь"] = "Сумеречный лагерь — один из четырёх станов Сумеречного Молота в Силитусе, обнесённое низкой стеной скопище хижин и нор. Сектанты в тёмных одеждах поклоняются Древним богам и по обрывкам старого пророчества возвели здесь Ветровой Камень, через который взывают к своим повелителям из Совета Бездны. Хранители лагеря ревниво берегут тексты Истинно Верующего, и любого чужака, застигнутого у камня, ждёт немедленная расправа.",
        ["Долина Кристаллов"] = "Долина Кристаллов лежит в дальнем северо-западном углу Силитуса, среди скал, богатых ториевой рудой. Здесь бродят духи земли и воздуха, и воздух гудит от их гнева. По рассказам сектантов, честолюбивый чернокнижник Демитриан из Сумеречного Молота попытался поработить в этой долине могучего повелителя ветра и сам угодил к нему в услужение. Теперь от его лагеря остались лишь обгорелые развалины, а сам Демитриан всё ещё скитается среди кристаллов.",
        ["Помост Скарабея"] = "Помост Скарабея стоит к северо-западу от врат, прямо перед Стеной Скарабея. На этом возвышении висит Гонг Скарабея — древний инструмент, оставленный здесь после Войны Зыбучих песков. По пророчеству, врата Ан'Киража откроются лишь тогда, когда носитель воссозданного Скипетра Зыбучих Песков ударит в гонг. Возле помоста несут вахту бронзовые драконы, и именно здесь, когда придёт время, должны сойтись войска Орды и Альянса для войны в Ан'Кираже.",
        ["Улей Аши"] = "Улей Аши — обширное гнездо силитидов в северной части Силитуса, у дороги на Крепость Кенария. Из земли торчат костяные шпили и уступы, а под ними уходят вглубь тоннели, где насекомые откладывают яйца. Именно отсюда рои силитидов расползаются к Роящейся вершине. Друиды Круга Кенария следят за этим гнездом и отправляют разведчиков к самому входу в улей, чтобы узнать, как далеко успели прокопаться насекомые.",
        ["Улей Зора"] = "Улей Зора раскинулся в западном Силитусе, между лагерями Сумеречного Молота и берегом Сокрытого Моря. Песок здесь прорезан рытвинами и норами, а над ними высятся колючие наросты, из которых постоянно выползают новые силитиды. Гнездо охраняют летучие осы и рои мелких насекомых, а в глубине улья, за узким входом, скрываются самые опасные его обитатели. Круг Кенария считает этот улей одной из главных угроз и щедро вознаграждает тех, кто бьётся с его роем.",
        ["Улей Регал"] = "Улей Регал лежит на юго-востоке Силитуса, у развалин Деревни Южного Ветра. Это один из самых опасных ульев пустыни: его тоннели уходят глубоко под скалы, а на поверхности снуют рабовладельцы, роющие силитиды и тяжёлые стражи гнезда. Неподалёку разбили лагеря дворфы Стальгорна и воины Орды под началом генерала Кирики: обе стороны добывают силитист, крупицы редкого кристалла, и не собираются уступать друг другу богатства пустыни.",
        ["Погост Отважных"] = "Погост Отважных — первое, что встречает путника, поднявшегося по тропе из кратера Ун'Горо в Силитус. На месте старых эльфийских руин стоит небольшой лагерь друидов Круга Кенария, а рядом — кладбище с могилами тех, кто пал в этой пустыне. Отсюда ночные эльфы наблюдают за силитидами и Сумеречным Молотом; именно они прорубили путь вниз, в кратер, чтобы возить припасы.",
        ["Роящаяся вершина"] = "Роящаяся вершина — высокий скалистый пик посреди Силитуса, к югу от Крепости Кенария. Своё имя он получил от бесчисленного роя мелких силитидов, что кружат над гнездом, устроенным в его склонах. Насекомые пришли сюда из Улья Аши и превратили гору в один из своих ульев. Гул крыльев слышен задолго до того, как вершина покажется из-за барханов.",
        ["Сумеречная застава"] = "Сумеречная застава — стан Сумеречного Молота на северо-западе Силитуса, далеко к западу от Крепости Кенария. Здесь, как и в других лагерях культа, установлен Ветровой Камень, у которого послушники в тёмных одеждах проводят ритуалы призыва. Хранители заставы следят, чтобы никто не обращался к Совету Бездны без разрешения, и наказывают нарушителей без промедления.",
        ["Сумеречный форт"] = "Сумеречный форт стоит в дальнем юго-западном углу Силитуса, к северо-западу от Стены Скарабея. Это самый большой из лагерей Сумеречного Молота: среди палаток и алтарей сектанты вызывают через Ветровые Камни повелителей стихий, чтобы приблизить Последние Дни, о которых говорит их вера. Стражи из камня и пламени, повелители земли и вихрей — все они слуги Совета Бездны, откликающиеся на зов культа. Друиды Крепости Кенария давно следят за этим местом.",
        ["Разоренный Сумеречный лагерь"] = "Разорённый Сумеречный лагерь лежит в Долине Кристаллов, среди северо-западных скал Силитуса. Когда-то здесь стоял северный стан Сумеречного Молота, но лагерь был разгромлен, и в свитках культа о его судьбе говорят как об испытании веры. Среди обугленных шатров теперь скрывается Демитриан, бывший верховный лорд культа, дрожащий перед каждым путником и бормочущий о том, что ему довелось пережить.",
        ["Кости Граккаронда"] = "Кости Граккаронда — исполинский скелет бронзового дракона, лежащий посреди песков центрального Силитуса. Граккаронд откликнулся на зов Анахроноса и сражался с киражами в Войне Зыбучих песков, пока каменный страж врага не пронзил его крыло; рухнув, дракон раздавил под собой множество насекомых, но рой довершил дело. С тех пор его кости стали святыней для каменных слуг киражей — свидетельством того, что даже дракон может пасть. Друиды Круга Кенария с опаской смотрят на это место.",
        ["Крепость Кенария"] = "Крепость Кенария стоит в сердце Силитуса на месте древнего поселения ночных эльфов и остаётся одним из крупнейших оплотов друидов в Калимдоре. Круг Кенария держит здесь гарнизон со времён Войны Зыбучих песков, наблюдая за ульями силитидов и за тем, что заперто за Стеной Скарабея. В крепости есть таверна, торговцы и площадка для грифонов и виверн, сюда стекаются гонцы из Стальгорна и Оргриммара. А командующий крепости с тревогой ждёт вестей о пропавшей жене, которую в последний раз видели среди силитидов.",
        ["Лагерь Оленьего Шлема"] = "Лагерь Оленьего Шлема — ночноэльфийская башня на вершине пика в северо-восточном Силитусе. Она носит имя рода Оленьего Шлема: верховного друида Фэндрала, что вёл ночных эльфов в Войне Зыбучих песков, и его сына Вальстана, павшего в ней. На вершине несёт вахту страж ночных эльфов, а над башней кружит бронзовый дракон из выводка Ноздорму. У подножия горы, чуть ниже по дороге, зияет вход в Сумеречную пещеру, и с башни за ним следят неотступно.",
        ["Лагерь Бронзоборода"] = "Лагерь Бронзоборода — маленькая стоянка дворфов Лиги исследователей в южном Силитусе, к востоку от Стены Скарабея. Здесь учёные изучают глифы, найденные у входов в ульи силитидов, и расспрашивают каждого путника о судьбе знаменитого исследователя Бранна Бронзоборода. Их исследования помогают командующему Крепости Кенария разгадать тайну исчезновения его жены.",
        ["Сумеречная пещера"] = "Сумеречная пещера — грот у подножия Лагеря Оленьего Шлема в северном Силитусе, где укрылась одна из общин Сумеречного Молота. У входа разбит небольшой стан, а в глубине, среди факелов и тёмных алтарей, повелители культа проводят свои обряды. Здесь прячутся самые опасные из сектантов, и ночные эльфы с башни наверху не спускают глаз с этого входа.",
        ["Укрытие Ортелла"] = "Укрытие Ортелла — маленькая пещера в скалах юго-восточного Силитуса. Здесь скрывается Ортелл, бывший член Сумеречного Молота, порвавший с культом. Сектанты не прощают предателей и ищут его, но Ортелл сумел пустить их по ложному следу: разведчики культа уверены, что он прячется в пещерах далёкого Западного Края. Отшельник знает шифры и обычаи своих прежних собратьев, и враг Сумеречного Молота для него — друг.",
        ["Руины Ан'Киража"] = "Руины Ан'Киража лежат за Стеной Скарабея, на самом юге Силитуса. Тысячу лет назад армии ночных эльфов и четырёх драконьих выводков дошли до ворот этой крепости киражей, но полчища силитидов оказались неисчислимы: врагов лишь заперли внутри магическим барьером, и война оставила город в руинах. Драконы заметили, что из большого храма на юге города исходит странная сила, которой подчиняются даже киражи, но проникнуть в него так и не сумели. Внутри стен, среди песка и обломков, до сих пор ждут своего часа тысячи воинов роя.",
    },
    ["Стальгорн"] = {
        _zone = "Стальгорн — столица дворфов, город, вырубленный в самой высокой горе Дун Морога. Первые дворфы, вышедшие из Ульдамана, врубились в гранит и поставили в сердце горы Великую Кузню, вокруг которой кольцами разошёлся весь город. Некогда здесь правил Модимус Старая Наковальня, чья статуя встречает гостей у ворот, а после Войны Трёх Молотов единственным хозяином Стальгорна остался клан Бронзобородов. Ныне на троне сидит король Магни Бронзобород, верный друг Альянса, потерявший брата Мурадина в далёком Нордсколе. Когда пал Гномреган, король дал беженцам кров: в Городе Механиков поселились гномы во главе с главным механиком Меггакрутом, мечтая вернуть себе дом. Отсюда же уходит Подземный поезд — гномье чудо, связавшее Стальгорн со Штормградом. В Зале Исследователей Лига Исследователей хранит находки со всего мира, в Заброшенном гроте шепчутся те, кто предпочитает тень, а в Военном квартале звенит сталь. Жар Великой Кузни не гаснет ни днём, ни ночью, и весь город живёт её дыханием.",
    },
    ["Степи"] = {
        _zone = "Степи — огромная сухая саванна в сердце Калимдора, раскинувшаяся между рекой Строптивой и Когтистыми горами. Когда-то эта земля была цветущим садом, но войны обратили её в пыль, и лишь оазисы, питаемые подземными водами, напоминают о былом. После Третьей войны сюда пришла Орда Тралла: орки вместе с тауренами Кровавого Копыта прошли через Степи, отбиваясь от кентавров. Теперь по Золотому Пути тянутся караваны, а Перекрёсток стал главным узлом Орды в этих краях. Покоя здесь нет: свинобразы, кентавры клана Колкар и гарпии Зачарованного Крыла грабят обозы, Торговая Компания качает нефть на севере, а на Вершине Багрового Тумана собирается культ Пылающего Клинка. В Пещерах Стенаний друиды Клыка предались кошмару, а на юге люди Терамора и дворфы Бейл Модана напоминают, что Альянс тоже пришёл в эти земли.",
        ["Бейл Модан"] = "Бейл Модан — раскоп дворфов Стальгорна в холмах на юге Степей. Здесь, у древних руин титанов, землекопы взрывают склоны и день и ночь грохочут машинами, а над ямами высится крепость Бейл'дан. Прежде в этих холмах жило племя тауренов: их земли захвачены, и Ганн Каменное Копьё в одиночестве бродит по родному краю, так и не добившись справедливости миром.",
        ["Лагерь Таурахо"] = "Лагерь Таурахо — стойбище охотников-тауренов на Золотом Пути к югу от Перекрёстка. Здесь Джорн Заклинатель Небес учит молодых следопытов читать следы великих зверей Степей — Ишамухала, Лакота'мани, Оватанки и Ваште Пауни. Лагерь живёт в вечной осаде свинобразов: дозорные не спускают глаз с холмов, а в клетке у частокола сидит пленный Кривозуб из племени Иглогривых, охотно делящийся силой Агамаггана с теми, кто приносит ему кровавые осколки.",
        ["Дальняя застава"] = "Дальняя застава — небольшой форпост Орды у моста через реку Строптивую, первое, что видит путник, входящий в Степи из Дуротара. Сторожевая башня, орочья землянка и пара катапульт стерегут переправу, а рядом собираются караваны с кодо, идущие на запад к Перекрёстку. Заставой командует Каргал, и именно он отправляет новобранцев Орды дальше по дороге. Здесь же Ак'Зелот ищет следы демонической порчи культа Пылающего Клинка.",
        ["Перекресток"] = "Перекрёсток — крупнейшее поселение Орды в Степях, выросшее там, где Золотой Путь пересекает дорогу из Кабестана в Когтистые горы. Отсюда ветрокрылы летят почти во все форпосты Орды в Калимдоре, а торговцы у кострищ громко расхваливают товар. Заправляет всем шаманка Сергра Чёрный Шип, оборону держит Торк, а друид Тонга Рунический Тотем изучает странную силу, пробуждающую оазисы. У ворот день за днём стоит Манкрик, высматривающий свинобразов: его жена пропала в бою.",
        ["Каменный карьер"] = "Каменный карьер — рудник на северо-восточной окраине Степей, у самой границы с Дуротаром. Орочьи постройки и знамёна говорят, что когда-то он принадлежал Орде, но теперь здесь хозяйничает Торговая Компания под началом начальника Медноклина, ревниво хранящего секреты самофланжа. По слухам, что ходят на пристани Кабестана, один из шахтёров нашёл здесь изумруд величиной с кулак, и охотников до такой добычи хватает.",
        ["Нефтяное болото"] = "Нефтяное болото — чёрная топь в северных Степях, над которой торчат вышки Торговой Компании. Гоблины качают нефть из смоляных ям, гоняют по грязи механические резаки и хранят в вёдрах с инструментами свои заготовки, а в юго-западной части болота они устроили исследовательский центр, где возятся с загадочной штуковиной под названием самофланж. Севернее стоит башня Компании под присмотром надсмотрщика, и у Орды среди этих гоблинов есть свой тайный человек.",
        ["Сухие холмы"] = "Сухие холмы — пыльные высоты на северо-западе Степей, где среди скал гнездятся гарпии стаи Зачарованного Крыла. Отсюда они налетают на караваны Орды со съестными припасами, и кости на склонах напоминают о цене этих набегов. Стаей правит Серена Кровавое Перо — сестра гарпии, которую давным-давно убил Рексар; месть за сестру и гонит её на дороги. На Перекрёстке Дарсок Точный Нож ведёт с гарпиями свою собственную войну.",
        ["Вершина Багрового Тумана"] = "Вершина Багрового Тумана — окутанная мглой гора к северо-западу от Перекрёстка. На её склонах собрались орки-чернокнижники культа Пылающего Клинка: они проводят тёмные обряды и, как подозревают шаманы, отравляют озёра на самой вершине, от которых зависит погода в Степях. Здесь же засел Сарилус Грязнорождённый, маг из нежити, насылающий порчу на духов воды. Даже в полдень над горой висит багровый туман, и мало кто поднимается сюда по своей воле.",
        ["Крепость Северной Стражи"] = "Крепость Северной Стражи стоит на Торговом побережье к югу от Кабестана. Её построили люди Терамора, и гарнизон Альянса встречает выстрелами всё, что движется: подозрительность здесь давно перешла все границы. Пушки крепости захватывают гоблинские корабли, а уцелевших моряков держат в застенках, за что капитан Тало'тас Сияющий из Кабестана затаил на крепость обиду. Для Орды это ближайший оплот Альянса в Степях.",
        ["Забытые пруды"] = "Забытые пруды — самый молодой из оазисов Степей, лежащий к северо-западу от Перекрёстка. Ещё недавно здесь была голая земля, а теперь у воды шумят пальмы и толпятся звери на водопое. Друиды Громового Утёса чувствуют, что из глубин к поверхности рвётся какая-то сила, и Тонга Рунический Тотем ищет её источник на дне прудов. У кромки оазиса разбили лагерь кентавры клана Колкар, так что мирной эта красота лишь кажется.",
        ["Цветущий оазис"] = "Цветущий оазис раскинулся к югу от Перекрёстка, у подножия холмов, скрывающих вход в Пещеры Стенаний. Среди деревьев бродят кентавры клана Колкар: отсюда их вождь Хэрзул Кровавая Отметина правит своими всадниками и отсюда посылает их в набеги. В воде водятся зубастые черепахи с изменёнными панцирями — порча из пещер добралась и до водопоя. И всё же оазис остаётся одним из немногих зелёных мест среди сухих равнин.",
        ["Застывший оазис"] = "Застывший оазис лежит на юго-востоке Степей, между Торговым побережьем и Золотым Путём. У его стоячих вод стоит командный шатёр кентавров клана Колкар, где скрывается Верог Дервиш, а по берегам бродят одинокие заблудившиеся кодо. В оазисе клюёт странная искажённая рыба, и друиды проверяют, нет ли и здесь расселины, дающей воде жизнь. Южнее, в гнёздах, стерегут кладки грозные ящеры.",
        ["Поля Великанов"] = "Поля Великанов занимают южную часть Степей между Лагерем Таурахо и границей Пылевых топей. По равнине бродят стада кодо и громадные грозовые ящеры, а Золотой Путь здесь охраняется куда хуже, чем на севере: сторожевые башни у дороги давно заброшены. Главная тревога последних лет — силитиды: их курганы, самые северные в Калимдоре, выросли посреди полей, и тролль Корран из Перекрёстка следит за насекомыми по приказу Оргриммара.",
        ["Торговое побережье"] = "Торговое побережье — полоса берега Великого моря на востоке Степей, названная так за прибыльную торговлю гоблинов Кабестана. Здесь стоят и сам порт, и крепость Северной Стражи, а у самой воды догнивает остов разбитого корабля. Южнее Кабестана разбили лагерь флибустьеры Южных морей: их канониры и головорезы грабят суда, а капитан «Безрассудной» барон Дольноберег объявлен в розыск. Напротив берега лежит Остров Битв.",
        ["Кабестан"] = "Кабестан — гоблинский порт на Торговом побережье, единственное место в Степях, где орку и человеку нальют за одной стойкой. Город основал Газлоу: Тралл щедро заплатил ему за помощь в строительстве Оргриммара, и на эти деньги гоблин отстроил гавань, а теперь достраивает обсерваторию. Отсюда ходит корабль в Пиратскую бухту, а торговлей заведует управляющий пристанью Головокружилкинс. Лишь пираты Южных морей да пушки Северной Стражи портят гоблинам прибыль.",
        ["Лестница Прилива"] = "Лестница Прилива — причудливые каменные террасы на берегу к югу от Кабестана, похожие на исполинские ступени, уходящие в море. Здесь удят рыбу и беседуют с духами воды двое тауренов, и среди них Марен Небесная Провидица. Глядя на прибой, охотники узнают об Иша Авак — огромной твари, что таится в глубинах у побережья.",
        ["Золотой Путь"] = "Золотой Путь — главная дорога Степей, что тянется с севера на юг через весь край. Он начинается у заставы Мор'шан на границе с Ясеневым лесом, спускается к Перекрёстку, проходит мимо оазисов и Пещер Стенаний, ведёт к Лагерю Таурахо и уходит дальше, к повороту на Мулгор и Великому Подъёмнику. По нему день и ночь идут караваны Орды, и на него же выходят из холмов свинобразы, гарпии и кентавры. Дорога эта не так безопасна, как её имя.",
        ["Остров Битв"] = "Остров Битв — клочок земли у Торгового побережья к югу от Кабестана. Здесь, вдали от чужих глаз, воины всех рас и вер сходятся в поединках, а хозяин острова, старый воин-человек, принимает вызовы всех, кто считает себя достойным. На песке стоят тренировочные чучела, у костров толпятся зрители, а в мутной воде у берега кишат хищные рыбёшки.",
        ["Река Строптивая"] = "Река Строптивая — самая большая река Калимдора. Она берёт начало в озере на горе Хиджал, срывается вниз каскадом водопадов, разделяет Ясеневый лес и Азшару, а затем становится границей между Степями и Дуротаром и впадает в Великое море. Через её быстрые воды переброшен мост у Дальней заставы — по нему проходят все караваны из Оргриммара. Шаманы Орды почитают реку: по преданию, вдоль её берегов лежит тайная тропа к святилищу огня.",
        ["Южные степи"] = "Южные степи — самая дальняя и глухая часть края, где сухая трава сменяется колючими зарослями. Здесь лежат владения свинобразов: Хребет Чёрных Шипов и Лабиринты Иглошкурых, где сходятся тропы племён Иглогривых и Дыбогривов. С юга к равнине подступают дворфы Бейл Модана, а дорога сворачивает к Великому Подъёмнику и Тысяче Игл. Форпостов Орды здесь нет, и путник может рассчитывать лишь на себя.",
        ["Южный Золотой Путь"] = "Южный Золотой Путь — продолжение великого тракта за Лагерем Таурахо. Дорога идёт через Поля Великанов мимо стад кодо и грозовых ящеров, минует поворот на Мулгор и спускается на юг, к Великому Подъёмнику. Охраняют её куда хуже северного отрезка: сторожевые башни у обочины стоят заброшенными, а свинобразы всё чаще выходят на дорогу. И всё же именно по ней таурены и орки идут в Тысячу Игл и Пылевые топи.",
        ["Курганы Иглошкурых"] = "Курганы Иглошкурых — древняя столица свинобразов, лабиринт из терновых лоз, выросших, по преданию, из крови полубога-вепря Агамаггана. Здесь жили верховные жрецы племени, но после Третьей войны в терновые залы пришла Плеть: лич подчинил себе свинобразов, и их святыня превратилась в оплот нежити. Чума расползлась по лабиринту, а племя ведёт отчаянную борьбу за свой город, пока холод Плети не пополз по всем Степям.",
        ["Лагерь Мор'шан"] = "Лагерь Мор'шан — одно из крупнейших поселений Орды в северных Степях, стоящее у самой границы с Ясеневым лесом, рядом с заставой. Здесь собираются всадники Песни Войны, готовящиеся к битвам в ущелье, а к югу от заставы обосновалась гоблинка-механик Венаки Бенике, обожающая возиться с диковинными устройствами. Отсюда же уходят на север отряды, которые Кадрак направляет на защиту новых рубежей Орды в лесу.",
        ["Земли Ящеров"] = "Земли Ящеров — небольшая долина к югу от Кабестана, к западу от крепости Северной Стражи. Её облюбовали яркочешуйчатые ящеры, необычайно смышлёные для своего рода: они строят из веток кривые хижины, мастерят подобие орудий и тащат в гнёзда всё блестящее. Из-за этой страсти к сокровищам ящеры воруют у поселений Орды, и караванщики не раз недосчитывались серебра, ушедшего в эти гнёзда.",
        ["Ежевичный овраг"] = "Ежевичный овраг — стойбище свинобразов племени Дыбогривов к югу от Перекрёстка, по восточную сторону Золотого Пути. Среди колючих зарослей их геоманты, водоискатели и терноплёты ткут свою земляную магию, а через дорогу, в Агама'горе, стоит второе стойбище того же племени. Дыбогривы нападают на всякого, кто подходит к их логову, и на их совести немало разграбленных обозов. Именно этих свинобразов день за днём высматривает у ворот Перекрёстка Манкрик.",
        ["Тернистый холм"] = "Тернистый холм — большое стойбище свинобразов племени Иглогривых на северном склоне горы между Перекрёстком и Дуротаром. Его обитатели повадились грабить караваны Орды на дороге в Дуротар, и набеги ведёт Криниг Грознорыл, чьё имя не даёт покоя Торку из Перекрёстка. На холме живут и старые мистики племени, хранящие его тайны. Пока Криниг жив, обозам на этой дороге не будет покоя.",
        ["Агама'гор"] = "Агама'гор — большое поселение свинобразов племени Дыбогривов к северу от дороги, уходящей на запад от Лагеря Таурахо. Здесь среди шипов и хижин племя выкапывает кроваво-красные камни: свинобразы носят их как тотемы, черпая в них силу для боя и заклинаний. Эти же осколки ищет Кривозуб, пленник Таурахо, обещающий за них благословение Агамаггана. Дыбогривы ведут войну с соседями Иглогривыми, и колючие заросли здесь пропитаны кровью.",
        ["Хребет Черных Шипов"] = "Хребет Чёрных Шипов — колючая долина на юге Степей, к северу от Лабиринтов Иглошкурых. Здесь хозяйничают следопыты и мистики племени Иглогривых, а среди них скрываются трое главарей — Нак, Куз и Лок Оркобой, вышедшие из Лабиринтов, чтобы вести набеги на Орду. На самом гребне живёт орочья шаманка-отшельница, а под её стоянкой лежит озерцо с удивительно чистой водой. Неподалёку бродит Ганн Каменное Копьё, изгнанный с родных холмов дворфами.",
        ["Застава Чести"] = "Застава Чести — западная окраина Степей, где дорога от Перекрёстка поднимается к перевалу в Когтистые горы. Здесь равнина кончается: сухая трава сменяется каменистыми склонами, и лишь редкие караваны пылят по дороге. Мимо проходят все, кто держит путь из сердца Орды на запад — к Пику Каменного Когтя и дальше.",
        ["Застава Мор'шан"] = "Застава Мор'шан — укреплённый вал с башнями на самом севере Степей, где Золотой Путь уходит в Ясеневый лес. Стену возвели орки клана Песни Войны, и отсюда Кадрак руководит кампанией Орды в лесу, набирая новобранцев для защиты новых рубежей. Ниже по дороге раскинулся лагерь всадников Песни Войны, а совсем рядом лежит вход в ущелье, где Орда и Альянс сходятся в бесконечной битве.",
        ["Ферма Гроль'дома"] = "Ферма Гроль'дома — орочье хозяйство на Золотом Пути к северу от Перекрёстка. За частоколом здесь держат кодо, а вокруг пасётся скот — небогатая, но упорная попытка орков прокормиться на сухой земле. Слишком близко от фермы лежит Тернистый холм, и свинобразы Иглогривых не раз спускались сюда за добычей. Неподалёку у дороги стоит Кранал Фисс, направляющий бойцов на север, к заставе Мор'шан.",
        ["Лабиринты Иглошкурых"] = "Лабиринты Иглошкурых — исполинский терновый холм на юге Степей, пронизанный ходами, где живёт племя Иглогривых. По преданию, шипы эти выросли из крови полубога Агамаггана, и свинобразы считают их священными. В глубине лабиринта правит старая шаманка племени, а по коридорам бродят вепри, летучие мыши и загнанные в клетки пленники — среди них незадачливый гоблин Вилликс, явившийся сюда за корнем синелиста. Кривозуб из Таурахо когда-то был здесь своим.",
        ["Великий Подъемник"] = "Великий Подъёмник — деревянный лифт, построенный тауренами на южном краю Степей, там, где равнина обрывается в каньоны Тысячи Игл. Скрипучая платформа на канатах — единственный удобный спуск с плато вниз, и по нему идут все, кто держит путь на юг. В последнее время свинобразы расширили свои владения и почти перекрыли дорогу к подъёмнику, так что путь до него стал опасным.",
        ["Пещера Багрового Тумана"] = "Пещера Багрового Тумана — тёмный грот в склоне горы, где культисты Пылающего Клинка укрываются от чужих глаз. Здесь, вдали от света, орки-чернокнижники ведут свои обряды и хранят предметы, пропитанные демонической силой. Из глубины тянет сыростью и гарью, а у входа дежурят послушники культа.",
        ["Крепость Бейл'дан"] = "Крепость Бейл'дан — каменная твердыня дворфов, нависающая над раскопом Бейл Модана. Гарнизон Стальгорна стережёт древние руины титанов и всё, что в них найдено, и встречает Орду огнём. За её стенами дворфы чувствуют себя как дома, и лишь одинокий таурен Ганн Каменное Копьё напоминает, что земля эта прежде принадлежала его племени.",
        ["Великое море"] = "Великое море — бескрайние воды, омывающие восточный берег Степей и отделяющие Калимдор от Восточных королевств. По нему из Кабестана уходят гоблинские корабли в Пиратскую бухту, а с востока приходят суда Терамора и пиратов Южных морей. В глубинах у побережья, как говорят таурены с Лестницы Прилива, таится исполинская Иша Авак.",
        ["Святилище Павшего Воина"] = "Святилище Павшего Воина стоит на вершине холма к западу от Перекрёстка, куда ведёт узкая тропа по гребню. На каменном постаменте застыла фигура орка-воина, а у подножия обелиска высечены руны. Перед святилищем несёт вечную вахту целительница духов.",
    },
    ["Сумеречный лес"] = {
        _zone = "Сумеречный лес лежит к югу от Элвиннского леса, между Западным Краем и перевалом Мёртвого Ветра, а на юге за мостом начинается Тернистая долина. Когда-то это была южная окраина Элвинна, но после того как с перевала пришла тьма, над лесом навсегда сгустился полумрак, деревья скрючились, а на кладбищах поднялась нежить. По чащам рыщут воргены, с юга подступили огры, на брошенных фермах хозяйничает Братство Справедливости. Штормград бросил эти земли на произвол судьбы, и жители Темнолесья создали своё ополчение – Ночной дозор. В сердце леса, в кратере потухшего вулкана, стоит древнее дерево с порталом в Изумрудный Сон, и вокруг него царят не мрак, а тихие сумерки. На северо-западе Свен ищет способ одолеть некроманта Морбента Скверна, поднявшего мертвецов на кладбище Вороньего холма. Люди здесь пугливы и подозрительны, но любой помощи рады: слишком много тьмы обступило их дома.",
        ["Темнолесье"] = "Темнолесье – единственный уцелевший город Сумеречного леса, некогда тихая лесная деревня, а ныне осаждённый тьмой посёлок за частоколом. Городом правит мэр лорд Элло Чернодрев с советом, а командир Алтея Чернодрев возглавляет Ночной дозор – ополчение из местных жителей, созданное после того, как Штормград отозвал своих солдат. В ратуше клерк Далтри ведёт записи обо всех, кто живёт здесь или проезжает мимо, а на площади раскладывает карты мадам Ева. В таверне «Алый ворон» шеф-повар Груаль печёт тёмные пирожки с «крабами», а хозяин Смиттс наливает путникам самогон.",
        ["Лощина Вул'Гол"] = "Лощина Вул'Гол – низина на юге Сумеречного леса, чуть западнее того места, где главная дорога поворачивает на юг, к Тернистой долине. Когда-то здесь жили люди, о чём напоминают развалины ферм, но теперь низину целиком заняли огры клана Дробящего Кулака во главе с Ззарк'Вулом, по имени которого и назван курган. В пещере огров валяются туши чёрных медведей – их припасы. Именно у этого кургана огры напали на старика-травника Аберкромби и отняли у него ящик с инструментами.",
        ["Вороний Холм"] = "Вороний Холм – опустевший городок на западе Сумеречного леса, между участком Эддла на юге и огромным кладбищем на севере. Некогда это было второе большое село здешних мест, но тьма и нежить выгнали жителей, и теперь дома стоят пустыми, а тишину нарушают лишь мертвецы, забредающие сюда с кладбища. Впрочем, Калор из Темнолесья клянётся, что две ночи подряд видел здесь крадущиеся тени, а на третью – свет в одном из окон. В брошенном доме и правда прячется нервный человек по прозвищу Трясунчик, сбежавший из города на запад.",
        ["Безмятежное кладбище"] = "Безмятежное кладбище лежит чуть юго-восточнее Темнолесья, сразу за городской оградой. Название давно стало насмешкой: среди могил поднялись скелеты-воины и маги-скелеты, хотя они и слабее той нежити, что бродит у Вороньего холма, поэтому именно сюда Ночной дозор посылает новых помощников. В разрушенной часовне или возле неё бродит Невменяемый Вурдалак. Неподалёку стоит старая ферма, где обитает несчастное привидение по имени Слепая Мэри, оплакивающее свою утраченную красоту.",
        ["Гниющий сад"] = "Гниющий сад раскинулся на юге Сумеречного леса, между усадьбой Йоргена на западе и Безмятежным кладбищем на востоке, к юго-западу от Темнолесья. Когда-то здесь были плодовые сады, но деревья медленно умирают под вечными сумерками, а в обветшалых постройках устроили логово воргены из стаи Ночной Погибели. Одни колдуют у костров, другие сторожат в тени, так что заходить сюда лучше с оружием наготове.",
        ["Светлая роща"] = "Светлая роща лежит к западу от Темнолесья, по обе стороны дороги. Название осталось от прежних времён: сейчас немногие дома на краю рощи лежат в развалинах, а по тёмным полям рыщут воргены из стаи Ночной Погибели, разбивая грубые стоянки и набрасываясь на всякого, кто подойдёт слишком близко. Ночной дозор посылает сюда новичков прореживать стаю, чтобы воргены не подступали к городским стенам. Среди руин порой попадаются забытые сундуки, за которыми стоит поглядывать.",
        ["Покинутая усадьба"] = "Покинутая усадьба – холм на северном краю кладбища Вороньего холма, окутанный особенно густой тьмой. На его вершине стоит дом некроманта Морбента Скверна, союзника тёмных всадников, который поднял мертвецов Сумеречного леса и правит ими из своего жилища. Его охраняют не только приспешники из нежити, но и защитная магия, против которой бессильно обычное оружие. Свен из лагеря на северо-западе леса ищет способ пробить эту защиту, а Штормград сюда солдат не пришлёт.",
        ["Усадьба Йоргена"] = "Усадьба Йоргена – заброшенная ферма на юге Сумеречного леса, к западу от Гниющего сада. Здесь жил Свен, пока тёмные всадники, спустившиеся с перевала Мёртвого Ветра, не перебили всю его семью, когда он был в отлучке. Вернувшись, Свен заметил у амбара незнакомца, который что-то закапывал возле старого пня, и с тех пор ищет ответы из своего лагеря на северо-западе леса. Теперь ферму заняли разбойники Братства Справедливости, и многие из них прячутся в тени, так что подходить сюда стоит с осторожностью.",
        ["Кладбище Вороньего Холма"] = "Кладбище Вороньего Холма – огромный погост на северо-западе Сумеречного леса, севернее опустевшего городка. С тех пор как на лес пала тьма, кладбище разрослось и поглотило округу, а покой мёртвых нарушили некромант и его слуги. Между могил бродят вурдалаки, плотояды, костеглоды и распространители чумы, в паутине сидят огромные пауки, а воры разоряют могилы: тела отсюда продавали самому Морбенту Скверну. По дорожкам ходит грозный неупокоенный рыцарь, от которого лучше держаться подальше. На холме в северо-западном углу стоит дом некроманта, два мавзолея ведут в катакомбы, а к северу от ограды – хижина отшельника Аберкромби.",
        ["Участок Эддла"] = "Участок Эддла – брошенная ферма на юго-западе Сумеречного леса, южнее Вороньего Холма и западнее лощины Вул'Гол. Хозяева ушли отсюда, когда в лес пришла тьма, а ферму целиком захватило Братство Справедливости: разбойники крадутся по полю, ночные клинки прячутся в амбаре, а зачаровыватели колдуют в маленьком доме. Агенты Штормграда полагают, что здесь хранятся бумаги, важные для короны, поэтому сюда порой посылают тех, кто не боится разбойников.",
        ["Приют Бродяги"] = "Приют Бродяги – заброшенная сторожевая башня стражи Штормграда на северо-востоке Сумеречного леса, у дороги, ведущей на перевал Мёртвого Ветра. Солдаты давно покинули её, и теперь в башне обосновались двое агентов Отрёкшихся, которые ведут здесь свои тайные дела и не жалуют чужаков. Извилистая тропа спускается от башни к небольшому пруду с водопадом, где стоит безымянная могила, а неподалёку от башни есть маленькое кладбище.",
        ["Темный берег"] = "Тёмный берег тянется вдоль всего северного края Сумеречного леса, по южному берегу реки, за которой лежит Элвиннский лес, от западной границы до моста в Красногорье. На западном конце берега, у самой реки, стоит лагерь Свена и его спутника Ларса – единственных, кто живёт вне городских стен, и именно отсюда чаще всего начинают знакомство с этим лесом. Между холмами и рекой плетут паутину ядовитые кругопряды, а вдоль воды рыщут голодные лютые волки, которые увязываются за каждым, кто несёт добычу в лагерь.",
        ["Мглистая роща"] = "Мглистая роща лежит в самом сердце Сумеречного леса, в кратере давно потухшего вулкана. Здесь, в отличие от остального леса, царит не мрак, а тихие сумерки: посреди рощи возвышается огромное древнее дерево с порталом в Изумрудный Сон, а рядом с ним – лунный колодец и беседка ночных эльфов. Говорят, именно сила этого дерева не даёт лесу умереть окончательно. Но с недавних пор из портала выходят зелёные драконы, поражённые кошмаром, и встречи с ними не пережить в одиночку.",
        ["Затихший берег"] = "Затихший берег – полоса Сумеречного леса вдоль западной реки, от места, где сходятся границы Западного Края, Элвиннского леса и Сумеречного леса, на юг до самой Тернистой долины. Здесь стоит крытый мост, по которому дорога уходит в Западный Край. Среди деревьев по берегу плетут сети ядовитые кругопряды и рыщут лютые волки, и дозорный Додс на западной границе рад любому, кто согласится проредить восьминогих тварей.",
        ["Поместье Мистмантла"] = "Поместье Мистмантла стоит на северо-востоке Сумеречного леса, к северу от Темнолесья и западнее Приюта Бродяги. Некогда здесь жил учитель и домашний наставник по имени Сталван, но усадьба давно заброшена: земля вокруг прогнила, а по саду бродят вурдалаки. Единственный признак жизни – один-единственный цветок в саду. В Темнолесье о хозяине поместья говорят неохотно, а мадам Ева, разложив карты, увидела в них его имя и Смерть – и с тех пор боится за всех.",
        ["Катакомбы Утреннего Леса"] = "Катакомбы Утреннего Леса тянутся под кладбищем Вороньего холма, и в них обитает самая опасная нежить Сумеречного леса. Внутрь ведут два мавзолея: восточный открывается в логово вурдалаков и распространителей чумы, самых заразных и свирепых, а западный – в залы, где скелеты-налетчики, скелеты-лекари и скелеты-хранители стерегут гробницы своих собратьев. Ночной дозор и Свен посылают сюда лишь тех, кто уже доказал свою силу, и спускаться в темноту лучше не в одиночку.",
        ["Погибель Роланда"] = "Погибель Роланда – старая шахта на юго-востоке Сумеречного леса, к востоку от Гниющего сада. Здесь теряется след жрицы ночных эльфов, принесшей в эти края Косу Элуны, и здесь же отряд людей, спустившийся в шахту в поисках источника тьмы, был растерзан воргенами: единственным уцелевшим стал человек по прозвищу Трясунчик, поднявший Косу из камней. Теперь в шахте живёт стая Ночной Погибели, в чьих жилах течёт горящая кровь, а их главарь Кишкодер хранит горящий камень.",
        ["Лагерь Джерода"] = "Лагерь Джерода – лодочная пристань на речном берегу к югу от Златоземья. С виду это простые доки, но по донесениям агентов Штормграда пристань захватило Братство Справедливости и превратило в перевалочный пункт: отсюда переправляют крупные партии контрабанды из Красногорья в Западный Край. Всем здесь заправляет портовый начальник, а расписание поставок он держит при себе.",
        ["Лесная опушка"] = "Лесная опушка – клин леса к юго-западу от Штормграда, зажатый между садом у Зеркального озера и реками, за которыми начинается Западный Край. Здесь, к югу от гарнизона, обосновались гноллы стаи Речной Лапы под началом Дробителя, могучего гнолла, которого стража так и не смогла изловить. Среди деревьев бродят кабаны, а по берегам рек попадаются медные жилы и лечебные травы. На северном краю опушки стоит гарнизон у Западного ручья.",
        ["Ферма Стоунфилдов"] = "Ферма Стоунфилдов стоит на юге Элвинна, у самого рудника Подземных Глубин. Стоунфилды давно враждуют с соседями Маклурами, и семьи не упускают случая уколоть друг друга. Тем не менее, Томми Джо Стоунфилд и Мэйбелл Маклур полюбили друг друга, и есть надежда, что эта любовь помирит два дома. Тётушка Бернис славится пирогами со свининой, а кабанов вокруг ферм водится видимо-невидимо.",
        ["Виноградники Маклура"] = "Виноградники Маклура тянутся по южному Элвинну, неподалёку от фермы Стоунфилдов, с которыми Маклуры ведут давнюю вражду. Между лоз то и дело шастает мальчишка Билли Маклур, а среди виноградников пасутся целые стада кабанов. Юная Мэйбелл Маклур мечтает сбежать отсюда к своему возлюбленному из семьи соседей.",
        ["Башня Азоры"] = "Башня Азоры – небольшая башня магов к востоку от Златоземья, на дороге к лесопилке. Ею правит верховный маг Теокрит, а прислуживают ему гномы. Маги Азоры давно враждуют с чернокнижником Моргантом из башни Илгалара в Красногорье, и обе башни без устали следят друг за другом с помощью магии. По словам слуг, всё живое, что забредает слишком близко к башне, странно меняется под действием её чар.",
        ["Рудник Подземных Глубин"] = "Рудник Подземных Глубин – заброшенная золотая шахта к югу от Златоземья, между фермами Стоунфилдов и Маклуров. Некогда её отбили у орков после Первой войны, а теперь штольни заняло целое племя кобольдов. Они носят с собой золотую пыль и большие свечи, за которые в Златоземье дают неплохую цену. По слухам, где-то в глубине прячется здоровенный кобольд с золотыми зубами.",
        ["Тыквенное поле Бреквеллов"] = "Тыквенное поле Бреквеллов лежит на юго-востоке Элвиннского леса. Когда-то это была спокойная ферма, но семья Бреквеллов пропала, а в доме и на грядках поселились бандиты Братства Справедливости. По донесениям стражи, здесь скрывается их главарь по прозвищу Вымогатель, который ждёт партию золота из рудников Элвинна. Между тыквенных гряд по-прежнему бродит призовая свинья Бреквеллов по кличке Принцесса, разжиревшая на овощах с соседней фермы Стоунфилдов.",
    },
    ["Танарис"] = {
        _zone = "Танарис — бескрайняя пустыня на юго-востоке Калимдора, к югу от Тысячи Игл и к востоку от кратера Ун'Горо. Под безоблачным небом здесь тянутся раскалённые дюны, а песчаные бури налетают внезапно и стирают любые следы. Когда-то эти земли были джунглями империи Гурубаши, но Великий Раскол превратил их в пески, и уцелевшие тролли племени Песчаной Бури заперлись в городе Зул'Фаррак. На севере гоблины картеля Хитрая Шестерёнка выстроили Прибамбасск и Порт Картеля, где рады любому, кто платит. Редкие колодцы в песках оспаривают друг у друга Скитальцы Пустыни, пираты Южных морей и огры клана Песчаного Молота, а под барханами роют свои ульи силитиды. В горах на востоке лежат Пещеры Времени, где с незапамятных времён обитают бронзовые драконы Ноздорму, а на дальнем юге, в Долине Стражей, стоят запертые врата древнего города титанов — Ульдума.",
        ["Прибамбасск"] = "Прибамбасск — столица картеля Хитрая Шестерёнка, гоблинский город за высокими стенами посреди северного Танариса. Здесь торгуют лучшие инженеры, рудокопы и алхимики Калимдора, а на нейтральном аукционе сходятся купцы Орды и Альянса: гоблины ценят прибыль выше верности, и любой с тугим кошельком здесь желанный гость. За порядком следят прибамбасские костоломы, готовые утихомирить каждого, кто мешает торговле. Отсюда Водная компания Прибамбасска управляет колодцами в пустыне, а гоблин Синь Гогельмогель мечтает разбогатеть на эликсире собственного изобретения. Дороги от ворот ведут к Порту Картеля на востоке, к Зул'Фарраку на западе и через горы в Тысячу Игл.",
        ["Порт Картеля"] = "Порт Картеля — маленькая гоблинская гавань на восточном берегу Танариса, соединённая дорогой с Прибамбасском. У причала ждут корабли, ходящие к далёким островам Южных морей, но делиться судами с другими народами картель не спешит. В посёлке живут гоблины и мирные тролли: одни рыбачат, другие стерегут склады от пиратов Южных морей, чьё логово лежит южнее по берегу. Здесь же обитает тролль Йе'кинья, собирающий духов ради старых тайн своего народа, а начальник отдела безопасности Чепухастер обещает награду за пиратские шляпы и за голову Андре Огнебородого.",
        ["Зул'Фаррак"] = "Зул'Фаррак — выжженный солнцем город троллей племени Песчаной Бури на северо-западе Танариса. Когда-то он стоял среди джунглей империи Гурубаши, но после Раскола тролли оказались отрезаны в пустыне и приспособились к ней, став песчаными троллями, известными жестокостью и тёмной магией. Вождь Укорз Песчаный Череп мечтает вернуть племени былое величие, а знахари поднимают мертвецов из городских могил. Легенды говорят о клинке, разрубленном надвое и спрятанном в этих стенах, и о наёмниках из Прибамбасска, попавших здесь в плен. Страшнее всего шёпот о древнем существе в священном пруду в сердце города: тролли поклоняются гидре Газ'рилле как божеству и будят её лишь тогда, когда есть чем накормить.",
        ["Застава Скорбных Песков"] = "Застава Скорбных Песков — обширные земли к западу от Прибамбасска, где среди сожжённых хижин и покосившихся башен хозяйничают тролли Песчаной Бури. Призыватели огня, метатели топоров и шкуродёры стерегут скудные источники воды и не терпят чужаков. Отсюда до стен Зул'Фаррака рукой подать, и всякий, кто идёт к городу троллей с востока, сначала проходит через эту заставу.",
        ["Долина Кактусов"] = "Долина Кактусов лежит на юго-западной окраине Танариса, у самого подъёма в кратер Ун'Горо. Это одно из самых низких мест пустыни, и здесь, единственные на весь Танарис, растут исполинские живые кактусы — верный знак воды глубоко под песком. Долину стерегут терновые собиратели росы и бугристые шипокожи, существа из живых лоз, нападающие на всякого, кто подойдёт близко. Синь Гогельмогель из Прибамбасска уверен, что в железах этих созданий хранится влага, из которой можно сварить чудесный эликсир, утоляющий жажду.",
        ["Зияющая бездна"] = "Зияющая бездна — один из малых силитидских ульев на юго-востоке Танариса. Песок здесь изрыт ходами, из которых торчат хитиновые своды, и всё вокруг кишит членистоногами улья Хаззали: рабочими, жалоносцами и целыми роями. Водная компания Прибамбасска посылала сюда младшего геодезиста, но он так и не вернулся. Старший геодезист Рудознатец подозревает, что эти твари выпивают воду пустыни и что ими управляет какая-то чуждая сила, грозящая не только Прибамбасску, но и всему Калимдору.",
        ["Ядовитый улей"] = "Ядовитый улей, который зовут ещё ульем Сентипаара, прячется на юго-западе Танариса, над обрывом в кратер Ун'Горо. Земля здесь просела, словно когда-то тут было русло реки или мелкое озеро, но силитиды выпили воду и высушили запад пустыни. Из песка торчат подрагивающие клешни зарывшихся тварей, а под землёй тянутся тёплые сырые туннели, чьи стены облеплены кислотой и незрелыми личинками. Здесь роятся членистоноги-сентипаары, а огры Песчаного Молота, говорят, не брезгуют их мясом.",
        ["Поселение Песчаного Молота"] = "Поселение Песчаного Молота — стойбище огров на юге Танариса: хижины вокруг одного из немногих водоёмов пустыни. Клан Песчаного Молота, бронзовокожие кочевники, пришёл в Танарис недавно и держится особняком: переход через пески требует больше воды, чем огры могут выделить, а гостей они не любят. В пещере правит Гор'марок Опустошитель, вожак клана, а вокруг него — громилы, головорезы, чернокнижники и огры-маги. Южнее, в Руинах Южной Луны, тоже хозяйничают огры этого клана, а порой их одиночки забредают и в дальние барханы.",
        ["Руины Восточной Луны"] = "Руины Восточной Луны — обломки древнего тролльского поселения к западу от Зияющей бездны. Тролли оставили эти камни задолго до прихода гоблинов, и теперь среди колонн хозяйничают огры клана Песчаного Молота, забредшие сюда с юга. Никаких дел у Прибамбасска в этих руинах нет — лишь ветер, песок и тени огров между обвалившихся стен.",
        ["Родниковое поле"] = "Родниковое поле названо так за водонапорные башни, которые качают живительную влагу из глубоких подземных запасов. Их построили гоблины Прибамбасска, чтобы напоить свои предприятия в пустыне, но затея сорвалась: в поле явились бродячие разбойники, называющие себя Скитальцами Пустыни, и присвоили башни себе. Бандиты, воры и тёмные маги шайки сидят на чужой земле, а их вожак Калиф Жало Скорпида бродит здесь с двумя телохранителями. Водная компания Прибамбасска платит за каждый отбитый у кочевников бурдюк с водой и за голову самого Калифа.",
        ["Логово Залашьи"] = "Логово Залашьи — небольшая пещера на восточном берегу Танариса, дом одинокого наги по имени Залашья. Он бродит между своей норой и полосой прибоя и подолгу смотрит на воду, словно ждёт кого-то с моря. Зачем нага поселился в пустыне и что связывает его с Южными морями, никто из гоблинов не знает.",
        ["Пляж на Краю Света"] = "Пляж на Краю Света — самая южная точка Танариса и всего Калимдора, дальний юго-восточный угол материка. Здесь кончается земля: за полосой песка лишь Южные моря, по берегу бродят береговые черепахи, а в прибое ворочаются земляные яростни — морские великаны, которым нет дела до чужаков, пока те держатся поодаль. Отсюда до силитидских ульев Зияющей бездны рукой подать, а на западе, за горами, скрываются врата Ульдума. Место тихое и пустынное, куда редко заходит кто-то, кроме охотников за черепашьими панцирями.",
        ["Берег Морского Бродяги"] = "Берег Морского Бродяги тянется вдоль восточного побережья Танариса от Порта Картеля до Бухты Сорванных Парусов. По песку неспешно бродят береговые черепахи и стальноклювые крепкохваты, а в дюнах над берегом шныряют берегоброды. В море напротив берега видны два горящих корабля, сцепившихся в бою, которому не видно конца.",
        ["Ульдум"] = "Ульдумом зовётся дальний юго-западный угол Танариса, где среди скал стоят неприступные ворота древнего города титанов. Многие считают Ульдум мифом, но иероглифы на дисках, найденных в Ульдамане, в переводе упоминают именно это место. Врата запечатаны с незапамятных времён, и никто из смертных не входил в них; лишь Каменный Страж, оставленный титаном Норганноном, хранителем знаний, отзывается тому, кто принесёт к постаменту нужные диски. Он говорит, что для входа не хватает Ульдумских пластин, а за воротами спят тайны земных глубин, грозящие великими опасностями.",
        ["Долина Стражей"] = "Долина Стражей лежит на юге Танариса, у самых ворот Ульдума. Между отвесных скал бродят дюнные крушители — исполинские горные великаны, будто поставленные стеречь подступы к городу титанов. Здесь, у запертых ворот, в одиночку несёт вахту геолог Ганстен из Лиги исследователей, ожидая дня, когда врата откроются.",
        ["Застава Ганстена"] = "Застава Ганстена — крошечный лагерь дворфа у самых ворот Ульдума, к югу от Руин Южной Луны. Геолог Ганстен из Лиги исследователей поставил здесь палатку и в одиночестве ведёт дозор за запертыми вратами города титанов, записывая всё, что удаётся разглядеть на древних камнях.",
        ["Руины Южной Луны"] = "Руины Южной Луны — древние тролльские развалины на юге Танариса, чуть севернее Долины Стражей. Между обрушенных колонн и статуй расположились огры клана Песчаного Молота, ушедшие сюда из своего поселения. Кто и когда возвёл эти стены, помнят разве что тролли Зул'Фаррака, а гоблины Прибамбасска предпочитают обходить руины стороной.",
        ["Бухта Сорванных Парусов"] = "Бухта Сорванных Парусов, укрытая горами с трёх сторон, — тайная гавань пиратов Южных морей на восточном берегу Танариса. Здесь стоят их корабли и верфь, где строится новое судно, а на причалах толпятся флибустьеры, сорвиголовы и портовые рабочие. Пираты давно досаждают гоблинам Порта Картеля, и начальник отдела безопасности Чепухастер обещает награду каждому, кто вернётся с их шляпами. Здесь же прячется и Андре Огнебородый, разыскиваемый картелем.",
        ["Руины Полуденной Тени"] = "Руины Полуденной Тени — древние тролльские развалины к востоку от Прибамбасска, на северо-востоке Танариса. Здесь укрылась часть шайки Скитальцев Пустыни: потомки пиратов, брошенных когда-то на этом берегу, теперь грабят гоблинские обозы и захватывают колодцы. Водная компания Прибамбасска ищет тех, кто сократит число кочевников и вернёт ей воду.",
        ["Разбитая Колонна"] = "Разбитая Колонна — несколько тролльских руин к югу от Прибамбасска, восточнее Безбрежных Песков. Здесь разбил лагерь Марвон Клепальщик, гоблин-учёный и искатель сокровищ из Кабестана, оставивший свою мастерскую ради тайн пустыни. Его интересуют газ'рилловые украшения — древние тролльские безделушки, разбросанные по всему Танарису. Марвон повидал немало древних мест и, говорят, однажды едва выбрался из затонувшего храма в Болоте Печали.",
        ["Безбрежные Пески"] = "Безбрежные Пески — бескрайнее море дюн в сердце Танариса, между Прибамбасском и южными горами. Здесь нет ни воды, ни тени: лишь хромоногие гиены, скорпиды и стеклошкурые василиски, а над раскалёнными барханами кружат огненные рухи. Говорят, под самой поверхностью песка тянутся ходы силитидов, поджидающих неосторожного путника.",
        ["Берег за Южной грядой"] = "Берег за Южной грядой — широкая тихая полоса песка к югу от Бухты Сорванных Парусов. В прибое бродят береговые черепахи и морские великаны — земляные яростни, а у самой воды попадаются черепахи размером с лодку. Неподалёку от берега лежит крошечный островок, где живёт гномка Однокнопка, ничем не объясняющая своего уединения.",
        ["Пещеры Времени"] = "Пещеры Времени — древнее логово Ноздорму, Аспекта времени, и его бронзовых драконов в горах восточного Танариса. С тех пор как мир был молод, бронзовые драконы стерегут этот извилистый лабиринт, следя, чтобы ход времени оставался неизменным, и по воле титанов не пускают внутрь смертных. Вход охраняют драконы Хроналис, Оккулус и Тик, а у самых ворот сидит Анахронос, наследник Ноздорму. Именно он первым понял, какую угрозу несут силитиды, гнездящиеся в дальних углах пустыни, и не забыл войну Зыбучих песков. Что скрыто в глубине пещер, знают лишь драконы, и тому, кто ступает под их своды, лучше держаться от них подальше.",
        ["Южные моря"] = "Южные моря омывают восточный и южный берег Танариса; это часть Великого моря, лежащая между Калимдором и Восточными королевствами, к югу от Водоворота. Где-то за горизонтом лежат тропические острова, откуда родом гоблины и куда уходят корабли из Порта Картеля. В этих водах хозяйничают пираты Южных морей, в глубине кружат большие акулы, а на мелководье у берега пасутся береговые черепахи.",
        ["Гремящая Клеть"] = "Гремящая Клеть — гоблинская забава Прибамбасска: железная клеть, где под рёв толпы сходятся бойцы, а зрители делают ставки на исход. Как и всё в городе картеля, здесь ничто не достаётся даром.",
    },
    ["Тельдрассил"] = {
        _zone = "Тельдрассил поднимается из вод Сокрытого Моря у северо-западного побережья Калимдора: это и остров, и исполинское древо, в кроне которого раскинулась новая родина ночных эльфов. После Третьей войны, когда Малфурион ушёл в Изумрудный Сон, верховный друид Фэндрал Олений Шлем убедил старейшин вырастить новое Древо Жизни взамен ослабевшего Нордрассила. Имя ему дали «венец земли», а в ветвях возвели столицу Дарнасс, где правит Тиранда Шелест Ветра. Но великие драконы не благословили это древо, и рост его оказался с изъяном. Над лесом стоит вечный сумрак, а в лунных колодцах хранится сила Элуны. И всё же сюда просачивается порча: древесники впадают в ярость, фурболги Кривой Сосны обратились против леса, в пещерах завелись грелли и сатиры. Часовые и друиды стерегут покой Тельдрассила, и отсюда юные ночные эльфы впервые выходят в большой мир.",
        ["Доланаар"] = "Доланаар — тихая деревня ночных эльфов в сердце Тельдрассила, на дороге из Тенистой долины к Дарнассу. Здесь есть таверна, где хозяйничает Кельдамир, и лунный колодец, у которого несёт стражу Коритрас Лунный Гнев. Друиды Атридас Медвежья Шкура и Таллонкай Гибкий Корень отсюда руководят борьбой с обезумевшими фурболгами и сатирами. У обочины ошивается сатир Зенн Грязное Копыто, а к северу чернеет вход в Пещеру Бесов.",
        ["Тенистая долина"] = "Тенистая долина — укромная поляна на северо-востоке Тельдрассила, окружённая горами и залитая вечными сумерками. Единственный выход лежит на юг, к Доланаару, а в центре высится древо Альдрассил. Здесь ночные эльфы делают первые шаги, и Опекун Илталайн следит за равновесием: после обильных дождей ночные саблезубы и щетинистые вепри расплодились сверх меры. В долину вернулась дриада Тариндрелла, которую много лет не видели в Калимдоре, и старшие считают это тревожным знаком.",
        ["Альдрассил"] = "Альдрассил — могучее древо в центре Тенистой долины, внутри которого устроено целое селение. В его верхней комнате обитает Тенарон Хватка Бури; он отправляет подающих надежды юных эльфов в большой мир и рассказывает им о недавней истории народа. Под сенью Альдрассила наставники обучают новичков, а чуть севернее лежит лунный колодец с водой, хранящей силу Элуны. У подножия древа стоит Гилшалан Буйный Ветер, изучающий пауков из Паучьего логова.",
        ["Паучье логово"] = "Паучье логово — пещера на северо-западной окраине Тенистой долины, целиком затянутая паутиной. В ней плодятся чащобные тенетники: они куда крупнее своих сородичей с материка, и друиды полагают, что виной тому влияние самого Древа Жизни. В глубине логова спрятано гнездо с яйцами, и пауки яростно его защищают. Гилшалан Буйный Ветер, стоящий у Альдрассила, собирает здесь образцы яда, чтобы понять природу этих тварей.",
        ["Пещера Бесов"] = "Пещера Бесов лежит к северу от Доланаара. Некогда это был красивый грот, но теперь его наводнили грелли — мелкие злобные духи, что стайками роятся во тьме. В глубине пещеры устроил логово сатир лорд Меленас, собравший вокруг себя шайку греллей-воинов; сердце его, по словам друидов, чернее ночи. То, что сатир поселился так близко к деревне, тревожит Таллонкая Гибкого Корня, и он ищет того, кто положит этому конец.",
        ["Озеро Аль'Амет"] = "Озеро Аль'Амет — одно из крупнейших озёр Тельдрассила; оно лежит к югу от Доланаара, и на берегу нет ничего, кроме маленького причала. У восточной оконечности разбил лагерь друид Деналан, изучающий растения великого древа. Больше всего его тревожат древесники — духи природы, которые здесь отчего-то впадают в ярость, а у воды прорастают всё новые их ростки. В пещере на южном берегу засел древесник Дубохмур, поражённый чудовищной опухолью и заражающий порчей всё вокруг.",
        ["Деревня Звездного Ветра"] = "Деревня Звёздного Ветра лежит на востоке Тельдрассила, между Тенистой долиной и Доланааром. Прежде это было тихое поселение ночных эльфов из нескольких домов, и здесь жил Гэролас Талветрен, Великий смотритель за спящими друидами обители Бен'этиль. Теперь деревню разграбили и заняли обезумевшие фурболги племени Кривой Сосны. К северу от неё засела шайка мистиков во главе с Фероситасом Пожирателем Снов, чьё ожерелье светится зелёным в ночи.",
        ["Лагерь у Кривой Сосны"] = "Лагерь у Кривой Сосны занимает дальний юго-западный угол Тельдрассила. Это родовое поселение фурболгов племени Кривой Сосны, некогда мирных соседей ночных эльфов и покровителей леса. Их вождь Урсал Изверг затмевает разум соплеменников мхом Скверны, и отсюда отряды фурболгов расходятся по всему острову. Именно Урсала друиды Доланаара винят в беде, постигшей спящих друидов-воронов.",
        ["Обитель Бен'этиль"] = "Обитель Бен'этиль — небольшой курган-святилище в глубине лощины Бен'этиль, построенный ночными эльфами для спящих друидов-воронов. В нижнем и верхнем ярусах они покоятся в Изумрудном Сне по уговору с Изерой, а реликвии Пробуждения хранятся в священных ларцах. Ныне обитель захватили фурболги Кривой Сосны: их шаман научился разлучать дух спящего с телом, и тела друидов, лишённые воли, нападают на всякого вошедшего. Дух Обена Яростного Когтя, запертый во Сне, ищет помощи.",
        ["Расселина"] = "Расселина — логово фурболгов Кривой Сосны к северо-западу от Доланаара, прямо под сторожевым постом Часовых. Отсюда душители племени выходят на дорогу и подстерегают путников, что везут грузы и вести между Доланааром и Дарнассом. У входа дорогу стережёт часовой Амара Ночная Странница со своими воинами.",
        ["Поляна Оракула"] = "Поляна Оракула — святилище на северо-западе Тельдрассила. Здесь растёт Древо-оракул с ветвями, похожими на орла на спине медведя; говорят, его вырастила магия природы. Вместе с друидами древо следит за ростом Тельдрассила и шлёт вести Фэндралу Оленьему Шлему на кусках исписанной коры. Под его ветвями лежит первый и самый могучий из лунных колодцев острова. Но на поляне свили гнёзда гарпии Кровавого Пера, и часовой Арания Проблеск Солнца с малым отрядом пытается их вытеснить.",
        ["Родниковая река"] = "Родниковая река берёт начало из источника, бьющего в глубине самого Тельдрассила. Она вытекает из Родникового озера и течёт на север, пока не срывается с края великого древа огромным водопадом в море далеко внизу. По её берегам бродят обезумевшие древесники, бросающиеся на всякого, кто подойдёт к воде.",
        ["Родниковое озеро"] = "Родниковое озеро — небольшой водоём к северо-востоку от Дарнасса, питаемый источником из недр Древа Жизни; из него вытекает Родниковая река. Когда-то здесь любили рыбачить, но теперь у воды бродят древесники, поражённые порчей сильнее всех на острове, а в окрестностях рыщут ночные саблезубы и пауки. Близ озера обитает леди Сатра — паучиха, некогда дорогая Элуне: она ткала серебряные нити под луной, и капли тумана с её паутины хранили в храме Луны как целебное средство. Ныне её постигло безумие.",
        ["Пруды Арлитриэна"] = "Пруды Арлитриэна — россыпь малых водоёмов на западе Тельдрассила, к юго-востоку от входа в Дарнасс. Когда-то здесь было спокойно, но теперь у воды хозяйничают злобные твари. На берегу стоит одинокий лунный колодец, который ночные эльфы оставили без присмотра: Часовым всё труднее наблюдать за этими местами из-за участившихся нападений фурболгов Кривой Сосны.",
        ["Деревня Рут'теран"] = "Деревня Рут'теран лежит у самого подножия Тельдрассила, среди его корней, на берегу Сокрытого Моря. Это гавань острова: отсюда паром и гиппогрифы укротителя Весприста возят путников в Аубердин на Тёмных берегах, а мерцающий портал ведёт наверх, в Дарнасс. Рыбаки здесь живут в достатке — рыба в этих водах крупная, и её много, как охотно рассказывает торговка Несса Песня Теней. Для прибывающих с материка Рут'теран — первые ворота в край ночных эльфов.",
        ["Лощина Бен'этиль"] = "Лощина Бен'этиль — тесное ущелье к югу от дороги, соединяющей Доланаар с Дарнассом. Здесь собралось больше всего фурболгов Кривой Сосны на острове; время от времени они выходят из лощины и нападают на путников. В глубине ущелья скрыт вход в обитель Бен'этиль, где покоятся спящие друиды. Часовые назначили награду за клыки этих фурболгов, ибо Скверна лишила их рассудка.",
        ["Сокрытое Море"] = "Сокрытое Море — бескрайние воды к северу и западу от Калимдора, из которых поднимается ствол Тельдрассила. Своё имя море получило от тумана, которым ночные эльфы веками скрывали Калимдор от чужих глаз, пока Третья война не сорвала эту завесу. В его глубинах живут исполинские морские черепахи, а с края великого древа в море срывается водопад Родниковой реки. За проливом лежит Аубердин на Тёмных берегах, куда из Рут'терана ходит паром.",
    },
    ["Темные берега"] = {
        _zone = "Тёмные берега — длинная полоса побережья на северо-западе Калимдора, где над серыми пляжами почти всегда висят тучи, а с моря тянет холодный туман. Между горами и водой растёт сумрачный хвойный лес, и на утёсах крошатся руины древних городов. Когда-то эта земля была одной из самых богатых в империи ночных эльфов, но Великий Раскол разрушил её города и перекроил всё побережье. Тысячи лет спустя эльфы вернулись сюда малым числом и отстроили портовую деревню Аубердин, откуда корабли уходят к Тельдрассилу и в Гавань Менетилов. В опустевших руинах хозяйничают наги, сатиры и беспокойные духи высокорожденных, а на пляжах промышляют мурлоки. Реки, текущие с гор из Оскверненного леса, несут порчу: от неё сходят с ума фурболги и болеют олени. На юге, у Меча Властителя, собирается клан Сумеречного Молота, а в северной башне Алталакса что-то замышляют чернокнижники.",
        ["Аубердин"] = "Аубердин — небольшая портовая деревня ночных эльфов на берегу Сокрытого Моря, единственное обжитое место на Тёмных берегах. Низкие деревянные дома соединены мостками и освещены фонарями, а над пристанью возвышается маяк. Отсюда корабли ходят к подножию Тельдрассила и через море в Гавань Менетилов, а гиппогрифы уносят путников на юг. Деревней управляет старейшина Тандрис Ветропряд, а рядом с эльфами живут дворфы, гномы и люди. Говорят, давным-давно у маяка разбился корабль капитана Элуры, и сундуки с элунитовой рудой до сих пор лежат на дне.",
        ["Руины Матистры"] = "На самом севере Тёмных берегов, за башней Алталакса, лежат руины Матистры. До Великого Раскола здесь стоял город ночных эльфов, но гибель Источника Вечности стёрла его с лица земли, и эльфы навсегда ушли отсюда в прибрежные поселения южнее. В траве и среди разбитых камней до сих пор попадаются реликвии высокорожденных, и молодые эльфы порой отправляются сюда на их поиски. Теперь же в руинах поселились наги, которые ревностно охраняют их от любых чужаков.",
        ["Башня Алталакса"] = "Одинокая башня Алталакса стоит на севере Тёмных берегов, к северо-востоку от Аубердина. В дни расцвета высокорожденных в ней проводил свои дни Атрикус Нарассин — маг, которого сама королева Азшара поставила править Амет'Араном и Башал'Араном. Спустя десять тысяч лет вокруг башни собрались чернокнижники клана Темной Нити, и среди них замечен даже сатир. Из Аубердина сюда послали Балтула Удар Тени наблюдать за ними, и он прячется в лесу неподалёку. Внутрь башни соваться не советуют: те, кто засел наверху, куда сильнее тех, что бродят снаружи.",
        ["Водопад Скалистый"] = "Водопад Скалистый низвергается с гор к востоку и чуть севернее Аубердина. Отсюда берёт начало река Скалистая, и это главный источник питьевой воды для всех Тёмных берегов. За водопадом скрыта пещера, где растут редкие грибы, но в последнее время в ней обосновались наги, а Древа из Рощи Древних чувствуют там незнакомое зло. Друиды подозревают, что именно отсюда расходится отрава, от которой болеют олени по всему побережью.",
        ["Башал'Аран"] = "К северо-востоку от Аубердина, на холмах над дорогой, лежат руины Башал'Арана. Вместе с Амет'Араном это был один из городов-близнецов, куда королева Азшара привела своих любимых слуг — высокорожденных; здесь жил маг Астерион, второй после правителя Атрикуса Нарассина. Раскол уничтожил город, а спустя тысячелетия в руинах поселились грелли и сатиры, что питаются остатками древней магии. Лишь к одному святилищу на западном краю руин демоны не приближаются: над ним разливается странное синее свечение.",
        ["Амет'Аран"] = "Руины Амет'Арана лежат к востоку от главной дороги, к югу от Аубердина. Когда-то здесь, среди базаров и храмов Элуны, слуги королевы Азшары свободно упражнялись в своей могучей магии, но Раскол погубил город вместе с жителями. Теперь среди колонн бродят неупокоенные духи высокорожденных, всё ещё сжимающие древние магические приспособления. В руинах стоят две каменные таблички с историей Амет'Арана и его падения, и до сих пор горит древний синий огонь. Один из друидов Аубердина, переживший те времена, узнал среди здешних призраков свою возлюбленную.",
        ["Роща Древних"] = "Роща Древних укрылась на юго-востоке Тёмных берегов, у подножия гор, там, где шумит Петляющая река. Это священные руины старого храма ночных эльфов, где обитает Ону, Древо Мудрости, — терпеливый и мудрый исполин, к чьему совету прислушиваются даже в Дарнассе. Рядом с ним расположились пара торговцев и друид Керлониан Вечный Сумрак, который очнулся от Изумрудного Сна и никак не может проснуться до конца. Ону тревожат наги на побережье и клан Сумеречного Молота у Меча Властителя.",
        ["Меч Властителя"] = "На юго-западе Тёмных берегов, посреди небольшого озера, возвышается Меч Властителя — исполинский клинок, вонзённый в череп невиданного существа. Ону из Рощи Древних говорит, что здесь пал один из старых, очень старых богов этой земли, низвергнутых в незапамятные времена. Ночные эльфы издавна считали это место священным, но теперь вокруг черепа разбил лагерь клан Сумеречного Молота. Культисты поклоняются Древним богам и, судя по всему, пытаются с помощью древней эльфийской магии вернуть в мир своих хозяев.",
        ["Раскопки рассеянного геолога"] = "На побережье к югу от Аубердина дворфы из Лиги исследователей ведут раскопки, названные в честь их начальника — геолога Сомнамбулера, знаменитого в Стальгорне своими открытиями и не менее знаменитого своей рассеянностью. Под слоем песка обнаружились следы некогда крупного поселения. Но стоило копнуть глубже, как из-под земли выскочили древние големы и заполонили весь раскоп. Говорят, геолог нашёл здесь удивительную окаменелость, наделённую таинственными свойствами, — и тут же забыл, куда её положил.",
        ["Туманный Предел"] = "Туманный Предел — самая длинная полоса побережья Тёмных берегов: она тянется от Аубердина на север до оконечности края. Здесь сменяют друг друга мрачные бухты и серые пляжи, усыпанные обломками и тушами морских тварей, которых выбрасывает на песок. В прибрежных водах лежат затонувшие корабли — среди них «Серебряная Заря» и «Туманная Пелена», потопленные мурлоками на подходе к Аубердину. Мурлоки и теперь не дают покоя берегу, но ещё больше здесь крабов, снующих по всей отмели. В эти воды впадает река Скалистая, несущая с гор порчу.",
        ["Длинный пролив"] = "Длинный пролив, вопреки названию, — самый короткий отрезок побережья: пустынная полоса песка к югу от Аубердина, до широты Амет'Арана. Под вечно пасмурным небом берег кажется сумрачным даже днём, а песок усеян обломками и костями морских животных. В воде к западу от деревни, рядом с затонувшим судном, лежит скелет морской черепахи. Мурлоки клана Серой Мглы появляются здесь всё чаще: в их поселении скрывается Глубомрак, за голову которого совет деревни назначил награду.",
        ["Петляющая река"] = "Петляющая река сбегает с восточных гор на юге Тёмных берегов и вьётся через лес к морю. Это продолжение реки, текущей из Оскверненного леса, и вместе с водой она приносит сюда порчу. На её берегах, у подножия гор, стоит Роща Древних, а в зарослях вдоль русла охотятся лунопарды — крупные кошки, чьи шкуры ценят друиды Аубердина.",
        ["Берлога в Чернолесье"] = "На самом юге Тёмных берегов, у границы с Ясеневым лесом, укрылась Берлога в Чернолесье — несколько стойбищ фурболгов клана Чернолесья и небольшая пещера. Когда-то эти фурболги были дружелюбны к ночным эльфам, но сатиры подчинили их при помощи талисманов, и порча превратила лесной народ в свирепых врагов. В пещере, окружённой их лагерями, скрывается раненый ночной эльф Волкор, а его верный медведь Мрачнокоготь ждёт у дороги, надеясь привести помощь.",
        ["Река Скалистая"] = "Река Скалистая начинается у водопада Скалистого в горах и течёт к северу от Аубердина через лес к морю, впадая в Туманный Предел. Дорога пересекает её по высокому мосту. Прежде это была чистая вода, но теперь река исполнилась порчи: звери, что пьют из неё, заболевают, и особенно страдают олени. В верховьях стоят лагеря фурболгов Чернолесья, и в Аубердине опасаются, что зараза скоро дойдёт до самой деревни.",
        ["Сумеречная долина"] = "Сумеречной долиной называют южные леса Тёмных берегов — от руин Амет'Арана до границы с Ясеневым лесом. Под тёмными кронами бродят одичавшие саблезубы, взбесившиеся медведи и фурболги Чернолесья, поражённые порчей, так что путникам советуют держаться дороги. Вдоль неё, к югу от Аубердина, стоят лагеря фурболгов, а на востоке, у гор, прячется Роща Древних. Здесь же встречаются больные олени, которых пытаются исцелить друиды.",
        ["Сумеречная Излучина"] = "Сумеречная Излучина — южный отрезок побережья, от Длинного пролива до самого Ясеневого леса. Это самая суровая часть берега: серые пляжи здесь разбиты отвесными скалами, а у южной оконечности в воде разбросаны мелкие островки. На отмелях селятся мурлоки, а в волнах ходят злобные крепкозубы, готовые броситься на любого, кто плывёт к берегу. На одной из отмелей лежат останки исполинского крепкозуба, каких на Тёмных берегах никогда не видели. В глубине суши, за скалами, возвышается Меч Властителя.",
        ["Сокрытое Море"] = "Сокрытое Море — огромный океан, омывающий Калимдор с запада и севера. Своё имя оно получило от тумана, которым ночные эльфы окутали континент, чтобы скрыть его от чужаков до самой Третьей войны. В его водах растёт мировое древо Тельдрассил, а из Аубердина через него ходят корабли в Гавань Менетилов. Море холодное и штормовое, и лишь умелые мореходы проводят суда сквозь дожди и туманы; те, кому не повезло, остались лежать на отмелях у берега. В глубинах живут гигантские черепахи и кракены, а после Раскола под воду ушли город Зорам и храм Непроглядной Пучины.",
    },
    ["Тернистая долина"] = {
        _zone = "Тернистая долина — влажные джунгли на юге Восточных королевств, к югу от Сумеречного леса, с трёх сторон окружённые морем. Тысячелетиями здесь правила империя Гурубаши, и руины её городов до сих пор крошатся под натиском лиан и зноя. В пору голода Гурубаши призвали кровавого лоа Хаккара Свежевателя Душ, но его жажда оказалась ненасытной: племя Зандалар с восставшими троллями низвергло его в Зул'Гурубе, а империя распалась на враждующие племена Кровавого Скальпа и Дробителей Черепов. Люди Штормграда пытались проложить сюда торговые пути, но их порт в бухте Черноводья разорили тролли, и на его месте гоблины выстроили Пиратскую бухту. Ныне Орда держит лагерь Гром'гол, Торговая компания валит лес, дворф Эрнестуэй ведёт большую охоту, а пираты Кровавого Паруса готовят удар по Пиратской бухте. В чаще рыщут тигры, пантеры и ящеры, а колючие лианы, давшие долине имя, оплетают каждую тропу.",
        ["Бухта Черноводья"] = "Бухта Черноводья — укрытая утёсами лагуна на южной оконечности долины, вокруг которой выросла Пиратская бухта. Когда-то Штормград основал здесь небольшой порт, но тролли быстро вытеснили людей, а затем гоблины изгнали троллей и обосновались в бухте сами. Отсюда и пошло имя Разбойников Черноводья — пиратов, воров и наёмников, которые правят городом. В тихой воде лагуны стоят корабли, а по берегам тянутся причалы и склады.",
        ["Зул'Гуруб"] = "Зул'Гуруб — древняя столица империи Гурубаши, укрытая в долине на северо-востоке джунглей. Среди увитых лианами зиккуратов тролли некогда призвали кровавого бога Хаккара Свежевателя Душ, требовавшего бесчисленных жертв. Племя Зандалар и восставшие Гурубаши штурмовали город и низвергли Хаккара на его алтаре, а жрецов Атал'ай изгнали в северные топи. Ныне тролли шепчут, что Свежеватель Душ возродился в своём храме и его верховные жрецы вновь собрались в Зул'Гурубе. Потому Зандалар ищет союзников среди чужаков.",
        ["Пиратская бухта"] = "Пиратская бухта — гоблинский портовый город, вырубленный в утёсах вокруг лагуны на южной оконечности долины. Путник входит в город через выбеленные челюсти исполинской акулы и попадает в лабиринт деревянных настилов, таверн и лавок над водой. Городом правит барон Ревилгаз, а порядок держат Разбойники Черноводья — пираты, которые убивают лишь по необходимости. Порт открыт для всех, кто платит, и отсюда ходят корабли в Кабестан. Но жизнь здесь дешева, доверять никому нельзя, а над городом нависает угроза Кровавого Паруса.",
        ["Озеро Назферити"] = "Озеро Назферити лежит в сердце северных джунглей, к западу от Зул'Гуруба. Его мутные воды кишат кроколисками и прожорливой рыбой, а по берегам обосновалась Торговая компания: гоблины валят лес, а посреди озера возвели буровую платформу. Здесь же они обрабатывают поющие кристаллы, добытые в холмах у Хрустальной шахты. Через озеро течёт длинная река, чьи истоки лежат далеко на севере.",
        ["Пустынный берег"] = "Пустынный берег тянется вдоль западного побережья северной части долины — от границы с Западным Краем до лагеря Гром'гол. Песчаные отмели и скалы облюбовали кроколиски и василиски, а по берегу разбросаны троллиные руины, занятые племенем Кровавого Скальпа. У побережья лежит Коварный риф, где среди затонувших развалин живут мурлоки. Это дикое место, где джунгли выходят прямо к Великому морю.",
        ["Лагерь Повстанцев"] = "Лагерь Повстанцев стоит на самом севере долины, у дороги из Сумеречного леса. Здесь укрылись солдаты Штормграда, некогда пришедшие в джунгли с экспедицией полковника Курцена. Когда их командир обезумел и обратился ко злу, часть отряда во главе с Дореном взбунтовалась и ушла на запад. Повстанцы по-прежнему верны Штормграду и ведут войну против бывших товарищей, а припасы и мины для обороны им присылает Кразек из Пиратской бухты.",
        ["Экспедиция Эрнестуэя"] = "Лагерь экспедиции Эрнестуэя разбит у реки, к северу от озера Назферити. Прославленный дворфийский охотник Эрнестуэй привёл сюда спутников ради большой охоты: Ажек учит выслеживать тигров, сэр Эрлгедин — пантер, а сам Эрнестуэй — ящеров. Верный Барнил записывает их приключения в книгу «Зелёные холмы Тернистой долины», страницы которой ветер разносит по всей долине. Новичку здесь придётся доказать своё мастерство, прежде чем его допустят к самым грозным зверям джунглей.",
        ["Лагерь Курцена"] = "Лагерь Курцена стоит на севере долины, к востоку от Лагеря Повстанцев. Полковник Курцен, некогда благородный офицер Штормграда, привёл сюда экспедицию, но попал под власть тёмной магии огра-мага с холма Мош'Огг и обратился против собственного королевства. Его бойцы держат лесопилку, дрессируют пойманных пантер и тигров для войны и стерегут пещеру-схрон в глубине лагеря. Повстанцы называют Курцена зверем и знают: покой не вернётся в джунгли, пока он жив.",
        ["Руины Зул'Кунды"] = "Руины Зул'Кунды — обширный троллиный город на северо-западе долины, ныне вотчина племени Кровавого Скальпа. Здесь живут их вожди и знахари, и отсюда племя совершает набеги на путников. Кровавый Скальп охраняет священные для них кристаллы в холмах и люто ненавидит гоблинов, что жаждут наживы. Ходят слухи, что за необычной магией племени стоит могущественный дух воды.",
        ["Руины Зул'Мамбве"] = "Руины Зул'Мамбве лежат в котловине среди гор к югу от холма Мош'Огг, открытой лишь с севера. Здесь обосновался клан Дробителей Черепов — второе великое племя долины, воюющее с Кровавым Скальпом за каждую пядь джунглей. Тролли достраивают древние стены Гурубаши под нужды растущего племени, а их знахарь держит при себе околдованных людей из экспедиции Курцена. Чужаков здесь встречают копьями.",
        ["Коварный риф"] = "Коварный риф — полоса пёстрых кораллов у западного берега долины, близ лагеря Гром'гол. Под водой лежат затонувшие троллиные руины, где среди развалин живут мурлоки, а между кораллами прячутся гигантские моллюски, в которых, по слухам, зреет голубой жемчуг. Волны прибивают сюда обломки кораблей, а с берега на риф приходят наги.",
        ["Холм Мош'Огг"] = "Холм Мош'Огг — логово огров племени Мош'Огг к югу от Зул'Гуруба. В глубине пещеры правит огр-маг, владеющий могущественной реликвией, с помощью которой он подчинил разум полковника Курцена. Огры грабят караваны Орды, идущие в Каменор, и держат в страхе окрестные джунгли. Задолго до огров эта пещера была святилищем троллей.",
        ["Схрон"] = "Схрон — пещера в глубине лагеря Курцена, где бойцы полковника хранят оружие и снаряжение для войны. Здесь укрываются его приближённые командиры и сам Курцен. Вход стерегут лучшие воины лагеря, и повстанцы считают Схрон самым опасным местом на севере джунглей.",
        ["Лагерь Гром'гол"] = "Лагерь Гром'гол — укреплённый форпост Орды на западном побережье долины. Частокол и сторожевые башни защищают его от троллей, наг и Альянса, что приходит из Пиратской бухты и Сумеречного леса. Отсюда караваны с припасами идут в Каменор, в Болото Печали, но огры Мош'Огг устраивают засады, а тролли Кровавого Скальпа крадут провизию. Дирижабли связывают лагерь с Оргриммаром и Подгородом, а тролли Чёрного Копья ищут здесь след Йеннику — пропавшего сына своего вождя.",
        ["Руины Зуулдая"] = "Руины Зуулдая стоят на северной части западного побережья, над Пустынным берегом. Некогда здесь жили Гурубаши, а теперь среди камней хозяйничают тролли Кровавого Скальпа. Отсюда тропа ведёт на восток, к Зул'Кунде, сердцу их племени.",
        ["Руины Бал'лал"] = "Руины Бал'лал лежат на северо-западном побережье, к северу от Гром'гола, над Коварным рифом. Остатки древних построек Гурубаши заняли тролли Кровавого Скальпа. Рядом проходит путь между лагерем Орды и северными землями, и потому этот берег особенно неспокоен.",
        ["Руины Кал'аи"] = "Руины Кал'аи — полузатопленные троллиные развалины на побережье северной части долины. Море давно поглотило нижние ярусы города, и в них поселилось племя мурлоков. Их бормотание разносится над водой среди обломков былой славы Гурубаши.",
        ["Руины Ткаши"] = "Руины Ткаши лежат к юго-западу от лагеря Эрнестуэя, в густых джунглях. Их занимает многочисленный отряд троллей Кровавого Скальпа, чьи знахари творят здесь свои обряды. Древние камни Гурубаши поросли лианами, но племя не оставляет этих мест.",
        ["Руины Балиа'ма"] = "Руины Балиа'ма стоят на восточном берегу реки, к юго-востоку от лагеря Гром'гол и к юго-западу от холма Мош'Огг. Здесь живут тролли клана Дробителей Черепов, и их охотники за головами стерегут развалины. Джунгли здесь особенно густы, а дорога проходит совсем рядом.",
        ["Руины Зиата'джаи"] = "Руины Зиата'джаи лежат в восточных джунглях, к югу от лагеря Гром'гол. Древние постройки Гурубаши заняли тролли клана Дробителей Черепов, чьи охотники за головами носят ожерелья из костей врагов. Путников здесь встречают копья и топоры.",
        ["Руины Мизжа"] = "Руины Мизжа лежат к юго-востоку от лагеря Гром'гол. Их заняли громилы и знахари огров Мош'Огг, которые отсюда устраивают засады на караваны Орды, идущие в Каменор. Древние камни троллей теперь служат ограм укрытием.",
        ["Остров Жагуаро"] = "Остров Жагуаро лежит у юго-восточного побережья, отделённый от материка мелким проливом. Его джунгли населяют небогривые гориллы и жагуары, а правит островом исполинская горилла, чей рёв заставляет содрогаться всё живое. В плену у неё томится знатная пленница-таурен, которая бросает в море бутылки с записками в надежде на спасение. Волны выносят их на Гибельный берег.",
        ["Гибельный берег"] = "Гибельный берег — самое южное побережье Восточных королевств, где земля встречается с Южными морями. У островков близ берега стоят на якоре три фрегата пиратов Кровавого Паруса, готовящих нападение на Пиратскую бухту, а на самом берегу разбит их лагерь. Вдоль полосы прибоя бродит морской великан Горлаш, а в песке попадаются бутылки с посланиями. На востоке пролив отделяет берег от острова Жагуаро.",
        ["Хрустальное взморье"] = "Хрустальное взморье — песчаный берег на юго-востоке долины, о который бьются волны Южных морей. От джунглей его отделяет крутой хребет, сквозь который ведут лишь две тропы, одна из них — в Мглистую долину. Над южными водами высятся буровые вышки Торговой компании, а на северной оконечности пляжа стоят руины Абораза.",
        ["Ракушечный пляж"] = "Ракушечный пляж — тихая полоса песка на северном побережье долины, куда прибой выносит раковины и обломки. Здесь редко ступает нога путника, и лишь крики чаек нарушают шум волн.",
        ["Хрустальная шахта"] = "Хрустальная шахта лежит близ Зул'Мамбве. В её недрах растут поющие кристаллы — редкость, встречающаяся только в Тернистой долине. Местные василиски питаются ими, отчего их шкура становится твёрдой как камень, а у входа стоят окаменевшие фигуры троллей и людей. Торговая компания мечтает разработать шахту, но василиски не пускают гоблинов внутрь.",
        ["Руины Абораза"] = "Руины Абораза стоят на юго-восточном побережье, на северном краю Хрустального взморья. Здесь обосновался Занзил Отверженный — знахарь, изгнанный своим племенем за то, что травил сородичей зельями. Его смеси лишают разума всех, кто их выпьет: по руинам бродят одурманенные наги, тролли и поднятые мертвецы. Среди его невольников — Йеннику, сын вождя Чёрного Копья, и должники пиратского капитана из Пиратской бухты.",
        ["Остров Жанейро"] = "Остров Жанейро — островок у входа в Пиратскую бухту. На нём возвышается исполинская статуя гоблина с распростёртыми руками — маяк, встречающий корабли. Остров избрал своим жилищем морской великан, у которого хранится кушак с монограммой потопленного им капитана Смоттса.",
        ["Руины Жубуваля"] = "Руины Жубуваля лежат к востоку от Арены Гурубаши, у главной дороги, что тянется через всю долину. Их населяют слуги Занзила Отверженного — наги, тролли и мертвецы, одурманенные его зельем. Среди них скрываются и должники сурового капитана МакКинли из Пиратской бухты, прозванного Морским волком.",
        ["Мыс Тернистой долины"] = "Мыс Тернистой долины — южная оконечность джунглей, полуостров, выступающий в Южные моря. На его утёсах стоит Пиратская бухта, к северу от неё лежит Арена Гурубаши, а по берегам разбросаны троллиные руины и песчаные пляжи. Здесь разворачивается противостояние Разбойников Черноводья и пиратов Кровавого Паруса, и здесь же прячутся слуги Занзила Отверженного.",
        ["Южный Гибельный берег"] = "Южный Гибельный берег — пляжи и отмели на западной стороне мыса, где Южные моря омывают сушу. Он тянется от Коварного рифа до Пиратской бухты и острова Жанейро, где переходит в Гибельный берег. Здесь на песке разбили лагерь пираты Кровавого Паруса, и отсюда флотоводец Фираллон грозит обстрелять Пиратскую бухту.",
        ["Мглистая долина"] = "Мглистая долина укрыта в южной части мыса, среди туманных холмов. Здесь обитают могучие гориллы, чьи клыки и жилы ценятся охотниками и знахарями. В северном конце долины прячется пещера Духов, где живёт троллиный знахарь.",
        ["Родник Нек'Мани"] = "Родник Нек'Мани бьёт высоко в скалах над Южным Гибельным берегом. Это единственный источник чистой пресной воды к югу от Сумеречного леса, и каждый народ Азерота считает его священным для себя. Недавно к роднику пробрался отряд наг, и они яростно охраняют воду от всех пришельцев.",
        ["Лагерь Кровавого Паруса"] = "Лагерь Кровавого Паруса — стоянка пиратов на западном побережье долины, у дороги на Пиратскую бухту. Здесь собрались воины и чернокнижники Кровавого Паруса, готовящие удар по городу Разбойников Черноводья. Обе стороны охотно нанимают чужаков, и путнику предстоит выбрать, кому служить.",
        ["Главный лагерь Торговой компании"] = "Главный лагерь Торговой компании стоит на берегу озера Назферити. Гоблины валят лес, крошилки ревут среди пней, а геологи обрабатывают поющие кристаллы, свезённые из холмов у Хрустальной шахты. Компания вытеснила отсюда прочих гоблинов, и барон Ревилгаз из Пиратской бухты видит в ней соперника. Рядом, посреди озера, высится штаб-квартира — буровая платформа.",
        ["Арена Гурубаши"] = "Арена Гурубаши стоит к северу от Пиратской бухты — древнее ристалище империи троллей, пережившее её гибель. В старину бои здесь шли до смерти, и песок арены пропитан кровью. Ныне пираты устроили здесь забаву: раз в несколько часов распорядитель, Коротышка Джон Мифрил, бросает в центр арены сундук с добычей, и за него сражаются все против всех. Старые истории предупреждают: кто найдёт в полночь кроваво-красный амулет, того к рассвету сожрёт демон.",
        ["Пещера Духов"] = "Пещера Духов скрыта на северном краю Мглистой долины. В ней живёт троллиный знахарь, к которому приходят больные лихорадкой джунглей: за клык гориллы он вызывает духов зверей. Стены пещеры помнят древние обряды.",
        ["Кровавая Завеса"] = "«Кровавая Завеса» — флагман пиратов Кровавого Паруса, средний из трёх фрегатов, стоящих на якоре у Гибельного берега. Им командует флотоводец Фираллон, замысливший обстрелять Пиратскую бухту и сжечь город. В капитанской каюте хранятся письма с планами нападения, за которыми охотятся Разбойники Черноводья.",
        ["Бурун"] = "«Бурун» — западный из трёх фрегатов Кровавого Паруса, что стоят у островков Гибельного берега. Команда ждёт приказа флотоводца, чтобы двинуться на Пиратскую бухту. Алые паруса на горизонте заставляют торговцев сдаваться прежде первого залпа.",
        ["Госпожа Удача"] = "«Госпожа Удача» — восточный из трёх фрегатов Кровавого Паруса у Гибельного берега. Пираты здесь пьют, спорят и точат сабли, ожидая нападения на Пиратскую бухту. Говорят, никто не выживает после нападения Кровавого Паруса, оттого пираты и небогаты: грабить им некого дважды.",
        ["Штаб-квартира Торговой компании"] = "Штаб-квартира Торговой компании — буровая платформа, возведённая гоблинами посреди озера Назферити. Здесь трудятся механики и геологи, а бригадир руководит вырубкой леса и добычей кристаллов. Крошилки компании оснащены новыми регуляторами топлива, чертежи которых очень интересуют барона Ревилгаза.",
        ["Ринг"] = "Ринг — площадка под открытым небом в сердце Арены Гурубаши. Здесь нет ни флагов, ни союзов: всякий, кто ступит на песок, становится добычей для всех остальных. Именно сюда пираты бросают сундук с добычей, и именно здесь решается, кто достоин звания мастера арены.",
        ["Южные моря"] = "Южные моря омывают южные берега Восточных королевств и Калимдора. Их тёплые воды кишат акулами и нагами, а над волнами бродят морские великаны. Где-то за горизонтом лежит Зандалар, родина троллей, и острова, где прячутся пираты Кровавого Паруса.",
        ["Великое море"] = "Великое море — бескрайний океан, разделяющий континенты Азерота. Оно родилось при Расколе мира, когда древний Калимдор был разорван, а в его центре по сей день бушует Водоворот. Западный берег Тернистой долины смотрит в эти воды: здесь ходят корабли из Пиратской бухты в Кабестан, а под волнами таятся наги и морские чудовища.",
        ["Остров Йоджамба"] = "Остров Йоджамба — крошечная группа островков в северо-западном углу долины, у самой границы с Западным Краем. Здесь высадилось племя Зандалар, вернувшееся в джунгли из-за возрождения Хаккара. Зандалары не понимают чужаков, но зовут и Орду, и Альянс на бой со Свежевателем Душ, награждая героев печатями и талисманами. С острова открывается путь к Зул'Гурубу.",
    },
    ["Тирисфальские леса"] = {
        _zone = "Тирисфальские леса лежат на северном побережье Лордерона, там, где некогда билось сердце людского королевства. Чума Короля-лича прошла по этим холмам, и с тех пор небо здесь вечно затянуто зеленоватой мглой, а деревья цепляются за последние крохи жизни. Теперь это земля Отрекшихся: восставшие из мёртвых, сбросившие волю Плети, они присягнули Тёмной Госпоже Сильване Ветрокрылой и устроили столицу в Подгороде, под руинами Лордерона. Но покоя здесь нет. С востока, из Чумных земель, мимо защитников Бастиона просачиваются приспешники Плети, а на заброшенных фермах бродят безмозглые мертвецы. На северо-востоке, в Монастыре Алого ордена, укрепились живые фанатики, для которых всякая нежить достойна лишь огня. И всё же у этого угрюмого края есть своя мрачная красота: каменистый северный берег, тихие улочки Брилла и обветшалые мельницы Агамондов ещё помнят иные времена.",
        ["Бастион"] = "Бастион — последний рубеж Отрекшихся на границе с Западными Чумными землями. У частокола стражи смерти несут дозор плечом к плечу с воинами Серебряного Рассвета: общая угроза Плети заставила на время забыть о разногласиях. Ворота на восток ведут прямо в чумную мглу, и отсюда опытных бойцов Орды отправляют сражаться с приспешниками Короля-лича. Защитники всегда начеку, но, как говорят в Брилле, порой Плеть всё же проскальзывает мимо них в Тирисфаль.",
        ["Руины Лордерона"] = "Перед вами руины Лордерона — всё, что осталось от столицы величайшего людского королевства. Город пал, когда принц Артас, вернувшись с севера, убил своего отца, короля Теренаса Менетила, и открыл ворота Плети. Дворец стоит до сих пор, и в его пустых залах, говорят, ещё звучат отголоски того дня: приглушённые голоса во дворе, звон колоколов, приветственные крики в честь принца. Теперь под руинами раскинулся Подгород, столица Отрекшихся, а наверху, по разорённым дворам, всё ещё бродят мертвецы Плети.",
        ["Могильник"] = "Могильник — маленькая деревня в укрытой горами долине на юго-западе Тирисфаля. Именно здесь пробуждаются те, кого чума подняла из могил, но кто сумел вырваться из-под воли Короля-лича. Прежде селение носило иное, человеческое имя, но Отрекшиеся нарекли его заново. Северную часть деревни вместе с кузницей заняли безмозглые твари Плети, и жители держат оборону у часовни, где жрец Тьмы Сарвис встречает новопробуждённых. Не хватает всего, особенно золота: рудник на северо-западе кишит пауками, а неподалёку разбил лагерь отряд Алого ордена.",
        ["Паучья низина"] = "Паучья низина — небольшая лощина с золотым рудником к северо-западу от Могильника. И сама долина, и штольни кишат ночными кругопрядами: молодые пауки снуют снаружи, взрослые прячутся в затянутых паутиной углах шахты, а в самой её глубине сидит паучья матка. Отрекшимся отчаянно нужно здешнее золото, но добывать его нельзя, пока рудник не расчищен, и молодых мертвецов из Могильника посылают сюда испытать свои силы.",
        ["Ферма Соллидена"] = "Ферма Соллидена — тыквенная ферма на западе Тирисфаля, к северу от Могильника. Это одно из немногих мест на севере Лордерона, где живые крестьяне пережили чуму: их защищает башня Алого ордена, стоящая за полями. Люди здесь враждебны ко всем чужакам, а Отрекшиеся смотрят на них как на плесень, расползающуюся по их земле. Королевское фармацевтическое общество, впрочем, проявляет интерес к здешним тыквам: в Брилле их используют в опытах с Новой чумой.",
        ["Мельницы Агамондов"] = "Мельницы Агамондов — обширная сеть ветряных мельниц на холмах северного Тирисфаля, некогда владение самой преуспевающей семьи в этих краях. Когда Плеть пришла впервые, Грегор Агамонд решил остаться: семья укрепила усадьбу и уговорила работников держать оборону вместе с хозяевами. Погубил их младший сын Девлин, переметнувшийся к Плети и впустивший мертвецов за стены. Теперь мельницы — едва ли не крупнейший оплот Плети в Тирисфале: между обветшалых крыльев бродят скелеты-солдаты и заклинатели, а на дороге, говорят, до сих пор слышно безумное бормотание Девлина. Колман Фартинг, бывший работник Агамондов, а ныне Отрекшийся из Брилла, так и не простил хозяевам своей смерти.",
        ["Семейная усыпальница Агамондов"] = "Семейная усыпальница Агамондов стоит чуть севернее мельниц — самое укреплённое место во всём поместье. Здесь устроил штаб капитан Даргол, скелет на службе Плети. С помощью некромантии он поднял из гробов предков рода Агамондов, и теперь стенающие и гниющие мертвецы набрасываются на всякого, кто войдёт в тёмные пыльные залы без приглашения.",
        ["Брилл"] = "Брилл — небольшой городок в самом сердце Тирисфаля, к северу от руин Лордерона. Во время Третьей войны он одним из первых был поражён Чумой нежити, и братские могилы у его окраин вырыли, чтобы вместить бесчисленных погибших. Ныне Брилл принадлежит Отрекшимся, и правит им из ратуши мировой судья Севрен. Сюда, покинув Могильник, приходят новопробуждённые: город даёт им кров, а стражи смерти и палачи — работу в войне против Плети и Алого ордена. Как здесь говорят, это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире.",
        ["Шепчущие сады"] = "Шепчущие сады раскинулись на холме к югу от входа в Монастырь Алого ордена. Когда-то здесь произошла большая битва между теми, кто позже стал Алым орденом, и полчищами Плети. Духи павших так и не покинули это место: в сумерках их голоса слышны как тихий шёпот среди деревьев. Ныне сады охраняют разведчики и чародеи ордена.",
        ["Терраса Покоя"] = "Терраса Покоя лежит у самого входа в Монастырь Алого ордена. Это одно из редких мест на севере Лордерона, куда не дотянулась Чума нежити: здесь зеленеют подстриженные живые изгороди, а в фонтане плещется свежая вода, а не стоячая гниль, как повсюду в Тирисфале. Орден бережёт этот уголок как напоминание о том, за что он сражается.",
        ["Озеро Ясноводное"] = "Озеро Ясноводное — самое большое озеро Тирисфаля, лежащее к северо-востоку от Брилла, между Северным побережьем и постами Алого ордена. Его воды по-прежнему широки и спокойны, хотя берега давно отравлены чумой, а в камышах бродят псы тьмы. Посреди озера поднимается большой остров, на котором укрылся лич Гюнтер, и его прислужники не подпускают к берегу никого.",
        ["Приют Гюнтера"] = "Приют Гюнтера — остров посреди озера Ясноводного. Здесь обитает лич Гюнтер, некогда маг Кирин-Тора из Даларана, павший жертвой Чумы. Он остался свободен от воли Короля-лича, но не верит, что свободны остальные: лич убеждён, что вся нежить по-прежнему служит Плети, и велел своим зомби нападать на всякого, кто ступит на берег. Бетор Ледострел из Подгорода, его старый друг по Кирин-Тору, надеется вернуть его к своим.",
        ["Ферма Гаррена"] = "Ферма Гаррена — большая усадьба на севере Тирисфаля: дом, амбар, пара силосных башен и широкое поле. Когда-то щедрая земля посерела и омертвела от чумы, а Гаррен с семьёй погиб при нашествии Плети. Теперь на ферме хозяйничают гноллы-Гнилошкуры и их вожак Червеглаз, объявленный в розыск в Брилле: Плеть подослала их разграблять братские могилы к юго-востоку отсюда и таскать трупы для армии Короля-лича.",
        ["Ферма Балнира"] = "Ферма Балнира — разорённое хозяйство на востоке Тирисфаля, к северо-востоку от руин Лордерона. Семья Балниров разводила знаменитых белых коней Лордерона, которых покупали для королевского двора. Теперь здесь гнездится Плеть: мертвецы, проскользнувшие мимо защитников Бастиона, находят приют на пустых полях, и страж смерти Линнея просит прореживать их ряды. Среди сорняков ещё цветёт львиный зев, который когда-то выращивали Балниры.",
        ["Поместье \"Остывший Очаг\""] = "Поместье «Остывший Очаг» стоит у главной дороги в центре Тирисфаля. Некогда оно славилось тёплым домом и щедрыми урожаями, но чума забрала всех, кто здесь жил и работал; поля заросли, и по ним теперь бродят безмозглые зомби Плети. Сам дом Отрекшиеся отвоевали и держат в нём небольшую торговлю для путников, идущих по тракту.",
        ["Застава Алого Ордена"] = "Застава Алого ордена — сторожевая башня на холмах восточного Тирисфаля. Отсюда воины ордена следят за главной дорогой и прикрывают подступы к монастырю с фланга. Командует башней капитан Вакон, чьи отряды совершают набеги на земли Отрекшихся близ фермы Балнира.",
        ["Северное побережье"] = "Северное побережье — полоса каменистого пляжа вдоль Великого моря на северной кромке Тирисфаля. С тех пор как чума отравила эти земли, берег стал тёмным и холодным: у кромки воды гниют выброшенные морем туши, а среди хижин копошатся мурлоки и их головастики — нерестилища этих тварей совсем недалеко от берега. Здесь же лежат обломки старого кораблекрушения.",
        ["Шепчущий берег"] = "Шепчущий берег — короткий отрезок побережья на западе Тирисфаля, к северу от фермы Соллидена. Когда-то сюда приходили рыбачить, но ныне вода здесь холодна и темна, а от былого изобилия не осталось и следа. Берег заняла стая мурлоков, которая яростно бросается на всякого, кто подойдёт к воде.",
        ["Могила Фаола"] = "Могила Фаола лежит на востоке Тирисфаля, к юго-западу от Монастыря Алого ордена. Здесь был похоронен почитаемый архиепископ Фаол, умерший ещё до прихода Плети. В прежние времена к его могиле приходили паломники, ныне же она стоит заброшенной и почти забытой, а из разрушенной башни за холмом совершают вылазки люди капитана Мелраша.",
        ["Сторожевой пост Алого ордена"] = "Сторожевой пост Алого ордена — башня на северо-востоке Тирисфаля, за могилой Фаола. Орден держит гарнизон в этой глуши лишь затем, чтобы никто не подобрался к монастырю с его плохо защищённой северной стороны. Командует постом жестокий капитан Мелраш, и именно отсюда, по сведениям палача Зуганда из Брилла, идут набеги на земли Отрекшихся.",
        ["Тихий Омут"] = "Тихий Омут — небольшое озерцо к западу от Брилла. До чумы сюда приходили на пикники, а дети, которым ещё рано было плавать в глубоком Ясноводном, плескались на его мелководье. Теперь пруд лежит серый и забытый: под поверхностью остались лишь скелеты рыб, а по берегам, у старого моста, бродят гниющие мертвецы Плети и псы тьмы.",
        ["Долина Кошмаров"] = "Долина Кошмаров — широкая долина на юго-западе Тирисфаля. Когда-то здесь зеленели рощи и водилось лесное зверьё, но деревья засохли, а всё живое сожрали голодные псы тьмы и огромные летучие мыши-вампиры. На краю долины стоит заброшенная башня, куда Алый орден прислал капитана Перрина с отрядом.",
        ["Долина ядовитых пауков"] = "Долина ядовитых пауков лежит на востоке Тирисфаля, к югу от Монастыря Алого ордена. Прежде здесь охотились на оленей и кроликов среди зелёных деревьев, теперь же долина отравлена и кишит ядовитыми пауками, давшими ей новое имя. Аптекари Брилла ценят яд здешних злобных ночных кругопрядов. В северной части долины бродят псы тьмы, а рядом стоит лагерь Алого ордена.",
        ["Мрачный склеп"] = "Мрачный склеп — усыпальница на вершине склона над кладбищем Могильника, у самых гор. Именно здесь, среди гробов, приходят в себя те, кого чума подняла из мёртвых, но кто сумел вырваться из-под воли Короля-лича. Смотритель склепа Мордо встречает их первым и отправляет вниз по тропе, к часовне, где ждёт жрец Тьмы Сарвис.",
        ["Ратуша Брилла"] = "Ратуша Брилла — самое заметное здание городка. С её кафедры правит мировой судья Севрен, раздавая поручения Отрекшимся, готовым послужить общему делу. Это редкий случай, когда ратушей управляют восставшие из мёртвых, и сюда стекаются донесения обо всём, что творится в Тирисфале.",
        ["Таверна \"Петля висельника\""] = "Таверна «Петля висельника» — постоялый двор в Брилле, единственная настоящая таверна во владениях Отрекшихся. Под её крышей собираются наставники воинов, жрецов, магов, разбойников и чернокнижников, а хозяйка держит комнаты для усталых путников. В подвалах, впрочем, не так уютно: там в клетках держат пленных — ревнителя Алого ордена и дворфа, на которых аптекари испытывают свои яды.",
        ["Великое море"] = "Великое море омывает северный берег Тирисфаля. Его холодные тёмные воды тянутся до самого горизонта, отделяя Восточные королевства от далёкого Калимдора. У берега на волнах покачиваются обломки кораблекрушений, а дальше, в глубине, нет ничего, кроме бесконечной серой воды.",
        ["Крепость Бандариона"] = "Крепость Бандариона стоит на утёсах Северной скалы к северо-западу от фермы Соллидена, отделяя Шепчущий лес от остального Тирисфаля. Во время Третьей войны твердыню удерживал Серебряный Рассвет, пока не отступил в Чумные земли. Теперь Отрекшиеся собирают здесь новый орден паладинов — восставших из мёртвых рыцарей, не отрёкшихся от Света. Крепость названа в честь капитана Гарека Бандариона, павшего при обороне Подгорода от тварей Наксрамаса; возглавляет орден Данита Морр. Стены обветшали, припасов не хватает, а из окрестного озера на крепость то и дело нападают мурлоки, некогда устроившие в ней нерестилище.",
        ["Шепчущий лес"] = "Шепчущий лес — большой лес, запертый в горах на западе Тирисфаля, за Северной скалой и крепостью Бандариона. Чума не пощадила и его: среди деревьев бродят больные олени с оленятами, крысы и одинокий медведь, а в лесном озере обитает неупокоенный ящер. Посреди леса стоит странное кольцо гигантских грибов, над которым висит туман и порой вспыхивает непонятное сияние, а рядом бродит призрачный рыцарь, связанный клятвой. К юго-западу от озера лежат руины деревушки Тенедол.",
        ["Тенедол"] = "Тенедол — разрушенная деревня на юго-западе Шепчущего леса. До нашествия Плети эта уединённая деревушка славилась шепчущим эликсиром из трав, растущих только в Тирисфале; его запретили продавать в городе, но аптекари, мистики и ценители ядов всё равно платили за него щедро. Ныне в руинах обосновались Омрачённые — восставшие паладины, не смирившиеся с новым существованием и поднявшие клинки на братьев-Отрекшихся, а рядом бродят безмозглые мертвецы, среди которых рассеяны осколки некротического кристалла, разбитого в битве Наксрамаса с Подгородом.",
    },
    ["Тлеющее ущелье"] = {
        _zone = "Тлеющее ущелье — выжженная котловина на юге Каз Модана, между Лок Моданом, Бесплодными землями и Чёрной горой. Когда-то здесь стояли зелёные горы Красногорья, но в Войну Трёх Молотов колдун-тан Тауриссан призвал Рагнароса, и взрыв разорвал землю: к югу от нового вулкана легли Пылающие степи, а к северу — провал, который назвали Тлеющим ущельем. Ныне здесь хозяйничают дворфы Чёрного Железа, служащие Повелителю Огня: посреди ущелья они вырыли исполинский Котлован, где невольники добывают руду для их кузниц. Гарнизоны Стальгорна давно отступили в Лок Модан и заперли ворота Подгорной тропы, а Орда прорубила к ущелью узкий проход из Каргата. Единственное убежище для путников — Лагерь Братства Тория на северных утёсах, где живут дворфы Чёрного Железа, порвавшие со своим кланом. Здесь нет ни воды, ни травы: лишь пепел, лава, боевые големы, лавовые пауки и элементали огня.",
        ["Котлован"] = "Котлован — исполинская выемка в сердце Тлеющего ущелья, вырытая дворфами Чёрного Железа. По его краям стоят огромные горные машины клана, а внизу, среди трещин, из которых сочится лава, бродят элементали огня и магмы. Здесь день и ночь трудятся невольники — все, кого Чёрное Железо сумело захватить. Жар, плети надсмотрщиков и нескончаемая работа давно свели их с ума, и они бросаются на любого, кто помешает им копать, даже на своих освободителей. В глубине Котлована открывается вход в Шлаковую Яму, подземный рудник клана.",
        ["Карьер Грязнули"] = "Карьер Грязнули лежит на востоке ущелья, у дороги к Выжженной долине. Когда-то это был раскоп дворфов Стальгорна: археологи из Зала Исследователей искали здесь древние реликвии, и, как говорят, именно в этой яме были найдены камни Сунтары. Ныне карьером владеют дворфы Чёрного Железа, и их надсмотрщики с плетьми гонят по ямам невольников. На дне карьера лежит раненый археолог Дориус — единственный, кто остался от экспедиции; остальных угнали в Котлован.",
        ["Гряда Огненной стражи"] = "Гряда Огненной стражи тянется по западу ущелья и нависает над Котлованом. Здесь стоит главный лагерь дворфов Чёрного Железа в этих землях: паровые кузнецы, дозорные и геологи клана, а рядом бродят тяжёлые боевые големы и огромные лавовые пауки. В холмах на северо-западе гряды скрыта пещера, где обосновались служители Сумеречного Молота — культисты, что приносят жертвы Рагнаросу и стерегут в своём святилище странную реликвию. Это одно из самых опасных мест ущелья, и ходить сюда в одиночку не советуют.",
        ["Шлаковая Яма"] = "Шлаковая Яма — подземный рудник в глубине Котлована, богатый рудой. Работают здесь невольники под плетьми рабовладельцев и надсмотрщиков Чёрного Железа, а в лавовых озёрах нижних штолен водятся прожорливые огненные ящеры. Командует рудником перебежчик из Братства Тория, которого клан поставил надзирателем, и Братство назначило награду за его голову. В самом низу, у алтаря Сунтары, порабощённые археологи Стальгорна собирают что-то по воле новых хозяев.",
        ["Пепельное Море"] = "Пепельное Море — плоская равнина на юге ущелья, у самого подножия Чёрной горы. Огонь и ветер давно выжгли здесь всё живое: земля ещё тлеет, и в воздухе постоянно кружат пепел и искры, забивая глаза и глотку. Среди тлеющих пустошей бродят элементали пламени и лавовые пауки. Путники стараются пересечь это место как можно быстрее — здесь негде укрыться и нечем дышать.",
        ["Черная гора"] = "Чёрная гора встаёт над южным краем ущелья — огромный вулкан, рождённый в тот день, когда колдун-тан Тауриссан призвал Рагнароса. Она отделяет Тлеющее ущелье от Пылающих степей, и единственный путь между ними проходит сквозь её недра. В глубине горы дворфы Чёрного Железа возвели свой город, Глубины Чёрной горы, а ещё ниже, в Огненных Недрах, дремлет сам Повелитель Огня. Вершину, Пик Чёрной горы, держат орки клана Чёрной горы, и над ними властвует чёрный дракон Нефариан. Из ущелья к горе ведёт дорога через Пепельное Море.",
        ["Лагерь Братства Тория"] = "Лагерь Братства Тория стоит на скальном уступе в северной части ущелья, над самым Котлованом. Его основали дворфы Чёрного Железа, порвавшие со своим кланом: они не пожелали служить Рагнаросу и живут своим ремеслом. Братство славится кузнецами — говорят, это лучшие мастера Азерота, хранящие секреты, добытые в Огненных Недрах. Лагерь открыт и для Альянса, и для Орды: здесь есть кузница, торговцы и площадка, откуда грифоны и ветрокрылы летают в Стальгорн, Каргат и Пылающие степи. Отсюда надзиратель Братства и его дозорные следят за делами Чёрного Железа и щедро платят тем, кто готов сражаться с их бывшими собратьями.",
        ["Обугленная пещера"] = "Обугленная пещера прячется в юго-западном углу ущелья, у самого подножия Чёрной горы. Вход в неё завален камнем, и что скрывают её глубины, никто не знает. Говорят лишь, что в пору, когда год обновляется и луна светит ярко, у пещеры пробуждается дух древнего старейшины из племени земельников.",
        ["Палатка Дубильщицы"] = "Палатка Дубильщицы — крошечный лагерь на юго-востоке ущелья, где живёт одинокая кожевница из Штормграда, лучший мастер Альянса по выделке шкур элементалей. Не всякий решится поселиться в таком месте, но здесь, среди лавовых пауков и огненных тварей, ей всегда есть с чем работать. За палаткой начинается длинный извилистый проход в холмы, в конце которого лежит логово громового ящера Маргола Яростня — грозы всех археологов, что когда-либо забредали в Тлеющее ущелье.",
        ["Выжженная долина"] = "Выжженная долина — продуваемая ветрами лощина на северо-востоке ущелья, ведущая к воротам Подгорной тропы и дальше, в Лок Модан. У верхнего конца долины разбит лагерь дворфов Чёрного Железа: отсюда клан следит за запертыми воротами и за всеми, кто спускается из Лок Модана в ущелье. По склонам бродят боевые големы и элементали пламени, а ветер несёт по долине пыль и пепел.",
        ["Подгорная тропа"] = "Подгорная тропа — тоннель в северо-восточных горах, соединяющий Тлеющее ущелье с Долиной Королей в Лок Модане. Его, как и великую плотину Лок Модана, спроектировал древний дворфийский зодчий, создатель подгорного стиля строительства. С обеих сторон тоннель заперт коваными воротами: когда Чёрное Железо захватило ущелье, гарнизоны Стальгорна отступили и закрыли проход. Ключ хранит горный пехотинец Щебеночка, стерегущая ворота со стороны Лок Модана, и отдаёт его лишь тем, кто докажет, что одолел Маргола Яростня.",
    },
    ["Тысяча Игл"] = {
        _zone = "Тысяча Игл — огромный сухой каньон на юге Калимдора, между Степями, Фераласом и Танарисом. До Раскола здесь текла река, и её воды выточили из песчаника десятки огромных столбов; потом земля вздыбилась, вода ушла, и остались лишь иглы, торчащие со дна ущелья, будто каменный лес. По их вершинам протянуты верёвочные мосты — так таурены пересекают каньон, не спускаясь на дно, где рыщут кентавры племени Галак. Таурены Орды держат Заставу Вольного Ветра на высокой столовой горе, а их мятежные сородичи из племени Зловещего Тотема засели на Пике Тёмного Облака. На западе, в Скальном гнездовье, гнездятся виверны, в южных ущельях кричат гарпии, в пещерах роются кобольды. На востоке каньон раскрывается в Мерцающую равнину — слепящую соляную пустошь, где гоблины и гномы день за днём выясняют на гонках, чей болид быстрее.",
        ["Мерцающая равнина"] = "Мерцающая равнина — необъятная соляная пустошь на юго-востоке Тысячи Игл, у границы с Танарисом. Когда-то здесь плескалось озеро; о нём напоминает остов парусника, застрявший в соли на севере равнины. Ни деревца, ни травинки — только слепящая белизна, по которой бродят василиски, скорпиды, черепахи и стервятники. Ровное дно высохшего озера приглянулось гоблинам и гномам: они устроили здесь Виражи на Миражах, и вся округа усеяна воронками и обломками их машин.",
        ["Карьер Ржавой Кувалды"] = "Карьер Ржавой Кувалды — заброшенный раскоп дворфов на юго-западе Мерцающей равнины. Лига Исследователей начала откапывать здесь древние руины, но на лагерь напал боевой отряд Орды и перебил землекопов; в пылу боя кто-то потревожил подземный улей, и из пещеры хлынули силитиды, обратив в бегство и самих нападавших. Теперь среди брошенных палаток и лесов кишат насекомые, а в песке лежит дневник погибшего дворфа.",
        ["Лагерь Э'Ток"] = "Лагерь Э'Ток — стоянка кентавров племени Галак на северо-западе Тысячи Игл, у дороги, ведущей на запад. Отсюда кентавры выходят в набеги на караваны: один из обозов был разграблен здесь дочиста, а погонщики перебиты. Единственное, что грабители не сумели забрать, — драгоценный прибор гоблина Визло, который тот на свою беду повесил на шею своей свирепой пантере; зверь до сих пор в ярости мечется среди шатров.",
        ["Утес Треснувшего Копыта"] = "Утёс Треснувшего Копыта — крепость кентавров племени Галак у северной стены каньона, к востоку от Пика Тёмного Облака. Среди шатров и костров здесь собираются мародёры, погонщики и заклинатели ветра, отсюда отряды уходят в набеги на караваны и на заставу тауренов. В сердце утёса, в пещере, называемой Оплотом Треснувшего Копыта, племя хранит свою величайшую реликвию.",
        ["Скальное гнездовье"] = "Скальное гнездовье — возвышенная долина на западе Тысячи Игл, где на скалах гнездятся гордые виверны. Над головой парят самки, вожаки стерегут кладки, под гнёздами белеет высохшая на солнце скорлупа. Молодых тауренов с Заставы Вольного Ветра посылают сюда за яйцами — из детёнышей вырастают ветрокрылы Орды. Не всякий возвращается с добычей: юный Паока Ходячая Гора, приехавший изучать здешних зверей, оказался в ловушке среди разъярённых виверн.",
        ["Каньон Визга"] = "Каньон Визга — ущелье на юге Тысячи Игл, названное за пронзительные крики гарпий, не смолкающие здесь ни днём, ни ночью. Гарпии кружат над скалами и бросаются на всякого, кто ступит на дно каньона; таурены Заставы Вольного Ветра считают их меньшей бедой, чем кентавров, но и с них не спускают глаз. В дальнем конце ущелья скрыт вход в Логово Легкопёрых, где стая прячет награбленное.",
        ["Застава Вольного Ветра"] = "Застава Вольного Ветра — поселение тауренов Орды на вершине столовой горы в сердце Тысячи Игл. Наверх ведут деревянный подъёмник и верёвочные мосты между иглами, и кентаврам до заставы не добраться. Здешние таурены сдерживают племя Галак, посылают молодых воинов в Скальное гнездовье за яйцами виверн и с тревогой следят за Пиком Тёмного Облака. Заставой ведает Рау Скальный Бегун, а Дозорный утёсов Долгорог собирает вести о злодеяниях Арнака Зловещего Тотема.",
        ["Великий Подъемник"] = "Великий Подъёмник — огромная деревянная машина, построенная тауренами на северной стене каньона. Она соединяет Тысячу Игл с южным обрывом Степей: с верхней площадки видны вершины игл, а внизу начинается дорога к Заставе Вольного Ветра. Подъёмник стерегут таурены-стражи, но путь к нему сверху год от года становится опаснее — свинобразы Южных Степей всё шире раздвигают свои владения.",
        ["Форт Галак"] = "Форт Галак — владения кентавров племени Галак в северной части Тысячи Игл. У подножия игл стоят их шатры и горят костры, а по дну каньона рыщут разведчики и мародёры племени, готовые напасть на всякого, кто спустится с мостов.",
        ["Логово Легкоперых"] = "Логово Легкопёрых — небольшая пещера в глубине Каньона Визга, гнездо стаи гарпий. Здесь обитают заклинательницы ветра и разбойницы стаи, а в дальнем конце логова гарпии ревниво стерегут свои запасы — всё, что удалось стащить с караванов и у неосторожных путников. Чужака они не убивают сразу: сперва переглянутся и повизжат меж собой, а уж потом бросаются в бой.",
        ["Угол Семи Ветров"] = "Угол Семи Ветров — маленькая, хорошо укрытая пещера в северной стене каньона. Чтобы найти её, нужно подняться от Заставы Вольного Ветра к утёсам над иглами и идти вдоль обрыва на восток до пологого подъёма. В пещере живут два старых таурена-отшельника: они испытывают веру, выносливость, силу и знания тех, кто приходит к ним за мудростью, и лишь прошедшему все испытания открывают последнюю тайну.",
        ["Оплот Треснувшего Копыта"] = "Оплот Треснувшего Копыта — пещера в глубине утёса, самая охраняемая часть крепости племени Галак. Кентавры хранят здесь Раздвоенное Копыто — реликвию, уцелевшую ещё со времён сотворения их народа, — и стерегут её священным пламенем, что горит в древней жаровне и не гаснет. Говорят, лишь вода из лунного колодца ночных эльфов способна на краткий миг утишить этот огонь, и шаманы Громового Утёса очень хотели бы разгадать тайну того, что он охраняет.",
        ["Пик Темного Облака"] = "Пик Тёмного Облака — три столовые горы к востоку от Великого Подъёмника, соединённые верёвочными мостами; на их вершинах стоит селение племени Зловещего Тотема, и оба подступа к нему хорошо охраняются. Здесь правит Арнак Зловещий Тотем, за чью голову назначена награда: его сородичи похищают тауренов с Заставы Вольного Ветра, а вожди племени ведут тайную переписку с некой тёмной силой. Что задумал Зловещий Тотем, на заставе хотели бы знать больше всего.",
        ["Застава Белого Плеса"] = "Застава Белого Плеса — крошечная стоянка Орды у дороги на северо-западе Тысячи Игл, по соседству с Лагерем Э'Ток. Несколько шатров тауренов да костёр — вот и вся застава, и кентавры племени Галак напоминают о себе постоянно. Здесь же нашёл приют гоблин Визло, чей караван разграбили кентавры: он никак не может смириться с потерей своего гипервместителя.",
        ["Виражи на Миражах"] = "Виражи на Миражах — гоночная трасса, проложенная по соляной корке Мерцающей равнины. Её построили гоблин Поззик, некогда один из лучших механиков Нижней шахты, и его вечные соперники — братья-гномы: каждая команда хочет доказать, что её народ строит самые быстрые машины. Гонки ракетных болидов идут здесь день за днём, а пилот гоблинов Раззерик мечтает обогнать гномов на два круга. На трибунах — зеваки из Орды и Альянса, и немало золота ставится на победителя.",
        ["Безветренный каньон"] = "Безветренный каньон — широкая полоса ущелий к северу от дороги между Заставой Вольного Ветра и Мерцающей равниной. Здесь гнездятся крылатые змеи, и их ядовитые стаи вьются над скалами. Именно у этих гнёзд нашли странное чужое яйцо, о котором шепчутся и на заставе, и на Пике Тёмного Облака: по преданию, из него должна вылупиться Арикара, Змея Мщения. Отсюда же начинается тропа к Углу Семи Ветров.",
        ["Лагерь Железного Камня"] = "Лагерь Железного Камня — маленькая стоянка Орды на границе Мерцающей равнины. Сюда отступили остатки боевого отряда, посланного выгнать дворфов из Карьера Ржавой Кувалды: с землекопами воины справились, но не ждали, что из пещеры на них хлынут силитиды. Теперь уцелевшие бойцы и их кодо стерегут этот пост и ищут добровольцев среди путников, съезжающихся на гонки, чтобы очистить карьер от роя.",
        ["Кратер Криворука"] = "Кратер Криворука — глубокая воронка в северной части Мерцающей равнины. Откуда она взялась, точно никто не скажет: то ли названа по имени того, кто её нашёл, то ли того, кто её сотворил, — а глядя на разбросанные вокруг обломки ракетных болидов, нетрудно догадаться, чьё изобретение здесь могло рвануть. Теперь на дне кратера греются на соли солекаменные василиски.",
        ["Руины Тахонды"] = "Руины Тахонды — остатки древней деревни тауренов на юге Мерцающей равнины, у тропы, ведущей через горы в Танарис. О её жителях не осталось ни преданий, ни имён: солёные ветра давно засыпали покосившиеся шатры, а в кожаных стенах видны следы огромных когтей. Теперь между развалинами бродят лишь солекаменные василиски.",
    },
    ["Фералас"] = {
        _zone = "Фералас — густые дождевые джунгли на юго-западе Калимдора, зажатые между пустошами на севере, Тысячей Игл на востоке и кратером Ун'Горо на юге. Под кронами исполинских деревьев скрыты руины древней державы ночных эльфов, и величайшая из них — Забытый Город, некогда столица Высокорожденных Эльдре'Талас. Ныне большую часть леса держат в страхе огры клана Гордунни: они оскверняют землю и с каждым годом теснят соседей. Альянс закрепился на острове Сардор, в Крепости Оперенной Луны под началом генерала Шандрисы, а Орда — в Лагере Мохаче, тауренском поселении у Штормового озера. Между ними бродят гноллы клана Древолапов и таурены Зловещего Тотема, а западные острова кишат нагами. На севере же, на острове посреди Нефритового озера, растёт одно из четырёх великих деревьев, чьи корни уходят в сам Изумрудный Сон.",
        ["Таланаар"] = "Таланаар — крохотный лагерь ночных эльфов на самой восточной границе Фераласа, там, где джунгли обрываются в каньоны Тысячи Игл. Здесь нет ни стен, ни рынка — лишь пара торговцев да гиппогрифы, готовые унести путника к Крепости Оперенной Луны или в Прибамбасск. За порядком в лагере присматривает Хранитель дорог Фалфиндел, друид, к которому стекаются тревожные вести из соседних степей. Для Альянса это последний мирный привал перед дорогой мимо тауренского Лагеря Мохаче.",
        ["Лагерь Мохаче"] = "Лагерь Мохаче — деревня тауренов на востоке Фераласа, раскинувшаяся над тихими водами Штормового озера. Быстрый ручей рассекает поселение надвое, а вдоль его берегов стоят шатры торговцев и кожевников. Отсюда Орда следит за лесом: Хадокен Быстрый Странник собирает воинов против гноллов клана Древолапов, а по приказу из Оргриммара здесь охотятся на тауренов Зловещего Тотема. Главная же забота лагеря — огры Гордунни, чьи набеги подступают всё ближе к его частоколу.",
        ["Лагерь Зловещего Тотема"] = "Восточнее Забытого Города, среди холмов, стоит поселение тауренов Зловещего Тотема — отступников, не признающих власть Громового Утёса. Лагерь разделён на две части, и в южной из них высится большая клетка, где томятся пойманные волшебные дракончики. Здесь правит Грундиг Тёмное Облако, и в Лагере Мохаче не забыли о его злодеяниях. К востоку от северной части лагеря тянутся стоянки гноллов, с которыми Зловещий Тотем делит эти холмы.",
        ["Гудящая Бездна"] = "На юго-востоке Фераласа земля вспучилась и разверзлась: из-под холмов Древолапов выползли силитиды улья Зукк'аш. Гудящая Бездна — их гнездо, прорытое в склонах и наполненное неумолчным стрёкотом. Именно эти твари, а не Орда, гонят гноллов на север, доводя их до исступления. В Лагере Мохаче лишь начинают понимать, что за древняя угроза пробудилась под лесом.",
        ["Штормовое озеро"] = "Штормовое озеро лежит у самого Лагеря Мохаче, и таурены построили свои шатры на его берегу. Ручей, бегущий через деревню, впадает здесь в спокойную воду, а над гладью по вечерам стелется туман от джунглей. Несмотря на грозное имя, это одно из самых мирных мест Фераласа — здесь ловят рыбу, поят зверей и отдыхают после дороги.",
        ["Поселение Гордунни"] = "В горах к северу от Павильона Лорисс огры Гордунни разбили одно из своих главных становищ. Их присутствие отравило землю: буйная зелень Фераласа здесь пожухла и побурела, и на склонах остались лишь голые камни да ямы. В холмах две пещеры — малая у входа и большой огрский курган в глубине, где обитают заклинатели и укротители клана. Отсюда Гордунни выходят в набеги, и здесь Орда рассчитывает нанести им ощутимый удар.",
        ["Мок'Гордун"] = "Мок'Гордун — имя, которым огры зовут свои владения в холмах над Павильоном Лорисс. Здесь, среди вытоптанной травы и костров, клан Гордунни живёт по собственному закону, и чужаку лучше не показываться на глаза дозорным.",
        ["Долина Свирепого Утеса"] = "Долина Свирепого Утёса — цепь пещер в Высокогорных дебрях на западе Фераласа, недалеко от Забытого берега. Здесь обитают йети Свирепого Утёса — свирепые звери, чьи толстые шкуры высоко ценят кожевники Крепости Оперенной Луны. Говорят, огры Гордунни вырубили леса на прежних землях йети, и звери ушли на восток, в холмы гноллов. В глубине первого туннеля гномы потеряли одну из своих механических куриц серии OOX, и её сигнал бедствия до сих пор ловят в округе.",
        ["Высокогорье Блеклых Перьев"] = "Высокогорье Блёклых Перьев — вотчина диких гиппогрифов, что вьют гнёзда на скалистых уступах. Грифоноподобные птицы с оленьими рогами кружат над лесом, и подходить к их кладкам опасно. Гоблины из Прибамбасска, впрочем, готовы щедро заплатить за яйца из этих гнёзд для своих сомнительных опытов.",
        ["Озеро Тихого Ветра"] = "Озеро Тихого Ветра — небольшая заводь в чаще Фераласа, о которой почти не говорят на картах. Воздух здесь и вправду неподвижен: ни ветра, ни птичьих криков, лишь плеск воды под тяжёлыми ветвями.",
        ["Забытый берег"] = "Забытый берег тянется вдоль всего западного края Фераласа, там, где джунгли выходят к Сокрытому Морю. По песку бродят водяные элементали и морские великаны, а в прибрежных скалах гнездятся ветрокрылы. У воды стоит рыбацкая деревенька мурлоков, живущих в вечном страхе перед птицами и набегами. С пристани на берегу отходит лодка к острову Сардор и Крепости Оперенной Луны — для Альянса это главная дорога в лес.",
        ["Восточная колонна"] = "Восточная колонна — одна из двух исполинских скал, которые зовут Двумя Колоссами. Её вершина плоская, и на ней прячется небольшое, но глубокое озерцо. Дворф Греган видел, как по отвесной стене сюда вскарабкался огромный макрура, и с тех пор наверху не бывает тихо. Спуститься отсюда своими ногами невозможно — путник, оказавшийся на вершине, должен заранее подумать о дороге вниз.",
        ["Западная колонна"] = "Западная колонна — второй из Двух Колоссов, гигантская столовая гора, между которой и её сестрой проходит дорога из Пустошей в Фералас. У её подножия живёт ночная эльфийка, владеющая искусством переносить желающих на вершину соседней скалы — путешествие, как она честно предупреждает, в один конец. Тень колонны ложится на лес ещё до заката.",
        ["Сонные Ветви"] = "На островке посреди Нефритового озера растёт великое дерево Сонных Ветвей — одно из четырёх деревьев Азерота, у корней которых открыт портал в Изумрудный Сон. Три других стоят в Ясеневом лесу, Сумеречном лесу и Внутренних землях. Портал охраняют зелёные драконы и их драконьи отпрыски, не подпускающие чужих к священному месту. Говорят, что с недавних пор сквозь такие порталы порой вырываются драконы, поражённые порчей, и тогда лес вокруг замирает в тревоге.",
        ["Нефритовое озеро"] = "Нефритовое озеро — большое спокойное озеро на севере Фераласа, чья вода отливает зеленью. В самой его середине лежит островок с великим деревом Сонных Ветвей, и потому берега стерегут зелёные драконьи отпрыски, охраняющие путь в Изумрудный Сон. На северо-западном берегу встречаются заражённые дракончики — тревожный знак того, что даже здесь порча нашла лазейку.",
        ["Онейрос"] = "Онейрос — руины ночных эльфов к югу от Нефритового озера, заросшие лианами и мхом. Само их имя созвучно древнему слову о снах, и не случайно: между колонн здесь патрулируют зелёные драконьи отпрыски, стражи Дремлющей Изеры. Они не терпят чужаков, и путнику лучше обходить разрушенные арки стороной.",
        ["Руины Яростного Ветра"] = "Руины Яростного Ветра на севере Фераласа — остатки поселения Высокорожденных, таких же древних, как Забытый Город. Ныне их заняли гарпии, гнездящиеся на обломках колонн. В центре руин растёт огромное дерево, которое ревностно берегут зелёные драконы с Нефритового озера. У старого алтаря среди развалин, как говорят в Крепости Оперенной Луны, ещё горят волшебные огни, способные вернуть силу древнему посоху.",
        ["Пещера Бешеного оврага"] = "Пещера Бешеного оврага — глубокая нора в скалах западного побережья Фераласа. В ней живут самые злобные йети Фераласа. Странно, но в глубине пещеры находят книги и магические знаки, а дальние залы сложены в манере ночных эльфов — быть может, некогда здесь было эльфийское убежище, чьих хозяев давно никто не видел.",
        ["Крепость Оперенной Луны"] = "Крепость Оперенной Луны — твердыня ночных эльфов на острове Сардор у западного берега Фераласа. Здесь командует генерал Шандриса Оперенная Луна, предводительница Часовых, а вокруг лунного колодца стоят дома торговцев и гиппогрифьи насесты. Крепость — единственный оплот Альянса в этих джунглях: отсюда Часовые следят за нагами клана Гребня Ненависти, что расползлись по островам под началом лорда Шалзару. С материка сюда ходит лодка от пристани на Забытом берегу.",
        ["Руины Соларсаля"] = "Руины Соларсаля лежат к юго-западу от Крепости Оперенной Луны, на том же острове Сардор. Некогда здесь стояло поселение ночных эльфов, а теперь среди упавших колонн хозяйничают наги Гребня Ненависти. В Крепости с тревогой следят за руинами: наги что-то ищут в развалинах, и находки, попадающие оттуда в руки эльфов, ставят учёных в тупик.",
        ["Два Колосса"] = "Два Колосса — пара исполинских столовых гор на западе Фераласа, самая высокая точка этих земель. Между ними проходит дорога из Пустошей, и всякий, кто входит в джунгли с севера, первым делом видит их отвесные стены. Склоны кишат зверьём, а на вершине Восточной колонны прячется глубокое озерцо. Отважный дворф Греган уверяет, что придумал способ спуститься с вершины без вреда для здоровья.",
        ["Остров Сардор"] = "Остров Сардор лежит у западного побережья Фераласа, к северу от Острова Ужаса. На его северной оконечности стоит Крепость Оперенной Луны, а южнее — руины Соларсаля, где обосновались наги. Между ними по лесу бродят волки и водятся гиппогрифы. С материка на остров ходит лодка от пристани на Забытом берегу, и для многих путников Альянса это первая земля Фераласа, на которую они ступают.",
        ["Остров Ужаса"] = "Остров Ужаса — южный из двух больших островов у побережья Фераласа, отделённый от Сардора узким проливом. Его сердце — замкнутая долина, куда можно войти лишь с юго-востока: со всех прочих сторон её запирают неприступные скалы. В долине обитают химероки — древние могучие химеры под началом своего лорда, а на северной оконечности острова, в извилистой пещере, засели наги Гребня Ненависти. Повар Могиль из Прибамбасска, по слухам, знает толк в мясе здешних химер.",
        ["Высокогорные дебри"] = "Высокогорные дебри — огромный лес, покрывающий запад Фераласа от Забытого берега до реки Вердантис. Под пологом древних деревьев водятся медведи и волки, кружат гиппогрифы, бродят древни, а в пещерах на склонах живут йети. Здесь же, в юго-западной части дебрей, лежат руины Исильдиэна, занятые ограми Гордунни. Тропы в этой чаще коварны, и путнику стоит держаться дороги.",
        ["Низинные чащобы"] = "Низинные чащобы — восточная часть Фераласа, что спускается от Лагеря Мохаче к каньонам Тысячи Игл. Лес здесь ниже и светлее, чем на западе, а по холмам бродят гориллы, медведи и гноллы клана Древолапов. Дорога из Таланаара в глубь джунглей проходит именно здесь, и таурены Лагеря Мохаче зорко следят за всеми, кто по ней идёт.",
        ["Сокрытое Море"] = "Сокрытое Море омывает весь запад Калимдора — от Тельдрассила на севере до берегов Фераласа и дальше. Имя своё оно получило от тумана, которым ночные эльфы веками укрывали свой континент от чужих глаз. У Забытого берега в его волнах поднимаются острова Сардор и Ужаса, а в глубинах ходят акулы и морские великаны.",
        ["Павильон Лорисс"] = "Павильон Лорисс — просторное открытое строение в эльфийском стиле к северу от Лагеря Мохаче. Дриады, что живут вокруг, некогда были мирными, но порча извратила их, и теперь они бросаются на всякого. Под сводами павильона нашёл приют Высокорожденный, покинувший Забытый Город: он не смирился с безумием принца Тортелдрина и ушёл потайным ходом, что открывается у подножия павильона. По дороге бесёнок стащил у него книгу заклинаний.",
        ["Холмы Древолапов"] = "Холмы Древолапов — лесистые взгорья на юго-востоке Фераласа, родные земли гноллов клана Древолапов. В последнее время гноллы будто обезумели: их набеги на Лагерь Мохаче становятся всё отчаяннее, и Хадокен Быстрый Странник собирает воинов, чтобы отбросить их. Но по лагерям Древолапов ходят слухи, что гноллов гонит на север нечто, вылезшее из-под земли на юге. Недавно в холмах появились и горные великаны, спустившиеся с вершин.",
        ["Логово Древолапов"] = "Логово Древолапов — пещера в холмах на юго-востоке Фераласа, где укрываются вожаки гноллов клана Древолапов. Здесь сходятся их тропы, здесь они хранят добычу и отсюда ведут свою отчаянную войну на два фронта. Южнее логова лежат заросшие руины.",
        ["Река Вердантис"] = "Река Вердантис — небольшая быстрая река, что петляет по центру Фераласа к юго-востоку от Забытого Города. Её прозрачная вода бежит по камням меж мшистых берегов, и рыбаки шепчут, что нигде больше в Азероте не водится такой рыбы, как в этих струях.",
        ["Руины Исильдиэна"] = "Руины Исильдиэна — остатки большого города ночных эльфов на юго-западе Фераласа, в глубине Высокогорных дебрей. Город погиб десять тысяч лет назад, во время Раскола, и с тех пор джунгли поглотили его улицы. Круглое здание в конце лестницы, похожее на Храм Луны, когда-то, возможно, было святилищем Элуны. Ныне руины — вотчина огров Гордунни, устроивших здесь стойбище, а в пещере на восточном краю развалин они устроили себе логово.",
        ["Забытый Город"] = "Забытый Город — колоссальные руины в самом сердце Фераласа. Двенадцать тысяч лет назад тайный орден чародеев Высокорожденных построил здесь город Эльдре'Талас, чтобы хранить самые ценные секреты королевы Азшары. Раскол не сумел разрушить его: принц Тортелдрин и его приближённые, Шен'дралар, сплели заклятие, укрывшее город, а потом, лишившись Источника Вечности, заточили демона и стали тянуть из него силу. Когда пленник ослаб, принц обратил магию против собственных подданных, и от Шен'дралар осталась лишь горстка. Ныне восток руин держит сатир Алззин Перевёртень, север — огры клана Гордок, а на западе среди призраков всё ещё бродит сам принц.",
        ["Убежище Шалзару"] = "Убежище Шалзару — большая извилистая пещера на северной оконечности Острова Ужаса, к югу от Крепости Оперенной Луны. Здесь, в глубине, обитает лорд Шалзару, повелитель наг клана Гребня Ненависти, и здесь же он изучает найденную им реликвию. Пещера состоит из двух залов, соединённых подводным ходом, и её коридоры стерегут колдуньи и змеиные стражи наг. Генерал Шандриса считает эту нору главной угрозой для Часовых на островах.",
        ["Ристалище"] = "Ристалище — огромная яма под открытым небом посреди разрушенных площадей Забытого Города. Говорят, огры устраивают здесь свои игрища, а между собой сходятся и искатели приключений: на арене нет ни своих, ни чужих, и всякий, кто спрыгнет вниз, становится добычей. Единственный выход — туннель на западной стороне, где дремлют своры гордокских гиен. Порой на арену выпускают редкого чудовищного зверя, и тогда бой идёт не на жизнь, а на смерть.",
        ["Долина Костей"] = "Долина Костей — ущелье на южном краю Пустошей, у самой дороги в Фералас. Её дно усеяно костями исполинов, а у скал лежат два колоссальных скелета, чьё происхождение никому не известно. Кентавры обходят это место стороной, считая его проклятым: здесь бродят скелеты и некроманты, а по ночам — призраки павших.",
        ["Деревня Гелкис"] = "Деревня Гелкис стоит на юго-западе Пустошей, у дороги, ведущей в Фералас. Это главное селение кентавров клана Гелкис: их хижины кольцом окружают глубокий овраг, через который перекинуты мосты, а в пещере на южном склоне восседает сам хан. Гелкис враждуют с кланом Маграм, и всякий путник, идущий по дороге к югу, рискует попасть под их копыта.",
        ["Поле Маннорок"] = "Поле Маннорок — выжженная земля среди руин ночных эльфов на юге Пустошей, названная в честь владыки преисподней Маннорота. Культисты Пылающего Клинка открыли здесь порталы, и теперь по полю бродят инферналы, гончие Скверны и стражи ужаса. Воздух густ от демонической магии, и путник чувствует, как на плечи ложится тяжесть, едва ступив на эту землю.",
    },
    ["Штормград"] = {
        _zone = "Штормград — столица людей и сердце Альянса, белокаменный город на юге Восточных королевств. В Первую войну Орда сровняла его с землёй, а после Второй войны Гильдия каменщиков заново возвела его из белого камня, вернув прежнее величие. Но знать так и не заплатила мастерам, и обиженные каменщики ушли в Западный край, где со временем превратились в Братство Справедливости. Король Вариан Ринн пропал при загадочных обстоятельствах, и ради порядка корону возложили на его юного сына Андуина. Регентом при мальчике-короле стоит верховный лорд Болвар Фордрагон, а при дворе большое влияние имеет леди Престор, чьё слово в совете весит не меньше королевского. Над крышами возвышается Собор Света — духовное сердце королевства, а в Торговом квартале не смолкает гул сделок. В Квартале Дворфов гудят кузни и уходит под землю Подземный поезд, связавший Штормград со Стальгорном. Старый город хранит свои тайны, Парк дышит зеленью, а в крепости Штормграда решаются судьбы королевства. Этот город был разрушен и восстал из руин, и в этом — его сила.",
        ["Аллея Героев"] = "Аллея Героев лежит перед вратами Штормграда, и каждый, кто входит в город по суше, проходит через неё. Каменный мост перекинут через узкий ров, а по обе стороны дороги высятся статуи пяти героев Альянса — тех, кто ушёл за Тёмный портал и разрушил его, спасая Азерот. Стражи у моста несут службу под их каменными взглядами. Здесь же, верхом на коне, встречает гостей генерал Маркус Джонатан, командующий обороной города. Аллея задумана и как приветствие, и как предостережение всякому, кто пришёл с недобрыми намерениями.",
        ["Порт Штормграда"] = "Порт Штормграда раскинулся у западных стен столицы, там, где белый камень спускается к водам Великого моря. Сюда приходят корабли с дальних берегов, и отсюда открывается путь ко всем побережьям Азерота. У причалов стоят на страже солдаты, а на верхних ярусах — орудия, охраняющие вход в город с моря. Крики чаек и скрип снастей смешиваются здесь с шумом столицы за стеной.",
    },
    ["Элвиннский лес"] = {
        _zone = "Элвиннский лес – сердце королевства Штормград, край могучих дубов, тихих озёр и ухоженных ферм. На севере его замыкают горы у подножия Пылающих степей, на востоке лежит Красногорье, на юге за рекой начинается Сумеречный лес, а на западе – Западный Край. В Первую войну орки сожгли этот лес почти дотла, но после Второй войны деревья поднялись вновь, а столицу отстроили руками гильдии каменщиков. Когда знать отказалась платить мастерам, из обиды родилось Братство Справедливости, и теперь его бандиты в красных повязках хозяйничают на фермах и в рудниках. Армия далеко от дома, и порядок держат лишь маршалы Макбрайд в Североземье и Дугхан в Златоземье. Кобольды заняли шахты, мурлоки расселились по озёрам, из Сумеречного леса приходят волки, а на западной границе рыщут гноллы стаи Речной Лапы во главе с грозным Дробителем. И всё же Элвинн остаётся самым мирным уголком людских земель – здесь начинается путь каждого, кто присягнул короне.",
        ["Долина Североземья"] = "Долина Североземья укрыта со всех сторон неприступными горами, и попасть в неё можно лишь через южный проход, защищённый каменной стеной и караулом. Здесь, под сенью аббатства, начинают свой путь новобранцы короны, а маршал Макбрайд отвечает за оборону долины. Спокойствие обманчиво: в леса пришли волки из Сумеречного леса, кобольды заняли рудник на западе, а на виноградниках у самой стены обосновались бандиты Братства Справедливости. Река, что течёт через долину, покидает Североземье и впадает в Хрустальное озеро.",
        ["Озеро Хрустальное"] = "Хрустальное озеро лежит к востоку от Златоземья, и его чистые воды издавна кормили рыбаков и фермеров округи. Сюда несёт свои воды река из Североземья. Ныне на берегах расселились мурлоки, и неопытному путнику здесь может быть опасно. Впрочем, эти существа иногда приносят из океана редкие водоросли, которые ценит аптекарь Вильям Пест из Златоземья.",
        ["Река Североземья"] = "Река Североземья рождается в горах к востоку от Штормграда, пробегает через всю долину мимо аббатства и виноградников и, миновав стену, впадает в Хрустальное озеро. Её берега поросли высокой травой, где бродят волки и кабаны. Для послушников аббатства это первая вода, у которой они учатся держать оружие.",
        ["Аббатство Североземья"] = "Аббатство Североземья – обитель ордена клириков, что столетия назад пришли с севера нести учение Света в молодое королевство. В Первую войну орки разрушили аббатство, и лишь после Второй войны его отстроили заново, а братство Североземья возродилось. Сегодня аббатство служит местом сбора и обучения всех, кто готов защищать королевство: здесь наставники всех ремёсел, библиотека с древними трактатами и гарнизон маршала Макбрайда. Заместитель судьи Виллем следит за порядком у ворот, а в лесу вокруг стало неспокойно от волков, кобольдов и бандитов.",
        ["Рудник Горного Эха"] = "Рудник Горного Эха уходит в скалы на северо-западе долины Североземья. Некогда здесь добывали руду для нужд королевства, но теперь штольни заняли кобольды со свечами на головах, и они упрямо не желают уходить. Маршал Макбрайд регулярно посылает новобранцев проредить их ряды. Кобольды пугливы и нападают лишь тогда, когда их трогают, а в глубине рудника извилистый ход выводит в просторную пещеру.",
        ["Воровской лагерь"] = "Воровской лагерь – одно из тех мест, что значатся лишь на старых картах королевства. Лагеря Братства Справедливости и вправду разбросаны по всему Элвиннскому лесу: бандиты в красных повязках жмутся к опушкам и брошенным фермам, деля добычу у костров. Стража Штормграда знает о них, но людей, чтобы очистить лес, не хватает.",
        ["Яшмовая шахта"] = "Яшмовая шахта лежит у подножия гор к северо-востоку от башни Азоры. Вместе с рудником Подземных Глубин она была одной из главных шахт Элвинна и снабжала Штормград рудой в годы войн. Теперь её заполонили кобольды, а армия, занятая на дальних границах, не может выделить людей, чтобы выгнать эту нечисть. В самых глубоких штольнях поселилась колония пауков, для которых кобольды стали лёгкой добычей, так что вглубь шахты лучше не соваться без нужды.",
        ["Часовые Вечности"] = "Часовые Вечности – каменное кольцо в сердце острова посреди Озера Каменных Столбов. Здесь стоит памятный камень в честь павших, когда орки в Первую войну разорили Златоземье и окрестные земли. Когда-то сюда приходили паломники, но ныне остров захватили чародеи, связанные с Братством Справедливости, и путнику здесь грозит опасность. Сами бандиты называют это место забытой всеми обителью веры.",
        ["Рудник Подземных Глубин"] = "Рудник Подземных Глубин – заброшенная золотая шахта к югу от Златоземья, между фермами Стоунфилдов и Маклуров. Некогда её отбили у орков после Первой войны, а теперь штольни заняло целое племя кобольдов. Они носят с собой золотую пыль и большие свечи, за которые в Златоземье дают неплохую цену. По слухам, где-то в глубине прячется здоровенный кобольд с золотыми зубами.",
        ["Виноградники Североземья"] = "Виноградники Североземья раскинулись к востоку от аббатства и когда-то были гордостью всего Штормграда. Милли Осворт по-прежнему собирает здесь урожай, но лозы захватили бандиты Братства Справедливости под началом Гаррика Тихокрада. Именно здесь новобранцы короны впервые сталкиваются с людьми в красных повязках. Заместитель судьи Виллем в аббатстве назначил награду за головы разбойников.",
        ["Лесная опушка"] = "Лесная опушка – клин леса к юго-западу от Штормграда, зажатый между садом у Зеркального озера и реками, за которыми начинается Западный Край. Здесь, к югу от гарнизона, обосновались гноллы стаи Речной Лапы под началом Дробителя, могучего гнолла, которого стража так и не смогла изловить. Среди деревьев бродят кабаны, а по берегам рек попадаются медные жилы и лечебные травы. На северном краю опушки стоит гарнизон у Западного ручья.",
        ["Ревущий водопад"] = "Ревущий водопад скрыт в узком ущелье среди гор на северо-западе Элвинна. Крутая тропа поднимается к нему справа от водопада Зеркального озера. Наверху стоит одинокая хижина с наковальней и костром, у маленького причала качается лодка, а вокруг обосновалась горстка бандитов. Ущелье замыкают водопады с обеих сторон, и река отсюда уходит к границе Западного Края.",
        ["Тыквенное поле Бреквеллов"] = "Тыквенное поле Бреквеллов лежит на юго-востоке Элвиннского леса. Когда-то это была спокойная ферма, но семья Бреквеллов пропала, а в доме и на грядках поселились бандиты Братства Справедливости. По донесениям стражи, здесь скрывается их главарь по прозвищу Вымогатель, который ждёт партию золота из рудников Элвинна. Между тыквенных гряд по-прежнему бродит призовая свинья Бреквеллов по кличке Принцесса, разжиревшая на овощах с соседней фермы Стоунфилдов.",
        ["Ферма Стоунфилдов"] = "Ферма Стоунфилдов стоит на юге Элвинна, у самого рудника Подземных Глубин. Стоунфилды давно враждуют с соседями Маклурами, и семьи не упускают случая уколоть друг друга. Тем не менее, Томми Джо Стоунфилд и Мэйбелл Маклур полюбили друг друга, и есть надежда, что эта любовь помирит два дома. Тётушка Бернис славится пирогами со свининой, а кабанов вокруг ферм водится видимо-невидимо.",
        ["Виноградники Маклура"] = "Виноградники Маклура тянутся по южному Элвинну, неподалёку от фермы Стоунфилдов, с которыми Маклуры ведут давнюю вражду. Между лоз то и дело шастает мальчишка Билли Маклур, а среди виноградников пасутся целые стада кабанов. Юная Мэйбелл Маклур мечтает сбежать отсюда к своему возлюбленному из семьи соседей.",
        ["Горы Штормграда"] = "Горы Штормграда – скалистая гряда, что замыкает Элвиннский лес с севера и тянется к самой столице, отделяя лес от Пылающих степей и Чёрной горы. Здесь не селятся люди: лишь снега, крутые склоны да орлы над обрывами. Из-за этих гор в Элвинн не пробраться иначе, как через перевалы и дороги, охраняемые стражей.",
        ["Озеро Каменных Столбов"] = "Озеро Каменных Столбов лежит на северо-востоке Элвинна, и большой остров посредине придаёт ему форму кольца. Своё имя озеро получило от каменного памятника на острове, воздвигнутого в честь павших в Первой войне с орками. Когда-то сюда ходили паломники, но теперь остров заняли чародеи-отступники, на южном берегу мурлоки выстроили хижины, а на северном раскинули лагерь гноллы. По берегам озера богаче всего в Элвинне залежи меди.",
        ["Златоземье"] = "Златоземье – главный посёлок Элвиннского леса, стоящий на перекрёстке дорог: к Штормграду, к аббатству Североземья, к Западному Краю и к Красногорью. Деревня возникла ещё на заре королевства, в Первую войну одной из последних пала под натиском Орды, а после Второй войны была отстроена вместе со столицей. Порядок здесь держит маршал Дугхан, чей стол завален донесениями о кобольдах, гноллах, мурлоках и бандитах. Путники со всего королевства отдыхают в таверне «Гордость льва», одном из самых славных питейных домов Азерота.",
        ["Лесопилка Восточной долины"] = "Лесопилка Восточной долины – сердце лесного промысла Элвинна, ряд пилорам и жилых домов на востоке леса, у дороги в Красногорье. Заказы на древесину идут сплошным потоком, и начальница лесорубов Раэлен вечно не укладывается в сроки. Работу осложняют волки и медведи: чем дальше от Златоземья, тем злее звери. В усадьбе неподалёку доживает свой век маршал Хаггард, некогда возглавлявший стражу Штормграда, а кожевница Сара Тимберлейн шьёт для лесорубов броню.",
        ["Сад у Зеркального озера"] = "Сад у Зеркального озера раскинулся на его южном берегу, в западной части Элвинна. Аккуратные яблони и домик садовника выглядят мирно, но и сюда добрались бандиты Братства Справедливости: они заняли сад и хижину, и хозяев здесь давно не видно. Рядом шумит водопад, а тропа за ним уводит в горы к Ревущему водопаду.",
        ["Башня Азоры"] = "Башня Азоры – небольшая башня магов к востоку от Златоземья, на дороге к лесопилке. Ею правит верховный маг Теокрит, а прислуживают ему гномы. Маги Азоры давно враждуют с чернокнижником Моргантом из башни Илгалара в Красногорье, и обе башни без устали следят друг за другом с помощью магии. По словам слуг, всё живое, что забредает слишком близко к башне, странно меняется под действием её чар.",
        ["Зеркальное озеро"] = "Зеркальное озеро – небольшое озеро в западной части Элвинна, к юго-западу от врат Штормграда, с красивым водопадом на северном берегу. Оно могло бы стать славным местом для рыбалки и купания, если бы не бандиты Братства Справедливости, что заняли сад на его берегу. Маги Штормграда опасаются, что после недавних магических потрясений течение волшебных потоков изменилось, и присматриваются к здешней воде.",
        ["Гарнизон у Западного ручья"] = "Гарнизон у Западного ручья – казармы стражи Штормграда на западной окраине Элвинна, у границы с Западным Краем. Пока армия далеко, здесь едва хватает людей, чтобы охранять дороги от гноллов и грабителей, которых становится всё больше. Заместитель судьи Рейнер просил у Златоземья подкрепление, и вместо солдат маршал Дугхан шлёт сюда добровольцев. На стенах гарнизона висят объявления о награде за голову Дробителя, вожака гноллов стаи Речной Лапы, что обитают в лесу к югу от башни.",
        ["Лагерь Джерода"] = "Лагерь Джерода – лодочная пристань на речном берегу к югу от Златоземья. С виду это простые доки, но по донесениям агентов Штормграда пристань захватило Братство Справедливости и превратило в перевалочный пункт: отсюда переправляют крупные партии контрабанды из Красногорья в Западный Край. Всем здесь заправляет портовый начальник, а расписание поставок он держит при себе.",
        ["Дозорная башня"] = "Дозорная башня – одна из сторожевых башен стражи Штормграда на востоке Элвинна. Такие башни хорошо защищены и стоят на страже людских земель. Эта следит за гноллами и орками, что могут прийти из Красногорья, за нежитью из Сумеречного леса и за бандитами из окрестных лагерей.",
        ["Долина Североземья – Camelot"] = "Долина Североземья со всех сторон укрыта горами, и единственный путь сюда ведёт через южный проход за каменной стеной. Под сенью аббатства начинают свой путь новобранцы короны, а за оборону долины отвечает маршал Макбрайд. В лесах появились волки, бежавшие из Сумеречного леса, рудник на западе заняли кобольды, а на виноградниках хозяйничают бандиты Братства Справедливости. Река, бегущая через долину, уходит за стену и впадает в Хрустальное озеро.",
    },
    ["Ясеневый лес"] = {
        _zone = "Ясеневый лес — древняя чаща на севере Калимдора, между Тёмными берегами и Степями, от Сокрытого Моря до реки Строптивой. Тысячи лет эти леса были владениями ночных эльфов, и они до сих пор держат здесь Астранаар и Приют Серебряного Ветра. Но после Третьей войны в лес пришли орки клана Песни Войны: они основали заставу Расщепленного Дерева и валят вековые деревья на востоке, а часовые Среброкрылых поклялись изгнать их из Ущелья Песни Войны. Порча из Осквернённого леса отравила озёра и свела с ума фурболгов Колючего Меха и Гиблой Чащи. В руинах Ксавиана и Сатирнаара укрылись сатиры, на Зорамском взморье хозяйничают наги, а над Каньоном Гибели Демона всё ещё чувствуется дыхание Пылающего Легиона. Дожди здесь почти не прекращаются, но густые кроны не пропускают их вниз.",
        ["Убежище Батрана"] = "Убежище Батрана лежит на самом севере Ясеневого леса, у границы с Тёмными берегами. От древнего поселения ночных эльфов здесь остались лишь поваленные колонны и куски мрамора в траве. Теперь среди руин хозяйничают Отрекшиеся: травники и их громилы разбили здесь лабораторию и обирают местные травы, а земля под их ногами буреет, и цветы вянут. Только тут растёт Батранов волос — редкая травка, которой, по преданию, лечили болезни души, и лекари до сих пор посылают за ней смельчаков.",
        ["Руины Ордил'Арана"] = "К северу от заставы Мейстры лежат руины Ордил'Арана — всё, что осталось от древнего города ночных эльфов. Среди разбитых камней обосновались сектанты клана Тёмной Нити, служители высокорожденного Атрикуса Нарассина из башни Алталакса на Тёмных берегах, и они нападают на всякого, кто подойдёт близко. Здесь же растёт Сердцедрево: говорят, оно поднялось на том месте, где во время Войны Древних двое влюблённых пали в битве, сделав последний вздох вместе.",
        ["Застава Мейстры"] = "Застава Мейстры — маленький лагерь ночных эльфов на западной дороге Ясеневого леса, между руинами Ордил'Арана и Астранааром: башня, один большой дом и горстка часовых. Здесь живут единственные в лесу люди — паладин Делгрен Очиститель и его спутник, пришедшие помочь эльфам против демонов и нежити и ведущие своё расследование о клане Тёмной Нити. Лекарь Орендил Широколист готовит тут снадобья для больных Астранаара, а Лиладрис Лунная Река встречает путников с Тёмных берегов.",
        ["Зорамское взморье"] = "Зорамское взморье — полоса пляжей на северо-западе Ясеневого леса, у самого Сокрытого Моря. Некогда здесь стоял эльфийский город Зорам, но Великий Раскол утопил его в волнах, и на много веков он был утрачен и почти забыт. Теперь к затопленным руинам вернулись наги клана Зловещего Хвоста, и никто не знает, зачем; их предводительница Руузель обитает на острове у северного края взморья. На песке лежат разбитые корабли и выброшенные морем твари, а под водой скрывается вход в Непроглядную Пучину.",
        ["Астранаар"] = "Астранаар — главный город ночных эльфов в Ясеневом лесу и самое крупное поселение края. Он стоит на острове посреди озера, прямо на большой дороге из Аубердина, и с берегом его соединяют лишь два моста. Городом командует часовая Раэна Волкопас; она следит за фурболгами Колючего Меха, что расплодились к северу, и ищет способ ослабить порчу, расползающуюся по лесу. Здесь же живёт Пельтур, чья дочь Релара тяжело больна. Орда нередко совершает набеги на город, так что часовые на мостах всегда настороже.",
        ["Святилище Эссины"] = "Святилище Эссины прячется в лесной лощине к западу от Астранаара и к югу от заставы Мейстры. Это древнее место ночных эльфов, посвящённое духу дикой природы Эссине: тихая поляна с прозрачной водой под сенью старых деревьев. Сюда не заходят ни сатиры, ни орки, и это одно из немногих мест в лесу, где ещё можно перевести дух, не опасаясь нападения.",
        ["Святилище Огненной Расщелины"] = "Святилище Огненной Расщелины лежит на юго-западе Ясеневого леса, к югу от святилища Эссины. Когда-то это было святое место ночных эльфов, но теперь его зовут местом великого зла: сюда пришли демоны, и земля вокруг выжжена и опалена. В святилище поселился Илкруд Магтрулл — могучий орочий чернокнижник, служащий клану Тёмной Нити и его хозяину Атрикусу Нарассину. Паладин Делгрен Очиститель с заставы Мейстры давно следит за ним и ждёт случая с ним разобраться.",
        ["Руины Звездной Пыли"] = "Руины Звёздной Пыли лежат на юге леса, у гряды, отделяющей Ясеневый лес от Когтистых гор. Древнее святилище ночных эльфов стоит на острове посреди озера; когда-то это было священное место, и в его центре до сих пор бьёт маленький фонтан. Но порча добралась и сюда: вода стала мутной, желтовато-зелёной, и по руинам бродят болотные твари. Лишь кусты звёздной пыли на берегах не тронуты порчей, и лекари ценят собранную с них пыль, способную унять лихорадку.",
        ["Воющая долина"] = "Воющая долина — глухая лощина на севере Ясеневого леса, у самой границы с Осквернённым лесом. В её глубине стоит древнее святилище с надписью, восхваляющей Элуну, и ночные эльфы чтут это место как священное. Но теперь в долине поселились воргены, и по ночам отсюда доносится их вой, а древние, что охраняли святилище, иссохли и обезумели. Говорят, здесь когда-то была спрятана Коса Элуны, и жрица, отыскавшая её, бесследно исчезла.",
        ["Приют Серебряного Ветра"] = "Приют Серебряного Ветра — поселение ночных эльфов на юге Ясеневого леса, к северу от озера Мистраль. Это вторая по величине застава Альянса в лесу после Астранаара: здесь есть уютная таверна, наставники охотников, травников и алхимиков, торговцы и часовые. Отсюда часовые следят за дорогой на юг, в Степи, и за озером, элементали которого с недавних пор нападают на всех подряд. Название приюта не обманывает: путников здесь встречают радушно.",
        ["Озеро Мистраль"] = "Озеро Мистраль — самое большое озеро Ясеневого леса, лежащее на юге, между Приютом Серебряного Ветра и Туннелем Когтя. Его воды кишат элементалями воды: прежде они были верны ночным эльфам, но Сарилус Грязнорожденный, маг из нежити с Вершины Багрового Тумана в Степях, наслал на них порчу, и теперь они бросаются на всех, кто подойдёт к берегу. К юго-востоку от озера живёт фурболг Кролг — один из немногих, кого не тронула порча Мха Скверны.",
        ["Зеркало Небес"] = "Озеро Зеркало Небес лежит на юго-востоке от Астранаара, к югу от Аванпоста Среброкрылых. Это небольшое тихое озеро с островком посередине, и раньше ночные эльфы собирали на его берегах лунный камень. Но потом сюда пришли чащобники — ожившие древесные твари, и их предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и укрыл их на острове.",
        ["Озеро Ирис"] = "Озеро Ирис лежит к востоку от Астранаара, у дороги, ведущей на восток к лунному колодцу. Когда-то это было чистое лесное озеро, но порча из Осквернённого леса дошла и до него: вода стала мутной, желтовато-зелёной, а по берегам бродят болотные твари, готовые броситься на любого, кто подойдёт к воде. На острове посреди озера лежит Слеза Элуны — камень, который, как говорят лекари, снимает порчу, и ради него сюда всё ещё приходят смельчаки.",
        ["Лунный колодец"] = "Лунные колодцы — святыни ночных эльфов, наполненные водой, что хранит благословение Элуны. В Ясеневом лесу их несколько: один стоит к востоку от озера Ирис, у дороги на Приют в Ночных Лесах, другой — на западном берегу реки Фалфаррен, к югу от главной дороги. У колодца близ озера Ирис живёт дриада Шаэлдрин; она хранит память о древнях этих краёв и помогает тем, кто ищет способ снять порчу с леса. Даже шаманы других народов приходят сюда за фиалом воды из колодца.",
        ["Приют в Ночных Лесах"] = "Приют в Ночных Лесах стоит в самом сердце Ясеневого леса, у великого древа, к востоку от лунного колодца. Это застава защитников природы: здесь несут стражу хранители Круга Кенария, дриады и мерцающие дракончики, а с холма они следят за дорогой на север, в Осквернённый лес. На вершине древа укрылся хранитель рощи, один из старших сыновей лесного бога Кенария: Совет Теней ищет его голову, и его стерегут пуще всего.",
        ["Тенистый закоулок"] = "Тенистый закоулок — небольшая долина к югу от Приюта в Ночных Лесах и к востоку от деревни Зелёной Лапы. Здесь нет ни руин, ни поселений: только пещера в склоне, в которой живёт медвежье семейство, да густой подлесок. Место тихое, но медведи не любят чужаков.",
        ["Ночная поляна"] = "Ночная поляна лежит на востоке леса, на узком мысе между Приютом в Ночных Лесах и заставой Расщепленного Дерева, и подойти к ней трудно: с трёх сторон её защищают отвесные скалы. Это самое маленькое из трёх сатирских логовищ Ясеневого леса: лишь несколько разбитых колонн среди развалин служат кровом сатирам. Они хранят один из камней душ клана Тёмной Нити, с которым состоят в союзе, и жгут в своих ритуалах масло, украденное с лесозаготовок Песни Войны.",
        ["Ксавиан"] = "Ксавиан лежит на северо-востоке Ясеневого леса, у водопадов, где река Фалфаррен спускается с гор в озеро. Сатиры поселились здесь в руинах древнего храма ночных эльфов, и из трёх сатирских логовищ леса Ксавиан считается главным: здесь живут их вожди. Название хранит память о Ксавиусе — высокорожденном, которого Саргерас обратил в первого сатира во время Войны Древних. Дриады, приходящие сюда, редко возвращаются невредимыми.",
        ["Сатирнаар"] = "Сатирнаар лежит на северо-востоке леса, у дороги от заставы Расщепленного Дерева в Азшару. Из трёх сатирских логовищ Ясеневого леса это самое обжитое: среди разрушенных эльфийских построек сатиры разбили шатры, а у жаровен с тёмным пламенем призывают бесов и демонов Бездны. Они в союзе с кланом Тёмной Нити и стерегут один из его камней душ. Поскольку Сатирнаар стоит у самой дороги, он чаще других становится целью и орков, и эльфов.",
        ["Застава Расщепленного Дерева"] = "Застава Расщепленного Дерева — главный оплот Орды в Ясеневом лесу, стоящий на восточной дороге. Её основал Гром Адский Крик со своим кланом Песни Войны в дни Третьей войны, когда орки впервые пришли в эти леса. За частоколом живут в основном орки и таурены — разведчики и стражи; есть таверна и ветрокрылы для полётов. Отсюда Сенани Громосерд отправляет молодых охотников на Большую охоту за зверями леса. Ночные эльфы помнят дела вождя Песни Войны, и застава нередко подвергается их ударам.",
        ["Обитель Дор'Данил"] = "Обитель Дор'Данил — курган друидов к югу от заставы Расщепленного Дерева. Издавна здесь спали ночные эльфы-друиды, погружённые в Изумрудный Сон, но приход Орды оставил курган в глубине вражеских земель. Оркам не было дела до спящих эльфов, зато Отрекшиеся заинтересовались ими: они принялись отделять спящих от их духов, и друиды сошли с ума. Теперь по тёмным коридорам крадутся убийцы Отрекшихся, а среди них бродят обезумевшие духи друидов Дор'Данила, и трое из них особенно сильны.",
        ["Река Фалфаррен"] = "Река Фалфаррен пересекает Ясеневый лес с северо-востока на юго-запад и служит рубежом между землями ночных эльфов у Астранаара и владениями орков у заставы Расщепленного Дерева. Она рождается на склонах Хиджала, водопадами спускается в озеро у Ксавиана и уходит под горы у северных Степей. Река невелика, но дожди быстро наполняют её, а на отмелях у Холма Демонического Огня прячутся болотные твари. Главный мост через Фалфаррен на большой дороге — самое оживлённое место в лесу.",
        ["Холм Демонического Огня"] = "Холм Демонического Огня возвышается к юго-востоку от заставы Расщепленного Дерева. В Третью войну сюда с неба обрушились инферналы Пылающего Легиона, и с тех пор земля здесь выжжена, а по склонам бродят демоны всех мастей. Орда укрепила оба моста, ведущие к холму, чтобы демоны не добрались до её лагерей. Отсюда скверна тянется дальше на юг, к Каньону Гибели Демона.",
        ["Каньон Гибели Демона"] = "Каньон Гибели Демона лежит на юго-востоке Ясеневого леса, к югу от Холма Демонического Огня. Здесь Гром Адский Крик и Тралл вышли против владыки преисподней Маннорота — того, чья кровь наложила проклятие на орков. Демон сразил Тралла, но Гром успел вонзить топор ему в грудь, и взрыв огня и света, унёсший жизнь Маннорота, забрал и его. Орки назвали это место в память о жертве вождя и приходят сюда поклониться его памятнику. Но скверна не ушла: по каньону до сих пор рыщут младшие демоны.",
        ["Гряда Гибели Демона"] = "Гряда Гибели Демона поднимается к западу над одноимённым каньоном. По её склонам бродят младшие демоны, а в толще скал зияет вход в заброшенный курган друидов, который они сделали своим логовом. В самой глубине кургана обитает повелитель ужаса, что правит демонами Ясеневого леса, и мало кто из вошедших туда возвращался.",
        ["Лесозаготовки Песни Войны"] = "Лесозаготовки Песни Войны раскинулись на востоке леса, к югу от Лесной Песни и к северу от Холма Демонического Огня. Здесь орки клана Песни Войны валят вековые деревья для строек Орды, и от чащи остаются лишь пни да штабеля брёвен. Лесорубов охраняют стражи и шаманы, а на восточном краю лагеря стоит крепость Каргатия. Припасы вечно в недостаче: верёвки и масло крадут фурболги и сатиры. Часовые Среброкрылых поклялись остановить рубку, и стычки здесь не утихают.",
        ["Тенистая Крона"] = "Тенистая Крона стоит в самом северо-восточном углу Ясеневого леса, за Лесной Песнью. Здесь растёт одно из Великих Древ, в котором открыт портал в Изумрудный Сон, и его охраняют зелёные драконы. Зелёные дракониды ходят дозором по трое, и в их числе оракулы, стражи ветвей и хранители деревьев. Говорят, порой из портала выходят драконы, поражённые Кошмаром, и тогда лучше держаться от Тенистой Кроны подальше.",
        ["Озеро Фалатим"] = "Озеро Фалатим лежит на западе Ясеневого леса, к юго-востоку от Зорамского взморья и к юго-западу от заставы Мейстры. Когда-то ночные эльфы приходили сюда купаться и ловить рыбу, но теперь озеро кишит свирепыми мурлоками. Здесь в последний раз видели учёного Терониса, друга Раэны Волкопас: он отправился искать предмет, способный ослабить порчу леса, и до сих пор не вернулся.",
        ["Река Строптивая"] = "Река Строптивая — самая большая река Калимдора и восточная граница Ясеневого леса. Она рождается в озере на горе Хиджал, водопадами обрушивается вниз и широким быстрым потоком отделяет лес от разорённых земель Азшары, а дальше на юг — Степи от Дуротара. Близ Ясеневого леса реку пересекает лишь один мост, ведущий в Азшару; ниже по течению, у Оргриммара, стоят мосты Орды. Оттуда к орочьим лагерям на востоке леса приходят подкрепления.",
        ["Туннель Когтя"] = "Туннель Когтя — извилистый проход в горах на юге Ясеневого леса, к западу от озера Мистраль. Он ведёт из лесной чащи к Утёсу Ветрорезов в Когтистых горах, где среди штормовых каньонов гнездятся гарпии. В туннеле много тупиков и странных дыр в стенах, но не живёт никто — ни друзей, ни врагов здесь не встретишь, и это единственный путь для тех, кто идёт из леса к Пику Каменного Когтя.",
        ["Деревня Колючего Меха"] = "Деревня Колючего Меха стоит прямо к северу от Астранаара, у дороги, что огибает город. Здесь живёт племя фурболгов Колючего Меха, поражённое порчей: они нападают на всякого, кто подойдёт слишком близко. Разведчики Раэны Волкопас доносят, что за последние месяцы фурболги чрезвычайно умножились числом, и Астранаар боится их набега. Орде деревня тоже мешает, преграждая дорогу к заставе Расщепленного Дерева. В глубине пещер фурболги держат в клетке таурена Руула, которого приняли за медведя.",
        ["Сокрытое Море"] = "Сокрытое Море омывает западный берег Ясеневого леса у Зорамского взморья. Это огромное море к северу и западу от Калимдора, названное так за туман, которым ночные эльфы веками укрывали свой континент от чужаков. После Великого Раскола под его волнами скрылись город Зорам и храм, ставший Непроглядной Пучиной. В его водах живут гигантские черепахи и, как говорят, кракены.",
        ["Лагерь Кровавого Клыка"] = "Лагерь Кровавого Клыка стоит к западу от реки Фалфаррен, к югу от главной дороги, близ южного лунного колодца. Здесь живёт племя фурболгов под началом Рэна Кровавого Клыка — жадного и властолюбивого вождя, которого порча лишь сделала сильнее. Его воины нападают на путников на дороге, что сворачивает на восток перед рекой, и часовые Астранаара просят отплатить им той же монетой. Даже фурболг Кролг, не тронутый порчей, считает Рэна злом, которое надо остановить.",
        ["Лесная Песнь"] = "Лесная Песнь — древние руины ночных эльфов на северо-востоке леса, к северу от лесозаготовок Песни Войны и к востоку от Сатирнаара. Некогда это было поселение, а теперь среди разбитых колонн живёт лишь один друид, последний из народа калдорей в этих местах. Отсюда он следит за Отрекшимися, что орудуют в округе, и за курганом Дор'Данил, и радуется каждому голосу, что снова звучит среди руин.",
        ["Деревня Зеленой Лапы"] = "Деревня Зелёной Лапы лежит в центре Ясеневого леса, к югу от Приюта в Ночных Лесах и к северо-востоку от Приюта Серебряного Ветра. Здесь живёт племя фурболгов Гиблой Чащи под началом вождя и шаманов, и порча сделала их врагами всему живому. Они воруют припасы у орков с лесозаготовок и нападают на всех подряд, так что и Орда, и Альянс нередко приходят сюда с оружием. Орочьи командиры из Зорам'гара считают, что лишь показательный удар по деревне остановит угрозу.",
        ["Аванпост Среброкрылых"] = "Аванпост Среброкрылых стоит на юге Ясеневого леса, на восточном берегу реки Фалфаррен, к юго-западу от заставы Расщепленного Дерева. Это восточный оплот Альянса, и, поскольку он стоит на орочьем берегу реки, часовые здесь отбивают постоянные атаки: воины клана Песни Войны поклялись избавить лес от Среброкрылых раз и навсегда. Гарнизоном командует Дариэль Лунное Пламя, а вестницы аванпоста разведывают лес до самой заставы орков. Орк Торек уже собирает бойцов для налёта.",
        ["Леса Ночной Песни"] = "Леса Ночной Песни — восточная часть Ясеневого леса, от Приюта в Ночных Лесах и дороги в Осквернённый лес до самой Азшары. Именно здесь идут самые жаркие бои между Ордой и Альянсом: река Фалфаррен делит эти леса на западную половину, где стоят эльфы, и восточную, где хозяйничает клан Песни Войны. Дальше на восток за землю спорят сатиры Сатирнаара и Ксавиана, лесозаготовки орков и демоны Холма Демонического Огня. Южные чащи здесь заметно поредели: орки вырубили их для своих строек.",
        ["Крепость Каргатия"] = "Крепость Каргатия стоит на восточном краю лесозаготовок Песни Войны, у самой реки Строптивой. Это оплот командиров клана Песни Войны в Ясеневом лесу — единственная настоящая орочья крепость в лесу, укреплённая частоколом и шипастыми заграждениями. Отсюда удобно получать подкрепления из Оргриммара, если Альянс решится на большое наступление, и здесь надсмотрщики лесозаготовок держат свой штаб.",
        ["Непроглядная Пучина"] = "Непроглядная Пучина — затопленные пещеры под Зорамским взморьем, вход в которые скрыт под водой. В давние времена здесь стоял великолепный храм Элуны, но Великий Раскол утопил его в Сокрытом Море. Тысячелетия спустя порча Древнего бога осквернила священный лунный колодец, и из глубин поднялась Аку'май — чудовищная гидра, любимица Древних богов. Сектанты Сумеречного Молота во главе с Келрисом сошлись здесь с нагами и приносят гидре невинные жертвы. Разведчик Талрид ушёл в пещеры и до сих пор не вернулся.",
        ["Форт Зорам'гар"] = "Форт Зорам'гар — небольшая застава Орды на южном конце Зорамского взморья, единственный оплот Орды на западном побережье леса. Орда поставила её недавно, и ей постоянно нужны новобранцы: с моря заставу атакует гидра Ворша Хлестунья, в честь которой наги жгут огонь на жаровне на прибрежном острове. Здесь стоят орк Муглаш, готовый выйти против гидры, тролль Марукайя, платящая за головы наг, и шаман Дже'неу Санкри, следящий за Сумеречным Молотом в Непроглядной Пучине.",
        ["Рабочий лагерь Песни Войны"] = "Рабочий лагерь Песни Войны — небольшой лагерь на юго-востоке леса, к востоку от озера Зеркало Небес и к юго-западу от обители Дор'Данил. Здесь трудятся лесорубы и сборщики клана Песни Войны под охраной орочьих стражей, и отсюда орк Торек ведёт своих бойцов на Аванпост Среброкрылых. Лагерь стоит на отшибе, и Альянс нередко нападает на него, зная, что помощь с заставы придёт не скоро.",
        ["Роща Среброкрылых"] = "Роща Среброкрылых лежит на юге Ясеневого леса, к юго-западу от Аванпоста Среброкрылых и к западу от озера Зеркало Небес. Это стан часовых Среброкрылых — ночных эльфов, поклявшихся изгнать орков клана Песни Войны из Ущелья Песни Войны, где те продолжают валить лес вопреки воле Тралла и шаманов. Отсюда открыт вход в само ущелье, и здесь собираются бойцы Альянса, а военачальники раздают награды за отбитые у орков знамёна.",
        ["Святилище Песни Теней"] = "Святилище Песни Теней — усыпанный руинами холм на западе Азшары, сразу за мостом из Ясеневого леса. Здесь бродят призраки высокорожденных, что жили в этих землях до Раскола, и они стремятся погасить всякую жизнь, вторгшуюся в их владения. Часовые с заставы Талрендис поглядывают на холм с опаской и не советуют путникам сходить с дороги.",
        ["Лагерь Халдарр"] = "Лагерь Халдарр стоит на западе Азшары, к северо-востоку от святилища Песни Теней, среди эльфийских руин. Здесь густо обосновались сатиры Халдарр, и часовые с заставы Талрендис платят за их головы. Всякий, кто идёт из Ясеневого леса вглубь Азшары, проходит мимо их костров, и мало кому это сходит с рук.",
        ["Застава Талрендис"] = "Застава Талрендис — маленький лагерь ночных эльфов на границе Азшары и Ясеневого леса, у самого моста через реку. Здесь стоит лишь горстка часовых, и путникам застава ничего не предлагает, кроме крыши от дождя. Зато отсюда рукой подать до восточной дороги в Ясеневый лес, и те, кто идёт в Азшару за призраками высокорожденных и сатирами, начинают путь отсюда.",
    },
}
